/// Raw handle for a PDL launch; opts the raw function into dynamic smem > 48 KB when needed
/// (the cudarc module's handles carry their own opt-ins; this second module's do not).
fn xq_raw_fn_smem(name: &str, smem: u32) -> Option<cudarc::driver::sys::CUfunction> {
    let f = xq_raw_fn(name)?;
    if smem > 48 * 1024 {
        use cudarc::driver::sys;
        let r = unsafe { sys::cuFuncSetAttribute(f,
            sys::CUfunction_attribute::CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, smem as i32) };
        if r != sys::CUresult::CUDA_SUCCESS { return None; }
    }
    Some(f)
}

/// cuLaunchKernelEx with CU_LAUNCH_ATTRIBUTE_PROGRAMMATIC_STREAM_SERIALIZATION.
unsafe fn launch_pss_raw(stream: cudarc::driver::sys::CUstream, f: cudarc::driver::sys::CUfunction,
                         grid: (u32, u32, u32), block: (u32, u32, u32), smem: u32,
                         params: &mut [*mut std::ffi::c_void]) -> Result<()> {
    use cudarc::driver::sys::*;
    let mut attr = CUlaunchAttribute {
        id: CUlaunchAttributeID::CU_LAUNCH_ATTRIBUTE_PROGRAMMATIC_STREAM_SERIALIZATION,
        pad: [0; 4],
        value: CUlaunchAttributeValue { programmaticStreamSerializationAllowed: 1 },
    };
    let mut cfg = CUlaunchConfig {
        gridDimX: grid.0, gridDimY: grid.1, gridDimZ: grid.2,
        blockDimX: block.0, blockDimY: block.1, blockDimZ: block.2,
        sharedMemBytes: smem,
        hStream: stream,
        attrs: &mut attr,
        numAttrs: 1,
    };
    let r = cuLaunchKernelEx(&mut cfg, f, params.as_mut_ptr(), std::ptr::null_mut());
    anyhow::ensure!(r == CUresult::CUDA_SUCCESS, "PDL launch failed: {r:?}");
    Ok(())
}

// ---------------------------------------------------------------------------
// S-A3-f-g — reconstruct→cuBLASLt wide-M dense path (the reference implementation's M>=17 split).
// For wide M the fused trellis-GEMM runs at 120 GB/s (weight-bound, 58 tok/s
// prefill); instead decode the trellis ONCE into an f16 staging matrix (the
// decode front-end is the oracle-validated `exl3_decode_dump`) and run the
// vendor GEMM (cuBLASLt → nvjet SM121) on it. Input/output Hadamard kernels
// (had_suh / had_svh) are UNCHANGED — the staged matrix is the same plain
// W_dec the fused mma consumes, so the substitution differs only in the GEMM
// reduction order (the drift class pre-authorized by the brief §1).
// Gated by --exl3-recon-min. S-A3-f-d step 0b (OWNER APPROVED 2026-09-21):
// the serving default is now 17 — the reference implementation's VLLM_EXL3_RECONSTRUCT_MIN_ROWS —
// so the shipped server takes the fast reconstruct→Lt prefill path by default
// (bit-drift class pre-authorized at f-g; decode m <= 16 NEVER reaches this
// path). 0 restores the wide trellis kernel.
// ---------------------------------------------------------------------------

fn recon_min_rows() -> usize {
    crate::opts::var(crate::opt!("exl3-recon-min"))
        .ok().and_then(|v| v.parse().ok()).unwrap_or(17)
}

// ---------------------------------------------------------------------------
// PFX1 (PLAN/SURPASS_PLAN_2026-09-26.md WP06 items 2-6 + WP00 B3's MT-by-chunk-size rule,
// PLAN/PROBES_14_2026-09-26.md): prefill fixed costs + memory diet. Every part is BITWISE —
// greedy output, prefill state and the draft side (head KV rows actually read) are unchanged.
// Default ON. --pfx1-off=1|all = every part off (the p2 behaviour); or a comma list of parts
// (diagnostics / A-B / bisect only — AGENTS §1b):
//   mt      (a) MoE prefill expert-GEMM m-tiles per CTA by chunk rows      -> MT = 4 always
//   headkv  (b) reset_slot before a head-filled prefill skips the head-KV memset -> memset
//   yraw    (c) PrefillScratch chain_yraw = max(c*12288, vocab)            -> c * vocab
//   rows8   (d) xq_gemm_f16_f32_rows8 prefill router on grids rows32 cannot fill -> rows32
//   ltplans (e) background pre-population of the cuBLASLt prefill plans    -> lazy per new m
//   w16     (f) prefill warm-up width 16                                   -> [C, 512, 160, 32]
// --exl3-wide-mt=1|2|4|8 still overrides (a) (every chunk, every wide launch).
// ---------------------------------------------------------------------------
const PFX1_MT: u8 = 1;
const PFX1_HEADKV: u8 = 2;
const PFX1_YRAW: u8 = 4;
const PFX1_ROWS8: u8 = 8;
const PFX1_LTPLANS: u8 = 16;
const PFX1_W16: u8 = 32;
const PFX1_ALL: u8 = PFX1_MT | PFX1_HEADKV | PFX1_YRAW | PFX1_ROWS8 | PFX1_LTPLANS | PFX1_W16;

fn pfx1_mask() -> u8 {
    static M: std::sync::OnceLock<u8> = std::sync::OnceLock::new();
    *M.get_or_init(|| {
        let mut m = PFX1_ALL;
        if let Ok(v) = crate::opts::var(crate::opt!("pfx1-off")) {
            for p in v.split(',') {
                match p.trim() {
                    "1" | "all" => m = 0,
                    "mt" => m &= !PFX1_MT,
                    "headkv" => m &= !PFX1_HEADKV,
                    "yraw" => m &= !PFX1_YRAW,
                    "rows8" => m &= !PFX1_ROWS8,
                    "ltplans" => m &= !PFX1_LTPLANS,
                    "w16" => m &= !PFX1_W16,
                    "" | "0" => {}
                    other => println!("PFX1: unknown --pfx1-off part '{other}' ignored"),
                }
            }
        }
        m
    })
}
fn pfx1_on(part: u8) -> bool { pfx1_mask() & part != 0 }

/// --exl3-wide-mt override of the wide-M trellis GEMM's m-tiles per CTA (1|2|4|8; any other
/// value is ignored, loudly — the kernels' MT switch has no default arm that computes).
fn wide_mt_override() -> Option<usize> {
    static O: std::sync::OnceLock<Option<usize>> = std::sync::OnceLock::new();
    *O.get_or_init(|| {
        let v = crate::opts::var(crate::opt!("exl3-wide-mt")).ok()?;
        match v.trim().parse::<usize>() {
            Ok(mt @ (1 | 2 | 4 | 8)) => Some(mt),
            _ => { println!("--exl3-wide-mt='{v}' ignored (must be 1, 2, 4 or 8)"); None }
        }
    })
}

/// PFX1 (a) chunk-row bounds of the MT rule (WP00 B3 on .14, prefill-window deltas vs MT=4:
/// c=26 -15.5 ms and c=72 -22.9 ms at MT=1; c=160 -17.8 ms at MT=2; c=512 flat). The cuts sit
/// at the linear-interpolated crossovers (MT=1 vs 2 ~117 rows; MT=2 vs 4 between 160 and 512).
const PFX1_MT1_MAX: usize = 112;
const PFX1_MT4_MIN: usize = 384;

/// PFX1 (a): m-tiles per CTA (16*MT rows per super-tile) of the MoE prefill expert GEMMs for a
/// chunk of `c` rows. BITWISE across MT (b7c8b3e: each output row's mma sequence over K is
/// MT-independent; --probe-exl3-wide) — only tile counts / CTA shapes change.
pub(crate) fn pfx1_moe_mt(c: usize) -> usize {
    if let Some(mt) = wide_mt_override() { return mt; }
    if !pfx1_on(PFX1_MT) { return 4; }
    if c <= PFX1_MT1_MAX { 1 } else if c < PFX1_MT4_MIN { 2 } else { 4 }
}

/// Device SM count (48 on GB10; queried once, 48 if the query fails).
fn dev_sms() -> usize {
    static N: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *N.get_or_init(|| {
        use cudarc::driver::sys;
        let mut dev_h: sys::CUdevice = 0;
        let mut sms: std::ffi::c_int = 0;
        let ok = unsafe { sys::cuDeviceGet(&mut dev_h, 0) } == sys::CUresult::CUDA_SUCCESS
            && unsafe { sys::cuDeviceGetAttribute(&mut sms,
                   sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT, dev_h) }
               == sys::CUresult::CUDA_SUCCESS;
        if ok && sms > 0 { sms as usize } else { 48 }
    })
}

/// PFX1 (d) row cut: rows8 for chunks of at most this many rows. rows8's cost grows ~linearly
/// with c (every 8-row CTA re-reads its 64-col router slab) while rows32 stays near-flat on its
/// sub-wave grid. GPU receipt (.13, --probe-exl3-binv ROUTER8 timing, ne 512, K 2560, DRAM-cold
/// weights; us/layer rows32 vs rows8): c=26 216.5 vs 34.6 | 72 209.1 vs 49.5 | 160 220.3 vs 86.4
/// | 512 234.4 vs 248.6 | 736 247.3 vs 354.0. Linear fits (rows8 ~23 + 0.45c, rows32 ~212 +
/// 0.04c) cross at c ~ 465-480; the cut sits at 384 (~14% predicted margin, clear of the noise
/// band). The old rule (the rows32 grid under two waves = c <= 736) lost up to 107 us/layer
/// (5.1 ms per 48-layer chunk) at c = 736. --pfx1-rows8-max=<c> overrides (0 = never rows8).
const PFX1_ROWS8_MAX: usize = 384;

/// --pfx1-rows8-max=<c>: Some(c) replaces the whole row rule (the 384 cut AND the two-wave
/// cap) — an A/B / tuning knob; the kernel's shape contract still applies. None = the default rule.
fn pfx1_rows8_max_override() -> Option<usize> {
    static O: std::sync::OnceLock<Option<usize>> = std::sync::OnceLock::new();
    *O.get_or_init(|| {
        let v = crate::opts::var(crate::opt!("pfx1-rows8-max")).ok()?;
        match v.trim().parse::<usize>() {
            Ok(n) => Some(n),
            Err(_) => { println!("--pfx1-rows8-max='{v}' ignored (must be a row count)"); None }
        }
    })
}

/// PFX1 (d): take xq_gemm_f16_f32_rows8 (64 cols x 8 rows per CTA) instead of rows32 for chunks of
/// c <= PFX1_ROWS8_MAX rows whose rows32 grid, ceil(c/32) * (ne/128) CTAs, is under two waves of
/// SMs (<= 736 rows at ne = 512 on 48 SMs — looser than the row cut there). Both kernels are
/// bitwise to the reference router, so the cut moves time only. Shape contract of the kernel:
/// ne % 64 == 0, K % 256 == 0 (else rows32).
pub(crate) fn pfx1_router_rows8(c: usize, ne: usize, k: usize) -> bool {
    pfx1_on(PFX1_ROWS8) && ne % 64 == 0 && k % 256 == 0 && k > 0
        && match pfx1_rows8_max_override() {
            Some(max) => c <= max,
            None => c <= PFX1_ROWS8_MAX && c.div_ceil(32) * (ne / 128) < 2 * dev_sms(),
        }
}

/// TP-4R1: the register-tiled prefill router kernels (`xq_gemm_f16_f32_tile128` = 128x64 outputs per CTA, 8x8 per
/// thread; `xq_gemm_f16_f32_tile64` = 64x64, 8x4) — the same single ascending-k fp32 chain per (row, expert) as
/// rows32/rows8/xq_gemm_f16_f32 (BITWISE equal; gate: --probe-exl3-routergemm), at ~2x the rate of rows32 (rows32 is
/// smem-operand-bound at one smem word per FFMA; these keep an 8x8 / 8x4 output tile in registers). Returns the
/// kernel name and its rows-per-CTA for a launch of `m` rows, or None when the shape contract fails
/// (ne % 64 == 0, K % 16 == 0) and the caller keeps rows32. 64x64 under `ROUTER_TILE128_MIN` rows (more CTAs per
/// wave: measured faster at m = 512..1021), 128x64 from there up.
pub(crate) const ROUTER_TILE128_MIN: usize = 1280;
pub(crate) fn router_tile_kernel(m: usize, ne: usize, k: usize) -> Option<(&'static str, usize)> {
    if m == 0 || ne % 64 != 0 || k == 0 || k % 16 != 0 { return None; }
    Some(if m < ROUTER_TILE128_MIN { ("xq_gemm_f16_f32_tile64", 64) } else { ("xq_gemm_f16_f32_tile128", 128) })
}

/// TP-SP2: the prefill router GEMM (fp32 logits of `m` rows of `x` into `out`, raw device addresses)
/// with the kernel the served dispatch picks for a chunk of `c_class` rows (`rows_on` = the tunable
/// prefill.router_rows) — the moe_prefill launches, callable on a row block (row-offset pointers).
/// Every variant is the same single ascending-k chain per (row, expert), so a row's bits do not depend
/// on m or on the block's offset (gate: --probe-exl3-sppin's EXL3-SP-ROUTER section).
#[allow(clippy::too_many_arguments)]
pub(crate) fn router_rows_launch(l: &Launcher, out: u64, w: u64, x: u64, m: usize, c_class: usize, ne: usize,
                                 h: usize, rows_on: bool) -> Result<()> {
    if rows_on {
        if pfx1_router_rows8(c_class, ne, h) {
            xqlaunch!(l, "xq_gemm_f16_f32_rows8", ((ne as u32) / 64, m.div_ceil(8) as u32, 1), (64, 1, 1), 0,
                     (out, w, x, m as i32, ne as i32, h as i32))?;
        } else if let Some((kn, bm)) = router_tile_kernel(m, ne, h) {
            xqlaunch!(l, kn, ((ne as u32) / 64, m.div_ceil(bm) as u32, 1), (128, 1, 1), 0,
                     (out, w, x, m as i32, ne as i32, h as i32))?;
        } else {
            xqlaunch!(l, "xq_gemm_f16_f32_rows32", ((ne as u32) / 128, ((m + 31) / 32) as u32, 1), (128, 1, 1), 0,
                     (out, w, x, m as i32, ne as i32, h as i32))?;
        }
    } else {
        xqlaunch!(l, "xq_gemm_f16_f32", ((ne as u32) / 128, m as u32, 1), (128, 1, 1), 0,
                 (out, w, x, m as i32, ne as i32, h as i32))?;
    }
    Ok(())
}

/// TUNE T0c (p5e): PFX1 (d) per prefill chunk class (the rows8 twin is bitwise == rows32). The
/// alias --pfx1-off (1|all|<parts>) decides exactly as before whenever it is set. PFX1's other
/// parts stay env-only: (a) mt IS prefill.wide_mt's default (the rule); (b) headkv / (c) yraw are
/// memory policy at admit / load; (e) ltplans / (f) w16 are host policy (P).
pub(crate) const T_PFX1_ROWS8: tune::TunableDef = tune::TunableDef {
    slot: 82, id: "pfx1.rows8", class: tune::Class::S, scope: tune::Scope::Chunk, fams: &[tune::Fam::Prefill],
    domain: &[0, 1], default: 1, valid: tune::valid_any, xcheck: "--probe-exl3-binv EXL3-ROUTER8 (rows8 vs rows32)",
    env: "--pfx1-off", env_parse: || tune::env_str(crate::opt!("pfx1-off")).map(|_| (pfx1_mask() & PFX1_ROWS8 != 0) as i32),
    rev: 1, wp: "PFX1",
};

/// PFX1 (c): the widest N of any m = c prefill chain (attention q_proj + gate = 12288; the head
/// fc chains run m = 4c at N = 2560 = 10240c elements). The prefill lm_head is the only wider
/// chain and runs at m = 1 (N = vocab).
const PF_CHAIN_NMAX: usize = 12288;

/// --exl3-head-fill=0 turns the chunked prefill's MTP head-KV fill off (diagnostic).
fn head_fill_on() -> bool {
    crate::opts::var(crate::opt!("exl3-head-fill")).as_deref() != Ok("0")
}

/// PFX1 (b) gate knob --pfx1-headkv-poison=1: where the head-KV memset is skipped, fill the
/// slot's head KV with a NaN pattern instead (diagnostic only; costs the memset it replaces).
fn pfx1_headkv_poison() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        let on = crate::opts::var(crate::opt!("pfx1-headkv-poison")).is_ok_and(|v| !v.is_empty() && v != "0");
        if on { println!("PFX1: --pfx1-headkv-poison — head KV NaN-poisoned at every fresh-prompt admit (gate)"); }
        on
    })
}

/// PFX1: one boot line with the live parts and the MT rule (FwdModel::load).
fn pfx1_announce() {
    static ONCE: std::sync::Once = std::sync::Once::new();
    ONCE.call_once(|| {
        let m = pfx1_mask();
        let rule = match wide_mt_override() {
            Some(mt) => format!("MT={mt} for every chunk (--exl3-wide-mt override)"),
            None if pfx1_on(PFX1_MT) => format!("MT=1 for c <= {PFX1_MT1_MAX}, MT=2 for c < {PFX1_MT4_MIN}, MT=4 from {PFX1_MT4_MIN} rows"),
            None => "MT=4 for every chunk (PFX1 mt off)".to_string(),
        };
        let router = if !pfx1_on(PFX1_ROWS8) {
            "rows32 for every chunk (PFX1 rows8 off)".to_string()
        } else if let Some(max) = pfx1_rows8_max_override() {
            format!("rows8 when c <= {max} (--pfx1-rows8-max override)")
        } else {
            format!("rows8 when c <= {PFX1_ROWS8_MAX} and ceil(c/32)*(ne/128) < 2*{} SMs", dev_sms())
        };
        println!("PFX1: parts on = {m:#04x} (mt 1, headkv 2, yraw 4, rows8 8, ltplans 16, w16 32{}); \
                  MoE prefill expert GEMM: {rule}; router: {router}",
                 crate::opts::var(crate::opt!("pfx1-off")).map(|v| format!("; --pfx1-off={v}")).unwrap_or_default());
    });
}

/// Buffers a caller must carry so `exl3_chain` can take the reconstruct+Lt arm.
/// Raw device pointers only (no borrows): the staging is written whole by
/// exl3_decode_dump before any read, the Lt workspace by cuBLASLt itself.
/// Decode paths pass None and keep byte-identical launches.
pub(crate) struct ReconBufs {
    ws: u64,       // staging device pointer (f16, [k_max * n_max])
    ws_len: usize, // staging capacity in u16 elements
    rc: u64,       // rc_of_t LUT device pointer
    ltws: u64,     // cuBLASLt workspace device pointer
    ltws_len: usize,
}

/// Everything cuBLASLt needs for ONE (k, n, m) shape: the heuristic-pinned algo
/// plus the descriptors. Created once per shape (first call, or PFX1's background
/// pre-population), reused forever — per-call descriptor creation would both cost
/// host time and leak.
struct LtPlan {
    algo: ltsys::cublasLtMatmulAlgo_t,
    desc: ltsys::cublasLtMatmulDesc_t,
    a_layout: ltsys::cublasLtMatrixLayout_t,
    b_layout: ltsys::cublasLtMatrixLayout_t,
    c_layout: ltsys::cublasLtMatrixLayout_t,
}
// The descriptors are opaque host objects: created on one thread (the prefill thread, or the
// PFX1 pre-population thread) and afterwards only READ, under the PLANS mutex, by the prefill
// thread's matmul; same contract as `unsafe impl Send for FwdModel`.
unsafe impl Send for LtPlan {}

/// Plan-cache key: (k, n, m, ta). The workspace preference is NOT in the key — every caller
/// passes the PrefillScratch's 32 MB lt_ws, and PFX1's pre-population replays the recorded one.
type LtKey = (usize, usize, usize, u8);

/// The process-wide cuBLASLt handle (created on first use; cuBLASLt handles are thread-safe —
/// PFX1's pre-population thread issues heuristic queries on it, never matmuls).
fn lt_handle() -> ltsys::cublasLtHandle_t {
    static HANDLE: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    // cublasLtHandle_t is an opaque pointer: stash as usize (Copy) and cast back.
    *HANDLE.get_or_init(|| lt::create_handle().expect("cublasLtCreate") as usize) as ltsys::cublasLtHandle_t
}

fn lt_plans() -> &'static std::sync::Mutex<std::collections::HashMap<LtKey, LtPlan>> {
    static PLANS: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<LtKey, LtPlan>>> =
        std::sync::OnceLock::new();
    PLANS.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// Build the plan of one (k, n, m, ta) shape: descriptors + the heuristic's top algo. A pure
/// function of (k, n, m, ta, ltws_len) — no timing, no pointers — so a plan built by PFX1's
/// background thread is the plan the lazy path would have built (same algo => same bits).
fn lt_plan_build(handle: ltsys::cublasLtHandle_t, k: usize, n: usize, m: usize, ta: bool,
                 ltws_len: usize) -> std::result::Result<LtPlan, String> {
    let e = |what: &str, r: lt::CublasError| format!("cublasLt {what} (k={k} n={n} m={m} ta={ta}): {r:?}");
    let bf = ltsys::cudaDataType_t::CUDA_R_16F;
    let desc = lt::create_matmul_desc(
        ltsys::cublasComputeType_t::CUBLAS_COMPUTE_32F,
        ltsys::cudaDataType_t::CUDA_R_32F)
        .map_err(|r| e("create_matmul_desc", r))?;
    // ta=true: A is a plain f16 weight row-major [N, K] → col-major [K, N] ld=K,
    // transposed (the xq_gemm_f16 a_w/b_w convention). ta=false: A is Wdec
    // row-major [K, N] → col-major [N, K] ld=N, not transposed.
    let ta_v: u32 = if ta { 1 } else { 0 };
    let tb: u32 = 0; // opB=N: B row-major [m, K] → col-major [K, m] ld=K
    unsafe {
        lt::set_matmul_desc_attribute(desc,
            ltsys::cublasLtMatmulDescAttributes_t::CUBLASLT_MATMUL_DESC_TRANSA,
            &ta_v as *const _ as *const _, 4).map_err(|r| e("set TRANSA", r))?;
        lt::set_matmul_desc_attribute(desc,
            ltsys::cublasLtMatmulDescAttributes_t::CUBLASLT_MATMUL_DESC_TRANSB,
            &tb as *const _ as *const _, 4).map_err(|r| e("set TRANSB", r))?;
    }
    let pref = lt::create_matmul_pref().map_err(|r| e("create_matmul_pref", r))?;
    let ws_size: usize = ltws_len;
    unsafe {
        lt::set_matmul_pref_attribute(pref,
            ltsys::cublasLtMatmulPreferenceAttributes_t::
                CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
            &ws_size as *const _ as *const _, 8).map_err(|r| e("set MAX_WORKSPACE", r))?;
    }
    // opA=T: A col-major [K, N] ld=K; opA=N: A col-major [N, K] ld=N.
    let a_layout = if ta {
        lt::create_matrix_layout(bf, k as u64, n as u64, k as i64)
    } else {
        lt::create_matrix_layout(bf, n as u64, k as u64, n as i64)
    }.map_err(|r| e("a_layout", r))?;
    let b_layout = lt::create_matrix_layout(bf, k as u64, m as u64, k as i64)
        .map_err(|r| e("b_layout", r))?;
    let c_layout = lt::create_matrix_layout(bf, n as u64, m as u64, n as i64)
        .map_err(|r| e("c_layout", r))?;
    let heur = lt::get_matmul_algo_heuristic(handle, desc,
            a_layout, b_layout, c_layout, c_layout, pref)
        .map_err(|r| e("heuristic (f16 wide-M)", r));
    // the preference only feeds the heuristic query (its result is a value copy)
    unsafe { let _ = lt::destroy_matmul_pref(pref); }
    Ok(LtPlan { algo: heur?.algo, desc, a_layout, b_layout, c_layout })
}

/// Release a plan's descriptors (PFX1: a pre-populated duplicate that lost the insert race).
fn lt_plan_drop(p: LtPlan) {
    unsafe {
        let _ = lt::destroy_matrix_layout(p.a_layout);
        let _ = lt::destroy_matrix_layout(p.b_layout);
        let _ = lt::destroy_matrix_layout(p.c_layout);
        let _ = lt::destroy_matmul_desc(p.desc);
    }
}

/// PFX1 (e): while set, every exl3_lt_matmul records its (k, n, m, ta, ltws_len) into LT_REC
/// (armed by prefill_warmup around its full-width chunk only).
static LT_REC_ON: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
static LT_REC: std::sync::Mutex<Vec<(usize, usize, usize, bool, usize)>> = std::sync::Mutex::new(Vec::new());
/// PFX1 (e): the Lt shape families of the served prefill at chunk width C — (k, n, ta, m/C,
/// ltws_len) — plus C, derived from the warm-up's full-width chunk; consumed by lt_prewarm_start.
#[allow(clippy::type_complexity)]
static LT_FAMILIES: std::sync::Mutex<Option<(Vec<(usize, usize, bool, usize, usize)>, usize)>> =
    std::sync::Mutex::new(None);

/// One wide-M GEMM through cuBLASLt (SM121 nvjet kernels) on a reconstructed f16
/// weight. Layouts (all f16, fp32 accumulate): A = Wdec row-major [K,N] →
/// col-major view [N,K], ld=N, opA=N; B = xh row-major [m,K] → col-major [K,m],
/// ld=K, opB=N (row offset applied by the caller via pointer); C row-major
/// [m,N] → col-major [N,m], ld=N. Heuristics per (k,n,m), cached process-wide
/// (the brief's "heuristics first"; the winning algo is pinned by the cache).
fn exl3_lt_matmul(l: &Launcher, a: u64, b: u64, c: u64,
                  k: usize, n: usize, m: usize, ta: bool, ltws: u64, ltws_len: usize) -> Result<()> {
    if LT_REC_ON.load(std::sync::atomic::Ordering::Relaxed) {
        let mut rec = LT_REC.lock().unwrap();
        if !rec.contains(&(k, n, m, ta, ltws_len)) { rec.push((k, n, m, ta, ltws_len)); }
    }
    let handle = lt_handle();
    let mut map = lt_plans().lock().unwrap();
    let plan = map.entry((k, n, m, ta as u8)).or_insert_with(|| {
        lt_plan_build(handle, k, n, m, ta, ltws_len).unwrap_or_else(|s| panic!("{s}"))
    });
    let alpha: f32 = 1.0;
    let beta: f32 = 0.0;
    let r = unsafe {
        lt::matmul(handle, plan.desc,
            &alpha as *const _ as *const core::ffi::c_void,
            &beta as *const _ as *const core::ffi::c_void,
            a as *const core::ffi::c_void, plan.a_layout,
            b as *const core::ffi::c_void, plan.b_layout,
            c as *mut core::ffi::c_void, plan.c_layout,
            c as *mut core::ffi::c_void, plan.c_layout,
            &plan.algo, ltws as *mut core::ffi::c_void, ltws_len,
            l.stream.stream as usize as ltsys::cudaStream_t)
    };
    r.with_context(|| format!("cublasLt matmul k={k} n={n} m={m}"))
}

// ---------------------------------------------------------------------------------------------
// TP-SP (sequence-parallel prefill): PINNED-PLAN mode. A rank that owns rows [lo, hi) of a c-row
// chunk runs the chunk's per-row GEMMs on its rows only, with the (k, n, c) plan's ALGO pinned on the
// m = hi - lo layouts (row-offset pointers) — TP-I3 §3.1: then every output row is bit-identical to
// the m = c call for c >= 97 (hc down; hc up at every c), while each half's OWN heuristic plan differs
// at 1,971 of 2,047 sizes (split-K 2/3/4/12 vs 1/2/3/4). The gate is `--probe-exl3-sppin` (also the
// EXL3-SP-PIN section of --probe-exl3-binv): every c in [T, SP_MAX] for every split shape, through
// exactly the functions below.
// ---------------------------------------------------------------------------------------------

/// Pinned-plan cache key: (k, n, m, ta, pin_m) — the plan of (k, n, pin_m)'s algo on m-row layouts.
type LtPinKey = (usize, usize, usize, u8, usize);

fn lt_pinned() -> &'static std::sync::Mutex<std::collections::HashMap<LtPinKey, LtPlan>> {
    static P: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<LtPinKey, LtPlan>>> = std::sync::OnceLock::new();
    P.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// Pinned keys whose algo does not run on the m-row layouts (AlgoCheck refused / workspace too big):
/// cached so the refusal is decided once, identically on every rank.
fn lt_pin_bad() -> &'static std::sync::Mutex<std::collections::HashMap<LtPinKey, String>> {
    static B: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<LtPinKey, String>>> = std::sync::OnceLock::new();
    B.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// The algo of the SERVED (k, n, m, ta) plan — the cached plan exl3_lt_matmul runs at that m (built the
/// same way, lazily, when absent: a pure function of (k, n, m, ta, ltws_len)).
fn lt_ref_algo(k: usize, n: usize, m: usize, ta: bool, ltws_len: usize) -> Result<ltsys::cublasLtMatmulAlgo_t> {
    let handle = lt_handle();
    let mut map = lt_plans().lock().unwrap();
    if let std::collections::hash_map::Entry::Vacant(v) = map.entry((k, n, m, ta as u8)) {
        v.insert(lt_plan_build(handle, k, n, m, ta, ltws_len).map_err(|s| anyhow::anyhow!(s))?);
    }
    Ok(map[&(k, n, m, ta as u8)].algo)
}

/// A plan whose algo is GIVEN (no heuristic): lt_plan_build's descriptors / layouts for (k, n, m, ta),
/// `algo` pinned, validated with cublasLtMatmulAlgoCheck and a workspace need <= ltws_len.
fn lt_plan_build_pinned(handle: ltsys::cublasLtHandle_t, k: usize, n: usize, m: usize, ta: bool, ltws_len: usize,
                        algo: ltsys::cublasLtMatmulAlgo_t) -> std::result::Result<LtPlan, String> {
    let e = |what: &str, r: lt::CublasError| format!("cublasLt {what} (pinned k={k} n={n} m={m} ta={ta}): {r:?}");
    let bf = ltsys::cudaDataType_t::CUDA_R_16F;
    let desc = lt::create_matmul_desc(ltsys::cublasComputeType_t::CUBLAS_COMPUTE_32F, ltsys::cudaDataType_t::CUDA_R_32F)
        .map_err(|r| e("create_matmul_desc", r))?;
    let ta_v: u32 = if ta { 1 } else { 0 };
    let tb: u32 = 0;
    unsafe {
        lt::set_matmul_desc_attribute(desc, ltsys::cublasLtMatmulDescAttributes_t::CUBLASLT_MATMUL_DESC_TRANSA,
            &ta_v as *const _ as *const _, 4).map_err(|r| e("set TRANSA", r))?;
        lt::set_matmul_desc_attribute(desc, ltsys::cublasLtMatmulDescAttributes_t::CUBLASLT_MATMUL_DESC_TRANSB,
            &tb as *const _ as *const _, 4).map_err(|r| e("set TRANSB", r))?;
    }
    let a_layout = if ta { lt::create_matrix_layout(bf, k as u64, n as u64, k as i64) }
                   else { lt::create_matrix_layout(bf, n as u64, k as u64, n as i64) }.map_err(|r| e("a_layout", r))?;
    let b_layout = lt::create_matrix_layout(bf, k as u64, m as u64, k as i64).map_err(|r| e("b_layout", r))?;
    let c_layout = lt::create_matrix_layout(bf, n as u64, m as u64, n as i64).map_err(|r| e("c_layout", r))?;
    let plan = LtPlan { algo, desc, a_layout, b_layout, c_layout };
    let mut chk = std::mem::MaybeUninit::<ltsys::cublasLtMatmulHeuristicResult_t>::zeroed();
    let rc = unsafe {
        ltsys::cublasLtMatmulAlgoCheck(handle, plan.desc, plan.a_layout, plan.b_layout, plan.c_layout, plan.c_layout,
                                       &plan.algo, chk.as_mut_ptr())
    };
    if rc != ltsys::cublasStatus_t::CUBLAS_STATUS_SUCCESS {
        lt_plan_drop(plan);
        return Err(format!("AlgoCheck(k={k} n={n} m={m}) = {rc:?}"));
    }
    let wsz = unsafe { chk.assume_init() }.workspaceSize;
    if wsz > ltws_len {
        lt_plan_drop(plan);
        return Err(format!("pinned workspace {wsz} > {ltws_len} (k={k} n={n} m={m})"));
    }
    Ok(plan)
}

/// Build (once) the pinned plan of (k, n, m, ta) under the (k, n, pin_m) algo; Err = it cannot run.
fn lt_pin_plan_ensure(k: usize, n: usize, m: usize, pin_m: usize, ta: bool, ltws_len: usize) -> Result<()> {
    let key: LtPinKey = (k, n, m, ta as u8, pin_m);
    if lt_pinned().lock().unwrap().contains_key(&key) { return Ok(()); }
    if let Some(why) = lt_pin_bad().lock().unwrap().get(&key) { anyhow::bail!("{why}"); }
    let algo = lt_ref_algo(k, n, pin_m, ta, ltws_len)?;
    match lt_plan_build_pinned(lt_handle(), k, n, m, ta, ltws_len, algo) {
        Ok(p) => {
            let mut map = lt_pinned().lock().unwrap();
            if let std::collections::hash_map::Entry::Vacant(v) = map.entry(key) { v.insert(p); } else { drop(map); lt_plan_drop(p); }
            Ok(())
        }
        Err(s) => { lt_pin_bad().lock().unwrap().insert(key, s.clone()); anyhow::bail!("{s}") }
    }
}

/// TP-SP: are the pinned plans of EVERY rank's row block of a c-row chunk runnable for (k, n)? Every
/// rank evaluates every block (not only its own), so the verdict is the same on all ranks (SPMD).
pub(crate) fn lt_pin_ready(k: usize, n: usize, c: usize, world: usize, ta: bool, ltws_len: usize) -> Result<()> {
    for r in 0..world {
        let (lo, hi) = crate::tp_xport::row_block(c, r, world);
        if hi > lo && hi - lo != c { lt_pin_plan_ensure(k, n, hi - lo, c, ta, ltws_len)?; }
    }
    Ok(())
}

/// TP-SP: rows [0, m) of `b` / `c` (row-offset pointers of a pin_m-row chunk) through the (k, n, pin_m)
/// plan's algo pinned on the m-row layouts — bitwise those rows of exl3_lt_matmul at m = pin_m wherever
/// the gate proved it (--probe-exl3-sppin). m == pin_m is exactly exl3_lt_matmul.
#[allow(clippy::too_many_arguments)]
fn exl3_lt_matmul_pinned(l: &Launcher, a: u64, b: u64, c: u64, k: usize, n: usize, m: usize, pin_m: usize,
                         ta: bool, ltws: u64, ltws_len: usize) -> Result<()> {
    if m == pin_m { return exl3_lt_matmul(l, a, b, c, k, n, m, ta, ltws, ltws_len); }
    if LT_REC_ON.load(std::sync::atomic::Ordering::Relaxed) {
        // PFX1 (e): the reference family (m = pin_m) is what the background pre-population must build
        let mut rec = LT_REC.lock().unwrap();
        if !rec.contains(&(k, n, pin_m, ta, ltws_len)) { rec.push((k, n, pin_m, ta, ltws_len)); }
    }
    lt_pin_plan_ensure(k, n, m, pin_m, ta, ltws_len)?;
    let handle = lt_handle();
    let map = lt_pinned().lock().unwrap();
    let plan = &map[&(k, n, m, ta as u8, pin_m)];
    let (alpha, beta) = (1.0f32, 0.0f32);
    let r = unsafe {
        lt::matmul(handle, plan.desc,
            &alpha as *const _ as *const core::ffi::c_void, &beta as *const _ as *const core::ffi::c_void,
            a as *const core::ffi::c_void, plan.a_layout, b as *const core::ffi::c_void, plan.b_layout,
            c as *mut core::ffi::c_void, plan.c_layout, c as *mut core::ffi::c_void, plan.c_layout,
            &plan.algo, ltws as *mut core::ffi::c_void, ltws_len, l.stream.stream as usize as ltsys::cudaStream_t)
    };
    r.with_context(|| format!("cublasLt pinned matmul k={k} n={n} m={m} (pin m={pin_m})"))
}

/// The prefill GEMM shapes a sequence-parallel chunk splits by rows (k, n; ta = plain f16 weights):
/// the hc down (rw -> lr) and hc up (lr -> rw) projections of every hc_pre. (The PLE and the router
/// stay replicated in SP-1.)
pub(crate) fn sp_split_shapes(h: usize, hcn: usize, lr: usize) -> [(usize, usize); 2] { [(h * hcn, lr), (lr, h * hcn)] }

/// TP-SP gate (`--probe-exl3-sppin`, default c = 128..=4095 = the split range; the EXL3-SP-PIN section of
/// --probe-exl3-binv over [SP_MIN_ROWS, SP_MAX_ROWS]): for every c in
/// `cs` and every split shape (the served hc down/up at h 2560, hc 4, lr 320), the reference is the
/// SERVED replicated call (exl3_lt_matmul at m = c over all rows) and the candidate is EXACTLY the SP
/// prefill's call — every rank block through exl3_lt_matmul_pinned on row-offset pointers, the plan
/// readiness decided by lt_pin_ready — at world `world`. Outputs are NaN-poisoned first; the reference
/// must be complete and plausible; every element is compared bitwise.
pub fn probe_sp_pinned(cs: &[usize], world: usize) -> Result<()> {
    let dev = CudaDevice::new(0).context("CudaDevice::new(0)")?;
    let stream = fork_blocking_stream(&dev);
    let l = Launcher { dev: &dev, stream: &stream };
    let ws_len = 32usize * 1024 * 1024; // the PrefillScratch lt_ws (every served prefill Lt call)
    let d_ws = unsafe { dev.alloc::<u8>(ws_len) }?;
    let ws = *d_ws.device_ptr() as u64;
    let cmax = cs.iter().copied().max().unwrap_or(2048);
    let mut st = 0x5EB1_7A11u32;
    let mut rnd = move || { st ^= st << 13; st ^= st >> 17; st ^= st << 5; st };
    let mut f16v = |n: usize, sc: f32| -> Vec<u16> {
        (0..n).map(|_| f16::from_f32((((rnd() >> 9) as f32 / (1u32 << 23) as f32) * 2.0 - 1.0) * sc).to_bits()).collect()
    };
    let t0 = std::time::Instant::now();
    let (mut n_cases, mut n_bad, mut n_unready) = (0usize, 0usize, 0usize);
    for (name, (k, n)) in [("hc down (rw -> lr)", sp_split_shapes(2560, 4, 320)[0]), ("hc up (lr -> rw)", sp_split_shapes(2560, 4, 320)[1])] {
        let d_a = dev.htod_sync_copy(&f16v(n * k, 0.05))?;
        let d_b = dev.htod_sync_copy(&f16v(cmax * k, 2.0))?;
        let d_ref = dev.alloc_zeros::<u16>(cmax * n)?;
        let d_sp = dev.alloc_zeros::<u16>(cmax * n)?;
        let (pa, pb) = (*d_a.device_ptr() as u64, *d_b.device_ptr() as u64);
        let (pr, ps) = (*d_ref.device_ptr() as u64, *d_sp.device_ptr() as u64);
        let (mut vr, mut vs) = (vec![0u16; cmax * n], vec![0u16; cmax * n]);
        let (mut s_bad, mut s_unready, mut s_n) = (Vec::<usize>::new(), Vec::<usize>::new(), 0usize);
        for &c in cs {
            if c < world { continue; }
            s_n += 1;
            n_cases += 1;
            let live = c * n;
            // NaN-poison the live rows of both outputs (legacy-stream memset: ordered before the blocking
            // stream's GEMMs)
            for p in [pr, ps] {
                let rc = unsafe { cudarc::driver::sys::cuMemsetD16_v2(p, 0x7E00, live) };
                anyhow::ensure!(rc == cudarc::driver::sys::CUresult::CUDA_SUCCESS, "cuMemsetD16 ({rc:?})");
            }
            exl3_lt_matmul(&l, pa, pb, pr, k, n, c, true, ws, ws_len)?;
            if let Err(e) = lt_pin_ready(k, n, c, world, true, ws_len) {
                s_unready.push(c);
                n_unready += 1;
                if s_unready.len() <= 8 { println!("  {name} c {c:>5}: pinned plans NOT READY ({e:#})"); }
                continue;
            }
            for r in 0..world {
                let (lo, hi) = crate::tp_xport::row_block(c, r, world);
                if hi == lo { continue; }
                exl3_lt_matmul_pinned(&l, pa, pb + (lo * k * 2) as u64, ps + (lo * n * 2) as u64, k, n, hi - lo, c,
                                      true, ws, ws_len)?;
            }
            dev.synchronize()?;
            dev.dtoh_sync_copy_into(&d_ref.slice(0..live), &mut vr[..live])?;
            dev.dtoh_sync_copy_into(&d_sp.slice(0..live), &mut vs[..live])?;
            let poisoned = vr[..live].iter().filter(|&&b| b == 0x7E00).count();
            anyhow::ensure!(poisoned == 0, "EXL3-SP-PIN {name} c {c}: the reference left {poisoned} poisoned outputs");
            let nzr = vr[..live].iter().filter(|&&b| b & 0x7fff != 0).count();
            anyhow::ensure!(nzr > live / 2, "EXL3-SP-PIN {name} c {c}: implausible reference ({nzr} nonzero of {live})");
            let mut nd = 0usize;
            let mut first = None;
            if vs[..live] != vr[..live] {
                for i in 0..live { if vs[i] != vr[i] { nd += 1; first.get_or_insert(i / n); } }
            }
            if nd > 0 {
                n_bad += 1;
                s_bad.push(c);
                if s_bad.len() <= 8 { println!("  {name} c {c:>5}: {nd} of {live} f16 DIFFER (first row {first:?})"); }
            }
        }
        println!("EXL3-SP-PIN {name} (k {k} n {n}): {s_n} c values at world {world}; bitwise differ at {} (c {:?}); \
                  pinned plans not ready at {} (c {:?})", s_bad.len(), &s_bad[..s_bad.len().min(20)],
                 s_unready.len(), &s_unready[..s_unready.len().min(20)]);
    }
    // TP-SP2 EXL3-SP-ROUTER: the router extension's calls (router_rows_launch + xq_router_topk on every
    // rank block, the kernel picked for the full chunk) vs the replicated router at m = c, for both
    // prefill.router_rows values: logits, ids and weights bitwise.
    if dev.get_func(MODULE, "xq_router_topk").is_none() { crate::exl3_bench::load_module_pub(&dev)?; }
    let (h, ne, topk) = (2560usize, 256usize, 8usize);
    let d_w = dev.htod_sync_copy(&f16v(ne * h, 0.05))?;
    let d_x = dev.htod_sync_copy(&f16v(cmax * h, 2.0))?;
    let (d_lr, d_ls) = (dev.alloc_zeros::<f32>(cmax * ne)?, dev.alloc_zeros::<f32>(cmax * ne)?);
    let (d_ir, d_is) = (dev.alloc_zeros::<i32>(cmax * topk)?, dev.alloc_zeros::<i32>(cmax * topk)?);
    let (d_wr, d_ws2) = (dev.alloc_zeros::<f32>(cmax * topk)?, dev.alloc_zeros::<f32>(cmax * topk)?);
    let (pw, px) = (*d_w.device_ptr() as u64, *d_x.device_ptr() as u64);
    let p = |s: &CudaSlice<f32>| *s.device_ptr() as u64;
    let (plr, pls, pwr, pws) = (p(&d_lr), p(&d_ls), p(&d_wr), p(&d_ws2));
    let (pir, pis) = (*d_ir.device_ptr() as u64, *d_is.device_ptr() as u64);
    let smem = ((256 + ne + 512) * 4) as u32;
    let mut n_router = 0usize;
    // standalone RANKING (not an in-round price, AGENTS §4) of the router kernels at the served chunk and its
    // half: does the own-row block's launch take half the time?
    if cmax >= 2048 {
        let tm = |f: &dyn Fn() -> Result<()>| -> Result<f64> {
            for _ in 0..3 { f()?; }
            dev.synchronize()?;
            let t = std::time::Instant::now();
            for _ in 0..20 { f()?; }
            dev.synchronize()?;
            Ok(t.elapsed().as_secs_f64() * 1e6 / 20.0)
        };
        let r8 = |m: usize| -> Result<()> {
            xqlaunch!(l, "xq_gemm_f16_f32_rows8", ((ne as u32) / 64, m.div_ceil(8) as u32, 1), (64, 1, 1), 0,
                     (pls, pw, px, m as i32, ne as i32, h as i32))
        };
        let a = tm(&|| router_rows_launch(&l, plr, pw, px, 2048, 2048, ne, h, true))?;
        let b = tm(&|| router_rows_launch(&l, pls, pw, px, 1024, 2048, ne, h, true))?;
        let c8 = tm(&|| r8(1024))?;
        let d8 = tm(&|| r8(2048))?;
        let e = tm(&|| router_rows_launch(&l, plr, pw, px, 4095, 4095, ne, h, true))?;
        let f = tm(&|| router_rows_launch(&l, pls, pw, px, 2048, 4095, ne, h, true))?;
        println!("EXL3-SP-ROUTER timing (standalone, L2-warm, us/launch; a ranking only): rows32 m=2048 {a:.1} | rows32 m=1024 \
                  {b:.1} | rows8 m=1024 {c8:.1} | rows8 m=2048 {d8:.1} | rows32 m=4095 {e:.1} | rows32 m=2048 (of 4095) {f:.1}");
    }
    for rows_on in [true, false] {
        let mut s_bad = Vec::<usize>::new();
        let mut s_n = 0usize;
        for &c in cs {
            if c < world { continue; }
            s_n += 1;
            n_cases += 1;
            n_router += 1;
            for (q, n) in [(plr, c * ne), (pls, c * ne), (pwr, c * topk), (pws, c * topk), (pir, c * topk), (pis, c * topk)] {
                let rc = unsafe { cudarc::driver::sys::cuMemsetD32_v2(q, 0x7FC0_0000, n) };
                anyhow::ensure!(rc == cudarc::driver::sys::CUresult::CUDA_SUCCESS, "cuMemsetD32 ({rc:?})");
            }
            router_rows_launch(&l, plr, pw, px, c, c, ne, h, rows_on)?;
            xqlaunch!(l, "xq_router_topk", (c as u32, 1, 1), (256, 1, 1), smem, (pir, pwr, plr, ne as i32, topk as i32, c as i32))?;
            for r in 0..world {
                let (lo, hi) = crate::tp_xport::row_block(c, r, world);
                if hi == lo { continue; }
                let m = hi - lo;
                router_rows_launch(&l, pls + (lo * ne * 4) as u64, pw, px + (lo * h * 2) as u64, m, c, ne, h, rows_on)?;
                xqlaunch!(l, "xq_router_topk", (m as u32, 1, 1), (256, 1, 1), smem,
                         (pis + (lo * topk * 4) as u64, pws + (lo * topk * 4) as u64, pls + (lo * ne * 4) as u64,
                          ne as i32, topk as i32, m as i32))?;
            }
            dev.synchronize()?;
            let mut lr = vec![0f32; c * ne]; dev.dtoh_sync_copy_into(&d_lr.slice(0..c * ne), &mut lr)?;
            let mut ls = vec![0f32; c * ne]; dev.dtoh_sync_copy_into(&d_ls.slice(0..c * ne), &mut ls)?;
            let mut ir = vec![0i32; c * topk]; dev.dtoh_sync_copy_into(&d_ir.slice(0..c * topk), &mut ir)?;
            let mut is = vec![0i32; c * topk]; dev.dtoh_sync_copy_into(&d_is.slice(0..c * topk), &mut is)?;
            let mut wr = vec![0f32; c * topk]; dev.dtoh_sync_copy_into(&d_wr.slice(0..c * topk), &mut wr)?;
            let mut ws2 = vec![0f32; c * topk]; dev.dtoh_sync_copy_into(&d_ws2.slice(0..c * topk), &mut ws2)?;
            anyhow::ensure!(lr.iter().all(|v| v.is_finite()) && ir.iter().all(|&i| (0..ne as i32).contains(&i))
                            && wr.iter().all(|v| v.is_finite() && *v > 0.0),
                            "EXL3-SP-ROUTER c {c}: incomplete / implausible reference");
            let bits = |a: &[f32], b: &[f32]| a.iter().zip(b).filter(|(x, y)| x.to_bits() != y.to_bits()).count();
            let (dl, di, dw) = (bits(&lr, &ls), ir.iter().zip(&is).filter(|(x, y)| x != y).count(), bits(&wr, &ws2));
            if dl + di + dw > 0 {
                n_bad += 1;
                s_bad.push(c);
                if s_bad.len() <= 8 { println!("  router rows={} c {c:>5}: logits {dl} / ids {di} / weights {dw} DIFFER", rows_on as u8); }
            }
        }
        println!("EXL3-SP-ROUTER (x -> {ne} experts, top-{topk}, prefill.router_rows {}): {s_n} c values at world {world}; \
                  bitwise differ at {} (c {:?})", rows_on as u8, s_bad.len(), &s_bad[..s_bad.len().min(20)]);
    }
    let range = format!("c in {}..={}", cs.iter().min().copied().unwrap_or(0), cmax);
    if n_bad == 0 && n_unready == 0 {
        println!("EXL3-SP-PIN: PASS ({n_cases} (shape, c) cases, {range}, world {world}: every rank block through the served \
                  pinned-plan call is bit-identical to the replicated m = c call; incl. {n_router} router cases: logits / ids / \
                  weights of every block == the replicated router; {:.1} s)", t0.elapsed().as_secs_f64());
        Ok(())
    } else {
        anyhow::bail!("EXL3-SP-PIN FAIL ({n_bad} of {n_cases} cases differ, {n_unready} not ready; {range}, world {world})")
    }
}

/// One cuBLASLt algo's config attributes, printable (TP-I3 (a) rung-1 probe).
fn lt_algo_desc(algo: &ltsys::cublasLtMatmulAlgo_t) -> String {
    use ltsys::cublasLtMatmulAlgoConfigAttributes_t as A;
    let get = |a: A| -> String {
        let mut need: usize = 0;
        let r0 = unsafe { ltsys::cublasLtMatmulAlgoConfigGetAttribute(algo, a, std::ptr::null_mut(), 0, &mut need) };
        if r0 != ltsys::cublasStatus_t::CUBLAS_STATUS_SUCCESS || need == 0 || need > 8 { return "?".into(); }
        let mut v: u64 = 0;
        let mut w: usize = 0;
        let r = unsafe { ltsys::cublasLtMatmulAlgoConfigGetAttribute(algo, a, &mut v as *mut u64 as *mut _, need, &mut w) };
        if r != ltsys::cublasStatus_t::CUBLAS_STATUS_SUCCESS { return "?".into(); }
        format!("{v}")
    };
    format!("id {} tile {} splitK {} red {} swz {} custom {} stages {} inner {} cluster {}",
            get(A::CUBLASLT_ALGO_CONFIG_ID), get(A::CUBLASLT_ALGO_CONFIG_TILE_ID), get(A::CUBLASLT_ALGO_CONFIG_SPLITK_NUM),
            get(A::CUBLASLT_ALGO_CONFIG_REDUCTION_SCHEME), get(A::CUBLASLT_ALGO_CONFIG_CTA_SWIZZLING),
            get(A::CUBLASLT_ALGO_CONFIG_CUSTOM_OPTION), get(A::CUBLASLT_ALGO_CONFIG_STAGES_ID),
            get(A::CUBLASLT_ALGO_CONFIG_INNER_SHAPE_ID), get(A::CUBLASLT_ALGO_CONFIG_CLUSTER_SHAPE_ID))
}

/// TP-I3 (a) rung 1 (`--probe-exl3-ltrows`, synthetic, no pack): is `exl3_lt_matmul` (cuBLASLt, one
/// heuristic plan per (k, n, m)) PER-ROW bit-identical when a chunk's rows are split between two
/// ranks (sequence-parallel prefill)? For each prefill Lt shape that a row split would touch (the hc
/// down/up projections; the PLE key/value GEMMs as the extension) and each chunk size c, the served
/// reference is the heuristic plan at m = c over all rows. Two candidates run the halves
/// [0, c0) and [c0, c) (c0 = ceil(c/2)) at m = c0 / c - c0 on row-offset pointers:
///   (H) each half with ITS OWN heuristic plan (what a naive split would do);
///   (P) each half with the reference plan's algo PINNED (layouts for the half's m; validated with
///       cublasLtMatmulAlgoCheck).
/// Every output element of both halves is compared bitwise with the reference rows. Prints the
/// algo configs and harness-only times (µs per call, L2-warm).
pub fn probe_lt_rows(cs: &[usize], shapes_sel: &str) -> Result<()> {
    let dev = CudaDevice::new(0).context("CudaDevice::new(0)")?;
    let stream = fork_blocking_stream(&dev);
    let l = Launcher { dev: &dev, stream: &stream };
    let handle = lt_handle();
    let ws_len = 32usize * 1024 * 1024; // the PrefillScratch lt_ws (every served prefill Lt call)
    let d_ws = unsafe { dev.alloc::<u8>(ws_len) }?;
    let ws = *d_ws.device_ptr() as u64;
    let cmax = cs.iter().copied().max().unwrap_or(2048);
    // (name, k, n): served prefill Lt shapes (ta = true: plain f16 weight rows [n][k])
    let shapes: [(&str, usize, usize); 4] = [("hc down (rw -> lr)", 10240, 320), ("hc up (lr -> rw)", 320, 10240),
                                            ("PLE key16 (ext)", 2560, 10240), ("PLE val (ext)", 2560, 2560)];
    let mut st = 0x2545_F491u32;
    let mut rnd = move || { st ^= st << 13; st ^= st >> 17; st ^= st << 5; st };
    let mut f16v = |n: usize, sc: f32| -> Vec<u16> {
        (0..n).map(|_| f16::from_f32((((rnd() >> 9) as f32 / (1u32 << 23) as f32) * 2.0 - 1.0) * sc).to_bits()).collect()
    };
    let (mut bad_h, mut bad_p, mut n_cases, mut p_invalid, mut bad_r) = (0usize, 0usize, 0usize, 0usize, 0usize);
    // sweep mode (many c): print only the failing cases + a per-shape summary; no timing
    let sweep = cs.len() > 40;
    for &(name, k, n) in shapes.iter().filter(|s| shapes_sel == "all" || s.0.starts_with("hc")) {
        let d_a = dev.htod_sync_copy(&f16v(n * k, 0.05))?;
        let d_b = dev.htod_sync_copy(&f16v(cmax * k, 2.0))?;
        let mut d_ref = dev.alloc_zeros::<u16>(cmax * n)?;
        let mut d_r2 = dev.alloc_zeros::<u16>(cmax * n)?;
        let mut d_h = dev.alloc_zeros::<u16>(cmax * n)?;
        let mut d_p = dev.alloc_zeros::<u16>(cmax * n)?;
        let (pa, pb) = (*d_a.device_ptr() as u64, *d_b.device_ptr() as u64);
        println!("LTROWS {name}: k {k} n {n}");
        let (mut s_fail_p, mut s_fail_h, mut s_fail_r, mut s_n) = (Vec::<usize>::new(), 0usize, Vec::<usize>::new(), 0usize);
        for &c in cs {
            let c0 = c.div_ceil(2);
            let c1 = c - c0;
            if c0 == 0 || c1 == 0 { continue; }
            n_cases += 1;
            s_n += 1;
            let poison = |d: &mut CudaSlice<u16>| -> Result<()> { dev.htod_copy_into(vec![0x7E00u16; cmax * n], d)?; Ok(()) };
            poison(&mut d_ref)?; poison(&mut d_h)?; poison(&mut d_p)?; poison(&mut d_r2)?;
            let pref_ = *d_ref.device_ptr() as u64;
            let pr2 = *d_r2.device_ptr() as u64;
            let (ph, pp) = (*d_h.device_ptr() as u64, *d_p.device_ptr() as u64);
            // reference: the served call (heuristic plan at m = c, cached like exl3_lt_matmul), and (R)
            // the same call again (run-to-run determinism of the served plan itself)
            exl3_lt_matmul(&l, pa, pb, pref_, k, n, c, true, ws, ws_len)?;
            exl3_lt_matmul(&l, pa, pb, pr2, k, n, c, true, ws, ws_len)?;
            // (H) naive split: each half with its own heuristic plan
            exl3_lt_matmul(&l, pa, pb, ph, k, n, c0, true, ws, ws_len)?;
            exl3_lt_matmul(&l, pa, pb + (c0 * k * 2) as u64, ph + (c0 * n * 2) as u64, k, n, c1, true, ws, ws_len)?;
            // (P) pinned: the m = c plan's algo on the halves' layouts
            let ref_algo = lt_plans().lock().unwrap().get(&(k, n, c, 1u8)).map(|p| p.algo).context("ref plan missing")?;
            let mut p_ok = true;
            let mut p_desc = String::new();
            for (m_h, boff, coff) in [(c0, 0usize, 0usize), (c1, c0 * k * 2, c0 * n * 2)] {
                let mut plan = lt_plan_build(handle, k, n, m_h, true, ws_len).map_err(|s| anyhow::anyhow!(s))?;
                plan.algo = ref_algo;
                let mut chk = std::mem::MaybeUninit::<ltsys::cublasLtMatmulHeuristicResult_t>::zeroed();
                let rc = unsafe {
                    ltsys::cublasLtMatmulAlgoCheck(handle, plan.desc, plan.a_layout, plan.b_layout, plan.c_layout,
                                                   plan.c_layout, &plan.algo, chk.as_mut_ptr())
                };
                if rc != ltsys::cublasStatus_t::CUBLAS_STATUS_SUCCESS {
                    p_ok = false;
                    p_desc = format!("AlgoCheck(m={m_h}) = {rc:?}");
                    lt_plan_drop(plan);
                    break;
                }
                let wsz = unsafe { chk.assume_init() }.workspaceSize;
                if wsz > ws_len { p_ok = false; p_desc = format!("workspace {wsz} > {ws_len}"); lt_plan_drop(plan); break; }
                let (alpha, beta) = (1.0f32, 0.0f32);
                let r = unsafe {
                    lt::matmul(handle, plan.desc, &alpha as *const _ as *const _, &beta as *const _ as *const _,
                        pa as *const _, plan.a_layout, (pb + boff as u64) as *const _, plan.b_layout,
                        (pp + coff as u64) as *mut _, plan.c_layout, (pp + coff as u64) as *mut _, plan.c_layout,
                        &plan.algo, ws as *mut _, ws_len, stream.stream as usize as ltsys::cudaStream_t)
                };
                lt_plan_drop(plan);
                r.with_context(|| format!("pinned matmul m={m_h}"))?;
            }
            dev.synchronize()?;
            let (vr, vh, vp) = (dev.dtoh_sync_copy(&d_ref)?, dev.dtoh_sync_copy(&d_h)?, dev.dtoh_sync_copy(&d_p)?);
            let vr2 = dev.dtoh_sync_copy(&d_r2)?;
            let live = c * n;
            let poisoned = vr[..live].iter().filter(|&&b| b == 0x7E00).count();
            anyhow::ensure!(poisoned == 0, "LTROWS {name} c {c}: the reference left {poisoned} poisoned outputs");
            let nzr = vr[..live].iter().filter(|&&b| b & 0x7fff != 0).count();
            anyhow::ensure!(nzr > live / 2, "LTROWS {name} c {c}: implausible reference ({nzr} nonzero of {live})");
            let neq = |v: &[u16]| -> (usize, Option<usize>) {
                let mut k2 = (0usize, None);
                for i in 0..live { if v[i] != vr[i] { k2.0 += 1; k2.1.get_or_insert(i / n); } }
                k2
            };
            let (nh, fh) = neq(&vh);
            let (np, fp) = if p_ok { neq(&vp) } else { (usize::MAX, None) };
            let (nr, _) = neq(&vr2);
            if nh > 0 { bad_h += 1; s_fail_h += 1; }
            if nr > 0 { bad_r += 1; s_fail_r.push(c); }
            if !p_ok { p_invalid += 1; s_fail_p.push(c); } else if np > 0 { bad_p += 1; s_fail_p.push(c); }
            if sweep {
                if nr > 0 || !p_ok || np > 0 {
                    println!("  c {c:>5}: (P) pinned {} | (R) ref re-run {} | ref [{}]",
                             if !p_ok { format!("INVALID ({p_desc})") } else { format!("differ {np} (first row {fp:?})") },
                             if nr == 0 { "identical".to_string() } else { format!("DIFFER {nr}") }, lt_algo_desc(&ref_algo));
                }
                continue;
            }
            let (ah, bh) = {
                let map = lt_plans().lock().unwrap();
                (map.get(&(k, n, c0, 1u8)).map(|p| lt_algo_desc(&p.algo)).unwrap_or_default(),
                 map.get(&(k, n, c1, 1u8)).map(|p| lt_algo_desc(&p.algo)).unwrap_or_default())
            };
            // harness-only times (L2-warm, 20 reps): ref at m = c, pinned halves, heuristic halves
            let time = |f: &mut dyn FnMut() -> Result<()>| -> Result<f64> {
                f()?; dev.synchronize()?;
                let t = std::time::Instant::now();
                for _ in 0..20 { f()?; }
                dev.synchronize()?;
                Ok(t.elapsed().as_secs_f64() * 1e6 / 20.0)
            };
            let t_ref = time(&mut || exl3_lt_matmul(&l, pa, pb, pref_, k, n, c, true, ws, ws_len))?;
            let t_h0 = time(&mut || exl3_lt_matmul(&l, pa, pb, ph, k, n, c0, true, ws, ws_len))?;
            println!("  c {c:>5} = {c0} + {c1}: (H) own-heuristic halves {} | (P) pinned {} | (R) ref re-run {} | ref [{}] | half0 [{ah}] \
                      | half1 [{bh}] | us: ref {t_ref:.1} half0(H) {t_h0:.1}",
                     if nh == 0 { "BIT-IDENTICAL".to_string() } else { format!("DIFFER {nh} of {live} (first row {fh:?})") },
                     if !p_ok { format!("INVALID ({p_desc})") } else if np == 0 { "BIT-IDENTICAL".to_string() }
                     else { format!("DIFFER {np} of {live} (first row {fp:?})") },
                     if nr == 0 { "identical".to_string() } else { format!("DIFFER {nr}") },
                     lt_algo_desc(&ref_algo));
        }
        println!("LTROWS {name} summary: {s_n} c values; own-heuristic halves differ at {s_fail_h}; pinned halves differ/invalid at {} \
                  (largest {:?}); served plan non-deterministic at {} (c {:?})",
                 s_fail_p.len(), s_fail_p.iter().max(), s_fail_r.len(), &s_fail_r[..s_fail_r.len().min(20)]);
    }
    println!("LTROWS RESULT: {n_cases} (shape, c) cases; own-heuristic halves differ in {bad_h}; pinned-plan halves differ in {bad_p} \
              ({p_invalid} pinned plans invalid); served plan re-run differs in {bad_r} -> {}",
             if bad_p == 0 && p_invalid == 0 && bad_r == 0 { "PINNED_ROW_IDENTITY_OK" } else { "PINNED_ROW_IDENTITY_FAIL" });
    Ok(())
}

/// Decode ONE trellis matrix into `ws` as plain W_dec row-major [K, N] f16 —
/// the same values the fused mma consumes. `tr` may be a Quad base (u64) or an
/// expert slice offset (same in-tree u64-pointer launch convention as
/// exl3_hmma_gemm_wide's MoE calls).
fn exl3_reconstruct(l: &Launcher, tr: u64, rc: u64,
                    ws: u64, k: i32, n: i32, bits: i32) -> Result<()> {
    let kb = (k as u32) / 16;
    let nb = (n as u32) / 16;
    if nb % 8 == 0 && bits <= 8 && crate::opts::var(crate::opt!("exl3-dump8")).map_or(true, |v| v != "0") {
        // S-A3-u G: coalesced strip reconstruct — same bytes (gated in --probe-exl3-kernel).
        return xqlaunch!(l, "exl3_decode_dump8", (kb * nb / 8, 1, 1), (256, 1, 1), 0,
                         (tr, rc, ws, nb as i32, bits));
    }
    xqlaunch!(l, "exl3_decode_dump", (kb * nb, 1, 1), (32, 1, 1), 0,
             (tr, rc, ws, nb as i32, bits))
}

/// S-A3-n F3: dynamic smem for the A-once GEMM body (`exl3_gemm_body_a1`, taken by
/// the grouped expert kernels when it fits). Must mirror `exl3_a1_fits` in
/// kernels/exl3_bench.cu; 0 = the kernel keeps the barrier body.
fn a1_smem(m: usize, k: usize) -> u32 {
    let bytes = m * (k + 8) * 2;
    if m >= 1 && m <= 16 && k % 8 == 0 && bytes <= 48 * 1024 { bytes as u32 } else { 0 }
}

/// S-A3-o G1: GDN commit mode — 1 = rank-1 ring commit (default), 0 = the replay
/// (--exl3-gdn-ring=0, A/B), 2 = replay + ring-on-a-copy bitwise diff every layer
/// (--exl3-gdn-ring-check=1; eager only — forces the verify graph off).
fn gdn_ring_mode() -> u8 {
    static M: std::sync::OnceLock<u8> = std::sync::OnceLock::new();
    *M.get_or_init(|| {
        if crate::opts::var(crate::opt!("exl3-gdn-ring-check")).is_ok() { 2 }
        else if crate::opts::var(crate::opt!("exl3-gdn-ring")).as_deref() == Ok("0") { 0 }
        else { 1 }
    })
}

/// WP12: the commit mode verify_commit ACTUALLY runs (the ring commit is specialised to
/// kd = 128 and C <= GDN_RING_CMAX = 8 since WP23). ONE predicate for both sides: verify_kernels
/// skips the replay-only saves (a_save/b_save/qkv_post) exactly when this says the replay never runs.
/// WP23: a depth ceiling past the ring's extent no longer drops to the replay SILENTLY (the last
/// depth-7 test lost the ring commit that way): it says so, once.
fn gdn_commit_mode(kd: usize, vd: usize) -> u8 {
    if kd == 128 && vd % 32 == 0 && MTP_MAX_K + 1 <= GDN_RING_CMAX { return gdn_ring_mode(); }
    if kd == 128 && vd % 32 == 0 {
        static WARN: std::sync::Once = std::sync::Once::new();
        WARN.call_once(|| eprintln!("[exl3] WARNING: MTP_MAX_K+1 = {} > {GDN_RING_CMAX} (xq_gdn_commit_ring extent) — \
                                     GDN commit falls back to the REPLAY (slower rounds)", MTP_MAX_K + 1));
    }
    0
}

/// WP12 parts (all bitwise, all default ON). --wp12-off=1|all restores every old path;
/// or a comma list of parts: step (register-resident GDN verify chunk + decode step ->
/// the old xq_gdn_step_chunk / xq_gdn_step), diet (the dead replay saves when the ring
/// commit runs), conv (nostore verify conv on the live ring -> the shadow copy + chunk),
/// ab (one a|b GEMV launch -> two). Diagnostic A/B + bisect only (AGENTS §1b).
const WP12_STEP: u8 = 1;
const WP12_DIET: u8 = 2;
const WP12_CONV: u8 = 4;
const WP12_AB: u8 = 8;
fn wp12_on(part: u8) -> bool {
    let t = match part {
        WP12_STEP => &T_WP12_STEP,
        WP12_DIET => &T_WP12_DIET,
        WP12_CONV => &T_WP12_CONV,
        WP12_AB => &T_WP12_AB,
        _ => return false,
    };
    tune::get_cur(t) != 0
}
/// The --wp12-off part mask (None = unset), parsed and reported once — the legacy alias of the
/// four wp12.* registry entries (same parse, same WP12 lines as before).
fn wp12_env_mask() -> Option<u8> {
    static M: std::sync::OnceLock<Option<u8>> = std::sync::OnceLock::new();
    *M.get_or_init(|| {
        let v = crate::opts::var(crate::opt!("wp12-off")).ok()?;
        let m = wp12_mask_of(&v);
        println!("WP12: parts on = {m:#x} (step 1, diet 2, conv 4, ab 8; --wp12-off={v})");
        Some(m)
    })
}
/// The --wp12-off value -> parts-on mask (the pre-registry parse, verbatim).
pub(crate) fn wp12_mask_of(v: &str) -> u8 {
    let mut m = WP12_STEP | WP12_DIET | WP12_CONV | WP12_AB;
    for p in v.split(',') {
        match p.trim() {
            "1" | "all" => m = 0,
            "step" => m &= !WP12_STEP,
            "diet" => m &= !WP12_DIET,
            "conv" => m &= !WP12_CONV,
            "ab" => m &= !WP12_AB,
            "" | "0" => {}
            other => println!("WP12: unknown --wp12-off part '{other}' ignored"),
        }
    }
    m
}
