/// S-A3-o O3: the grouped expert entry. The A-once 3-bit body runs in its own kernel
/// (`xq_gemm_grouped_a1b3`, 3 CTAs/SM) — bitwise identical to xq_gemm_grouped_xh, which
/// keeps every other (m, K, bits). --exl3-a1b3=0 = A/B diagnostic (old entry).
fn grouped_fn(m: usize, k: usize, bits: usize) -> &'static str {
    let off = tune::get_cur(&T_MOE_A1B3) == 0;
    if !off && bits == 3 && a1_smem(m, k) > 0 { "xq_gemm_grouped_a1b3" } else { "xq_gemm_grouped_xh" }
}

/// A5 WP20 (PLAN/SURPASS_PLAN_2026-09-26.md): 0 = off (--wp20-off=1 — the pre-WP20 expert
/// path, bit for bit, kernels untouched), 1 = rung 1 only (--wp20-epi=0: the word-diet body
/// `xq_gemm_grouped_a1b3_wd` in the old launch sequence), 2 = rungs 1 + 2 (default: the
/// epilogue kernels xq_moe_gu_epi / xq_moe_dn_epi_k<topk>). A mode-2 call that rung 2 cannot
/// take (logged, see FwdModel::wp20_select) still gets rung 1 wherever the a1b3 entry runs.
/// Diagnostics only — every mode is bitwise.
fn wp20_mode() -> u8 {
    tune::get_cur(&T_WP20_MODE).clamp(0, 2) as u8
}
// TUNE T0 (p3c): WP20's rungs (every mode bitwise: --probe-exl3-binv EXL3-MOE-EPI + MOE_EPI_CHECK).
pub(crate) const T_WP20_MODE: tune::TunableDef = tune::TunableDef {
    slot: 38, id: "wp20.mode", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    domain: &[0, 1, 2], default: 2, valid: tune::valid_any,
    xcheck: "--probe-exl3-binv EXL3-MOE-EPI + --exl3-moe-epi-check",
    env: "--wp20-off|--wp20-epi",
    // the old precedence exactly: OFF=1 -> 0, else EPI=0 -> 1, else 2 (None when neither is set)
    env_parse: || {
        let (off, epi) = (tune::env_str(crate::opt!("wp20-off")), tune::env_str(crate::opt!("wp20-epi")));
        if off.is_none() && epi.is_none() { return None; }
        Some(if off.as_deref() == Some("1") { 0 } else if epi.as_deref() == Some("0") { 1 } else { 2 })
    },
    rev: 1, wp: "WP20",
};
pub(crate) const T_WP20_DIET: tune::TunableDef = tune::TunableDef {
    slot: 39, id: "wp20.diet", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    domain: &[0, 1], default: 1, valid: tune::valid_any,
    xcheck: "--probe-exl3-binv EXL3-MOE-EPI (word diet vs SHFL)",
    env: "--wp20-diet", env_parse: || tune::env_on_unless_0(crate::opt!("wp20-diet")), rev: 1, wp: "WP20",
};

/// --wp20-diet=0: rung 2's epilogue kernels on the old SHFL decode (isolates rung 2's A/B);
/// also keeps rung 1 off (no diet anywhere).
fn wp20_diet_on() -> bool {
    tune::get_cur(&T_WP20_DIET) != 0
}

/// --exl3-moe-epi-check=1: the eager bitwise old-vs-WP20 diff (see moe_wp20_xcheck).
fn wp20_check_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| crate::opts::var(crate::opt!("exl3-moe-epi-check")).is_ok())
}

/// WP20-v1b: the top-k values the down epilogue is compiled for (kernels/exl3_bench.cu
/// WP20_DN_ENTRY: the combine's j loops are a compile-time TOPK template — AGENTS §4). Any
/// other top-k keeps the pre-WP20 launch sequence, with a loud WP20 FALLBACK line.
const WP20_TOPKS: [usize; 2] = [8, 10];

/// The down-epilogue entry for (top-k, decode body), None = no compiled instance.
pub(crate) fn wp20_dn_fn(topk: usize, diet: bool) -> Option<&'static str> {
    match (topk, diet) {
        (8, true) => Some("xq_moe_dn_epi_k8"),
        (8, false) => Some("xq_moe_dn_epi_sh_k8"),
        (10, true) => Some("xq_moe_dn_epi_k10"),
        (10, false) => Some("xq_moe_dn_epi_sh_k10"),
        _ => None,
    }
}

/// The gate/up epilogue entry (top-k independent) for the decode body.
pub(crate) fn wp20_gu_fn(diet: bool) -> &'static str {
    if diet { "xq_moe_gu_epi" } else { "xq_moe_gu_epi_sh" }
}

/// A rung-2 selection for one MoE call (FwdModel::wp20_select -> moe_wp20): the boot-verified
/// suh sequence id (logged only — WP20-v1c pins the sequence in the kernels) and the exact
/// entries to launch (the down one compiled for `topk`).
#[derive(Clone, Copy)]
struct Wp20Sel {
    conv: u32,
    gu: &'static str,
    dn: &'static str,
    topk: usize,
}

/// WP20 path decisions are logged ONCE per distinct key (class, m, detail): the MoE block runs
/// per layer per step (and every draft pass), so every active path and every fallback reason
/// shows up exactly once per width — never silently, never per call. Classes: 0 mode line,
/// 1 rung 2 active, 2 rung 2 fallback (detail = reason code), 3 rung 1 active (detail = K),
/// 4 rung 1 fallback (detail = K), 5 rung 1 pre-empted (coop / fh), 6 xcheck.
fn wp20_log_once(key: (u8, usize, usize), msg: impl FnOnce() -> String) {
    static SEEN: std::sync::Mutex<Vec<(u8, usize, usize)>> = std::sync::Mutex::new(Vec::new());
    let first = match SEEN.lock() {
        Ok(mut v) => if v.contains(&key) { false } else { v.push(key); true },
        Err(_) => true,
    };
    if first { println!("{}", msg()); }
}

/// Rung 1 in the old launch sequence: the diet twin behind the a1b3 entry's exact contract
/// when `rung1` (mode 1, or a mode-2 call rung 2 did not take; never the xcheck reference).
/// Logs which body each (m, K) actually runs, and why not when the twin cannot apply.
fn wp20_grouped(name: &'static str, rung1: bool, m: usize, k: usize) -> &'static str {
    if !rung1 { return name; }
    if name == "xq_gemm_grouped_a1b3" {
        wp20_log_once((3, m, k), || format!(
            "WP20 rung 1 ACTIVE m={m} K={k}: xq_gemm_grouped_a1b3_wd (word diet: 2 ring words/lane/k16 step, no SHFL) \
             in the pre-WP20 launch sequence"));
        "xq_gemm_grouped_a1b3_wd"
    } else {
        wp20_log_once((4, m, k), || format!(
            "WP20 FALLBACK rung 1 m={m} K={k}: {name} runs (the diet twin needs the a1b3 entry: 3-bit, \
             m*(K+8)*2 = {} B <= 48 KiB, --exl3-a1b3 != 0) — old SHFL decode for this GEMM", m * (k + 8) * 2));
        name
    }
}

/// The process-wide suh verification (see crate::exl3_bench::wp20_calibrate): the epilogue's
/// pinned suh sequence (WP20-v1c) checked bitwise against the JIT'd xq_had_suh_multi ONCE,
/// eagerly at FwdModel::load (mode 2, MoE model) or at the first non-capturing eligible call;
/// Some(seq id) = verified, None = mismatch / launch error (rung 2 then stays off, loudly).
static WP20_CONV: std::sync::OnceLock<Option<u32>> = std::sync::OnceLock::new();

fn wp20_calibrated(dev: &Arc<CudaDevice>) -> Option<u32> {
    *WP20_CONV.get_or_init(|| match crate::exl3_bench::wp20_calibrate(dev) {
        Ok(Some(c)) => {
            println!("WP20: suh sequence 0x{c:02x} VERIFIED (the epilogue's pinned FMUL/FFMA suh stage == the JIT'd \
                      xq_had_suh_multi, bitwise on realistic + f16 edge-case rows)");
            Some(c)
        }
        Ok(None) => {
            println!("WP20 FALLBACK: suh verification FAILED (the pinned sequence != the JIT'd xq_had_suh_multi) — \
                      MoE epilogues (rung 2) OFF for this process");
            None
        }
        Err(e) => {
            println!("WP20 FALLBACK: suh verification failed ({e:#}) — MoE epilogues (rung 2) OFF for this process");
            None
        }
    })
}

/// FwdModel::load: announce the WP20 plan for this model (mode, top-k instance, decode body) and
/// verify the pinned suh sequence eagerly, so the first graph capture can never be the first
/// eligible call.
fn wp20_announce(dev: &Arc<CudaDevice>, cfg: &crate::qwen::Config) {
    if cfg.num_experts == 0 { return; }
    let topk = cfg.num_experts_per_tok;
    let diet = wp20_diet_on();
    match wp20_mode() {
        0 => println!("WP20: OFF (--wp20-off=1) — pre-WP20 expert path (SHFL decode, 5 glue launches per MoE layer)"),
        1 => println!("WP20: mode 1 (--wp20-epi=0) — rung 1 only (word-diet twin {}), no MoE epilogues",
                      if diet { "on" } else { "OFF: --wp20-diet=0" }),
        _ => {
            match wp20_dn_fn(topk, diet) {
                Some(dn) => {
                    let (gu, have_gu, have_dn) = (wp20_gu_fn(diet), xq_raw_fn(wp20_gu_fn(diet)).is_some(), xq_raw_fn(dn).is_some());
                    println!("WP20: mode 2 — rungs 1+2 planned for top-k {topk}: {gu} + {dn} (decode body {}){}",
                             if diet { "diet" } else { "SHFL: --wp20-diet=0" },
                             if have_gu && have_dn { String::new() }
                             else { format!(" — KERNEL MISSING (gu {have_gu}, dn {have_dn}; stale PTX?) -> rung 2 will fall back") });
                    let _ = wp20_calibrated(dev);
                }
                None => println!("WP20 FALLBACK: mode 2 requested but top-k {topk} has no down-epilogue instance \
                                  (compiled: {WP20_TOPKS:?}) — rung 2 OFF for this model; rung 1 still applies"),
            }
        }
    }
}

// (WP20's free `stream_capturing(CUstream)` duplicated WP11's `stream_capturing(&Launcher)`:
// p2 keeps WP11's; the WP20 call sites pass the launcher.)

/// A5 WP20: raw launch of a 256-thread MoE epilogue kernel (> 12 params: past the typed
/// launcher's cap), with the PDL twin under --exl3-pdl=1 exactly as xqlaunch! does.
unsafe fn wp20_launch(stream: cudarc::driver::sys::CUstream, name: &str, grid: u32, smem: u32,
                      params: &mut [*mut std::ffi::c_void]) -> Result<()> {
    use cudarc::driver::sys;
    if pdl_on() {
        if let Some(f) = xq_raw_fn_smem(name, smem) {
            return launch_pss_raw(stream, f, (grid, 1, 1), (256, 1, 1), smem, params)
                .with_context(|| format!("launch {name} (pdl)"));
        }
    }
    let f = xq_raw_fn(name).ok_or_else(|| anyhow::anyhow!("{name} raw fn unavailable (stale PTX?)"))?;
    let r = sys::cuLaunchKernel(f, grid, 1, 1, 256, 1, 1, smem, stream, params.as_mut_ptr(), std::ptr::null_mut());
    anyhow::ensure!(r == sys::CUresult::CUDA_SUCCESS, "launch {name} ({r:?})");
    Ok(())
}

// ---- W4/MOE (decode wave 4): persistent grouped-expert kernels (kernels/exl3_bench.cu "W4/MOE") ----
// The LMH byte schedule (persistent grid, cp.async ring + evict_first, A staged per expert run)
// under the WP20 rung-2 epilogues, and the gate/up input transform folded in. Every knob is a
// schedule knob of a bitwise package (the kernel contract).
// p5e DEFAULT = OFF (the p3 WP20 rung-2 launches: xq_had_suh_multi + xq_moe_gu_epi +
// xq_moe_dn_epi_k<topk>). Bitwise, but SLOWER IN-ROUND (p5c on .13, 2026-09-27 03:17-05:02 UTC,
// hashes exact, every XCHECK zero): +2.4..+4.5 ms/round on every class; nsys per call
// xq_moe_gu_pk_s8 361.7 vs xq_moe_gu_epi 295.2 us, xq_moe_dn_pk 182.0 vs 150.6 us.
//   (unset)                     OFF (default): the WP20 rung-2 launches exactly, as in p3
//   --w4moe=1                opt in (any value but ""/0/off): every part (gu, dn, fold)
//   --w4moe-off=1|all        escape, unchanged; wins over --w4moe=1
//   --w4moe-off=<parts>      with --w4moe=1: comma list gu (gate/up keeps xq_moe_gu_epi),
//                               dn (down keeps xq_moe_dn_epi_k<topk>), fold (persistent gate/up
//                               reads xh_e from xq_had_suh_multi instead of forming A in-kernel)
//   --w4moe-order=il         interleaved item order (the LMH order, A per item); default
//                               contiguous item ranges (A per expert run)
//   --w4moe-nst=4|8          ring depth (default: the occupancy rule in mpk_plan)
//   --w4moe-g=<n>            persistent grid for both kernels (clamped to [1, items cap])
//   --w4moe-minm=<m>         persistent kernels only at widths >= m (default 1)
//   --w4moe-shovl=1          lever (c), opt-in: shared expert on a WP27 sibling branch
// The ORDER / NST / G / MINM / SHOVL knobs act only while the package is ON (the OFF boot line
// lists any that are set as ignored).
// XCHECK: --exl3-moe-epi-check=1 (eager) diffs this path against the pre-WP20 chain (ygu/xhd/
// yd/moe_out bitwise + counters re-armed). Probe: --probe-exl3-binv EXL3-MOE-EPI (W4/MOE rows).
pub(crate) const MPK_GU: u8 = 1;
pub(crate) const MPK_DN: u8 = 2;
pub(crate) const MPK_FOLD: u8 = 4;
/// Kernel flag bits (mirror MPK_IL / MPK_FOLD in kernels/exl3_bench.cu).
pub(crate) const MPK_FLAG_IL: i32 = 1;
pub(crate) const MPK_FLAG_FOLD: i32 = 2;
/// Mirror of MPK_STB (ring slot bytes) / MPK_EMAX (live-expert table cap) in exl3_bench.cu.
const MPK_STB: usize = 4 * 768;
pub(crate) const MPK_EMAX: usize = 256;
/// Mirror of MPK_RTMAX: the down kernel's combine tables hold m * topk entries.
const MPK_RTMAX: usize = 256;

/// --w4moe opt-in (p5e: the package is DEFAULT OFF): set to anything but "", "0" or "off".
fn w4moe_opt_in() -> bool {
    crate::opts::var(crate::opt!("w4moe")).is_ok_and(|v| !matches!(v.trim(), "" | "0" | "off" | "OFF"))
}
/// Live W4/MOE parts (MPK_GU | MPK_DN | MPK_FOLD). p5e: 0 (the WP20 rung-2 kernels) unless
/// --w4moe=1; then --w4moe-off (1|all|<parts>) applied on top, as before.
/// TUNE T0c (p5e): the parts mask is the registry entry w4moe.parts (per width; every mask bitwise),
/// so a full tune re-evaluates the package in-round per (family, m); the aliases decide exactly as
/// before whenever one is set (w4moe_parts_env).
pub(crate) fn w4moe_parts() -> u8 {
    let p = tune::get_cur(&T_W4MOE_PARTS).clamp(0, 7) as u8;
    if p & MPK_GU == 0 { p & !MPK_FOLD } else { p }
}
/// The aliases' parts mask (the pre-registry parse, verbatim; its warnings once); None when
/// neither --w4moe nor --w4moe-off is set.
fn w4moe_parts_env() -> Option<u8> {
    static V: std::sync::OnceLock<Option<u8>> = std::sync::OnceLock::new();
    *V.get_or_init(|| {
        let (opt, off) = (crate::opts::var(crate::opt!("w4moe")).ok(), crate::opts::var(crate::opt!("w4moe-off")).ok());
        if opt.is_none() && off.is_none() { return None; }
        Some(w4moe_parts_of(opt.as_deref(), off.as_deref()))
    })
}
/// The --w4moe / --w4moe-off values -> the live parts mask (the pre-registry w4moe_parts
/// body, verbatim: w4moe_opt_in's test, then the escape's parts on top, fold only with gu).
pub(crate) fn w4moe_parts_of(opt_in: Option<&str>, off: Option<&str>) -> u8 {
    let mut p = if opt_in.is_some_and(|v| !matches!(v.trim(), "" | "0" | "off" | "OFF")) {
        MPK_GU | MPK_DN | MPK_FOLD
    } else { 0 };
    if let Some(v) = off {
        for t in v.split(',').map(|t| t.trim().to_ascii_lowercase()) {
            match t.as_str() {
                "1" | "all" => p = 0,
                "gu" => p &= !MPK_GU,
                "dn" => p &= !MPK_DN,
                "fold" => p &= !MPK_FOLD,
                "" | "0" => {}
                other => println!("W4/MOE: unknown --w4moe-off part '{other}' ignored"),
            }
        }
    }
    if p & MPK_GU == 0 { p &= !MPK_FOLD; }
    p
}
/// W4/MOE lever (c): --w4moe-shovl=1 = the shared expert on a WP27 sibling branch of the routed
/// gate/up path in captured graphs (opt-in; see moe_wp20).
/// --w4moe-minm=<m>: the persistent kernels only at widths >= m (narrower widths — e.g. the
/// m = 1 draft pass — keep the WP20 rung-2 kernels). Default 1 (every width). A/B + bisect knob
/// (TUNE: env-only — the per-width w4moe.parts subsumes it).
fn w4moe_minm() -> usize {
    static V: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *V.get_or_init(|| crate::opts::var(crate::opt!("w4moe-minm")).ok().and_then(|v| v.trim().parse::<usize>().ok()).unwrap_or(1).max(1))
}
fn w4moe_shovl() -> bool {
    tune::get_cur(&T_W4MOE_SHOVL) != 0
}
/// A5-K1 (w6/SHOVL): the shared expert on a WP27 sibling branch of the routed path on the DEFAULT
/// WP20 rung-2 MoE path (xq_router_fold[_w4] -> xq_had_suh_multi -> xq_moe_gu_epi ‖ shared expert,
/// joined before xq_moe_dn_epi_k<topk>) — the W4/MOE (c) placement without the persistent package.
/// Registry entry moe.shovl (S class, per width); alias --moe-shovl=0 = escape (linear MoE window,
/// the pre-K1 graphs exactly), any other value = on. DEFAULT ON since the A5-K1 in-round A/B on .14
/// (6 boots interleaved, 12/12 pairs faster: -0.87..-1.23 ms/round per class, trajectories and
/// served hashes identical) — PLAN/notes_2026-09-27/K1_SHOVL.md.
fn moe_shovl() -> bool {
    tune::get_cur(&T_MOE_SHOVL) != 0
}
fn w4moe_order_il() -> bool {
    tune::get_cur(&T_W4MOE_ORDER) != 0
}
/// The ring-depth pin (None = mpk_plan's occupancy rule): w4moe.nst 4 | 8, 0 = the rule.
fn w4moe_nst_env() -> Option<usize> {
    match tune::get_cur(&T_W4MOE_NST) { 4 => Some(4), 8 => Some(8), _ => None }
}
/// The persistent grid pin (None = the rule): w4moe.g > 0.
fn w4moe_g_env() -> Option<u32> {
    let g = tune::get_cur(&T_W4MOE_G);
    (g > 0).then_some(g as u32)
}
// TUNE T0c (p5e): the W4/MOE registry entries (class S, per width; every value bitwise by the kernel
// contract). --w4moe-minm stays an env-only diagnostic.
const W4MOE_XCHECK: &str = "--probe-exl3-binv EXL3-MOE-EPI (W4/MOE rows) + --exl3-moe-epi-check";
pub(crate) const T_W4MOE_PARTS: tune::TunableDef = tune::TunableDef {
    slot: 72, id: "w4moe.parts", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    // MPK_GU 1 | MPK_DN 2 | MPK_FOLD 4 (fold needs gu): every reachable mask
    domain: &[0, 1, 2, 3, 5, 7], default: 0, valid: tune::valid_any, xcheck: W4MOE_XCHECK,
    env: "--w4moe|--w4moe-off", env_parse: || w4moe_parts_env().map(|p| p as i32), rev: 1, wp: "W4/MOE",
};
pub(crate) const T_W4MOE_ORDER: tune::TunableDef = tune::TunableDef {
    slot: 73, id: "w4moe.order", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    domain: &[0, 1], default: 0, valid: tune::valid_any, xcheck: W4MOE_XCHECK,
    env: "--w4moe-order",
    env_parse: || tune::env_str(crate::opt!("w4moe-order")).map(|v| matches!(v.as_str(), "il" | "IL" | "1") as i32),
    rev: 1, wp: "W4/MOE",
};
pub(crate) const T_W4MOE_NST: tune::TunableDef = tune::TunableDef {
    slot: 74, id: "w4moe.nst", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    domain: &[0, 4, 8], default: 0, valid: tune::valid_any, xcheck: W4MOE_XCHECK,
    env: "--w4moe-nst",
    env_parse: || tune::env_str(crate::opt!("w4moe-nst")).map(|v| match v.as_str() { "4" => 4, "8" => 8, _ => 0 }),
    rev: 1, wp: "W4/MOE",
};
pub(crate) const T_W4MOE_G: tune::TunableDef = tune::TunableDef {
    slot: 75, id: "w4moe.g", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    domain: &[0, 48, 96, 144, 192], default: 0, valid: tune::valid_any, xcheck: W4MOE_XCHECK,
    env: "--w4moe-g",
    env_parse: || tune::env_str(crate::opt!("w4moe-g")).map(|v| v.trim().parse::<u32>().ok().filter(|&g| g > 0)
        .map_or(0, |g| g.min(i32::MAX as u32) as i32)),
    rev: 1, wp: "W4/MOE",
};
pub(crate) const T_W4MOE_SHOVL: tune::TunableDef = tune::TunableDef {
    slot: 76, id: "w4moe.shovl", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    domain: &[0, 1], default: 0, valid: tune::valid_any, xcheck: W4MOE_XCHECK,
    env: "--w4moe-shovl", env_parse: || tune::env_on_if_1(crate::opt!("w4moe-shovl")), rev: 1, wp: "W4/MOE",
};
/// A5-K1: shared-expert overlap on the default WP20 rung-2 path (see moe_shovl). Same kernels, same
/// inputs, same launch shapes; only the captured dependency edges differ (bitwise class S).
pub(crate) const T_MOE_SHOVL: tune::TunableDef = tune::TunableDef {
    slot: 85, id: "moe.shovl", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    domain: &[0, 1], default: 1, valid: tune::valid_any,
    xcheck: "WP27 capture-DAG audit (shared expert reads sc.x only; private last-arrival counters) + --probe-exl3-binv",
    env: "--moe-shovl", env_parse: || tune::env_on_unless_0(crate::opt!("moe-shovl")), rev: 1, wp: "A5-K1",
};

/// A5-K7 (ledger #1(a)): xq_had_suh_multi folded into the DEFAULT WP20 rung-2 gate/up prologue —
/// xq_moe_gu_epi_f forms A = f16(H128(x * suh_e)) in-kernel (the pinned, boot-verified sequence;
/// same bytes as xq_had_suh_multi -> xq_moe_gu_epi) and the separate launch goes. Diet body only
/// (--wp20-diet=0 keeps the unfolded pair); inert under a W4/MOE persistent gate/up. Class S
/// (bitwise; --probe-exl3-binv EXL3-MOE-EPI "fold" rows + --exl3-moe-epi-check=1 eager xcheck).
/// VALUE = the widest MoE call that folds: at width m the fold runs iff m <= value (0 = off). v1
/// (fold at every width) measured the fold's cost growing with m (each of an expert's 10 CTAs forms
/// all m x 20 transforms) against a ~constant saved launch: fitted verify delta -1.12 + 0.167 m
/// ms/verify, crossover m ~ 6.7 — so v2's candidate is 6 (draft m = 1 and the narrow verifies fold,
/// m = 7..8 keep the separate launch). Alias --moe-gu-fold=<max width> (0..16; any width-scoped
/// table value works the same way per width). Default 0 (OFF) until integrated
/// (PLAN/notes_2026-09-27/K7.md).
pub(crate) const T_MOE_GU_FOLD: tune::TunableDef = tune::TunableDef {
    slot: 90, id: "moe.gu_fold", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_DECODE,
    domain: &[0, 1, 4, 5, 6, 7, 9], default: 6, valid: tune::valid_any,
    xcheck: "--probe-exl3-binv EXL3-MOE-EPI (fold rows) + --exl3-moe-epi-check=1 (eager)",
    env: "--moe-gu-fold", env_parse: || tune::env_str(crate::opt!("moe-gu-fold"))
        .map(|v| v.trim().parse::<i32>().unwrap_or(0).clamp(0, 16)), rev: 1, wp: "A5-K7",
};
/// A5-K7: does the WP20 gate/up at width m fold xq_had_suh_multi (moe.gu_fold = max folded width)?
fn moe_gu_fold(l: &Launcher, m: usize) -> bool {
    let v = tune::get(&T_MOE_GU_FOLD, &l.cx());
    v > 0 && m <= v as usize
}
/// The folded gate/up entry (A5-K7).
pub(crate) const WP20_GU_FOLD_FN: &str = "xq_moe_gu_epi_f";

/// Mirror of mpk_smem_bytes() in kernels/exl3_bench.cu (the kernel traps if launched short).
pub(crate) fn mpk_smem_bytes(nst: usize, m: usize, k: usize, gu: bool, fold: bool) -> usize {
    let epi = if gu { (m * 256).max(4096) } else { m * 256 };
    nst * MPK_STB + m * (k + 8) * 2 + if gu && fold { k * 2 } else { 0 } + epi
}

/// Entry name for (side, top-k, ring depth); None = not compiled.
pub(crate) fn mpk_entry(gu: bool, topk: usize, nst: usize) -> Option<&'static str> {
    Some(match (gu, topk, nst) {
        (true, _, 4) => "xq_moe_gu_pk_s4",
        (true, _, 8) => "xq_moe_gu_pk_s8",
        (false, 8, 4) => "xq_moe_dn_pk_k8_s4",
        (false, 8, 8) => "xq_moe_dn_pk_k8_s8",
        (false, 10, 4) => "xq_moe_dn_pk_k10_s4",
        (false, 10, 8) => "xq_moe_dn_pk_k10_s8",
        _ => return None,
    })
}

/// Raw handle of one W4/MOE entry opted in to `smem` dynamic bytes, with its co-resident CTAs
/// per SM at that smem (occupancy API, 256 threads). Cached per (entry, smem); None = unusable
/// (stale PTX, over the opt-in cap, or zero occupancy) — the caller keeps the WP20 kernel.
pub(crate) fn mpk_fn(name: &'static str, smem: u32) -> Option<(cudarc::driver::sys::CUfunction, u32)> {
    use cudarc::driver::sys;
    #[derive(Clone, Copy)]
    struct FnH(sys::CUfunction);
    unsafe impl Send for FnH {}
    unsafe impl Sync for FnH {}
    static C: std::sync::Mutex<Vec<(&'static str, u32, FnH, u32, u32)>> = std::sync::Mutex::new(Vec::new());
    let mut c = C.lock().ok()?;
    if let Some(e) = c.iter().find(|e| e.0 == name && e.1 == smem) { return Some((e.2 .0, e.3)); }
    let f = xq_raw_fn(name)?;
    if smem as usize > crate::gpu::SMEM_OPTIN_CAP as usize { return None; }
    // the opt-in only ever grows (a later smaller request must not lower it below a cached one)
    let optin = c.iter().filter(|e| e.0 == name).map(|e| e.4).max().unwrap_or(0).max(smem);
    let r = unsafe { sys::cuFuncSetAttribute(f,
        sys::CUfunction_attribute::CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, optin as i32) };
    if r != sys::CUresult::CUDA_SUCCESS { eprintln!("[w4moe] {name}: smem opt-in {optin} B failed ({r:?})"); return None; }
    let mut nb: i32 = 0;
    let r = unsafe { sys::cuOccupancyMaxActiveBlocksPerMultiprocessor(&mut nb, f, 256, smem as usize) };
    if r != sys::CUresult::CUDA_SUCCESS || nb < 1 {
        eprintln!("[w4moe] {name}: not resident at {smem} B smem (occupancy {nb}, {r:?})");
        return None;
    }
    for e in c.iter_mut().filter(|e| e.0 == name) { e.4 = optin; }
    c.push((name, smem, FnH(f), nb as u32, optin));
    Some((f, nb as u32))
}

/// One W4/MOE launch plan: entry, grid, dynamic smem, CTAs/SM, ring depth.
#[derive(Clone, Copy, Debug)]
pub(crate) struct MpkPlan {
    pub name: &'static str,
    pub grid: u32,
    pub smem: u32,
    pub cps: u32,
    pub nst: usize,
}

/// Plan one side (gate/up or down) at width m: items cap = min(emax, m*topk) * N/128 (the live
/// expert count is device-side; m*topk bounds it). Rule: the ring depth giving the most
/// co-resident CTAs (occupancy x SMs, capped at the items cap), ties -> the deeper ring; env
/// --w4moe-nst / --w4moe-g override. None = not launchable (the caller keeps WP20).
pub(crate) fn mpk_plan(dev: &Arc<CudaDevice>, gu: bool, topk: usize, m: usize, k: usize, n: usize,
                       emax: usize, fold: bool) -> Option<MpkPlan> {
    if m == 0 || m > 16 || n % 128 != 0 || k % 128 != 0 || (gu && n % 256 != 0) { return None; }
    if (!gu && m * topk > MPK_RTMAX) || emax.min(m * topk) > MPK_EMAX { return None; }
    let cap = (emax.min(m * topk).max(1) * (n / 128)) as u32;
    let sms = lmh_sm_count(dev);
    let nsts: &[usize] = match w4moe_nst_env() { Some(4) => &[4], Some(8) => &[8], _ => &[8, 4] };
    let mut best: Option<MpkPlan> = None;
    for &nst in nsts {
        let Some(name) = mpk_entry(gu, topk, nst) else { continue };
        let smem = mpk_smem_bytes(nst, m, k, gu, fold) as u32;
        let Some((_, cps)) = mpk_fn(name, smem) else { continue };
        let grid = (cps * sms).min(cap).max(1);
        if best.map_or(true, |b| grid > b.grid) { best = Some(MpkPlan { name, grid, smem, cps, nst }); }
    }
    let mut p = best?;
    if let Some(g) = w4moe_g_env() { p.grid = g.min(cap).max(1); }
    Some(p)
}

/// W4/MOE gate/up launch (the SERVED launcher; also the binv probe's). ain = x (fold) or xh_e;
/// every pointer is a device address. Plain stream launch (graph-capturable), PDL-aware.
#[allow(clippy::too_many_arguments)]
pub(crate) fn mpk_launch_gu(dev: &Arc<CudaDevice>, stream: cudarc::driver::sys::CUstream, plan: &MpkPlan,
                            base: u64, offs: u64, ain: u64, suh_gu: u64, ygu: u64, m: usize, k: usize, n: usize,
                            esel: u64, idxmap: u64, svh: u64, suh_d: u64, xhd: u64, cnt: u64, x: u64, sg: u64,
                            sgv: u64, flags: i32) -> Result<()> {
    let _ = dev;
    let mut a = [base, offs, ain, suh_gu, ygu];
    let mut d = [m as i32, k as i32, n as i32];
    let mut b = [esel, idxmap, svh, suh_d, xhd, cnt, x, sg, sgv];
    let mut fl = flags;
    let mut p: [*mut std::ffi::c_void; 18] = [
        &mut a[0] as *mut u64 as *mut _, &mut a[1] as *mut u64 as *mut _, &mut a[2] as *mut u64 as *mut _,
        &mut a[3] as *mut u64 as *mut _, &mut a[4] as *mut u64 as *mut _,
        &mut d[0] as *mut i32 as *mut _, &mut d[1] as *mut i32 as *mut _, &mut d[2] as *mut i32 as *mut _,
        &mut b[0] as *mut u64 as *mut _, &mut b[1] as *mut u64 as *mut _, &mut b[2] as *mut u64 as *mut _,
        &mut b[3] as *mut u64 as *mut _, &mut b[4] as *mut u64 as *mut _, &mut b[5] as *mut u64 as *mut _,
        &mut b[6] as *mut u64 as *mut _, &mut b[7] as *mut u64 as *mut _, &mut b[8] as *mut u64 as *mut _,
        &mut fl as *mut i32 as *mut _,
    ];
    mpk_raw_launch(stream, plan, &mut p)
}

/// W4/MOE down launch (the SERVED launcher; also the binv probe's).
#[allow(clippy::too_many_arguments)]
pub(crate) fn mpk_launch_dn(dev: &Arc<CudaDevice>, stream: cudarc::driver::sys::CUstream, plan: &MpkPlan,
                            base: u64, offs: u64, xhd: u64, yd: u64, m: usize, k: usize, n: usize,
                            esel: u64, idxmap: u64, svh: u64, cnt_dn: u64, ysh: u64, ids: u64, wts: u64,
                            slotmap: u64, sgv: u64, out: u64, topk: usize, flags: i32) -> Result<()> {
    let _ = dev;
    let mut a = [base, offs, xhd, yd];
    let mut d = [m as i32, k as i32, n as i32];
    let mut b = [esel, idxmap, svh, cnt_dn, ysh, ids, wts, slotmap, sgv, out];
    let (mut tk, mut fl) = (topk as i32, flags);
    let mut p: [*mut std::ffi::c_void; 19] = [
        &mut a[0] as *mut u64 as *mut _, &mut a[1] as *mut u64 as *mut _, &mut a[2] as *mut u64 as *mut _,
        &mut a[3] as *mut u64 as *mut _,
        &mut d[0] as *mut i32 as *mut _, &mut d[1] as *mut i32 as *mut _, &mut d[2] as *mut i32 as *mut _,
        &mut b[0] as *mut u64 as *mut _, &mut b[1] as *mut u64 as *mut _, &mut b[2] as *mut u64 as *mut _,
        &mut b[3] as *mut u64 as *mut _, &mut b[4] as *mut u64 as *mut _, &mut b[5] as *mut u64 as *mut _,
        &mut b[6] as *mut u64 as *mut _, &mut b[7] as *mut u64 as *mut _, &mut b[8] as *mut u64 as *mut _,
        &mut b[9] as *mut u64 as *mut _, &mut tk as *mut i32 as *mut _, &mut fl as *mut i32 as *mut _,
    ];
    mpk_raw_launch(stream, plan, &mut p)
}

fn mpk_raw_launch(stream: cudarc::driver::sys::CUstream, plan: &MpkPlan, p: &mut [*mut std::ffi::c_void]) -> Result<()> {
    use cudarc::driver::sys;
    let (f, _) = mpk_fn(plan.name, plan.smem)
        .ok_or_else(|| anyhow::anyhow!("W4/MOE: {} unavailable at {} B smem (stale PTX?)", plan.name, plan.smem))?;
    if pdl_on() {
        return unsafe { launch_pss_raw(stream, f, (plan.grid, 1, 1), (256, 1, 1), plan.smem, p) }
            .with_context(|| format!("launch {} (pdl)", plan.name));
    }
    let r = unsafe { sys::cuLaunchKernel(f, plan.grid, 1, 1, 256, 1, 1, plan.smem, stream, p.as_mut_ptr(), std::ptr::null_mut()) };
    anyhow::ensure!(r == sys::CUresult::CUDA_SUCCESS, "launch {} ({r:?})", plan.name);
    Ok(())
}

/// FwdModel::load: resolve + opt in every W4/MOE entry the widths 1..=width can take (outside any
/// graph capture), and print the feature marker with the per-width plan.
fn w4moe_announce(dev: &Arc<CudaDevice>, cfg: &crate::qwen::Config, width: usize) {
    if cfg.num_experts == 0 || wp20_mode() != 2 { return; }
    let parts = w4moe_parts();
    if parts & (MPK_GU | MPK_DN) == 0 {
        let esc = crate::opts::var(crate::opt!("w4moe-off")).ok().filter(|v| !matches!(v.trim(), "" | "0"));
        let why = match (w4moe_opt_in(), esc) {
            (false, None) => "default".to_string(),
            (false, Some(v)) => format!("--w4moe-off={v}"),
            (true, Some(v)) => format!("--w4moe-off={v} overrides --w4moe=1"),
            (true, None) => "no live part".to_string(),
        };
        let knobs: Vec<String> = [crate::opt!("w4moe-order"), crate::opt!("w4moe-nst"), crate::opt!("w4moe-g"), crate::opt!("w4moe-minm"), crate::opt!("w4moe-shovl")]
            .into_iter().filter(|k| crate::opts::var_os(*k).is_some()).map(|k| k.to_string()).collect();
        println!("W4/MOE: OFF ({why}) — WP20 rung-2 kernels (xq_had_suh_multi + xq_moe_gu_epi + xq_moe_dn_epi); \
                  --w4moe=1 = persistent grouped experts{}",
                 if knobs.is_empty() { String::new() } else { format!(" ({} ignored while OFF)", knobs.join("/")) });
        w4moe_prewarm(dev, cfg, width, parts);
        return;
    }
    let (h, mi, topk) = (cfg.hidden_size, cfg.moe_intermediate_size, cfg.num_experts_per_tok);
    let fold = parts & MPK_FOLD != 0;
    let mut rows = Vec::new();
    for m in 1..=width.clamp(1, 16) {
        if a1_smem(m, h) == 0 || a1_smem(m, mi) == 0 { continue; } // WP20 rung 2's envelope
        let emax = width * topk;
        let on = m >= w4moe_minm();
        let gu = if on && parts & MPK_GU != 0 { mpk_plan(dev, true, topk, m, h, 2 * mi, emax, fold) } else { None };
        let dn = if on && parts & MPK_DN != 0 { mpk_plan(dev, false, topk, m, mi, h, emax, false) } else { None };
        let f = |p: Option<MpkPlan>| p.map_or("WP20".to_string(), |p| format!("s{}xG{}({}/SM)", p.nst, p.grid, p.cps));
        rows.push(format!("m{m} gu {} dn {}", f(gu), f(dn)));
    }
    println!("W4/MOE: persistent grouped experts ON (opt-in --w4moe=1) — parts gu {} dn {} fold {}, order {}, \
              shared-expert overlap {}, top-k {topk}; plans [{}] (default OFF / --w4moe-off=1 = WP20 rung-2 kernels)",
             (parts & MPK_GU != 0) as u8, (parts & MPK_DN != 0) as u8, fold as u8,
             if w4moe_order_il() { "interleaved" } else { "contiguous" },
             if w4moe_shovl() { "ON (--w4moe-shovl=1)" } else { "off" }, rows.join(", "));
    w4moe_prewarm(dev, cfg, width, parts);
}

/// TUNE T0c: plan (and so opt in) every W4/MOE entry the OTHER reachable parts masks can take — a
/// table value or the --autotune overlay can turn the package on (or change the fold) at some width —
/// here, outside any graph capture, silently. Nothing reachable beyond `planned`: a no-op (the
/// default posture plans exactly what it did before).
fn w4moe_prewarm(dev: &Arc<CudaDevice>, cfg: &crate::qwen::Config, width: usize, planned: u8) {
    let (h, mi, topk) = (cfg.hidden_size, cfg.moe_intermediate_size, cfg.num_experts_per_tok);
    for p in tune::reachable(&T_W4MOE_PARTS) {
        let p = { let p = p.clamp(0, 7) as u8; if p & MPK_GU == 0 { p & !MPK_FOLD } else { p } };
        if p == planned || p & (MPK_GU | MPK_DN) == 0 { continue; }
        for m in 1..=width.clamp(1, 16) {
            if a1_smem(m, h) == 0 || a1_smem(m, mi) == 0 { continue; }
            let emax = width * topk;
            if p & MPK_GU != 0 { let _ = mpk_plan(dev, true, topk, m, h, 2 * mi, emax, p & MPK_FOLD != 0); }
            if p & MPK_DN != 0 { let _ = mpk_plan(dev, false, topk, m, mi, h, emax, false); }
        }
    }
}

// ---- W3/LMH (2026-09-27): persistent lm_head GEMM (kernels/exl3_bench.cu "W3/LMH") ----
// Every path below is bitwise-identical by the kernel's contract; the knobs are A/B + bisect
// tools only (AGENTS §1b — the new path is the default):
//   --lmh-off=1      the old exl3_hmma_gemm + exl3_had_svh pair
//   --lmh-had=0      new GEMM writing y_raw + the separate exl3_had_svh (fused epilogue off)
//   --lmh-nst=4|6|8  cp.async ring depth of the 5-bit head (default 6; 3/4-bit always 6)
//   --lmh-xcheck=1   eager bit-diff of every NON-captured lm_head chain vs the old pair
//                       (use --exl3-no-graph=1 for coverage; prints LMH_XCHECK lines)
fn lmh_off() -> bool {
    tune::get_cur(&T_LMH_OFF) != 0
}
fn lmh_had() -> bool {
    tune::get_cur(&T_LMH_HAD) != 0
}
fn lmh_nst() -> usize {
    tune::get_cur(&T_LMH_NST).max(1) as usize
}
// TUNE T0 (p3c): the W3/LMH switches (bitwise twins: LMH_XCHECK + the binv ring sweep).
pub(crate) const T_LMH_OFF: tune::TunableDef = tune::TunableDef {
    slot: 28, id: "lmh.off", class: tune::Class::S, scope: tune::Scope::Global, fams: FAMS_LMH,
    domain: &[0, 1], default: 0, valid: tune::valid_any, xcheck: "--probe-exl3-binv W3/LMH + --lmh-xcheck",
    env: "--lmh-off", env_parse: || tune::env_on_if_1(crate::opt!("lmh-off")), rev: 1, wp: "W3/LMH",
};
pub(crate) const T_LMH_HAD: tune::TunableDef = tune::TunableDef {
    slot: 29, id: "lmh.had", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_LMH,
    domain: &[0, 1], default: 1, valid: tune::valid_any, xcheck: "--probe-exl3-binv W3/LMH (fused svh) + --lmh-xcheck",
    env: "--lmh-had", env_parse: || tune::env_on_unless_0(crate::opt!("lmh-had")), rev: 1, wp: "W3/LMH",
};
pub(crate) const T_LMH_NST: tune::TunableDef = tune::TunableDef {
    slot: 30, id: "lmh.nst", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_LMH,
    // cp.async ring depth of the 5-bit head (3/4-bit heads always run 6: lmh_nst_for — inert there)
    domain: &[4, 6, 8], default: 6, valid: tune::valid_any, xcheck: "--probe-exl3-binv [full head, ring sweep]",
    env: "--lmh-nst",
    env_parse: || tune::env_str(crate::opt!("lmh-nst")).map(|v| match v.as_str() { "4" => 4, "8" => 8, _ => 6 }),
    rev: 1, wp: "W3/LMH",
};
/// Families whose graphs run an lm_head-class chain (verify / step full head, draft slice).
pub(crate) const FAMS_LMH: &[tune::Fam] = &[tune::Fam::Step, tune::Fam::Verify, tune::Fam::DraftPass,
                                            tune::Fam::DraftChain, tune::Fam::Util];
fn lmh_xcheck() -> bool {
    static V: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *V.get_or_init(|| crate::opts::var(crate::opt!("lmh-xcheck")).is_ok_and(|v| !v.is_empty() && v != "0"))
}

/// k16 steps per ring slot — mirror of LMH_KSTEP (kernels/exl3_bench.cu).
pub(crate) const LMH_KSTEP: usize = 4;

/// Mirror of lmh_smem_bytes() in kernels/exl3_bench.cu (the kernel traps if launched short).
pub(crate) fn lmh_smem_bytes(bits: usize, mrows: usize, nst: usize, k: usize) -> usize {
    nst * LMH_KSTEP * 8 * 32 * bits + if mrows == 8 { 8 * (k + 8) * 2 } else { 0 } + mrows * 136 * 2
}

fn lmh_entry(bits: usize, mrows: usize, nst: usize) -> Option<&'static str> {
    Some(match (bits, mrows, nst) {
        (5, 8, 4) => "exl3_lmh_b5_m8_s4",
        (5, 8, 6) => "exl3_lmh_b5_m8_s6",
        (5, 8, 8) => "exl3_lmh_b5_m8_s8",
        (5, 16, 4) => "exl3_lmh_b5_m16_s4",
        (5, 16, 6) => "exl3_lmh_b5_m16_s6",
        (5, 16, 8) => "exl3_lmh_b5_m16_s8",
        (4, 8, 6) => "exl3_lmh_b4_m8_s6",
        (4, 16, 6) => "exl3_lmh_b4_m16_s6",
        (3, 8, 6) => "exl3_lmh_b3_m8_s6",
        (3, 16, 6) => "exl3_lmh_b3_m16_s6",
        _ => return None,
    })
}

/// Raw handle of one exl3_lmh_* entry (the xq-raw module), opted in to `smem` dynamic bytes and
/// checked to fit >= 1 CTA/SM at 256 threads. Cached per entry; the opt-in is raised when a
/// later call needs more. None = unusable (the caller keeps the old kernel).
fn lmh_fn(name: &'static str, smem: u32) -> Option<cudarc::driver::sys::CUfunction> {
    use cudarc::driver::sys;
    #[derive(Clone, Copy)]
    struct FnH(sys::CUfunction);
    unsafe impl Send for FnH {}
    unsafe impl Sync for FnH {}
    static C: std::sync::Mutex<Vec<(&'static str, FnH, u32)>> = std::sync::Mutex::new(Vec::new());
    let mut c = C.lock().ok()?;
    if let Some(e) = c.iter().find(|e| e.0 == name) {
        if smem <= e.2 { return Some(e.1 .0); }
    }
    let f = xq_raw_fn(name)?;
    if smem as usize > crate::gpu::SMEM_OPTIN_CAP as usize {
        eprintln!("[lmh] {name}: {smem} B over the {} B opt-in cap", crate::gpu::SMEM_OPTIN_CAP);
        return None;
    }
    let r = unsafe { sys::cuFuncSetAttribute(f,
        sys::CUfunction_attribute::CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, smem as i32) };
    if r != sys::CUresult::CUDA_SUCCESS { eprintln!("[lmh] {name}: smem opt-in {smem} B failed ({r:?})"); return None; }
    let mut nb: i32 = 0;
    let r = unsafe { sys::cuOccupancyMaxActiveBlocksPerMultiprocessor(&mut nb, f, 256, smem as usize) };
    if r != sys::CUresult::CUDA_SUCCESS || nb < 1 {
        eprintln!("[lmh] {name}: not resident at {smem} B smem (occupancy {nb}, {r:?})");
        return None;
    }
    println!("W3/LMH: {name} ready (dynamic smem {smem} B, {nb} CTA/SM; --lmh-off=1 = old exl3_hmma_gemm)");
    c.retain(|e| e.0 != name);
    c.push((name, FnH(f), smem));
    Some(f)
}

/// Ring depths instantiated per rate: 5-bit 4/6/8, 3/4-bit 6 (kernels/exl3_bench.cu LMH_ENTRY).
fn lmh_nst_for(bits: usize, nst: usize) -> usize {
    if bits == 5 && matches!(nst, 4 | 6 | 8) { nst } else { 6 }
}

/// Resolve + opt in both lm_head entries (m <= 8, m 9..16) at LOAD, outside any graph capture
/// (the lazy first use could otherwise land inside a verify capture). Prints the feature marker.
fn lmh_prewarm(bits: usize, k: usize) {
    if lmh_off() {
        println!("W3/LMH: OFF (--lmh-off=1) — lm_head runs exl3_hmma_gemm + exl3_had_svh");
        return;
    }
    let nst = lmh_nst_for(bits, lmh_nst());
    for mrows in [8usize, 16] {
        match lmh_entry(bits, mrows, nst) {
            Some(name) if lmh_fn(name, lmh_smem_bytes(bits, mrows, nst, k) as u32).is_some() => {}
            _ => println!("W3/LMH: no usable entry for bits {bits} mrows {mrows} nst {nst} K {k} — \
                           those widths keep exl3_hmma_gemm"),
        }
    }
    // TUNE: every other ring depth the frozen table (or the --autotune overlay) can select is
    // opted in here too, so no lazy cuFuncSetAttribute ever lands inside a capture.
    for alt in tune::reachable(&T_LMH_NST) {
        let alt = lmh_nst_for(bits, alt.max(1) as usize);
        if alt == nst { continue; }
        for mrows in [8usize, 16] {
            if let Some(name) = lmh_entry(bits, mrows, alt) {
                let _ = lmh_fn(name, lmh_smem_bytes(bits, mrows, alt, k) as u32);
            }
        }
    }
    println!("W3/LMH: lm_head persistent GEMM ON (nst {nst}, fused had_svh {}, xcheck {})",
             lmh_had() as u8, lmh_xcheck() as u8);
}

pub(crate) fn lmh_sm_count(dev: &Arc<CudaDevice>) -> u32 {
    use cudarc::driver::sys;
    static V: std::sync::OnceLock<u32> = std::sync::OnceLock::new();
    *V.get_or_init(|| dev.attribute(sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT)
        .ok().filter(|&v| v > 0).map(|v| v as u32).unwrap_or(48))
}

/// W3/LMH launch on `stream`: out = logits (fuse_had: Hadamard + svh fused) or y_raw. Ok(false)
/// = shape/resources not eligible (the caller runs exl3_hmma_gemm). grid = min(#SMs, N/128),
/// 256 threads, 1 CTA/SM. PDL-aware (--exl3-pdl=1), graph-capturable (plain stream launch).
#[allow(clippy::too_many_arguments)]
pub(crate) fn lmh_gemm_launch(dev: &Arc<CudaDevice>, stream: cudarc::driver::sys::CUstream,
                              tr: u64, xh: u64, out: u64, svh: u64, m: usize, k: usize, n: usize,
                              bits: usize, nst: usize, fuse_had: bool) -> Result<bool> {
    use cudarc::driver::sys;
    if m == 0 || m > 16 || n == 0 || n % 128 != 0 || k == 0 || k % (16 * LMH_KSTEP) != 0 || k % 128 != 0 {
        return Ok(false);
    }
    let nst = lmh_nst_for(bits, nst);
    let mrows = if m <= 8 { 8 } else { 16 };
    let Some(name) = lmh_entry(bits, mrows, nst) else { return Ok(false); };
    let smem = lmh_smem_bytes(bits, mrows, nst, k);
    let Some(f) = lmh_fn(name, smem as u32) else { return Ok(false); };
    let grid = lmh_sm_count(dev).min((n / 128) as u32).max(1);
    let (mut p_tr, mut p_xh, mut p_out, mut p_svh) = (tr, xh, out, svh);
    let (mut p_m, mut p_k, mut p_n, mut p_f) = (m as i32, k as i32, n as i32, fuse_had as i32);
    let mut params: [*mut std::ffi::c_void; 8] = [
        &mut p_tr as *mut u64 as *mut _, &mut p_xh as *mut u64 as *mut _,
        &mut p_out as *mut u64 as *mut _, &mut p_svh as *mut u64 as *mut _,
        &mut p_m as *mut i32 as *mut _, &mut p_k as *mut i32 as *mut _,
        &mut p_n as *mut i32 as *mut _, &mut p_f as *mut i32 as *mut _,
    ];
    if pdl_on() {
        unsafe { launch_pss_raw(stream, f, (grid, 1, 1), (256, 1, 1), smem as u32, &mut params) }
            .with_context(|| format!("launch {name} (pdl)"))?;
    } else {
        let r = unsafe {
            sys::cuLaunchKernel(f, grid, 1, 1, 256, 1, 1, smem as u32, stream,
                                params.as_mut_ptr(), std::ptr::null_mut())
        };
        anyhow::ensure!(r == sys::CUresult::CUDA_SUCCESS, "launch {name} failed: {r:?}");
    }
    Ok(true)
}

/// --lmh-xcheck: the old pair (exl3_hmma_gemm [+ exl3_had_svh]) on side buffers from the SAME
/// xh, bit-diffed against the new path's output rows (`got`: logits if fused, else y_raw).
fn lmh_xcheck_run(l: &Launcher, q: &Quad, xh: &CudaSlice<u16>, got: &CudaSlice<u16>, m: usize,
                  fused: bool) -> Result<()> {
    use std::sync::atomic::{AtomicUsize, Ordering};
    static N: AtomicUsize = AtomicUsize::new(0);
    static BAD: AtomicUsize = AtomicUsize::new(0);
    let n = q.n as usize;
    let mut yr = l.dev.alloc_zeros::<u16>(m * n)?;
    xqlaunch!(l, "exl3_hmma_gemm", ((q.n as u32) / 128, 1, 1), (256, 1, 1), 0,
              (&q.tr, xh, &mut yr, m as i32, q.k, q.n, q.bits))?;
    let refv = if fused {
        let mut yo = l.dev.alloc_zeros::<u16>(m * n)?;
        xqlaunch!(l, "exl3_had_svh", (m as u32 * (q.n as u32 / 128), 1, 1), (32, 1, 1), 0,
                  (&yr, &q.svh, &mut yo, q.n))?;
        l.dev.synchronize()?;
        l.dev.dtoh_sync_copy(&yo)?
    } else {
        l.dev.synchronize()?;
        l.dev.dtoh_sync_copy(&yr)?
    };
    let newv = l.dev.dtoh_sync_copy(got)?;
    let (mut mism, mut maxd, mut first) = (0usize, 0f32, None);
    for i in 0..m * n {
        if newv[i] != refv[i] {
            mism += 1;
            if first.is_none() { first = Some((i / n, i % n, newv[i], refv[i])); }
            let d = (f16::from_bits(newv[i]).to_f32() - f16::from_bits(refv[i]).to_f32()).abs();
            if d.is_nan() || d > maxd { maxd = if d.is_nan() { f32::INFINITY } else { d }; }
        }
    }
    let nz = refv[..m * n].iter().filter(|&&b| b != 0).count();
    let c = N.fetch_add(1, Ordering::SeqCst) + 1;
    if mism > 0 { BAD.fetch_add(1, Ordering::SeqCst); }
    if mism > 0 || c == 1 || c % 100 == 0 {
        println!("LMH_XCHECK: checks {c} bad {} | this: m {m} n {n} fused {} mism {mism} max|d| {maxd:e} \
                  ref_nonzero {nz} first(row,col,new,old) {first:?}",
                 BAD.load(Ordering::SeqCst), fused as u8);
    }
    Ok(())
}

/// WP21: split-K fixup epilogue in exl3_hmma_gemm_ks(_x2) — DEFAULT ON. The last-arriving
/// CTA per N-tile does the ascending fp32 combine + H128 svh in-launch, so a ks > 1 chain is
/// had_suh + ONE GEMM launch (was + exl3_ks_combine + exl3_had_svh). Bitwise the same y.
/// Sites: exl3_chain_impl (single), exl3_chain_pair (x2), and REPRIME's wp22r1 row slabs (one
/// fused launch per <= 16-row slab; the slab loop's trailing exl3_had_svh is gone too). Opt-in
/// paths keep their own tails: W4/DENSE (--w4dense=1, its own in-kernel fixup) runs first,
/// PSK (--psk=1) keeps combine + svh; LMH (ks = 1) never reaches a split-K site.
/// --wp21-off=1 = the 3-launch chain tail (A/B + bisect escape).
/// --wp21-ks-off=<ks,ks,...> (diagnostics): the listed split counts keep the 3-launch tail —
/// a per-shape A/B without a rebuild (ks is a pure function of (K, N), so every width of a shape
/// takes the same path; both paths are bitwise equal anyway). Parsed once; malformed entries are
/// ignored and the parsed set is printed on first use.
///
/// Concurrency (WP27 capture-DAG forks + the other in-flight classes). The fixup's counter set is
/// `Quad.cnt` (one self re-arming u32 per N-tile, per weight matrix; shared only with W4/DENSE's
/// opt-in exl3_dks_* on the same Quad, which is a different launch of the SAME site, never both).
/// A counter set is therefore only ever hit by launches of ONE Quad, and no graph ever has two
/// launches of one Quad on parallel branches:
///  - GDN fork (verify + step graphs): in_qkv runs from the fork base, in_z from in_qkv's tail
///    (so the two chains are ordered, never concurrent; distinct Quads, and in_z has its own
///    z_xh / z_yraw / z_ws); the branches beside them (a|b GEMV + saves, conv, scan) hold no
///    counter. out_proj runs after the join.
///  - MoE fork (the pre-WP20 fallback sequence) and W4/MOE SHOVL (opt-in): the shared-expert
///    branch holds sh_gate|sh_up (x2: two counter slices, cnt0 != cnt1 enforced) then sh_down;
///    the routed branch holds only the router fold's private fold_cnt and sc.moe_cnt — no Quad.
///  - PLE fork: dropped in p3c. Draft graphs: no forks.
///  - HOST speculative pass, REPRIME graph, multi-lane rounds: stream-ordered on the ONE compute
///    stream (consecutive launches of a Quad complete — counters back at 0 — before the next
///    starts; under --exl3-pdl=1 XQ_PDL_ENTRY waits on the whole previous grid first).
/// A pair launch with both members on the same counter set (q0.cnt == q1.cnt) would double-count
/// arrivals; wp21_pair_ok refuses it (the 3-launch x2 tail runs instead).
fn wp21_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| crate::opts::var(crate::opt!("wp21-off")).as_deref() != Ok("1"))
}

fn wp21_on(ks: u32) -> bool {
    static KS_OFF: std::sync::OnceLock<Vec<u32>> = std::sync::OnceLock::new();
    if !wp21_enabled() { return false; }
    let off = KS_OFF.get_or_init(|| {
        let v: Vec<u32> = crate::opts::var(crate::opt!("wp21-ks-off")).ok()
            .map(|s| s.split(',').filter_map(|t| t.trim().parse().ok()).collect())
            .unwrap_or_default();
        if !v.is_empty() { println!("WP21: --wp21-ks-off -> 3-launch tail for ks in {v:?}"); }
        v
    });
    !off.contains(&ks)
}

/// WP21 eligibility of one member: one counter per 128-column tile of N (load-time sizing).
fn wp21_cnt_ok(q: &Quad) -> bool {
    q.n > 0 && q.n % 128 == 0 && q.cnt.len() * 128 >= q.n as usize
}

/// WP21 eligibility of a same-input pair: both members' counters fit AND are distinct slices
/// (a shared set would take 2 * ks arrivals per tile — see the concurrency note at wp21_on).
fn wp21_pair_ok(q0: &Quad, q1: &Quad, n: i32) -> bool {
    q0.n == n && q1.n == n && wp21_cnt_ok(q0) && wp21_cnt_ok(q1)
        && *q0.cnt.device_ptr() != *q1.cnt.device_ptr()
}

/// Load-time feature marker: which split-K chain tail this process runs (AGENTS §1a.4).
fn wp21_log_boot() {
    if !wp21_enabled() {
        println!("EXL3-FWD WP21: OFF (--wp21-off=1) — split-K chains run the 3-launch tail \
                  (exl3_hmma_gemm_ks + exl3_ks_combine + exl3_had_svh)");
        return;
    }
    let mut notes: Vec<&str> = Vec::new();
    if dense::dense_on() { notes.push("W4/DENSE ON: its chains take the DENSE fixup, WP21 serves the rest"); }
    if !psk_off() { notes.push("PSK ON: PSK grids keep the combine + svh tail"); }
    if crate::opts::var_os(crate::opt!("wp21-ks-off")).is_some() { notes.push("--wp21-ks-off set: listed ks keep the 3-launch tail"); }
    if wp21_xcheck() { notes.push("--wp21-xcheck: eager fused calls diffed vs the 3-launch tail"); }
    println!("EXL3-FWD WP21: split-K fixup epilogue ON — ks > 1 chains (single / pair / REPRIME slabs) = had_suh + ONE \
              exl3_hmma_gemm_ks_fx(_x2) launch (last CTA per N-tile: ascending combine + H128 svh){}; \
              --wp21-off=1 = the 3-launch tail",
             if notes.is_empty() { String::new() } else { format!(" [{}]", notes.join("; ")) });
}

/// WP21 v2 receipt, printed once from the first EAGER fused call (skipped while capturing).
/// The fused kernels only pay at 4 CTAs/SM (64 regs, like exl3_hmma_gemm_ks): v2 carries
/// `.maxntid 256` WITHOUT a min-blocks cap (the (256,4) cap made ptxas degrade the k-loop, the
/// v1 regression), so the register count is the driver JIT's own choice — offline ptxas 13.0
/// picks 64. This line proves what the JIT actually built on the box.
fn wp21_occupancy_once(l: &Launcher) {
    static DONE: std::sync::OnceLock<()> = std::sync::OnceLock::new();
    if DONE.get().is_some() || stream_capturing(l) { return; }
    DONE.get_or_init(|| {
        use cudarc::driver::sys;
        for name in ["exl3_hmma_gemm_ks_fx", "exl3_hmma_gemm_ks_fx_x2", "exl3_hmma_gemm_ks"] {
            let Some(f) = xq_raw_fn(name) else {
                println!("WP21_OCC: {name} raw fn unavailable");
                continue;
            };
            let (mut regs, mut bps): (std::ffi::c_int, std::ffi::c_int) = (-1, -1);
            unsafe {
                let _ = sys::cuFuncGetAttribute(&mut regs, sys::CUfunction_attribute::CU_FUNC_ATTRIBUTE_NUM_REGS, f);
                let _ = sys::cuOccupancyMaxActiveBlocksPerMultiprocessor(&mut bps, f, 256, 0);
            }
            println!("WP21_OCC: {name} regs {regs} blocks/SM {bps} -> {}",
                     if bps >= 4 { "OK" } else { "WARNING: < 4 CTAs/SM (fused path loses occupancy vs the 3-launch tail)" });
        }
    });
}

/// WP21 eager bitwise cross-check (--wp21-xcheck=1; add --exl3-no-graph=1 for full
/// coverage — calls issued while the stream is capturing are skipped, never synced).
/// Every fused call: fused y vs the 3-launch y on the live activations, counters back at 0
/// (WP21_XCHECK lines). First use of each chain / pair shape: a synthetic m = 1..=16 sweep —
/// fused vs 3-launch at every width, row-0 batch invariance, counters (WP21_SWEEP lines).
fn wp21_xcheck() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| crate::opts::var(crate::opt!("wp21-xcheck")).is_ok())
}

/// (mismatches, first mismatch index, max |a - b| as f16 values) over the first `n` elements.
fn wp21_diff(a: &[u16], b: &[u16], n: usize) -> (usize, Option<usize>, f32) {
    let (mut bad, mut first, mut maxd) = (0usize, None, 0f32);
    for i in 0..n {
        if a[i] != b[i] {
            bad += 1;
            if first.is_none() { first = Some(i); }
            let d = (f16::from_bits(a[i]).to_f32() - f16::from_bits(b[i]).to_f32()).abs();
            if !(d <= maxd) { maxd = d; } // NaN-propagating
        }
    }
    (bad, first, maxd)
}

fn wp21_report(kind: &str, m: usize, k: i32, n: i32, d: (usize, Option<usize>, f32), cnt_nz: usize) {
    use std::sync::atomic::{AtomicUsize, Ordering};
    static CALLS: AtomicUsize = AtomicUsize::new(0);
    static BAD: AtomicUsize = AtomicUsize::new(0);
    let c = CALLS.fetch_add(1, Ordering::SeqCst) + 1;
    let fail = d.0 > 0 || cnt_nz > 0;
    if fail { BAD.fetch_add(1, Ordering::SeqCst); }
    if fail || c == 1 || c % 500 == 0 {
        println!("WP21_XCHECK: calls {c} bad {} (this: {kind} m {m} K {k} N {n} mism {} first {:?} maxdiff {:e} cnt_nonzero {cnt_nz})",
                 BAD.load(Ordering::SeqCst), d.0, d.1, d.2);
    }
}

/// Deterministic synthetic f16 activations in [-1, 1) for the WP21 width sweeps.
fn wp21_synth(len: usize, seed: u64) -> Vec<u16> {
    let mut s = seed ^ 0x9E37_79B9_7F4A_7C15;
    (0..len).map(|_| {
        s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let u = ((s >> 40) as f32) / ((1u64 << 24) as f32);
        f16::from_f32(u * 2.0 - 1.0).to_bits()
    }).collect()
}

/// The pre-WP21 single-chain tail (xh already holds had_suh(x)): ks GEMM -> combine -> svh.
fn wp21_old_single(l: &Launcher, q: &Quad, xh: &CudaSlice<u16>, yraw: &mut CudaSlice<u16>,
                   y: &mut CudaSlice<u16>, m: usize, ws: &CudaSlice<f32>) -> Result<()> {
    xqlaunch!(l, "exl3_hmma_gemm_ks", ((q.n as u32) / 128, q.ks, 1), (256, 1, 1), 0,
             (&q.tr, xh, ws, m as i32, q.k, q.n, q.bits))?;
    let mn = (m * q.n as usize) as u32;
    xqlaunch!(l, "exl3_ks_combine", ((mn + 255) / 256, 1, 1), (256, 1, 1), 0,
             (ws, &mut *yraw, m as i32, q.n, q.ks as i32))?;
    xqlaunch!(l, "exl3_had_svh", (m as u32 * (q.n as u32 / 128), 1, 1), (32, 1, 1), 0,
             (&*yraw, &q.svh, &mut *y, q.n))
}

/// The pre-WP21 pair tail: ks GEMM x2 -> combine x2 -> svh x2.
#[allow(clippy::too_many_arguments)]
fn wp21_old_pair(l: &Launcher, q0: &Quad, q1: &Quad, xh0: &CudaSlice<u16>, xh1: &CudaSlice<u16>,
                 yraw0: &mut CudaSlice<u16>, yraw1: &mut CudaSlice<u16>,
                 ws0: &CudaSlice<f32>, ws1: &CudaSlice<f32>,
                 y0: &mut CudaSlice<u16>, y1: &mut CudaSlice<u16>, m: usize) -> Result<()> {
    let (k, n) = (q0.k, q0.n);
    xqlaunch!(l, "exl3_hmma_gemm_ks_x2", ((n as u32) / 128, q0.ks, 2), (256, 1, 1), 0,
             (&q0.tr, &q1.tr, xh0, xh1, ws0, ws1, m as i32, k, n, q0.bits))?;
    let mn = (m * n as usize) as u32;
    xqlaunch!(l, "exl3_ks_combine_x2", ((mn + 255) / 256, 1, 2), (256, 1, 1), 0,
             (ws0, ws1, &mut *yraw0, &mut *yraw1, m as i32, n, q0.ks as i32))?;
    xqlaunch!(l, "exl3_had_svh_x2", (m as u32 * (n as u32 / 128), 1, 2), (32, 1, 1), 0,
             (&*yraw0, &*yraw1, &q0.svh, &q1.svh, &mut *y0, &mut *y1, n))
}

/// WP21: exl3_hmma_gemm_ks_fx_x2 takes 16 parameters (cudarc's tuple launch stops at 12), so it
/// launches raw through the xq raw module — the xq_router_topk_route precedent — honoring the
/// same --exl3-pdl switch as xqlaunch!. Captures into graphs like any stream launch.
/// `p` = device addresses [tr0, tr1, xh0, xh1, ws0, ws1, svh0, svh1, y0, y1, cnt0, cnt1]; grid
/// (N/128, ks, 2). The served pair chain AND the binv probe (EXL3-WP21) launch through here.
#[allow(clippy::too_many_arguments)]
pub(crate) fn wp21_fx_x2_raw(stream: cudarc::driver::sys::CUstream, mut p: [u64; 12], m: usize, k: i32, n: i32,
                             bits: i32, ks: u32) -> Result<()> {
    use std::ffi::c_void;
    static F: std::sync::OnceLock<usize> = std::sync::OnceLock::new(); // CUfunction, cached
    let fu = match F.get() {
        Some(&v) => v,
        None => {
            let f = xq_raw_fn("exl3_hmma_gemm_ks_fx_x2")
                .ok_or_else(|| anyhow::anyhow!("exl3_hmma_gemm_ks_fx_x2 raw fn unavailable (stale PTX?)"))?;
            *F.get_or_init(|| f as usize)
        }
    };
    anyhow::ensure!(p[10] != p[11], "WP21 x2: both members on one counter set");
    let f = fu as cudarc::driver::sys::CUfunction;
    let mut iv: [i32; 4] = [m as i32, k, n, bits];
    let mut args: [*mut c_void; 16] = [std::ptr::null_mut(); 16];
    for (i, v) in p.iter_mut().enumerate() { args[i] = v as *mut u64 as *mut c_void; }
    for (i, v) in iv.iter_mut().enumerate() { args[12 + i] = v as *mut i32 as *mut c_void; }
    let grid = ((n as u32) / 128, ks, 2u32);
    if pdl_on() {
        return unsafe { launch_pss_raw(stream, f, grid, (256, 1, 1), 0, &mut args) }
            .context("launch exl3_hmma_gemm_ks_fx_x2 (pdl)");
    }
    let r = unsafe {
        cudarc::driver::sys::cuLaunchKernel(f, grid.0, grid.1, grid.2, 256, 1, 1, 0, stream,
                                            args.as_mut_ptr(), std::ptr::null_mut())
    };
    anyhow::ensure!(r == cudarc::driver::sys::CUresult::CUDA_SUCCESS, "exl3_hmma_gemm_ks_fx_x2 launch ({r:?})");
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn wp21_launch_fx_x2(l: &Launcher, q0: &Quad, q1: &Quad, xh0: &CudaSlice<u16>, xh1: &CudaSlice<u16>,
                     ws0: &CudaSlice<f32>, ws1: &CudaSlice<f32>,
                     y0: &mut CudaSlice<u16>, y1: &mut CudaSlice<u16>, m: usize) -> Result<()> {
    let p: [u64; 12] = [
        *q0.tr.device_ptr() as u64, *q1.tr.device_ptr() as u64,
        *xh0.device_ptr() as u64, *xh1.device_ptr() as u64,
        *ws0.device_ptr() as u64, *ws1.device_ptr() as u64,
        *q0.svh.device_ptr() as u64, *q1.svh.device_ptr() as u64,
        *y0.device_ptr() as u64, *y1.device_ptr() as u64,
        *q0.cnt.device_ptr() as u64, *q1.cnt.device_ptr() as u64,
    ];
    wp21_fx_x2_raw(l.stream.stream, p, m, q0.k, q0.n, q0.bits, q0.ks)
}

fn wp21_cnt_nonzero(l: &Launcher, q: &Quad) -> Result<usize> {
    Ok(l.dev.dtoh_sync_copy(&q.cnt)?.iter().filter(|&&c| c != 0).count())
}

/// --wp21-xcheck, single chain: the fused launch just ran; diff it against the 3-launch
/// tail on the same xh (y is left holding the 3-launch result — equal when the check passes).
fn wp21_check_single(l: &Launcher, q: &Quad, xh: &CudaSlice<u16>, yraw: &mut CudaSlice<u16>,
                     y: &mut CudaSlice<u16>, m: usize, ws: &CudaSlice<f32>) -> Result<()> {
    if stream_capturing(l) { return Ok(()); }
    l.dev.synchronize()?;
    let fx = l.dev.dtoh_sync_copy(&*y)?;
    let cnt_nz = wp21_cnt_nonzero(l, q)?;
    wp21_old_single(l, q, xh, yraw, y, m, ws)?;
    l.dev.synchronize()?;
    let old = l.dev.dtoh_sync_copy(&*y)?;
    wp21_report("chain", m, q.k, q.n, wp21_diff(&fx, &old, m * q.n as usize), cnt_nz);
    wp21_sweep_single(l, q)
}

/// --wp21-xcheck, REPRIME wp22r1 slabs (m > 16 rows): the fused per-slab launches just ran;
/// diff y against the pre-WP21 slab loop on the same xh — per slab ks GEMM + combine into its
/// yraw rows, then ONE exl3_had_svh over all m rows (y is left holding that result).
#[allow(clippy::too_many_arguments)]
fn wp21_check_slabs(l: &Launcher, q: &Quad, xh: &CudaSlice<u16>, yraw: &mut CudaSlice<u16>,
                    y: &mut CudaSlice<u16>, m: usize, ws: &CudaSlice<f32>) -> Result<()> {
    if stream_capturing(l) { return Ok(()); }
    let (k, n) = (q.k as usize, q.n as usize);
    l.dev.synchronize()?;
    let fx = l.dev.dtoh_sync_copy(&*y)?;
    let cnt_nz = wp21_cnt_nonzero(l, q)?;
    let (xh_p, yr_p) = (*xh.device_ptr() as u64, *yraw.device_ptr() as u64);
    for (r0, ms) in wp22r1_slabs(m) {
        xqlaunch!(l, "exl3_hmma_gemm_ks", ((q.n as u32) / 128, q.ks, 1), (256, 1, 1), 0,
                 (&q.tr, xh_p + (r0 * k * 2) as u64, ws, ms as i32, q.k, q.n, q.bits))?;
        xqlaunch!(l, "exl3_ks_combine", (((ms * n) as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                 (ws, yr_p + (r0 * n * 2) as u64, ms as i32, q.n, q.ks as i32))?;
    }
    xqlaunch!(l, "exl3_had_svh", ((m * (n / 128)) as u32, 1, 1), (32, 1, 1), 0, (&*yraw, &q.svh, &mut *y, q.n))?;
    l.dev.synchronize()?;
    let old = l.dev.dtoh_sync_copy(&*y)?;
    wp21_report("slabs", m, q.k, q.n, wp21_diff(&fx, &old, m * n), cnt_nz);
    wp21_sweep_single(l, q)
}

/// --wp21-xcheck, pair: fused x2 launch vs the 3-launch x2 tail (both members).
#[allow(clippy::too_many_arguments)]
fn wp21_check_pair(l: &Launcher, q0: &Quad, q1: &Quad,
                   xh0: &CudaSlice<u16>, yraw0: &mut CudaSlice<u16>, ws0: &CudaSlice<f32>,
                   xh1: &CudaSlice<u16>, yraw1: &mut CudaSlice<u16>, ws1: &CudaSlice<f32>,
                   y0: &mut CudaSlice<u16>, y1: &mut CudaSlice<u16>, m: usize) -> Result<()> {
    if stream_capturing(l) { return Ok(()); }
    let mn = m * q0.n as usize;
    l.dev.synchronize()?;
    let (f0, f1) = (l.dev.dtoh_sync_copy(&*y0)?, l.dev.dtoh_sync_copy(&*y1)?);
    let cnt_nz = wp21_cnt_nonzero(l, q0)? + wp21_cnt_nonzero(l, q1)?;
    wp21_old_pair(l, q0, q1, xh0, xh1, yraw0, yraw1, ws0, ws1, y0, y1, m)?;
    l.dev.synchronize()?;
    let (o0, o1) = (l.dev.dtoh_sync_copy(&*y0)?, l.dev.dtoh_sync_copy(&*y1)?);
    let (d0, d1) = (wp21_diff(&f0, &o0, mn), wp21_diff(&f1, &o1, mn));
    let d = (d0.0 + d1.0, d0.1.or(d1.1.map(|i| i + mn)), if d0.2 >= d1.2 { d0.2 } else { d1.2 });
    wp21_report("pair", m, q0.k, q0.n, d, cnt_nz);
    wp21_sweep_pair(l, q0, q1)
}

/// First use per (k, n, bits, ks): synthetic m = 1..=16 sweep, fused vs 3-launch + row-0
/// batch invariance + counters re-armed.
fn wp21_sweep_single(l: &Launcher, q: &Quad) -> Result<()> {
    static SEEN: std::sync::Mutex<Vec<(i32, i32, i32, u32)>> = std::sync::Mutex::new(Vec::new());
    let key = (q.k, q.n, q.bits, q.ks);
    {
        let mut s = SEEN.lock().unwrap();
        if s.contains(&key) { return Ok(()); }
        s.push(key);
    }
    let (k, n) = (q.k as usize, q.n as usize);
    let x = l.dev.htod_sync_copy(&wp21_synth(16 * k, ((k as u64) << 32) ^ n as u64))?;
    let mut xh = l.dev.htod_sync_copy(&vec![0u16; 16 * k])?;
    let mut yraw = l.dev.htod_sync_copy(&vec![0u16; 16 * n])?;
    let mut ya = l.dev.htod_sync_copy(&vec![0u16; 16 * n])?;
    let mut yb = l.dev.htod_sync_copy(&vec![0u16; 16 * n])?;
    let ws = l.dev.htod_sync_copy(&vec![0f32; q.ks as usize * 16 * n])?;
    let (mut bad, mut binv_bad, mut cnt_bad) = (0usize, 0usize, 0usize);
    let mut row0: Option<Vec<u16>> = None;
    for m in 1..=16usize {
        xqlaunch!(l, "exl3_had_suh", (m as u32 * (q.k as u32 / 128), 1, 1), (32, 1, 1), 0,
                 (&x, &q.suh, &mut xh, q.k))?;
        xqlaunch!(l, "exl3_hmma_gemm_ks_fx", ((q.n as u32) / 128, q.ks, 1), (256, 1, 1), 0,
                 (&q.tr, &xh, &ws, &q.svh, &mut ya, &q.cnt, m as i32, q.k, q.n, q.bits))?;
        l.dev.synchronize()?;
        cnt_bad += wp21_cnt_nonzero(l, q)?;
        wp21_old_single(l, q, &xh, &mut yraw, &mut yb, m, &ws)?;
        l.dev.synchronize()?;
        let (a, b) = (l.dev.dtoh_sync_copy(&ya)?, l.dev.dtoh_sync_copy(&yb)?);
        bad += wp21_diff(&a, &b, m * n).0;
        match &row0 {
            None => row0 = Some(a[..n].to_vec()),
            Some(r) => if r[..] != a[..n] { binv_bad += 1; },
        }
    }
    let ok = bad == 0 && binv_bad == 0 && cnt_bad == 0;
    println!("WP21_SWEEP: chain K {k} N {n} bits {} ks {} m=1..16 mism {bad} binv_bad {binv_bad} cnt_nonzero {cnt_bad} -> {}",
             q.bits, q.ks, if ok { "PASS" } else { "FAIL" });
    Ok(())
}

/// Pair twin of wp21_sweep_single (x2 kernels, both members).
fn wp21_sweep_pair(l: &Launcher, q0: &Quad, q1: &Quad) -> Result<()> {
    static SEEN: std::sync::Mutex<Vec<(i32, i32, i32, u32)>> = std::sync::Mutex::new(Vec::new());
    let key = (q0.k, q0.n, q0.bits, q0.ks);
    {
        let mut s = SEEN.lock().unwrap();
        if s.contains(&key) { return Ok(()); }
        s.push(key);
    }
    let (k, n) = (q0.k as usize, q0.n as usize);
    let zb = |len: usize| l.dev.htod_sync_copy(&vec![0u16; len]);
    let x = l.dev.htod_sync_copy(&wp21_synth(16 * k, ((n as u64) << 32) ^ k as u64))?;
    let (mut xh0, mut xh1) = (zb(16 * k)?, zb(16 * k)?);
    let (mut yr0, mut yr1) = (zb(16 * n)?, zb(16 * n)?);
    let (mut ya0, mut ya1) = (zb(16 * n)?, zb(16 * n)?);
    let (mut yb0, mut yb1) = (zb(16 * n)?, zb(16 * n)?);
    let ws0 = l.dev.htod_sync_copy(&vec![0f32; q0.ks as usize * 16 * n])?;
    let ws1 = l.dev.htod_sync_copy(&vec![0f32; q0.ks as usize * 16 * n])?;
    let (mut bad, mut binv_bad, mut cnt_bad) = (0usize, 0usize, 0usize);
    let mut row0: Option<(Vec<u16>, Vec<u16>)> = None;
    for m in 1..=16usize {
        xqlaunch!(l, "exl3_had_suh_x2", (m as u32 * (q0.k as u32 / 128), 1, 2), (32, 1, 1), 0,
                 (&x, &q0.suh, &q1.suh, &mut xh0, &mut xh1, q0.k))?;
        wp21_launch_fx_x2(l, q0, q1, &xh0, &xh1, &ws0, &ws1, &mut ya0, &mut ya1, m)?;
        l.dev.synchronize()?;
        cnt_bad += wp21_cnt_nonzero(l, q0)? + wp21_cnt_nonzero(l, q1)?;
        wp21_old_pair(l, q0, q1, &xh0, &xh1, &mut yr0, &mut yr1, &ws0, &ws1, &mut yb0, &mut yb1, m)?;
        l.dev.synchronize()?;
        let (a0, a1) = (l.dev.dtoh_sync_copy(&ya0)?, l.dev.dtoh_sync_copy(&ya1)?);
        let (b0, b1) = (l.dev.dtoh_sync_copy(&yb0)?, l.dev.dtoh_sync_copy(&yb1)?);
        bad += wp21_diff(&a0, &b0, m * n).0 + wp21_diff(&a1, &b1, m * n).0;
        match &row0 {
            None => row0 = Some((a0[..n].to_vec(), a1[..n].to_vec())),
            Some((r0, r1)) => if r0[..] != a0[..n] || r1[..] != a1[..n] { binv_bad += 1; },
        }
    }
    let ok = bad == 0 && binv_bad == 0 && cnt_bad == 0;
    println!("WP21_SWEEP: pair K {k} N {n} bits {} ks {} m=1..16 mism {bad} binv_bad {binv_bad} cnt_nonzero {cnt_bad} -> {}",
             q0.bits, q0.ks, if ok { "PASS" } else { "FAIL" });
    Ok(())
}

fn exl3_chain(l: &Launcher, q: &Quad, x: &CudaSlice<u16>, xh: &mut CudaSlice<u16>,
              yraw: &mut CudaSlice<u16>, y: &mut CudaSlice<u16>, m: usize,
              ws: &CudaSlice<f32>) -> Result<()> {
    exl3_chain_impl(l, q, x, xh, yraw, y, m, ws, None)
}

// ---------------------------------------------------------------------------
// T4e / w3-PSK: persistent split-K chain GEMM (exl3_hmma_gemm_ks_p / exl3_hmma_gemm_ks_p_x2).
// Every fp32 partial is BITWISE the old exl3_hmma_gemm_ks(_x2) partial for EVERY grid size G:
// the logical items are exactly the old grid's CTAs (member, N128 tile, K slab at the SAME
// chain_ks), each computed by the same per-element sequence (kernels/exl3_bench.cu contract).
// The combine is untouched, so G is a pure schedule knob — the autotuner's T4e axis.
// p3 DEFAULT = OFF (preview/p4c @ 6300674, .14, 2026-09-27: PSK-off faster in every greedy class
// over 3 reps, -0.73..-0.93 ms/round — an in-round regression). OFF = the old (N/128, ks[, 2])
// grids everywhere, incl. REPRIME's wp22r1 row slabs.
//   --psk=1          enable the persistent split-K grids (the knobs below apply only then).
//   --psk-off=1      escape: the old (N/128, ks[, 2]) grids, every shape (wins over --psk=1).
//   --psk-g=<n>      G for every shape; or a per-shape list "KxN=G,KxNp=G,..." (p = the pair
//                       kernel), e.g. "2560x6144=240,2560x512p=96". Clamped to [1, items];
//                       unlisted shapes keep the built-in rule (psk_grid).
//   --psk-pf=<d>     trellis L2 prefetch distance in 8-step blocks (default 1; 0 = off).
//   --psk-xcheck=1   eager only: after each PSK launch the old kernel re-runs into a twin
//                       workspace and every fp32 partial is bit-compared (PSK_XCHECK lines).
// ---------------------------------------------------------------------------
fn psk_off() -> bool {
    tune::get_cur(&T_PSK_ON) == 0
}
/// --psk-off=1: the explicit escape (as before p3; overrides --psk=1).
fn psk_escape() -> bool {
    crate::opts::var(crate::opt!("psk-off")).as_deref() == Ok("1")
}
/// --psk=1: opt in to the persistent split-K grids (p3: default OFF).
fn psk_opt_in() -> bool {
    crate::opts::var(crate::opt!("psk")).as_deref() == Ok("1")
}
fn psk_pf() -> i32 {
    tune::get_cur(&T_PSK_PF).clamp(0, 127)
}
// TUNE T0 (p3c): the PSK knobs. G is the T4e axis — a pure schedule knob at fixed ks (EXL3-KS-P
// sweeps G in {1, odd, 48-multiples, the default, items-1, items, > items} x M 1..16 x PF 0/1/2).
// p5e: PSK is an OPT-IN package (p3: default OFF, --psk=1 opts in, --psk-off=1 wins) — so
// the registry switch is psk.on (value 1 = the persistent grids), per width: bitwise at every G and
// M 1..16, so the tuner may re-evaluate it per (family, m) in-round (what its standalone estimate lacked).
pub(crate) const T_PSK_ON: tune::TunableDef = tune::TunableDef {
    slot: 24, id: "psk.on", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_CHAIN,
    domain: &[0, 1], default: 0, valid: tune::valid_any, xcheck: "--probe-exl3-binv EXL3-KS-P + --psk-xcheck",
    env: "--psk|--psk-off",
    // either alias set = the old rule exactly (on iff --psk == "1" and --psk-off != "1")
    env_parse: || (tune::env_str(crate::opt!("psk")).is_some() || tune::env_str(crate::opt!("psk-off")).is_some())
        .then(|| (psk_opt_in() && !psk_escape()) as i32),
    rev: 2, wp: "w3/PSK",
};
/// psk.g / psk.g_pair value that means "the legacy --psk-g parse decides" (the env alias: a
/// global G or a per-shape "KxN=G,KxNp=G" list — context-dependent, so the registry carries only
/// this marker and psk_grid applies the old parse verbatim).
const PSK_G_ENV: i32 = -1;
/// G candidates: 0 = the built-in rule min(items, slots); else a CTA count (clamped to [1, items]).
const PSK_G_DOMAIN: &[i32] = &[0, 48, 96, 144, 192, 240, 288, 336, 384];
fn psk_g_valid(cx: &tune::Ctx, v: i32, members: u32) -> bool {
    if v <= 0 { return true; }
    let ks = chain_ks(cx.k, cx.n);
    let items = ((cx.n.max(0) as u32) / 128) * ks * members;
    ks > 1 && (v as u32) <= items
}
pub(crate) const T_PSK_G: tune::TunableDef = tune::TunableDef {
    slot: 25, id: "psk.g", class: tune::Class::S, scope: tune::Scope::Shape, fams: FAMS_CHAIN,
    domain: PSK_G_DOMAIN, default: 0, valid: |cx, v| psk_g_valid(cx, v, 1),
    xcheck: "--probe-exl3-binv EXL3-KS-P (G sweep) + --psk-xcheck",
    env: "--psk-g", env_parse: || tune::env_str(crate::opt!("psk-g")).map(|_| PSK_G_ENV), rev: 1, wp: "w3/PSK",
};
pub(crate) const T_PSK_G2: tune::TunableDef = tune::TunableDef {
    slot: 26, id: "psk.g_pair", class: tune::Class::S, scope: tune::Scope::Shape, fams: FAMS_CHAIN,
    domain: PSK_G_DOMAIN, default: 0, valid: |cx, v| psk_g_valid(cx, v, 2),
    xcheck: "--probe-exl3-binv EXL3-KS-P (pair G sweep) + --psk-xcheck",
    env: "--psk-g", env_parse: || tune::env_str(crate::opt!("psk-g")).map(|_| PSK_G_ENV), rev: 1, wp: "w3/PSK",
};
pub(crate) const T_PSK_PF: tune::TunableDef = tune::TunableDef {
    // p5e: per width (it pairs with psk.on in the tuner's joint grid; bitwise for every PF)
    slot: 27, id: "psk.pf", class: tune::Class::S, scope: tune::Scope::Width, fams: FAMS_CHAIN,
    domain: &[0, 1, 2, 3], default: 1, valid: tune::valid_any, xcheck: "--probe-exl3-binv EXL3-KS-P (PF 0/1/2)",
    env: "--psk-pf",
    env_parse: || tune::env_str(crate::opt!("psk-pf")).and_then(|v| v.trim().parse::<i32>().ok()).map(|v| v.clamp(0, 127)),
    rev: 1, wp: "w3/PSK",
};
/// Families whose graphs run split-K dense chains (every forward + the re-prime's fc slabs).
pub(crate) const FAMS_CHAIN: &[tune::Fam] = &[tune::Fam::Step, tune::Fam::Verify, tune::Fam::DraftPass,
                                              tune::Fam::DraftChain, tune::Fam::Reprime, tune::Fam::Util];
fn psk_xcheck() -> bool {
    static V: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *V.get_or_init(|| crate::opts::var(crate::opt!("psk-xcheck")).map_or(false, |v| !v.is_empty() && v != "0"))
}
/// --psk-g parse: (global G, per-shape [(K, N, pair, G)]). Malformed entries are ignored
/// (and reported once), never fatal.
fn psk_g_env() -> &'static (Option<u32>, Vec<(i32, i32, bool, u32)>) {
    static V: std::sync::OnceLock<(Option<u32>, Vec<(i32, i32, bool, u32)>)> = std::sync::OnceLock::new();
    V.get_or_init(|| {
        let Ok(raw) = crate::opts::var(crate::opt!("psk-g")) else { return (None, Vec::new()) };
        if let Ok(g) = raw.trim().parse::<u32>() { return (Some(g.max(1)), Vec::new()); }
        let mut v = Vec::new();
        for ent in raw.split(',').map(str::trim).filter(|e| !e.is_empty()) {
            let parsed = (|| {
                let (shape, g) = ent.split_once('=')?;
                let (k, n) = shape.trim().split_once(['x', 'X'])?;
                let (n, pair) = match n.trim().strip_suffix(['p', 'P']) { Some(n2) => (n2, true), None => (n.trim(), false) };
                Some((k.trim().parse::<i32>().ok()?, n.parse::<i32>().ok()?, pair, g.trim().parse::<u32>().ok()?.max(1)))
            })();
            match parsed {
                Some(e) => v.push(e),
                None => println!("EXL3-FWD PSK: ignoring malformed --psk-g entry {ent:?} (want KxN=G or KxNp=G)"),
            }
        }
        (None, v)
    })
}
/// Co-resident CTAs (occupancy API x SMs) of the two PSK kernels as compiled; 0 = query failed
/// (stale PTX) => that kernel is never launched (the old grid runs, consistently for all m).
fn psk_slots(dev: &Arc<CudaDevice>) -> (u32, u32) {
    static V: std::sync::OnceLock<(u32, u32)> = std::sync::OnceLock::new();
    *V.get_or_init(|| (wp11_capacity(dev, "exl3_hmma_gemm_ks_p"), wp11_capacity(dev, "exl3_hmma_gemm_ks_p_x2")))
}
/// Built-in grid rule: items = (N/128) * ks * members; G = min(items, slots) — one full wave of
/// persistent CTAs (slots = occupancy x 48 SMs, a multiple of 48), never more CTAs than items.
/// 0 = run the old kernel (PSK off, ks <= 1, or no measured capacity).
fn psk_grid(dev: &Arc<CudaDevice>, k: i32, n: i32, bits: i32, ks: u32, pair: bool) -> u32 {
    if psk_off() || ks <= 1 { return 0; }
    let items = ((n.max(0) as u32) / 128) * ks * if pair { 2 } else { 1 };
    let (s1, s2) = psk_slots(dev);
    let slots = if pair { s2 } else { s1 };
    if slots == 0 || items == 0 { return 0; }
    // TUNE: psk.g / psk.g_pair per (K, N, bits); the env alias (PSK_G_ENV) keeps the old parse
    let v = tune::get(if pair { &T_PSK_G2 } else { &T_PSK_G }, &tune::current().shape(k, n, bits));
    let g = if v == PSK_G_ENV {
        let env = psk_g_env();
        env.1.iter().find(|e| e.0 == k && e.1 == n && e.2 == pair).map(|e| e.3)
            .or(env.0)
            .unwrap_or_else(|| items.min(slots))
    } else if v > 0 {
        v as u32
    } else {
        items.min(slots)
    };
    g.clamp(1, items)
}
/// Kernel launch word: bits | ks << 8 | pf_d << 24 (mirrors PSK_CFG_* in exl3_bench.cu).
fn psk_cfg(bits: i32, ks: u32) -> i32 {
    (bits & 0xFF) | (((ks as i32) & 0xFFFF) << 8) | ((psk_pf() & 0x7F) << 24)
}
/// Bit-compare report for --psk-xcheck (fp32 partials, raw bits).
fn psk_xcheck_report(site: &str, new: &[f32], old: &[f32]) {
    use std::sync::atomic::{AtomicUsize, Ordering};
    static N: AtomicUsize = AtomicUsize::new(0);
    static BAD: AtomicUsize = AtomicUsize::new(0);
    let n = new.len().min(old.len());
    let mut mism = 0usize;
    let mut first: Option<usize> = None;
    for i in 0..n {
        if new[i].to_bits() != old[i].to_bits() {
            mism += 1;
            if first.is_none() { first = Some(i); }
        }
    }
    let k = N.fetch_add(1, Ordering::SeqCst) + 1;
    if mism > 0 { BAD.fetch_add(1, Ordering::SeqCst); }
    if mism > 0 || k % 500 == 0 || k == 1 {
        let fi = first.map_or(String::from("-"), |i| format!("{i} (new {:e} old {:e})", new[i], old[i]));
        println!("PSK_XCHECK {site}: checks {k} bad {} | this: n {n} mism {mism} first {fi}",
                 BAD.load(Ordering::SeqCst));
    }
}
/// --psk-xcheck (single): the old exl3_hmma_gemm_ks into a twin workspace, bit-diffed against
/// the PSK partials already in ws[..ks*m*n]. Skipped (noted once) while a graph is capturing.
/// `xh` = device address of the chain's first A row (p3c: raw, so REPRIME's wp22r1 row slabs
/// can check their own slab).
fn psk_xcheck_single(l: &Launcher, q: &Quad, xh: u64, ws: &CudaSlice<f32>, m: usize,
                     g: u32) -> Result<()> {
    if stream_capturing(l) {
        static ONCE: std::sync::Once = std::sync::Once::new();
        ONCE.call_once(|| println!("PSK_XCHECK: skipped inside graph capture (run eager: --exl3-no-graph=1)"));
        return Ok(());
    }
    let need = q.ks as usize * m * q.n as usize;
    let twin = l.dev.alloc_zeros::<f32>(need)?;       // every entry is written by the old kernel
    xqlaunch!(l, "exl3_hmma_gemm_ks", ((q.n as u32) / 128, q.ks, 1), (256, 1, 1), 0,
             (&q.tr, xh, &twin, m as i32, q.k, q.n, q.bits))?;
    l.dev.synchronize()?;
    let mut newp = vec![0f32; need];
    l.dev.dtoh_sync_copy_into(&ws.slice(0..need), &mut newp)?;
    let oldp = l.dev.dtoh_sync_copy(&twin)?;
    psk_xcheck_report(&format!("K{}xN{} b{} ks{} m{m} G{g}", q.k, q.n, q.bits, q.ks), &newp, &oldp);
    Ok(())
}
/// --psk-xcheck (pair): the old exl3_hmma_gemm_ks_x2 into twins, bit-diffed per member.
#[allow(clippy::too_many_arguments)]
fn psk_xcheck_pair(l: &Launcher, q0: &Quad, q1: &Quad, xh0: &CudaSlice<u16>, xh1: &CudaSlice<u16>,
                   ws0: &CudaSlice<f32>, ws1: &CudaSlice<f32>, m: usize, g: u32) -> Result<()> {
    if stream_capturing(l) {
        static ONCE: std::sync::Once = std::sync::Once::new();
        ONCE.call_once(|| println!("PSK_XCHECK: skipped inside graph capture (run eager: --exl3-no-graph=1)"));
        return Ok(());
    }
    let need = q0.ks as usize * m * q0.n as usize;
    let t0 = l.dev.alloc_zeros::<f32>(need)?;
    let t1 = l.dev.alloc_zeros::<f32>(need)?;
    xqlaunch!(l, "exl3_hmma_gemm_ks_x2", ((q0.n as u32) / 128, q0.ks, 2), (256, 1, 1), 0,
             (&q0.tr, &q1.tr, xh0, xh1, &t0, &t1, m as i32, q0.k, q0.n, q0.bits))?;
    l.dev.synchronize()?;
    let (mut n0, mut n1) = (vec![0f32; need], vec![0f32; need]);
    l.dev.dtoh_sync_copy_into(&ws0.slice(0..need), &mut n0)?;
    l.dev.dtoh_sync_copy_into(&ws1.slice(0..need), &mut n1)?;
    let (o0, o1) = (l.dev.dtoh_sync_copy(&t0)?, l.dev.dtoh_sync_copy(&t1)?);
    let site = format!("pair K{}xN{} b{} ks{} m{m} G{g}", q0.k, q0.n, q0.bits, q0.ks);
    psk_xcheck_report(&format!("{site} [0]"), &n0, &o0);
    psk_xcheck_report(&format!("{site} [1]"), &n1, &o1);
    Ok(())
}
/// Load-time log: the chosen G for every chain shape this model splits (singles, and the k/v +
/// shared gate/up pairs), once.
fn psk_log_shapes(dev: &Arc<CudaDevice>, layers: &[LayerDev], mtp: Option<&DraftHead>) {
    use std::collections::BTreeSet;
    if psk_off() {
        let why = if psk_escape() {
            if psk_opt_in() { "--psk-off=1 overrides --psk=1" } else { "--psk-off=1" }
        } else { "default" };
        let knobs: Vec<String> = [crate::opt!("psk-g"), crate::opt!("psk-pf"), crate::opt!("psk-xcheck")].into_iter()
            .filter(|k| crate::opts::var_os(*k).is_some()).map(|k| k.to_string()).collect();
        println!("EXL3-FWD PSK: OFF ({why}) — split-K chains run the old (N/128, ks) grids; \
                  --psk=1 = persistent split-K ON{}",
                 if knobs.is_empty() { String::new() } else { format!(" ({} ignored while OFF)", knobs.join("/")) });
        // TUNE T0c: a table value or the --autotune overlay can turn PSK on at some width — measure
        // the kernels' co-residency now, outside any graph capture
        if tune::reachable(&T_PSK_ON).contains(&1) { let _ = psk_slots(dev); }
        return;
    }
    let (s1, s2) = psk_slots(dev);
    let mut singles: BTreeSet<(i32, i32, i32, u32)> = BTreeSet::new();
    let mut pairs: BTreeSet<(i32, i32, i32, u32)> = BTreeSet::new();
    let mut visit = |attn: Option<&AttnLayer>, gdn: Option<&GdnLayer>, moe: &MoeLayer| {
        let mut one = |q: &Quad| { if q.ks > 1 { singles.insert((q.k, q.n, q.bits, q.ks)); } };
        if let Some(g) = gdn { one(&g.in_qkv); one(&g.in_z); one(&g.out_proj); }
        if let Some(a) = attn {
            one(&a.q_proj); one(&a.o_proj); one(&a.k_proj); one(&a.v_proj);
            if let Some(ix) = &a.idx { one(&ix.qk); }
        }
        one(&moe.sh_gate); one(&moe.sh_up); one(&moe.sh_down);
        let mut two = |a: &Quad, b: &Quad| {
            if a.ks > 1 && a.ks == b.ks && a.k == b.k && a.n == b.n && a.bits == b.bits {
                pairs.insert((a.k, a.n, a.bits, a.ks));
            }
        };
        if let Some(a) = attn { two(&a.k_proj, &a.v_proj); }
        two(&moe.sh_gate, &moe.sh_up);
    };
    for l in layers {
        match &l.mixer {
            Mixer::Gdn(g) => visit(None, Some(g), &l.moe),
            Mixer::Attn(a) => visit(Some(a), None, &l.moe),
        }
    }
    if let Some(h) = mtp {
        visit(Some(&h.attn), None, &h.moe);
        for q in [&h.fc_hidden, &h.fc_embed] { if q.ks > 1 { singles.insert((q.k, q.n, q.bits, q.ks)); } }
    }
    println!("EXL3-FWD PSK: persistent split-K ON (--psk=1; default OFF) — slots single {s1} / pair {s2} \
              (occupancy x SMs), trellis prefetch {} block(s) ahead; --psk-off=1 = old grids", psk_pf());
    for (set, pair) in [(&singles, false), (&pairs, true)] {
        for &(k, n, bits, ks) in set.iter() {
            let items = ((n as u32) / 128) * ks * if pair { 2 } else { 1 };
            let g = psk_grid(dev, k, n, bits, ks, pair);
            let slots = if pair { s2 } else { s1 };
            let rounds = if g > 0 { (items + g - 1) / g } else { 0 };
            println!("  PSK {} K={k:<5} N={n:<6} b{bits} ks={ks:<3} items {items:>4} -> G {g:>4}{}",
                     if pair { "pair  " } else { "single" },
                     if g == 0 { format!(" (old grid: capacity {slots})") }
                     else { format!(" ({rounds} item(s)/CTA max, {:.2} waves of {slots})", items as f32 / slots.max(1) as f32) });
        }
    }
}

/// S-A3-o C1: two same-input decode/verify chains (q0, q1 read the same x) in ONE launch
/// per stage (grid.z = member). Each member keeps its own suh/svh/trellis and the SAME ks
/// partition + ascending combine as exl3_chain, through the same device bodies => each
/// output is bitwise its exl3_chain result. Falls back to two exl3_chain calls unless both
/// members share (K, N, bits, ks > 1), m <= 16 and the pair buffers fit.
/// --exl3-chain-pair=0 = A/B escape (always two chains).
#[allow(clippy::too_many_arguments)]
fn exl3_chain_pair(l: &Launcher, q0: &Quad, q1: &Quad, x: &CudaSlice<u16>,
                   xh0: &mut CudaSlice<u16>, yraw0: &mut CudaSlice<u16>, ws0: &CudaSlice<f32>,
                   xh1: &mut CudaSlice<u16>, yraw1: &mut CudaSlice<u16>, ws1: &CudaSlice<f32>,
                   y0: &mut CudaSlice<u16>, y1: &mut CudaSlice<u16>, m: usize) -> Result<()> {
    let off = tune::get(&T_CHAIN_PAIR, &l.cx().shape(q0.k, q0.n, q0.bits)) == 0;
    if !off && m <= 16 && q0.ks > 1 && q1.ks > 1 && dense::dense_on() {
        // W4/DENSE: both members in ONE launch (suh + ks GEMM + combine + svh each), bitwise the
        // x2 path below. Ok(false) = not taken, nothing launched.
        use dense::{dptr, DOut};
        let o0 = DOut { y: dptr(y0), y_len: y0.len(), yraw: dptr(yraw0), yraw_len: yraw0.len(), xh: dptr(xh0), xh_len: xh0.len() };
        let o1 = DOut { y: dptr(y1), y_len: y1.len(), yraw: dptr(yraw1), yraw_len: yraw1.len(), xh: dptr(xh1), xh_len: xh1.len() };
        if dense::dense_chains(l, &[q0, q1], &[o0, o1], (dptr(x), x.len()), (0, 0), m,
                               &[(dptr(ws0), ws0.len()), (dptr(ws1), ws1.len())])? {
            return Ok(());
        }
    }
    let need_ws = q0.ks as usize * m * q0.n as usize;
    let ok = !off && m <= 16 && q0.ks > 1 && q0.ks == q1.ks && q0.k == q1.k && q0.n == q1.n
        && q0.bits == q1.bits && ((q0.k as u32) / 16) % q0.ks == 0
        && need_ws <= ws0.len() && need_ws <= ws1.len()
        && m * q0.k as usize <= xh1.len() && m * q0.n as usize <= yraw1.len();
    if !ok {
        exl3_chain(l, q0, x, xh0, yraw0, y0, m, ws0)?;
        return exl3_chain(l, q1, x, xh0, yraw0, y1, m, ws0);
    }
    let (k, n) = (q0.k, q0.n);
    xqlaunch!(l, "exl3_had_suh_x2", (m as u32 * (k as u32 / 128), 1, 2), (32, 1, 1), 0,
             (x, &q0.suh, &q1.suh, &mut *xh0, &mut *xh1, k))?;
    // w3-PSK: persistent pair grid (bitwise == exl3_hmma_gemm_ks_x2 for every G); 0 = old grid.
    // PSK is opt-in (--psk=1) and keeps the 3-launch tail (the WP21 fixup is not in its body).
    let g = psk_grid(l.dev, k, n, q0.bits, q0.ks, true);
    if g > 0 {
        // trailing &q0.tr / &q1.tr = the prefetch bases (same addresses; see PSK_CFG_* note)
        xqlaunch!(l, "exl3_hmma_gemm_ks_p_x2", (g, 1, 1), (256, 1, 1), 0,
                 (&q0.tr, &q1.tr, &*xh0, &*xh1, ws0, ws1, m as i32, k, n, psk_cfg(q0.bits, q0.ks),
                  &q0.tr, &q1.tr))?;
        if psk_xcheck() { psk_xcheck_pair(l, q0, q1, &*xh0, &*xh1, ws0, ws1, m, g)?; }
        let mn = (m * n as usize) as u32;
        xqlaunch!(l, "exl3_ks_combine_x2", ((mn + 255) / 256, 1, 2), (256, 1, 1), 0,
                 (ws0, ws1, &mut *yraw0, &mut *yraw1, m as i32, n, q0.ks as i32))?;
        xqlaunch!(l, "exl3_had_svh_x2", (m as u32 * (n as u32 / 128), 1, 2), (32, 1, 1), 0,
                 (&*yraw0, &*yraw1, &q0.svh, &q1.svh, &mut *y0, &mut *y1, n))?;
    } else if wp21_on(q0.ks) && wp21_pair_ok(q0, q1, n) {
        // WP21: ks GEMM + ascending combine + H128 svh in ONE launch (last-arriving CTA per
        // N-tile per member does the fixup) — bitwise the 3-launch path below.
        wp21_occupancy_once(l);
        wp21_launch_fx_x2(l, q0, q1, &*xh0, &*xh1, ws0, ws1, &mut *y0, &mut *y1, m)?;
        if wp21_xcheck() {
            wp21_check_pair(l, q0, q1, xh0, yraw0, ws0, xh1, yraw1, ws1, y0, y1, m)?;
        }
    } else {
        xqlaunch!(l, "exl3_hmma_gemm_ks_x2", ((n as u32) / 128, q0.ks, 2), (256, 1, 1), 0,
                 (&q0.tr, &q1.tr, &*xh0, &*xh1, ws0, ws1, m as i32, k, n, q0.bits))?;
        let mn = (m * n as usize) as u32;
        xqlaunch!(l, "exl3_ks_combine_x2", ((mn + 255) / 256, 1, 2), (256, 1, 1), 0,
                 (ws0, ws1, &mut *yraw0, &mut *yraw1, m as i32, n, q0.ks as i32))?;
        xqlaunch!(l, "exl3_had_svh_x2", (m as u32 * (n as u32 / 128), 1, 2), (32, 1, 1), 0,
                 (&*yraw0, &*yraw1, &q0.svh, &q1.svh, &mut *y0, &mut *y1, n))?;
    }
    if crate::opts::var(crate::opt!("exl3-chain-pair-check")).is_ok() {
        // diagnostic (eager only: --exl3-no-graph=1): pair outputs vs two plain chains
        let mn = m * n as usize;
        l.dev.synchronize()?;
        let p0 = l.dev.dtoh_sync_copy(&*y0)?;
        let p1 = l.dev.dtoh_sync_copy(&*y1)?;
        exl3_chain(l, q0, x, xh0, yraw0, y0, m, ws0)?;
        exl3_chain(l, q1, x, xh0, yraw0, y1, m, ws0)?;
        l.dev.synchronize()?;
        let r0 = l.dev.dtoh_sync_copy(&*y0)?;
        let r1 = l.dev.dtoh_sync_copy(&*y1)?;
        let bad = (0..mn).filter(|&i| p0[i] != r0[i] || p1[i] != r1[i]).count();
        use std::sync::atomic::{AtomicUsize, Ordering};
        static N: AtomicUsize = AtomicUsize::new(0);
        static BAD: AtomicUsize = AtomicUsize::new(0);
        let c = N.fetch_add(1, Ordering::SeqCst) + 1;
        if bad > 0 { BAD.fetch_add(1, Ordering::SeqCst); }
        if bad > 0 || c % 500 == 0 {
            println!("CHAIN_PAIR_CHECK: calls {c} bad {} (this: m {m} K {k} N {n} mism {bad})", BAD.load(Ordering::SeqCst));
        }
    }
    Ok(())
}

/// TUNE T0 (S24): the prefill wide-M chain's M-tiles per CTA (exl3_chain_impl m > 16, moe_prefill).
/// MT only regroups rows over CTAs — the per-row K-ascending mma sequence is unchanged (bitwise,
/// b7c8b3e; the B3 receipt's MT-by-chunk-size rule is the tuner's known-answer test).
/// p5e (PFX1 a): value 0 = the built-in rule — the B3 MT-by-chunk rule for the MoE expert GEMMs
/// (pfx1_moe_mt) and MT 4 for the dense wide chains; 1|2|4|8 = that MT for every wide launch of the
/// chunk class. The alias keeps PFX1's parse exactly (trimmed; only 1|2|4|8 count, else ignored).
pub(crate) const T_WIDE_MT: tune::TunableDef = tune::TunableDef {
    slot: 7, id: "prefill.wide_mt", class: tune::Class::S, scope: tune::Scope::Chunk, fams: &[tune::Fam::Prefill],
    domain: &[0, 1, 2, 4, 8], default: 0, valid: tune::valid_any, xcheck: "--probe-exl3-wide (mt sweep)",
    env: "--exl3-wide-mt",
    env_parse: || tune::env_str(crate::opt!("exl3-wide-mt"))
        .and_then(|v| match v.trim().parse::<usize>() { Ok(mt @ (1 | 2 | 4 | 8)) => Some(mt as i32), _ => None }),
    rev: 2, wp: "S-A3-f-b / PFX1",
};

/// A5-P2 (PLAN/notes_2026-09-27/P2.md): the prefill hc elementwise chain fused and regridded —
/// hc_post's inject deferred into the next hc_pre's norm (xq_pf_hc_inj_norm, 128-thread CTAs) and
/// the mix as xq_pf_hc_mix_2560x4. Bitwise == xq_hc_inject + xq_hc_norm / xq_hc_mix4 (same leaf
