/// Prefill-side chain that MAY take the reconstruct+cuBLASLt arm (rb present AND
/// --exl3-recon-min > 0 AND m >= min). Otherwise byte-identical to exl3_chain.
fn exl3_chain_rb(l: &Launcher, q: &Quad, x: &CudaSlice<u16>, xh: &mut CudaSlice<u16>,
                 yraw: &mut CudaSlice<u16>, y: &mut CudaSlice<u16>, m: usize,
                 ws: &CudaSlice<f32>, rb: &ReconBufs) -> Result<()> {
    // PFX1 (c): every prefill chain but the qsa indexer and the m = 1 lm_head goes through here
    // (m = c, or 4c for the head fc chains)
    pf_chain_check_n(q, m, xh, yraw)?;
    exl3_chain_impl(l, q, x, xh, yraw, y, m, ws, Some(rb))
}

/// PFX1 (c): a prefill chain's staging must fit the PrefillScratch buffers (m*K into chain_xh,
/// m*N into chain_yraw) — a loud error instead of an out-of-bounds write if a future chain
/// outgrows the max(c*12288, vocab) chain_yraw. The m = 1 prefill lm_head uses this form.
fn pf_chain_check(q: &Quad, m: usize, xh: &CudaSlice<u16>, yraw: &CudaSlice<u16>) -> Result<()> {
    anyhow::ensure!(m * q.k as usize <= xh.len() && m * q.n as usize <= yraw.len(),
                    "prefill chain m={m} K={} N={} exceeds chain_xh {} / chain_yraw {}",
                    q.k, q.n, xh.len(), yraw.len());
    Ok(())
}

/// PFX1 (c): pf_chain_check + N <= PF_CHAIN_NMAX — every m = c (or 4c) prefill chain site.
fn pf_chain_check_n(q: &Quad, m: usize, xh: &CudaSlice<u16>, yraw: &CudaSlice<u16>) -> Result<()> {
    anyhow::ensure!(q.n as usize <= PF_CHAIN_NMAX,
                    "prefill chain N={} exceeds PF_CHAIN_NMAX={PF_CHAIN_NMAX} (chain_yraw diet)", q.n);
    pf_chain_check(q, m, xh, yraw)
}

#[allow(clippy::too_many_arguments)]
fn exl3_chain_impl(l: &Launcher, q: &Quad, x: &CudaSlice<u16>, xh: &mut CudaSlice<u16>,
                   yraw: &mut CudaSlice<u16>, y: &mut CudaSlice<u16>, m: usize,
                   ws: &CudaSlice<f32>, rb: Option<&ReconBufs>) -> Result<()> {
    if m <= 16 && q.ks > 1 && dense::dense_on() {
        // W4/DENSE: the whole split-K chain (suh + ks GEMM + combine + svh) in ONE launch on the
        // LMH streaming body — bitwise this function's path below. Ok(false) = not taken, nothing
        // launched (shape / buffer / grid outside the kernel's class). Package default OFF (p5e;
        // opt-in --w4dense=1): then this block is skipped and the p3 path below runs.
        use dense::{dptr, DOut};
        let o = DOut { y: dptr(y), y_len: y.len(), yraw: dptr(yraw), yraw_len: yraw.len(), xh: dptr(xh), xh_len: xh.len() };
        if dense::dense_chains(l, &[q], &[o], (dptr(x), x.len()), (0, 0), m, &[(dptr(ws), ws.len())])? {
            return Ok(());
        }
    }
    xqlaunch!(l, "exl3_had_suh", (m as u32 * (q.k as u32 / 128), 1, 1), (32, 1, 1), 0, (x, &q.suh, &mut *xh, q.k))?;
    // W3/LMH: true when the persistent lm_head GEMM already applied the output Hadamard.
    let mut svh_done = false;
    if m <= 16 {
        // Decode/verify contract path (G-A3-5, batch invariance).
        // S-A3-f-f ITEM 2: chains with ks > 1 run the split-K body (grid
        // (N/128, ks), fp32 partials) + the fixed-order ascending combine. ks is a
        // pure function of (K, N): the reduction per row is IDENTICAL at every m,
        // so batch invariance holds; the order vs ks=1 differs (re-baseline
        // protocol, brief §5). ks == 1 (lm_head) keeps the ORIGINAL kernel,
        // byte-identical launch shape.
        if q.ks > 1 {
            let kb = (q.k as u32) / 16;
            anyhow::ensure!(kb % q.ks == 0, "chain ks {} does not divide kb {}", q.ks, kb);
            let need = q.ks as usize * m * q.n as usize;
            anyhow::ensure!(need <= ws.len(), "chain_ws too small: need {} have {}", need, ws.len());
            // w3-PSK: persistent grid (bitwise == exl3_hmma_gemm_ks for every G); 0 = old grid.
            // PSK is opt-in (--psk=1) and keeps the combine + svh tail (no WP21 fixup in its body).
            let g = psk_grid(l.dev, q.k, q.n, q.bits, q.ks, false);
            if g > 0 {
                // trailing &q.tr = the prefetch base (same address; see PSK_CFG_* note)
                xqlaunch!(l, "exl3_hmma_gemm_ks_p", (g, 1, 1), (256, 1, 1), 0,
                         (&q.tr, &*xh, ws, m as i32, q.k, q.n, psk_cfg(q.bits, q.ks), &q.tr))?;
                if psk_xcheck() { psk_xcheck_single(l, q, *xh.device_ptr() as u64, ws, m, g)?; }
            } else if wp21_on(q.ks) && wp21_cnt_ok(q) {
                // WP21: split-K fixup epilogue — the last-arriving CTA per N-tile does the
                // ascending combine + H128 svh in-launch (exl3_ks_combine and exl3_had_svh
                // are not launched; bitwise the same y). --wp21-off=1 = the path below.
                wp21_occupancy_once(l);
                xqlaunch!(l, "exl3_hmma_gemm_ks_fx", ((q.n as u32) / 128, q.ks, 1), (256, 1, 1), 0,
                         (&q.tr, &*xh, ws, &q.svh, &mut *y, &q.cnt, m as i32, q.k, q.n, q.bits))?;
                if wp21_xcheck() { wp21_check_single(l, q, xh, yraw, y, m, ws)?; }
                return Ok(());
            } else {
                xqlaunch!(l, "exl3_hmma_gemm_ks", ((q.n as u32) / 128, q.ks, 1), (256, 1, 1), 0,
                         (&q.tr, &mut *xh, ws, m as i32, q.k, q.n, q.bits))?;
            }
            let mn = (m * q.n as usize) as u32;
            xqlaunch!(l, "exl3_ks_combine", ((mn + 255) / 256, 1, 1), (256, 1, 1), 0,
                     (ws, &mut *yraw, m as i32, q.n, q.ks as i32))?;
        } else if q.lmh && !lmh_off() && {
            // W3/LMH: the lm_head class (ks == 1) — persistent 1-CTA/SM GEMM, bitwise ==
            // exl3_hmma_gemm (+ exl3_had_svh when fused). Ok(false) = ineligible -> old kernel.
            let out_p = if lmh_had() { *y.device_ptr() } else { *yraw.device_ptr() };
            lmh_gemm_launch(l.dev, l.stream.stream, *q.tr.device_ptr(), *xh.device_ptr(), out_p,
                            *q.svh.device_ptr(), m, q.k as usize, q.n as usize, q.bits as usize,
                            lmh_nst(), lmh_had())?
        } {
            svh_done = lmh_had();
            if lmh_xcheck() && !stream_capturing(l) {
                let got: &CudaSlice<u16> = if svh_done { &*y } else { &*yraw };
                lmh_xcheck_run(l, q, &*xh, got, m, svh_done)?;
            }
        } else {
            xqlaunch!(l, "exl3_hmma_gemm", ((q.n as u32) / 128, 1, 1), (256, 1, 1), 0, (&q.tr, &mut *xh, &mut *yraw, m as i32, q.k, q.n, q.bits))?;
        }
    } else {
        chain_wide_gemm(l, q, xh, yraw, m, rb)?;
    }
    if !svh_done {
        xqlaunch!(l, "exl3_had_svh", (m as u32 * (q.n as u32 / 128), 1, 1), (32, 1, 1), 0, (&mut *yraw, &q.svh, &mut *y, q.n))?;
    }
    Ok(())
}

/// TP-B: the m > 16 chain up to y_raw (had_suh + the wide / recon GEMM), no output transform —
/// the row-parallel prefill partial (xtp::chain_rowpar).
fn chain_wide_raw(l: &Launcher, q: &Quad, x: &CudaSlice<u16>, xh: &mut CudaSlice<u16>,
                  yraw: &mut CudaSlice<u16>, m: usize, rb: Option<&ReconBufs>) -> Result<()> {
    anyhow::ensure!(m > 16, "chain_wide_raw is the m > 16 arm");
    xqlaunch!(l, "exl3_had_suh", (m as u32 * (q.k as u32 / 128), 1, 1), (32, 1, 1), 0, (x, &q.suh, &mut *xh, q.k))?;
    chain_wide_gemm(l, q, xh, yraw, m, rb)
}

/// The m > 16 GEMM of exl3_chain_impl (xh -> y_raw), factored out for chain_wide_raw.
fn chain_wide_gemm(l: &Launcher, q: &Quad, xh: &mut CudaSlice<u16>, yraw: &mut CudaSlice<u16>, m: usize,
                   rb: Option<&ReconBufs>) -> Result<()> {
    {
        // S-A3-f-g dispatch: reconstruct+cuBLASLt when the caller supplied buffers
        // AND --exl3-recon-min > 0 AND m >= the threshold; else the wide-M
        // trellis kernel (S-A3-f-b) — row-wise bitwise equal to the m16 body.
        let rmin = recon_min_rows();
        let recon = match rb {
            Some(r) if rmin > 0 && m >= rmin => Some(r),
            _ => None,
        };
        if let Some(r) = recon {
            let need = (q.k as usize) * (q.n as usize);
            anyhow::ensure!(need <= r.ws_len,
                "recon staging too small: need {need} have {}", r.ws_len);
            exl3_reconstruct(l, *q.tr.device_ptr() as u64, r.rc, r.ws, q.k, q.n, q.bits)?;
            exl3_lt_matmul(l, r.ws, *xh.device_ptr() as u64, *yraw.device_ptr() as u64,
                           q.k as usize, q.n as usize, m, false, r.ltws, r.ltws_len)?;
        } else {
            // S-A3-f-b chunked prefill (M > 16): wide-M kernel — row-wise bitwise
            // equal to the m16 body (same decode, same fixed K-ascending mma
            // sequence per element); gated by --probe-exl3-wide before serving use.
            // Decode/verify (m <= 16) never reaches this arm; AGENTS §6 discipline.
            // (dense chains: only reached with --exl3-recon-min=0 or no recon buffers; the
            // PFX1 MT rule is calibrated on the MoE rows and does not apply here)
            // TUNE S24: prefill.wide_mt (0 = the built-in value 4 here; 1|2|4|8 = a fixed MT)
            let mt: usize = match tune::get(&T_WIDE_MT, &l.cx()) { v @ (1 | 2 | 4 | 8) => v as usize, _ => 4 };
            let msup = (m + 16 * mt - 1) / (16 * mt);
            xqlaunch!(l, "exl3_hmma_gemm_wide", (msup as u32, (q.n as u32) / 128, 1), (256, 1, 1), 0, (&q.tr, &mut *xh, &mut *yraw, m as i32, q.k, q.n, q.bits, mt as i32))?;
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Load
// ---------------------------------------------------------------------------

impl FwdModel {
    pub fn load(pack_dir: &str, width: usize, max_pos: usize) -> Result<Arc<FwdModel>> {
        Self::load_tp(pack_dir, width, max_pos, None)
    }

    /// TP-A: `load` with an optional tensor-parallel attachment (rank/world + the RDMA link). With
    /// `tp = Some`, every TRUNK MoE layer loads only this rank's statically dealt routed experts
    /// (xtp::ep_local_experts; load-time shape asserts in xtp::EpShard::new) and the link is
    /// attached (payload set, proxy thread spawned) before the model is returned. Everything else
    /// (hc mixers, router, shared expert, attention/GDN, lm_head, PLE, the MTP head) is REPLICATED.
    pub fn load_tp(pack_dir: &str, width: usize, max_pos: usize, tp: Option<xtp::TpAttach>) -> Result<Arc<FwdModel>> {
        // TUNE §4.6: the table is frozen before any knob is read (Load-scope knobs are read below);
        // entry points that booted no table run the built-in defaults (today's behaviour).
        tune::ensure_frozen("FwdModel::load");
        let pack = Exl3Pack::open(pack_dir)?;
        // B32: a shard dir (gb10_shard.json) must be THIS attach's (format, world, rank); a whole pack passes.
        let shard_info = match tp.as_ref() {
            Some(a) => crate::shard_plan::check_shard_dir(std::path::Path::new(pack_dir),
                crate::shard_plan::ShardFormat::Exl3, a.world as usize, a.rank as usize)?,
            None => crate::shard_plan::read_shard_info(std::path::Path::new(pack_dir))?
                .map(|i| -> Result<_> { anyhow::bail!("{pack_dir} is a B32 shard dir (rank {} of world {}) — it cannot be loaded without TP", i.rank, i.world) })
                .transpose()?,
        };
        let shard_tag = shard_info.as_ref().map(|i| format!(" (B32 shard dir: exl3 rank {} of world {}, deal {} — the head's shipped plan omitted it)", i.rank, i.world, i.deal)).unwrap_or_default();
        let cfg = pack.cfg.clone();
        let kv_fmt = kv_fmt_from_opts();
        let dev = CudaDevice::new(0).context("CudaDevice::new(0)")?;
        crate::exl3_bench::load_module_pub(&dev)?;
        // A5 WP20: log the MoE expert-path plan for this model + verify the pinned suh sequence
        // eagerly (before any graph capture can be the first eligible call).
        wp20_announce(&dev, &cfg);
        // TUNE T0 / AUTOTUNE_DESIGN finding §14.1: the served EXL3 modules had no stale-kernel
        // handshake — a fresh binary next to an old exl3_bench.ptx ran silently whenever the kernel
        // NAMES still resolved. Launch the loaded module's kernel_build_id and compare.
        crate::gpu::GpuModel::assert_kernel_build_id(&dev, MODULE)
            .context("EXL3 kernel handshake (exl3_bench)")?;
        w4moe_announce(&dev, &cfg, width); // W4/MOE: opt in + plan the persistent expert kernels (outside any capture)
        pfx1_announce(); // PFX1: live parts + the MoE prefill MT rule, once
        w4qsa_announce(); // W4/QSA: one boot line with the verify gather in use (feature marker)
        // S-A3-i: the selection chain reuses the gpu_batch-side qsa_* kernels. In serve mode
        // gpu.rs has already loaded the module; in bench/probe mode nothing else does, so
        // load it here with just the four names (idempotent guard via get_func).
        if dev.get_func("gpu_batch", "qsa_key_write_b").is_none() {
            let ptx = cudarc::nvrtc::Ptx::from_src(
                std::fs::read_to_string("src/ptx/gpu_batch.ptx")
                    .context("src/ptx/gpu_batch.ptx missing — run cargo build --release")?,
            );
            dev.load_ptx(ptx, "gpu_batch", &["qsa_key_write_b", "qsa_score_b", "qsa_block_keys_b", "qsa_score_prefill_b",
                                            "qsa_pool_update_b", "qsa_pool_range_b", "qsa_score_pooled_b",
                                            "qsa_score_pooled_mr"])
                .context("load gpu_batch module (qsa subset)")?;
        }

        // TUNE T0 (§14.1): the gpu_batch half of the EXL3 stale-kernel handshake.
        tune::assert_gpu_batch_build_id(&dev).context("EXL3 kernel handshake (gpu_batch)")?;
        let h = cfg.hidden_size;

        let mut plain: BTreeMap<String, PlainTensor> = BTreeMap::new();
        for s in &pack.shards {
            for (k, mut v) in read_hdr(&format!("{}/{}", pack_dir.trim_end_matches('/'), s))? {
                v.shard = s.clone(); // B32: the index's RELATIVE path (a shard dir keeps its segments under seg/)
                plain.entry(k).or_insert(v);
            }
        }
        let modules: BTreeMap<&str, &ModuleMeta> =
            pack.modules.iter().map(|m| (m.name.as_str(), m)).collect();

        let t_load = std::time::Instant::now();
        println!(
            "EXL3-FWD load: {} layers ({} gdn / {} attn), {} experts, hc={} hidden={} vocab={}",
            cfg.layer_types.len(),
            cfg.layer_types.iter().filter(|l| matches!(l, crate::qwen::LayerType::LinearAttention)).count(),
            cfg.layer_types.iter().filter(|l| matches!(l, crate::qwen::LayerType::FullAttention)).count(),
            cfg.num_experts,
            cfg.hc_count,
            h,
            cfg.vocab_size
        );

        let get_plain_f16 = |name: &str| -> Result<CudaSlice<u16>> {
            let t = plain.get(name).with_context(|| format!("missing plain tensor {name}"))?;
            let bits = to_f16_bits(&t.read(pack_dir)?, &t.dtype)?;
            Ok(dev.htod_sync_copy(&bits)?)
        };
        let get_f32_bf16 = |name: &str| -> Result<CudaSlice<f32>> {
            let t = plain.get(name).with_context(|| format!("missing plain tensor {name}"))?;
            Ok(dev.htod_sync_copy(&bf16_to_f32(&t.read(pack_dir)?))?)
        };
        let get_quad = |name: &str| -> Result<Quad> {
            let m = modules.get(name).with_context(|| format!("missing quad module {name}"))?;
            let tr: Vec<u16> = m
                .trellis
                .read_bytes(pack_dir)?
                .chunks_exact(2)
                .map(|c| u16::from_le_bytes([c[0], c[1]]))
                .collect();
            let (qk, qn) = (m.k as i32, m.n as i32);
            Ok(Quad {
                tr: dev.htod_sync_copy(&tr)?,
                suh: dev.htod_sync_copy(&le_f16_bits(&m.suh.read_bytes(pack_dir)?))?,
                svh: dev.htod_sync_copy(&le_f16_bits(&m.svh.read_bytes(pack_dir)?))?,
                bits: m.bits as i32,
                k: qk,
                n: qn,
                ks: chain_ks(qk, qn),
                lmh: false,
                cnt: dev.htod_sync_copy(&vec![0u32; ((qn.max(0) as usize) / 128).max(1)])?, // W4/DENSE, explicit zero
                rowpar: false,
            })
        };

        // TP-B: this rank's trunk shard (None = TP=1: every trunk tensor whole) + the TRUNK's
        // per-rank geometry (local head counts; == cfg at TP=1). The MTP head keeps `cfg`.
        let tp_rw: Option<(usize, usize)> = tp.as_ref().map(|t| (t.rank as usize, t.world as usize));
        let tsplit = tp_rw.map(|(rank, world)| xtp::TrunkSplit { rank, world });
        let tc = match tp_rw { Some((_, w)) => xtp::trunk_cfg(&cfg, w)?, None => cfg.clone() };
        // ShardSpec::{Col, Row} quad: `rows` / `cols` = element ranges (128-aligned, refused
        // otherwise), None = whole. A copy of whole 16x16 trellis blocks + the matching suh / svh
        // slices — never a requant (G-T1-0). `rowpar` marks the K-sliced (partial-output) class.
        let get_quad_sl = |name: &str, rows: Option<&[(usize, usize)]>, cols: Option<&[(usize, usize)]>,
                           rowpar: bool| -> Result<Quad> {
            let m = modules.get(name).with_context(|| format!("missing quad module {name}"))?;
            let tr: Vec<u16> = m.trellis.read_bytes(pack_dir)?.chunks_exact(2)
                .map(|c| u16::from_le_bytes([c[0], c[1]])).collect();
            let suh = le_f16_bits(&m.suh.read_bytes(pack_dir)?);
            let svh = le_f16_bits(&m.svh.read_bytes(pack_dir)?);
            let (kb, nb) = (m.k / 16, m.n / 16);
            anyhow::ensure!(tr.len() == kb * nb * 16 * m.bits && suh.len() == m.k && svh.len() == m.n,
                "{name}: trellis/suh/svh shapes do not match k={} n={} bits={}", m.k, m.n, m.bits);
            let rr = match rows { Some(r) => xtp::r16(r)?, None => vec![(0, kb)] };
            let cc = match cols { Some(c) => xtp::r16(c)?, None => vec![(0, nb)] };
            anyhow::ensure!(rr.iter().all(|&(_, b)| b <= kb) && cc.iter().all(|&(_, b)| b <= nb),
                "{name}: slice outside k={} n={}", m.k, m.n);
            let t2 = xtp::slice_trellis(&tr, nb, m.bits, &rr, &cc);
            let suh2: Vec<u16> = rr.iter().flat_map(|&(a, b)| (a * 16..b * 16).map(|i| suh[i])).collect();
            let svh2: Vec<u16> = cc.iter().flat_map(|&(a, b)| (a * 16..b * 16).map(|i| svh[i])).collect();
            let (qk, qn) = (suh2.len() as i32, svh2.len() as i32);
            anyhow::ensure!(t2.len() == (qk as usize / 16) * (qn as usize / 16) * 16 * m.bits,
                "{name}: sliced trellis {} words != {}x{} blocks", t2.len(), qk / 16, qn / 16);
            Ok(Quad {
                tr: dev.htod_sync_copy(&t2)?,
                suh: dev.htod_sync_copy(&suh2)?,
                svh: dev.htod_sync_copy(&svh2)?,
                bits: m.bits as i32,
                k: qk,
                n: qn,
                // TP-I #8: a TP-sliced quad may take the TP split-K target (unset = chain_ks)
                ks: if tp_rw.is_some() { xtp::tp_chain_ks(qk, qn) } else { chain_ks(qk, qn) },
                lmh: false,
                cnt: dev.htod_sync_copy(&vec![0u32; ((qn.max(0) as usize) / 128).max(1)])?,
                rowpar,
            })
        };
        let plain_bits = |name: &str| -> Result<Vec<u16>> {
            let t = plain.get(name).with_context(|| format!("missing plain tensor {name}"))?;
            to_f16_bits(&t.read(pack_dir)?, &t.dtype)
        };
        let plain_f32_bf16 = |name: &str| -> Result<Vec<f32>> {
            let t = plain.get(name).with_context(|| format!("missing plain tensor {name}"))?;
            Ok(bf16_to_f32(&t.read(pack_dir)?))
        };

        let emb_name = plain
            .keys()
            .find(|k| k.ends_with("embed_tokens.weight"))
            .context("embed_tokens.weight not found")?
            .clone();
        let embed = get_plain_f16(&emb_name)?;

        let mut layers = Vec::new();
        // S-A3-i: per-full-attn-layer raw-key planes, in layer order (attn layers only).
        let mut qsa_keys_vec: Vec<CudaSlice<u16>> = Vec::new();
        let mut qsa_pool_vec: Vec<CudaSlice<u16>> = Vec::new();
        let pool_on = crate::opts::var(crate::opt!("qsa-pool")).as_deref() != Ok("0")
            && dev.get_func("gpu_batch", "qsa_pool_update_b").is_some()
            && dev.get_func("gpu_batch", "qsa_score_pooled_b").is_some();
        let mut qsa_keys_plane: Option<CudaSlice<u16>> = None;
        let mut qsa_pool_plane: Option<CudaSlice<u16>> = None;
        let mut bytes_round = 0u64;
        // Stacked-experts loader, shared by the trunk layers and the MTP draft head (S-A3-e M1).
        let mk_moe = |p: String, tag: String, ep_rank: Option<(usize, usize)>| -> Result<MoeLayer> {
            let ne = cfg.num_experts;
            let mi = cfg.moe_intermediate_size;
            // TP-A: this rank's routed experts in LOCAL stacked order (all of them when replicated).
            // TP-I #6: the deal may be per layer (--ep-deal=freq); the MTP head is never EP.
            let li: usize = tag.strip_prefix('L').and_then(|v| v.parse().ok()).unwrap_or(usize::MAX);
            let local: Vec<usize> = match ep_rank {
                Some((r, w)) => xtp::ep_local_experts(ne, r, w, li)?,
                None => (0..ne).collect(),
            };
            // TP-B: shared-expert intermediate range of this rank (EP layers only; --tp-shared-repl=1
            // keeps TP-A's replicated shared expert — a diagnostic A/B, rides TpConfig.exl3_env).
            let sh_split: Option<(usize, usize)> = match ep_rank {
                Some((r, w)) if crate::opts::var(crate::opt!("tp-shared-repl")).is_err() =>
                    Some(xtp::TrunkSplit { rank: r, world: w }.shared(mi)?),
                _ => None,
            };
            let mut gu_words = 0u64;
            let mut d_words = 0u64;
            let mut gu_tr_h: Vec<u16> = Vec::new();
            let mut d_tr_h: Vec<u16> = Vec::new();
            let mut suh_gu_h: Vec<u16> = Vec::with_capacity(ne * 2560);
            let mut svh_gu_h: Vec<u16> = Vec::with_capacity(ne * mi * 2);
            let mut suh_d_h: Vec<u16> = Vec::with_capacity(ne * mi);
            let mut svh_d_h: Vec<u16> = Vec::with_capacity(ne * 2560);
            for &e in &local {
                let gname = format!("{p}.experts.{e}.gate_proj");
                let g = modules.get(gname.as_str()).with_context(|| format!("expert {e} gate ({gname}) missing @{tag}{shard_tag}"))?;
                let u = modules
                    .get(format!("{p}.experts.{e}.up_proj").as_str())
                    .with_context(|| format!("expert {e} up ({p}.experts.{e}.up_proj) missing @{tag}{shard_tag}"))?;
                let d = modules
                    .get(format!("{p}.experts.{e}.down_proj").as_str())
                    .with_context(|| format!("expert {e} down ({p}.experts.{e}.down_proj) missing @{tag}{shard_tag}"))?;
                if g.bits != u.bits || g.n != mi || u.n != mi || d.k != mi {
                    bail!("expert geometry mismatch @{tag} e{e}");
                }
                let gw = 16 * g.bits;
                let kb = g.k / 16;
                let gnb = g.n / 16;
                let g_tr: Vec<u16> = g
                    .trellis
                    .read_bytes(pack_dir)?
                    .chunks_exact(2)
                    .map(|c| u16::from_le_bytes([c[0], c[1]]))
                    .collect();
                let u_tr: Vec<u16> = u
                    .trellis
                    .read_bytes(pack_dir)?
                    .chunks_exact(2)
                    .map(|c| u16::from_le_bytes([c[0], c[1]]))
                    .collect();
                for r in 0..kb {
                    gu_tr_h.extend_from_slice(&g_tr[r * gnb * gw..(r + 1) * gnb * gw]);
                    gu_tr_h.extend_from_slice(&u_tr[r * gnb * gw..(r + 1) * gnb * gw]);
                }
                d_tr_h.extend(
                    d.trellis
                        .read_bytes(pack_dir)?
                        .chunks_exact(2)
                        .map(|c| u16::from_le_bytes([c[0], c[1]])),
                );
                suh_gu_h.extend(le_f16_bits(&g.suh.read_bytes(pack_dir)?));
                svh_gu_h.extend(le_f16_bits(&g.svh.read_bytes(pack_dir)?));
                svh_gu_h.extend(le_f16_bits(&u.svh.read_bytes(pack_dir)?));
                suh_d_h.extend(le_f16_bits(&d.suh.read_bytes(pack_dir)?));
                svh_d_h.extend(le_f16_bits(&d.svh.read_bytes(pack_dir)?));
                gu_words = (kb * gnb * 2 * gw) as u64;
                d_words = ((d.k / 16) * (d.n / 16) * 16 * d.bits) as u64;
            }
            Ok(MoeLayer {
                router: get_plain_f16(&format!("{p}.gate.weight"))?,
                sg: get_plain_f16(&format!("{p}.shared_expert_gate.weight"))?,
                gu_tr: dev.htod_sync_copy(&gu_tr_h)?,
                d_tr: dev.htod_sync_copy(&d_tr_h)?,
                suh_gu: dev.htod_sync_copy(&suh_gu_h)?,
                svh_gu: dev.htod_sync_copy(&svh_gu_h)?,
                suh_d: dev.htod_sync_copy(&suh_d_h)?,
                svh_d: dev.htod_sync_copy(&svh_d_h)?,
                // TP-B: the shared expert's intermediate is dealt 384 | 256 (uneven 128-block, G-T1-0)
                // on EP layers — gate/up column slices, down row slice. Its partial needs NO extra
                // reduce: each rank adds sgv * its own partial inside the EP combine, and the MoE
                // layer's one all-reduce sums them (xtp::EpShard::shared_split).
                sh_gate: match sh_split { Some(r) => get_quad_sl(&format!("{p}.shared_expert.gate_proj"), None, Some(&[r]), false)?,
                                          None => get_quad(&format!("{p}.shared_expert.gate_proj"))? },
                sh_up: match sh_split { Some(r) => get_quad_sl(&format!("{p}.shared_expert.up_proj"), None, Some(&[r]), false)?,
                                        None => get_quad(&format!("{p}.shared_expert.up_proj"))? },
                sh_down: match sh_split { Some(r) => get_quad_sl(&format!("{p}.shared_expert.down_proj"), Some(&[r]), None, false)?,
                                          None => get_quad(&format!("{p}.shared_expert.down_proj"))? },
                gu_words,
                d_words,
                li,
                ep: match ep_rank {
                    Some((r, w)) => {
                        let mut e = xtp::EpShard::new(&dev, ne, r, w, &local, &tag,
                                                      gu_tr_h.len(), d_tr_h.len(), suh_gu_h.len(), svh_gu_h.len(),
                                                      suh_d_h.len(), svh_d_h.len(), gu_words, d_words,
                                                      cfg.hidden_size, mi)?;
                        e.shared_split = sh_split.is_some();
                        Some(e)
                    }
                    None => None,
                },
            })
        };
        for (li, lt) in cfg.layer_types.iter().enumerate() {
            let p = format!("model.language_model.layers.{li}");
            let mut mk_hc = |base: String, inject: bool| -> Result<HcDev> {
                bytes_round += 2 * (320 * 10240 + 10240 * 320) as u64 * 2;
                Ok(HcDev {
                    norm: get_plain_f16(&format!("{base}.hc_norm.weight"))?,
                    down: get_plain_f16(&format!("{base}.input_mix_weight_down.weight"))?,
                    up: get_plain_f16(&format!("{base}.input_mix_weight_up.weight"))?,
                    winj: if inject {
                        Some(get_plain_f16(&format!("{base}.block_inject_weight.weight"))?)
                    } else {
                        None
                    },
                    q8: None,
                })
            };
            let hc_attn = mk_hc(format!("{p}.attn_hyper_connection"), true)?;
            let hc_mlp = mk_hc(format!("{p}.mlp_hyper_connection"), true)?;

            let mixer = match lt {
                crate::qwen::LayerType::LinearAttention if tsplit.is_some() => {
                    // TP-B: this rank's GDN heads (design §1.3): in_qkv re-tiled [q | k | v] of its
                    // key/value head groups, in_z its value heads' columns, out_proj their ROWS
                    // (row-parallel partial -> one FP32 all-reduce), a|b rows + A_log/dt_bias of its
                    // value heads, conv1d over its qkv channels; the gated-norm weight is per-dim.
                    let ts = tsplit.as_ref().unwrap();
                    bytes_round += (2560 * 10240 + 2560 * 6144 + 6144 * 2560) as u64 * 5 / 8 / ts.world as u64;
                    let qkv = ts.gdn_qkv(&cfg);
                    let vr = ts.gdn_v(&cfg);
                    let (h0, h1) = ts.gdn_heads(&cfg);
                    let rows_of = |v: Vec<u16>, rw: usize| -> Vec<u16> { v[h0 * rw..h1 * rw].to_vec() };
                    let a_w = rows_of(plain_bits(&format!("{p}.linear_attn.in_proj_a.weight"))?, h);
                    let b_w = rows_of(plain_bits(&format!("{p}.linear_attn.in_proj_b.weight"))?, h);
                    let a_log = plain_f32_bf16(&format!("{p}.linear_attn.A_log"))?;
                    let dt_bias = plain_f32_bf16(&format!("{p}.linear_attn.dt_bias"))?;
                    let conv_w = plain_f32_bf16(&format!("{p}.linear_attn.conv1d.weight"))?;
                    let ck = cfg.conv_kernel;
                    let conv_full = cfg.key_dim() * 2 + cfg.value_dim();
                    anyhow::ensure!(a_log.len() == cfg.lin_num_v_heads && dt_bias.len() == cfg.lin_num_v_heads
                                    && conv_w.len() == conv_full * ck,
                        "TP-B GDN L{li}: A_log {} dt_bias {} conv {} vs nv {} conv_dim*ck {}",
                        a_log.len(), dt_bias.len(), conv_w.len(), cfg.lin_num_v_heads, conv_full * ck);
                    let conv_l: Vec<f32> = qkv.iter().flat_map(|&(a, b)| conv_w[a * ck..b * ck].iter().copied()).collect();
                    let norm_bits = plain_bits(&format!("{p}.linear_attn.norm.weight"))?;
                    anyhow::ensure!(norm_bits.len() == cfg.lin_v_dim,
                        "TP-B GDN L{li}: gated-norm weight len {} != v_dim {} (per-head norms would need a slice)",
                        norm_bits.len(), cfg.lin_v_dim);
                    let g = GdnLayer {
                        in_qkv: get_quad_sl(&format!("{p}.linear_attn.in_proj_qkv"), None, Some(&qkv), false)?,
                        in_z: get_quad_sl(&format!("{p}.linear_attn.in_proj_z"), None, Some(&[vr]), false)?,
                        out_proj: get_quad_sl(&format!("{p}.linear_attn.out_proj"), Some(&[vr]), None, true)?,
                        a_w: dev.htod_sync_copy(&a_w)?,
                        b_w: dev.htod_sync_copy(&b_w)?,
                        a_log: dev.htod_sync_copy(&a_log[h0..h1])?,
                        dt_bias: dev.htod_sync_copy(&dt_bias[h0..h1])?,
                        conv_w: dev.htod_sync_copy(&conv_l)?,
                        norm: dev.htod_sync_copy(&norm_bits)?,
                    };
                    // load-time shape asserts (design §1.3: the boot fails on a mismatch)
                    let conv_l_dim = tc.key_dim() * 2 + tc.value_dim();
                    anyhow::ensure!(g.in_qkv.n as usize == conv_l_dim && g.in_z.n as usize == tc.value_dim()
                                    && g.out_proj.k as usize == tc.value_dim() && g.out_proj.n as usize == h
                                    && g.a_w.len() == tc.lin_num_v_heads * h && g.conv_w.len() == conv_l_dim * ck,
                        "TP-B GDN L{li}: per-rank shapes (qkv {} z {} out {}x{} a {} conv {}) != local geometry \
                         (conv_dim {conv_l_dim}, value_dim {}, nv {}) — refusing to boot",
                        g.in_qkv.n, g.in_z.n, g.out_proj.k, g.out_proj.n, g.a_w.len(), g.conv_w.len(),
                        tc.value_dim(), tc.lin_num_v_heads);
                    Mixer::Gdn(g)
                }
                crate::qwen::LayerType::LinearAttention => {
                    bytes_round += (2560 * 10240 + 2560 * 6144 + 6144 * 2560) as u64 * 5 / 8;
                    Mixer::Gdn(GdnLayer {
                        in_qkv: get_quad(&format!("{p}.linear_attn.in_proj_qkv"))?,
                        in_z: get_quad(&format!("{p}.linear_attn.in_proj_z"))?,
                        out_proj: get_quad(&format!("{p}.linear_attn.out_proj"))?,
                        a_w: get_plain_f16(&format!("{p}.linear_attn.in_proj_a.weight"))?,
                        b_w: get_plain_f16(&format!("{p}.linear_attn.in_proj_b.weight"))?,
                        a_log: get_f32_bf16(&format!("{p}.linear_attn.A_log"))?,
                        dt_bias: get_f32_bf16(&format!("{p}.linear_attn.dt_bias"))?,
                        conv_w: get_f32_bf16(&format!("{p}.linear_attn.conv1d.weight"))?,
                        norm: get_plain_f16(&format!("{p}.linear_attn.norm.weight"))?,
                    })
                }
                crate::qwen::LayerType::FullAttention => {
                    if tsplit.is_none() { bytes_round += (2560 * 13312 + 6144 * 2560) as u64 * 5 / 8; }
                    let qn_t = plain.get(&format!("{p}.self_attn.q_norm.weight")).context("q_norm")?;
                    let kn_t = plain.get(&format!("{p}.self_attn.k_norm.weight")).context("k_norm")?;
                    let qn = to_f16_bits(&qn_t.read(pack_dir)?, &qn_t.dtype)?;
                    let kn = to_f16_bits(&kn_t.read(pack_dir)?, &kn_t.dtype)?;
                    let qnkn: Vec<u16> = qn.into_iter().chain(kn).collect();
                    // S-A3-i: load the QSA indexer (the qwen4_exp native attention)
                    // when the pack carries one. The raw-key plane is per-slot bf16
                    // [width][max_pos][hdx], explicitly zeroed (alloc_zeros does NOT).
                    let idx = if cfg.has_indexer() {
                        let f32_of = |name: &str| -> Result<CudaSlice<f32>> {
                            let t = plain.get(&format!("{p}.self_attn.indexer.{name}.weight"))
                                .with_context(|| format!("indexer {name}"))?;
                            let bits = to_f16_bits(&t.read(pack_dir)?, &t.dtype)?;
                            let v: Vec<f32> = bits.iter().map(|b| h16_to_f32(*b)).collect();
                            Ok(dev.htod_sync_copy(&v)?)
                        };
                        Some(IndexerDev {
                            qk: get_quad(&format!("{p}.self_attn.indexer.index_qk_proj"))?,
                            qn: f32_of("q_layernorm")?,
                            kn: f32_of("k_layernorm")?,
                            params: None, // built once the rope tables exist (after cos_tab)
                        })
                    } else { None };
                    if idx.is_some() {
                        let plane = width * max_pos * cfg.indexer_head_dim;
                        qsa_keys_plane = Some(dev.htod_sync_copy(&vec![0u16; plane])?);
                        if pool_on {
                            // WP02: ceil (the partial last block of a window that is not a multiple of
                            // the ratio has a home; the per-slot stride stays max_pos/ratio).
                            let pl = width * max_pos.div_ceil(cfg.indexer_compress_ratio).max(1) * cfg.indexer_head_dim;
                            qsa_pool_plane = Some(dev.htod_sync_copy(&vec![0u16; pl])?);
                        }
                    }
                    match tsplit.as_ref() {
                        // TP-B: this rank's query heads (q|gate columns), its KV head (k/v columns;
                        // the KV cache holds only it), o_proj ROWS (row-parallel partial -> one FP32
                        // all-reduce). q/k norms are per head-dim (replicated); the QSA indexer is
                        // replicated (the selection is per layer, shared by all heads — design §1.3).
                        Some(ts) => {
                            let (qr, kvr, orr) = (ts.attn_q(&cfg), ts.attn_kv(&cfg)?, ts.attn_o(&cfg));
                            let a = AttnLayer {
                                q_proj: get_quad_sl(&format!("{p}.self_attn.q_proj"), None, Some(&[qr]), false)?,
                                k_proj: get_quad_sl(&format!("{p}.self_attn.k_proj"), None, Some(&[kvr]), false)?,
                                v_proj: get_quad_sl(&format!("{p}.self_attn.v_proj"), None, Some(&[kvr]), false)?,
                                o_proj: get_quad_sl(&format!("{p}.self_attn.o_proj"), Some(&[orr]), None, true)?,
                                qnkn: dev.htod_sync_copy(&qnkn)?,
                                idx,
                            };
                            let (hd, nhl, nkvl) = (tc.head_dim, tc.num_heads, tc.num_kv_heads);
                            anyhow::ensure!(a.q_proj.n as usize == nhl * 2 * hd && a.k_proj.n as usize == nkvl * hd
                                            && a.v_proj.n as usize == nkvl * hd && a.o_proj.k as usize == nhl * hd
                                            && a.o_proj.n as usize == h && qnkn.len() == 2 * hd,
                                "TP-B attn L{li}: per-rank shapes (q {} k {} v {} o {}x{} qnkn {}) != local geometry \
                                 ({nhl} heads, {nkvl} kv heads, hd {hd}) — refusing to boot",
                                a.q_proj.n, a.k_proj.n, a.v_proj.n, a.o_proj.k, a.o_proj.n, qnkn.len());
                            bytes_round += (2560 * 13312 + 6144 * 2560) as u64 * 5 / 8 / ts.world as u64;
                            Mixer::Attn(a)
                        }
                        None => Mixer::Attn(AttnLayer {
                            q_proj: get_quad(&format!("{p}.self_attn.q_proj"))?,
                            k_proj: get_quad(&format!("{p}.self_attn.k_proj"))?,
                            v_proj: get_quad(&format!("{p}.self_attn.v_proj"))?,
                            o_proj: get_quad(&format!("{p}.self_attn.o_proj"))?,
                            qnkn: dev.htod_sync_copy(&qnkn)?,
                            idx,
                        }),
                    }
                }
            };

            let moe = mk_moe(format!("{p}.mlp"), format!("L{li}"), tp.as_ref().map(|t| (t.rank as usize, t.world as usize)))?;
            bytes_round += (10 * (moe.gu_words + moe.d_words)) * 2;
            bytes_round += (2560 * 640 * 3) as u64 * 5 / 8;
            bytes_round += (512 * 2560) as u64 * 2;
            if let Some(k) = qsa_keys_plane.take() { qsa_keys_vec.push(k); }
            if let Some(k) = qsa_pool_plane.take() { qsa_pool_vec.push(k); }
            layers.push(LayerDev { hc_attn, hc_mlp, mixer, moe });
            if li % 12 == 0 {
                println!("  layer {li} ({lt:?}) loaded ({:.0}s)", t_load.elapsed().as_secs_f32());
            }
        }

        let hc_mixer = {
            let names: Vec<String> = plain
                .keys()
                .filter(|k| k.contains("hyper_connection_mixer") && !k.contains(".layers.") && !k.contains("mtp"))
                .cloned()
                .collect();
            let pick = |suffix: &str| -> Result<String> {
                names
                    .iter()
                    .find(|k| k.ends_with(suffix))
                    .cloned()
                    .with_context(|| format!("final mixer *{suffix} not found (have {names:?})"))
            };
            let rd = |name: &str| -> Result<CudaSlice<u16>> {
                let t = plain.get(name).context("mixer tensor")?;
                let bits = to_f16_bits(&t.read(pack_dir)?, &t.dtype)?;
                Ok(dev.htod_sync_copy(&bits)?)
            };
            HcDev {
                norm: rd(&pick("hc_norm.weight")?)?,
                down: rd(&pick("input_mix_weight_down.weight")?)?,
                up: rd(&pick("input_mix_weight_up.weight")?)?,
                winj: None,
                q8: None,
            }
        };

        let mut lm_head = get_quad("lm_head")?;
        lm_head.lmh = true; // W3/LMH
        lmh_prewarm(lm_head.bits as usize, lm_head.k as usize);
        bytes_round += (2560 * cfg.vocab_size) as u64 * 5 / 8;

        // ---- MTP draft head (S-A3-e M1): load mtp.* as EXL3 through the same weight path. ----
        let mut mtp = if modules.contains_key("mtp.fc_hidden") {
            let t0h = std::time::Instant::now();
            let hcn = cfg.hc_count.max(1);
            let hp = "mtp.layers.0";
            let mk_hc = |base: String, inject: bool| -> Result<HcDev> {
                Ok(HcDev {
                    norm: get_plain_f16(&format!("{base}.hc_norm.weight"))?,
                    down: get_plain_f16(&format!("{base}.input_mix_weight_down.weight"))?,
                    up: get_plain_f16(&format!("{base}.input_mix_weight_up.weight"))?,
                    winj: if inject {
                        Some(get_plain_f16(&format!("{base}.block_inject_weight.weight"))?)
                    } else {
                        None
                    },
                    q8: None,
                })
            };
            let hc_attn = mk_hc(format!("{hp}.attn_hyper_connection"), true)?;
            let hc_mlp = mk_hc(format!("{hp}.mlp_hyper_connection"), true)?;
            let qn_t = plain.get(&format!("{hp}.self_attn.q_norm.weight")).context("mtp q_norm")?;
            let kn_t = plain.get(&format!("{hp}.self_attn.k_norm.weight")).context("mtp k_norm")?;
            let qnkn: Vec<u16> = to_f16_bits(&qn_t.read(pack_dir)?, &qn_t.dtype)?
                .into_iter()
                .chain(to_f16_bits(&kn_t.read(pack_dir)?, &kn_t.dtype)?)
                .collect();
            let attn = AttnLayer {
                q_proj: get_quad(&format!("{hp}.self_attn.q_proj"))?,
                k_proj: get_quad(&format!("{hp}.self_attn.k_proj"))?,
                v_proj: get_quad(&format!("{hp}.self_attn.v_proj"))?,
                o_proj: get_quad(&format!("{hp}.self_attn.o_proj"))?,
                qnkn: dev.htod_sync_copy(&qnkn)?,
                // Head QSA (2026-09-26): load the MTP layer's own indexer (the S-A3-i session
                // left it unwired by scope, not by finding). Past qsa_limit the draft attends
                // its QSA selection — the model spec and the reference implementation's draft — instead of a dense
                // scan whose cost grew with context (4.7 ms/pass at 128K, fp32 K/V).
                idx: if cfg.has_indexer() && plain.get(&format!("{hp}.self_attn.indexer.q_layernorm.weight")).is_some() {
                    let f32_of = |name: &str| -> Result<CudaSlice<f32>> {
                        let t = plain.get(&format!("{hp}.self_attn.indexer.{name}.weight"))
                            .with_context(|| format!("mtp indexer {name}"))?;
                        let bits = to_f16_bits(&t.read(pack_dir)?, &t.dtype)?;
                        let v: Vec<f32> = bits.iter().map(|b| h16_to_f32(*b)).collect();
                        Ok(dev.htod_sync_copy(&v)?)
                    };
                    Some(IndexerDev {
                        qk: get_quad(&format!("{hp}.self_attn.indexer.index_qk_proj"))?,
                        qn: f32_of("q_layernorm")?,
                        kn: f32_of("k_layernorm")?,
                        params: None,
                    })
                } else { None },
            };
            let head_qsa_keys = if attn.idx.is_some() {
                Some(dev.htod_sync_copy(&vec![0u16; width * max_pos * cfg.indexer_head_dim])?)
            } else { None };
            let head_qsa_pool = if attn.idx.is_some() && pool_on {
                let pl = width * max_pos.div_ceil(cfg.indexer_compress_ratio).max(1) * cfg.indexer_head_dim; // WP02: ceil
                Some(dev.htod_sync_copy(&vec![0u16; pl])?)
            } else { None };
            // TP-A (T1): the MTP head is REPLICATED on every rank — no EP shard, no reduce sites.
            let moe = mk_moe(format!("{hp}.mlp"), "mtp".to_string(), None)?;
            let fc_hidden = get_quad("mtp.fc_hidden")?;
            let fc_embed = get_quad("mtp.fc_embedding")?;
            let pre_fc_norm_hidden = get_plain_f16("mtp.pre_fc_norm_hidden.weight")?;
            let pre_e = get_plain_f16("mtp.pre_fc_norm_embedding.weight")?;
            let pre_e_h: Vec<u16> = dev.dtoh_sync_copy(&pre_e)?;
            let mut tiled: Vec<u16> = Vec::with_capacity(pre_e_h.len() * hcn);
            for _ in 0..hcn {
                tiled.extend_from_slice(&pre_e_h);
            }
            let pre_fc_norm_embedding = dev.htod_sync_copy(&tiled)?;
            let mixer = HcDev {
                norm: get_plain_f16("mtp.hyper_connection_mixer.hc_norm.weight")?,
                down: get_plain_f16("mtp.hyper_connection_mixer.input_mix_weight_down.weight")?,
                up: get_plain_f16("mtp.hyper_connection_mixer.input_mix_weight_up.weight")?,
                winj: None,
                q8: None,
            };
            let nkv = cfg.num_kv_heads;
            let hd = cfg.head_dim;
            let kv = dev.alloc_zeros::<u8>(width * 2 * nkv * max_pos * kv_rowbytes(kv_fmt, hd))?;
            println!(
                "  MTP draft head (mtp.*) loaded as EXL3 (M1 decision): fc 4bpw, attn 5bpw, experts 3bpw ({:.0}s)",
                t0h.elapsed().as_secs_f32()
            );
            Some(DraftHead {
                hc_attn,
                hc_mlp,
                attn,
                moe,
                fc_hidden,
                fc_embed,
                pre_fc_norm_hidden,
                pre_fc_norm_embedding,
                mixer,
                kv,
                qsa_keys: head_qsa_keys,
                qsa_pool: head_qsa_pool,
            })
        } else {
            None
        };

        // TP-B: the trunk's recurrent / conv / KV state is per-rank (its heads / channels only).
        let kd = tc.lin_k_dim;
        let vd = tc.lin_v_dim;
        let nh = tc.lin_num_v_heads;
        let conv_dim = tc.key_dim() * 2 + tc.value_dim();
        // Expert-flagged stride contract: xq_gdn_step derives qkv_stride in-kernel as
        // 2*n_k_heads*kd + nh*vd; this host conv_dim must equal it or lane rows misalign.
        debug_assert_eq!(conv_dim, 2 * tc.lin_num_k_heads * tc.lin_k_dim + tc.lin_num_v_heads * tc.lin_v_dim);
        let ck = cfg.conv_kernel;
        let n_attn = cfg
            .layer_types
            .iter()
            .filter(|l| matches!(l, crate::qwen::LayerType::FullAttention))
            .count();
        let mut conv_state = Vec::new();
        let mut s_state = Vec::new();
        for lt in &cfg.layer_types {
            if matches!(lt, crate::qwen::LayerType::LinearAttention) {
                conv_state.push(dev.alloc_zeros::<f32>(width * conv_dim * ck)?);
                s_state.push(dev.alloc_zeros::<f32>(width * nh * kd * vd)?);
            }
        }
        let mut k_cache = Vec::new();
        for _ in 0..n_attn {
            k_cache.push(dev.alloc_zeros::<u8>(width * 2 * tc.num_kv_heads * max_pos * kv_rowbytes(kv_fmt, tc.head_dim))?);
        }

        println!(
            "EXL3-FWD loaded in {:.1}s; W={width} max_pos={max_pos}; byte model ~{:.2} GB/round (W=1)",
            t_load.elapsed().as_secs_f32(),
            bytes_round as f64 / 1e9
        );

        // ---- PLE (S-A3-d Phase 0b): optional — present in packs with n-gram injection.
        let ple = {
            const PLE_KEY: &str = "model.language_model.layers.1.ple";
            match plain.get(&format!("{PLE_KEY}.key_proj.weight")) {
                None => None,
                Some(_) => {
                    use std::io::Read;
                    // WP09: host bits once -> the row-major device copy (prefill) + the k-major one
                    // (decode/verify). Same bits as get_plain_f16.
                    let plain_bits = |name: &str| -> Result<Vec<u16>> {
                        let t = plain.get(name).with_context(|| format!("missing plain tensor {name}"))?;
                        to_f16_bits(&t.read(pack_dir)?, &t.dtype)
                    };
                    let key_bits = plain_bits(&format!("{PLE_KEY}.key_proj.weight"))?;
                    let value_bits = plain_bits(&format!("{PLE_KEY}.value_proj.weight"))?;
                    anyhow::ensure!(key_bits.len() == 10240 * 2560 && value_bits.len() == 2560 * 2560,
                                    "ple key/value shapes {} / {}", key_bits.len(), value_bits.len());
                    let key_w = dev.htod_sync_copy(&key_bits)?;
                    let value_w = dev.htod_sync_copy(&value_bits)?;
                    let (key_km, value_km) = if wp09_ple_on() {
                        (Some(dev.htod_sync_copy(&relayout_km16(&key_bits, 10240, 2560))?),
                         Some(dev.htod_sync_copy(&relayout_km16(&value_bits, 2560, 2560))?))
                    } else {
                        (None, None)
                    };
                    drop((key_bits, value_bits));
                    let conv_w = get_plain_f16(&format!("{PLE_KEY}.conv1d.weight"))?;
                    let mut normw = Vec::new();
                    for nm in ["norm_key", "norm_query", "norm_conv"] {
                        let t = plain.get(&format!("{PLE_KEY}.{nm}.weight"))
                            .with_context(|| format!("ple {nm}"))?;
                        normw.push(to_f16_bits(&t.read(pack_dir)?, &t.dtype)?);
                    }
                    let norm_key_w = { let mut d = dev.alloc_zeros::<u16>(10240)?; dev.htod_copy_into(normw.remove(0), &mut d)?; d };
                    let norm_query_w = { let mut d = dev.alloc_zeros::<u16>(10240)?; dev.htod_copy_into(normw.remove(0), &mut d)?; d };
                    let norm_conv_w = { let mut d = dev.alloc_zeros::<u16>(10240)?; dev.htod_copy_into(normw.remove(0), &mut d)?; d };
                    let aux = |nm: &str| -> Result<Vec<i64>> {
                        let t = plain.get(&format!("{PLE_KEY}.ple_embedding.ngram_embedding.{nm}"))
                            .with_context(|| format!("ple {nm}"))?;
                        let raw = t.read(pack_dir)?;
                        Ok(raw.chunks_exact(8).map(|c| i64::from_le_bytes(c.try_into().unwrap())).collect())
                    };
                    let head_offsets = aux("head_offsets")?;
                    let head_vocab_sizes = aux("head_vocab_sizes")?;
                    let lm = aux("layer_multipliers")?;
                    anyhow::ensure!(lm.len() == 3, "ple layer_multipliers");
                    let hb_t = plain.get(&format!("{PLE_KEY}.ple_embedding.ngram_embedding.head_bias"))
                        .with_context(|| "ple head_bias".to_string())?;
                    let head_bias_bits = to_f16_bits(&hb_t.read(pack_dir)?, &hb_t.dtype)?;
                    let index: serde_json::Value = serde_json::from_reader(
                        std::fs::File::open(format!("{pack_dir}/model.safetensors.index.json"))
                            .with_context(|| "ple index".to_string())?)?;
                    let wmap = index["weight_map"].as_object().context("ple weight_map")?;
                    let mut shards = Vec::new();
                    let mut shard_data_off = Vec::new();
                    let mut rows_per_shard = 0i64;
                    for snum in 0..128usize {
                        let name = format!("{PLE_KEY}.ple_embedding.ngram_embedding.shard_{snum}.trellis");
                        let fname = wmap.get(&name).and_then(|v| v.as_str())
                            .with_context(|| format!("ple shard {snum} not in index"))?.to_string();
                        let mut f = std::fs::File::open(format!("{pack_dir}/{fname}"))
                            .with_context(|| format!("ple open {fname}"))?;
                        let mut lb = [0u8; 8];
                        f.read_exact(&mut lb)?;
                        let hlen = u64::from_le_bytes(lb) as usize;
                        let mut hb = vec![0u8; hlen];
                        f.read_exact(&mut hb)?;
                        let hdr: serde_json::Value = serde_json::from_slice(&hb)?;
                        let ent = &hdr[name.as_str()];
                        let shape: Vec<i64> = ent["shape"].as_array().context("ple shard shape")?
                            .iter().map(|v| v.as_i64().unwrap_or(0)).collect();
                        if snum == 0 {
                            rows_per_shard = shape[0];
                            anyhow::ensure!(shape[1] == 51, "ple shard row width");
                        }
                        let off0 = ent["data_offsets"][0].as_u64().context("ple shard offset")?;
                        shard_data_off.push(8 + hlen as u64 + off0);
                        shards.push(f);
                    }
                    let ram = ple_ram_load(&shards, &shard_data_off, rows_per_shard)?;
                    Some(PleDev {
                        key_w,
                        value_w,
                        key_km,
                        value_km,
                        conv_w,
                        norm_key_w,
                        norm_query_w,
                        norm_conv_w,
                        shards,
                        ram,
                        shard_data_off,
                        rows_per_shard,
                        head_offsets,
                        head_vocab_sizes,
                        layer_multipliers: [lm[0], lm[1], lm[2]],
                        head_bias_f32: head_bias_bits.iter().map(|&b| half::f16::from_bits(b).to_f32()).collect(),
                        head_bias_bits,
                        codebook: PleDev::mul1_codebook(),
                        eos: 248046,
                    })
                }
            }
        };

        let ple_state = dev.alloc_zeros::<u16>(width * 10240 * 9)?;

        // S-A3-f Item 1: full RoPE table, host-computed with the SAME powf/cos/sin
        // code the per-step loop used (bitwise-identical bits, paid once at load),
        // and ONE blocking compute stream for the model's lifetime.
        let rdim_t = cfg.rotary_dim;
        let theta_t = cfg.rope_theta;
        let mut cos_tab_h: Vec<f32> = Vec::with_capacity(max_pos * 2 * rdim_t);
        for p in 0..max_pos {
            for i in 0..rdim_t / 2 {
                let inv = theta_t.powf(-(2.0 * i as f32) / rdim_t as f32);
                let f = p as f32 * inv;
                cos_tab_h.push(f.cos());
            }
            for _ in 0..rdim_t / 2 { cos_tab_h.push(0.0); }
            for i in 0..rdim_t / 2 {
                let inv = theta_t.powf(-(2.0 * i as f32) / rdim_t as f32);
                let f = p as f32 * inv;
                cos_tab_h.push(f.sin());
            }
            for _ in 0..rdim_t / 2 { cos_tab_h.push(0.0); }
        }
        let cos_tab = dev.htod_sync_copy(&cos_tab_h)?;
        // VIS-2: per-slot mrope buffers, zero = text-only (alloc_zeros does not zero: upload zeros)
        let rope_map = dev.htod_sync_copy(&vec![0i32; width * max_pos])?;
        let rope_plen = dev.htod_sync_copy(&vec![0i32; width])?;
        let rope_delta = dev.htod_sync_copy(&vec![0i32; width])?;
        let mrope_tab = dev.htod_sync_copy(&vec![0f32; width * VIS_MROPE_ROWS * 2 * rdim_t])?;
        // WP05: the prefill prologue gathers its RoPE rows from cos_tab. Compare the table with
        // the prefill's own host loop (prefill_cossin_host, the pre-WP05 code) on sampled rows —
        // all of [0, 2048), every 127th row after, the last 128 — and refuse the gather (keep the
        // host loop, loudly) on any bit mismatch.
        let cos_gather_ok = {
            let row = 2 * rdim_t;
            let mut ps: Vec<usize> = (0..max_pos.min(2048)).collect();
            ps.extend((2048..max_pos).step_by(127));
            ps.extend(max_pos.saturating_sub(128).max(2048)..max_pos);
            let mut bad = 0usize;
            for &p in &ps {
                let hrow = prefill_cossin_host(theta_t, rdim_t, p, 1);
                let trow = &cos_tab_h[p * row..(p + 1) * row];
                bad += hrow.iter().zip(trow).filter(|(a, b)| a.to_bits() != b.to_bits()).count();
            }
            if bad > 0 {
                println!("WP05: cos_tab differs from the prefill host RoPE loop in {bad} values over {} sampled rows — prefill keeps the host loop", ps.len());
            } else {
                println!("WP05: prefill RoPE gather armed — cos_tab == prefill host loop bit-for-bit on {} sampled rows", ps.len());
            }
            bad == 0
        };
        // S-A3-i: deinterleaved indexer rope tables + per-layer QsaParams blocks. Same
        // powf/sin/cos formula and order as cos_tab (identical bits); the block layout
        // mirrors gpu.rs qsa_params so the shared bf16 selection kernels read it as-is.
        let (mut qsa_cos_h, mut qsa_sin_h): (Vec<f32>, Vec<f32>) = (Vec::new(), Vec::new());
        // --qsa-key-rope full: both rotary halves (the reference / the NVFP4 engine's table); half
        // (pre-v0.7.1 bytes, A/B only) = the old table with dims rdim/2..rdim left at zero. Default full (owner 2026-10-02).
        let qsa_full = qsa_key_rope_full();
        for p in 0..max_pos {
            qsa_cos_h.resize(qsa_cos_h.len() + rdim_t, 0.0);
            qsa_sin_h.resize(qsa_sin_h.len() + rdim_t, 0.0);
            for i in 0..rdim_t / 2 {
                let inv = theta_t.powf(-(2.0 * i as f32) / rdim_t as f32);
                let f = p as f32 * inv;
                qsa_cos_h[p * rdim_t + i] = f.cos();
                qsa_sin_h[p * rdim_t + i] = f.sin();
                if qsa_full {
                    qsa_cos_h[p * rdim_t + i + rdim_t / 2] = f.cos();
                    qsa_sin_h[p * rdim_t + i + rdim_t / 2] = f.sin();
                }
            }
        }
        // VIS-3: per-slot indexer image rows (qsa_cos/qsa_sin layout) + the QsaMrope block every
        // indexer's QsaParams.mr points at (gpu_batch.cu; the shared rope_map/plen/delta).
        let qm_cos = dev.htod_sync_copy(&vec![0f32; width * VIS_MROPE_ROWS * rdim_t])?;
        let qm_sin = dev.htod_sync_copy(&vec![0f32; width * VIS_MROPE_ROWS * rdim_t])?;
        let qsa_mrope = {
            let mut b: Vec<u8> = Vec::with_capacity(48);
            for ptr in [*rope_map.device_ptr() as u64, *rope_plen.device_ptr() as u64, *rope_delta.device_ptr() as u64,
                        *qm_cos.device_ptr() as u64, *qm_sin.device_ptr() as u64] {
                b.extend_from_slice(&ptr.to_le_bytes());
            }
            b.extend_from_slice(&(width as i32).to_le_bytes());
            b.extend_from_slice(&(max_pos as i32).to_le_bytes());
            dev.htod_sync_copy(&b)?
        };
        let qsa_cos = dev.htod_sync_copy(&qsa_cos_h)?;
        let qsa_sin = dev.htod_sync_copy(&qsa_sin_h)?;
        if cfg.has_indexer() {
            let cos_p = *qsa_cos.device_ptr() as u64;
            let sin_p = *qsa_sin.device_ptr() as u64;
            let (hdx, heads, ratio) = (cfg.indexer_head_dim, cfg.indexer_n_heads, cfg.indexer_compress_ratio);
            let head_attn: Option<&mut AttnLayer> = mtp.as_mut().map(|h| &mut h.attn);
            for a in layers.iter_mut()
                .filter_map(|ld| match &mut ld.mixer { Mixer::Attn(a) => Some(a), _ => None })
                .chain(head_attn) {
                let ix = match a.idx.as_mut() { Some(ix) => ix, None => continue };
                let mut b: Vec<u8> = Vec::with_capacity(64);
                for ptr in [cos_p, sin_p, *ix.kn.device_ptr() as u64, *ix.qn.device_ptr() as u64] {
                    b.extend_from_slice(&ptr.to_le_bytes());
                }
                b.extend_from_slice(&(cfg.rms_eps as f32).to_le_bytes());
                for v in [hdx, heads, cfg.rotary_dim, ratio, cfg.indexer_budget / ratio,
                          cfg.indexer_budget + ratio - 1, 0usize] {
                    b.extend_from_slice(&(v as i32).to_le_bytes());
                }
                b.extend_from_slice(&(*qsa_mrope.device_ptr() as u64).to_le_bytes()); // VIS-3 QsaParams.mr
                ix.params = Some(dev.htod_sync_copy(&b)?);
            }
            println!("  QSA indexer loaded: budget {} ratio {} sel_max {} (dense <= {} visible); pooled-key rope {}",
                     cfg.indexer_budget, ratio, cfg.indexer_budget + ratio - 1,
                     cfg.indexer_budget + ratio - 1,
                     if qsa_full { "full (the reference)" } else { "HALF (--qsa-key-rope half: the pre-v0.7.1 table, dims rdim/2..rdim zero)" });
        }
        let stream = fork_blocking_stream(&dev);

        // S-A3-f-f ITEM 1: grid-barrier co-residency must be MEASURED, not assumed
        // (a deadlock here would hang the graph). 0 disables the fused mixer entirely.
        let hc_fuse_cap = hc_fuse_co_residency(&dev);
        println!(
            "EXL3-FWD hc_fuse co-residency: {} blocks (256t){}",
            hc_fuse_cap,
            if hc_fuse_cap > 0 { "" } else { " -> fused hc mixer DISABLED (old path, all m)" }
        );
        // WP11: the k-major twins are enabled (q_up relayout at quantize time) only when THEIR
        // own measured residency covers every width the fused int8 arm can see (m <= 60 there:
        // bx = clamp(cap/m, 4, 40) with bx*m <= hc_fuse_cap*5/6).
        let wp11_cap = if wp11_r3_on() && hc_fuse_cap > 0 {
            let c = (wp11_capacity(&dev, "xq_hc_fuse_i8k"), wp11_capacity(&dev, "xq_hc_fuse_i8_rbk"));
            if (hc_fuse_cap.min(c.0) * 5) / 6 >= 64 { c } else { (0, 0) }
        } else { (0, 0) };
        println!(
            "EXL3-FWD WP11 hc rungs: {} (caps i8k {} rbk {}; R1 pf={} R2={} R4={} cvt={}; --wp11-off=1 = old path)",
            if wp11_off() { "OFF" } else if wp11_cap.0 > 0 { "R3 k-major twins" } else { "R3 off (old fuse kernels)" },
            wp11_cap.0, wp11_cap.1, wp11_pf_mode(), wp11_r2_on() as u8, wp11_r4_on() as u8,
            if wp11_cvt_i2f() { "i2f" } else { "prmt" }
        );
        // HC (w4): the regridded mix-fused mixer needs the WP11 k-major up weights and its shape
        // contract (4 streams, h % 64, rw % 1024, lr % 16 <= 512); its grid is clamped to ITS OWN
        // measured co-residency x 5/6 (pinned-carveout handle), so the grid barrier is safe.
        let (w4hc_grid, w4hc_cap) = {
            let (h, hcn, lr) = (cfg.hidden_size, cfg.hc_count.max(1), cfg.hc_lowrank);
            let shape_ok = hcn == 4 && h % 64 == 0 && h <= 0xFFFF && (h * hcn) % 1024 == 0
                && lr % 16 == 0 && lr >= 16 && lr <= 512;
            // TUNE T0c: probed whenever a lookup can turn the mixer on (the default, a table value,
            // or the --autotune overlay); w4hc_takes still asks w4hc.fuse per width
            let fuse_reachable = tune::reachable(&T_W4HC_OFF).contains(&0) && tune::reachable(&T_W4HC_FUSE).contains(&1);
            if fuse_reachable && !wp11_off() && wp11_cap.0 > 0 && hc_fuse_cap > 0 && shape_ok {
                let cap = w4hc_capacity();
                let g = w4hc_default_grid(cap, h);
                println!("EXL3-FWD HC-W4 mixer: xq_hc_w4 co-residency {cap} blocks (256t, carveout max) -> grid {g}{}",
                         if g > 0 { "" } else { " -> OFF (fewer co-resident CTAs than the phase-B minimum ceil(h/32))" });
                (g, cap)
            } else {
                (0, 0)
            }
        };
        println!(
            "EXL3-FWD HC-W4: fuse {} (grid {w4hc_grid}, m=1 {}, mix-fused {}, geom flags {:#x}), inject+norm fusion {}{}; \
             --w4hc-off=1 = p4c hc path",
            if w4hc_grid > 0 { "ON" } else { "OFF" }, if w4hc_m1_on() { "on" } else { "off" },
            if w4hc_mix_on() { "on" } else { "off" }, w4hc_geom_flags(),
            if w4hc_inj_on() && cfg.hidden_size <= 4096 { "ON" } else { "OFF" },
            if w4hc_xcheck() { " [XCHECK]" } else { "" }
        );

        // S-A3-f-g: tmap-inverse LUT for exl3_decode_dump (the reconstruct front-end).
        let rc_lut = dev.htod_sync_copy(&crate::exl3_bench::tmap_inv_table())?;
        let qsa_dbg = match crate::opts::var(crate::opt!("qsa-dump-layer")).ok().and_then(|v| v.parse::<usize>().ok()) {
            Some(k) if cfg.has_indexer() => {
                let nbs = (max_pos / cfg.indexer_compress_ratio).max(1);
                let sm = cfg.indexer_budget + cfg.indexer_compress_ratio;
                Some((k, dev.htod_sync_copy(&vec![0i32; sm])?, dev.htod_sync_copy(&vec![0f32; nbs])?,
                      dev.htod_sync_copy(&vec![0i32; 2048 * sm])?, dev.htod_sync_copy(&vec![0f32; 2048 * nbs])?))
            }
            _ => None,
        };
        let qsa_rowdbg = match crate::opts::var(crate::opt!("qsa-rowdump-layer")).ok().and_then(|v| v.parse::<usize>().ok()) {
            Some(k) if cfg.has_indexer() => {
                let sm = cfg.indexer_budget + cfg.indexer_compress_ratio - 1;
                Some((k, dev.htod_sync_copy(&vec![-7i32; QSA_ROWDUMP_CAP * sm])?, dev.htod_sync_copy(&vec![-7i32; QSA_ROWDUMP_CAP])?,
                      dev.htod_sync_copy(&vec![-7i32; QSA_ROWDUMP_CAP * sm])?, dev.htod_sync_copy(&vec![-7i32; QSA_ROWDUMP_CAP])?))
            }
            _ => None,
        };
        let esel_hist = if crate::opts::var(crate::opt!("exl3-esel-hist")).is_ok() {
            Some(dev.htod_sync_copy(&vec![0i32; 17 * ESEL_HIST_W])?)
        } else { None };
        let expert_hist = match crate::opts::var(crate::opt!("tp-ep-hist")) {
            Ok(path) if !path.is_empty() && path != "0" => {
                println!("[exl3] --tp-ep-hist diagnostic: per-(layer, expert) routing histogram -> {path} (cumulative, at every request finish)");
                Some((dev.htod_sync_copy(&vec![0i32; cfg.num_layers * 2 * cfg.num_experts])?, path))
            }
            _ => None,
        };

        // S-A3-f-d: pruned draft lm_head (reference patch 0002). Column slice of the
        // shared head's trellis: nb_keep = n2/16 leading 16-col blocks per k-block.
        // n2 = min(--exl3-mtp-head-n || 65536, n_full) rounded DOWN to /128.
        // 0 disables. svh is n-indexed -> plain prefix slice.
        let lm_head_draft: Option<Quad> = if mtp.is_some() {
            let n_full = lm_head.n;
            let env_n: usize = crate::opts::var(crate::opt!("exl3-mtp-head-n"))
                .ok().and_then(|v| v.parse().ok()).unwrap_or(65536);
            let n2 = ((env_n.min(n_full as usize)) / 128 * 128) as i32;
            if n2 > 0 && n2 < n_full {
                let l0 = Launcher { dev: &dev, stream: &stream };
                let nb_full = (n_full / 16) as usize;
                let nb_keep = (n2 / 16) as usize;
                let bw = (16 * lm_head.bits) as i64;
                let words = (lm_head.tr.len() / nb_full) * nb_keep;
                let mut tr2 = dev.alloc_zeros::<u16>(words)?;
                let total = words as u32;
                xqlaunch!(l0, "xq_slice_trellis_u16",
                          (((total) + 255) / 256, 1, 1), (256, 1, 1), 0,
                          (&mut tr2, &lm_head.tr, nb_full as i32, nb_keep as i32, bw))?;
                let mut svh2 = dev.alloc_zeros::<u16>(n2 as usize)?;
                xqlaunch!(l0, "xq_copy_u16", (((n2 as u32) + 255) / 256, 1, 1), (256, 1, 1), 0,
                          (&mut svh2, &lm_head.svh, n2 as i64, 0i64, 0i64))?;
                let mut suh2 = dev.alloc_zeros::<u16>(lm_head.suh.len())?;
                xqlaunch!(l0, "xq_copy_u16", (((lm_head.suh.len() as u32) + 255) / 256, 1, 1), (256, 1, 1), 0,
                          (&mut suh2, &lm_head.suh, lm_head.suh.len() as i64, 0i64, 0i64))?;
                l0.dev.synchronize()?;
                let draft = Quad {
                    tr: tr2,
                    suh: suh2,
                    svh: svh2,
                    bits: lm_head.bits,
                    k: lm_head.k,
                    n: n2,
                    ks: chain_ks(lm_head.k, n2),
                    lmh: true, // W3/LMH: the draft slice is the same lm_head class
                    cnt: dev.htod_sync_copy(&vec![0u32; ((n2.max(0) as usize) / 128).max(1)])?, // W4/DENSE, explicit zero
                    rowpar: false,
                };
                println!("EXL3-MTP pruned draft head: n {n_full} -> {n2} (trellis {:.0} MB -> {:.0} MB)",
                         (lm_head.tr.len() * 2) as f64 / 1e6, (words * 2) as f64 / 1e6);
                Some(draft)
            } else {
                if env_n == 0 { println!("EXL3-MTP pruned draft head disabled (--exl3-mtp-head-n=0)"); }
                None
            }
        } else { None };
        // DHEAD (w2): the draft passes' screen + exact rescore over the slice above (draft-only).
        let dhead: Option<dhead::DHead> = match lm_head_draft.as_ref() {
            Some(qd) if !dhead::dhead_off() => match dhead::DHead::build(&dev, &stream, qd) {
                Ok(d) => Some(d),
                Err(e) => { println!("DHEAD: NOT built ({e:#}) — the old draft head serves"); None }
            },
            Some(_) => { println!("DHEAD: off (--dhead-off=1) — the old draft head serves"); None }
            None => None,
        };

        // S-A3-p: --hc-int8 — quantize every decode/verify mixer (trunk, final, MTP head).
        let mut layers = layers;
        let mut hc_mixer = hc_mixer;
        let mut mtp = mtp;
        if hc_int8_enabled() {
            let t0q = std::time::Instant::now();
            let (lr, rw) = (cfg.hc_lowrank, cfg.hidden_size * cfg.hc_count.max(1));
            let mut n = 0usize;
            for l in layers.iter_mut() {
                hc_quantize_i8(&dev, &mut l.hc_attn, lr, rw, wp11_cap.0 > 0)?;
                hc_quantize_i8(&dev, &mut l.hc_mlp, lr, rw, wp11_cap.0 > 0)?;
                n += 2;
            }
            hc_quantize_i8(&dev, &mut hc_mixer, lr, rw, wp11_cap.0 > 0)?;
            n += 1;
            if let Some(h) = mtp.as_mut() {
                hc_quantize_i8(&dev, &mut h.hc_attn, lr, rw, wp11_cap.0 > 0)?;
                hc_quantize_i8(&dev, &mut h.hc_mlp, lr, rw, wp11_cap.0 > 0)?;
                hc_quantize_i8(&dev, &mut h.mixer, lr, rw, wp11_cap.0 > 0)?;
                n += 3;
            }
            println!("EXL3 hc mixers: {n} quantized to int8 (per-row fp32 scales) in {:.1}s — DEFAULT; --hc-fp16 = bit-exact fp16 mixer",
                     t0q.elapsed().as_secs_f32());
        }

        let snap = if crate::opts::var(crate::opt!("exl3-prefix")).as_deref() == Ok("1") {
            let rw = cfg.hc_count.max(1) * cfg.hidden_size;
            let mk = |v: &Vec<CudaSlice<f32>>| -> Result<Vec<CudaSlice<f32>>> {
                v.iter().map(|b| Ok(dev.alloc_zeros::<f32>(b.len())?)).collect()
            };
            let ps = PrefixSnap {
                conv: mk(&conv_state)?,
                s: mk(&s_state)?,
                ple: dev.alloc_zeros::<u16>(ple_state.len())?,
                carry: dev.alloc_zeros::<f32>(width * rw)?,
                hist: std::sync::Mutex::new(vec![248046i32; width * 2]),
            };
            let mb: usize = ps.s.iter().map(|b| b.len() * 4).sum::<usize>() + ps.conv.iter().map(|b| b.len() * 4).sum::<usize>();
            println!("  prefix cache: per-slot recurrent-state snapshots ({:.0} MB for {width} slot(s))", mb as f64 / 1e6);
            Some(ps)
        } else { None };

        // W4/DENSE: the per-job grid plan + entry prewarm (feature marker); when it is off (p5e
        // default; opt-in --w4dense=1), the w3-PSK persistent split-K grid chosen for every chain
        // shape (p3: OFF unless --psk=1), logged once — the p3 boot sequence.
        dense::log_and_prewarm(&dev, &layers, mtp.as_ref());
        if !dense::dense_on() { psk_log_shapes(&dev, &layers, mtp.as_ref()); }
        else if tune::reachable(&T_PSK_ON).contains(&1) { let _ = psk_slots(&dev); } // TUNE T0c: outside any capture
        wp21_log_boot(); // WP21 feature marker (the split-K chain tail in effect)
        let w4s_lptr = w4s::w4s_build_lptr(&dev, &s_state, &conv_state)?;
        // TP-H #4 (--tp-vp-head, default on): this rank's column shard of the lm_head for the
        // vocab-parallel greedy verify / plain-step tail (xtp.rs vp_greedy_tail). The lmh GEMM is
        // column-tile independent (ks = 1, 128-column tiles), so shard columns [r*n/2, (r+1)*n/2)
        // are bitwise the replicated head's. The replicated head stays for prefill, the draft
        // slice and the sampled/penalized tails. World 2 or 4 (TP-4C: a multi-round key merge; the TP-H2 row
        // all-gather: world 2 = one exchange per group, world 4 = TP-4H2's recursive doubling, two).
        let vp_rw = tp.as_ref().map(|t| (t.rank, t.world));
        let lm_head_vp: Option<VpHead> = match vp_rw {
            Some((rank, world)) if xtp::vp_head_on() && (world == 2 || world == 4) && xtp::dec_xport_mode() == 1
                && lm_head.lmh && lm_head.ks == 1 && (lm_head.n as usize) % (world as usize * 128) == 0
                && crate::opts::var(crate::opt!("mtp-dump")).map_or(true, |v| v.is_empty())
                && crate::opts::var(crate::opt!("step-topk-dir")).is_err() => {
                let l0 = Launcher { dev: &dev, stream: &stream };
                let n_full = lm_head.n;
                let n_sh = n_full / world;
                let nb_full = (n_full / 16) as usize;
                let nb_keep = (n_sh / 16) as usize;
                let nb_off = rank as usize * nb_keep;
                let bw = (16 * lm_head.bits) as i64;
                anyhow::ensure!(lm_head.tr.len() % nb_full == 0, "lm_head trellis {} words not a multiple of nb {nb_full}", lm_head.tr.len());
                let words = (lm_head.tr.len() / nb_full) * nb_keep;
                let mut tr2 = dev.alloc_zeros::<u16>(words)?;
                xqlaunch!(l0, "xq_slice_trellis_u16_off",
                          ((words as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                          (&mut tr2, &lm_head.tr, nb_full as i32, nb_keep as i32, bw, nb_off as i32))?;
                let mut svh2 = dev.alloc_zeros::<u16>(n_sh as usize)?;
                xqlaunch!(l0, "xq_copy_u16", (((n_sh as u32) + 255) / 256, 1, 1), (256, 1, 1), 0,
                          (&mut svh2, &lm_head.svh, n_sh as i64, 0i64, (rank * n_sh) as i64))?;
                let mut suh2 = dev.alloc_zeros::<u16>(lm_head.suh.len())?;
                xqlaunch!(l0, "xq_copy_u16", (((lm_head.suh.len() as u32) + 255) / 256, 1, 1), (256, 1, 1), 0,
                          (&mut suh2, &lm_head.suh, lm_head.suh.len() as i64, 0i64, 0i64))?;
                l0.dev.synchronize()?;
                let q = Quad {
                    tr: tr2, suh: suh2, svh: svh2, bits: lm_head.bits, k: lm_head.k, n: n_sh,
                    ks: chain_ks(lm_head.k, n_sh), lmh: true,
                    cnt: dev.htod_sync_copy(&vec![0u32; ((n_sh.max(0) as usize) / 128).max(1)])?, // explicit zero
                    rowpar: false,
                };
                anyhow::ensure!(q.ks == 1, "vocab shard chain ks {} != 1 (the replicated head's reduction order)", q.ks);
                println!("TP-H vocab-parallel lm_head: rank {rank}/{world} shard columns [{}, {}) ({:.0} MB trellis) — \
                          greedy verify/step tail = shard GEMM + argmax + {} key exchange(s) (--tp-vp-head=0 = replicated)",
                         rank * n_sh, (rank + 1) * n_sh, (words * 2) as f64 / 1e6, world.trailing_zeros());
                if world == 2 {
                    // TP-H2: the sampled / penalized / ratio-rule rows' tail (row all-gather of the shard rows)
                    xtp::set_vp_rows_cols(n_sh as usize);
                    println!("TP-H2 vocab-parallel sampled rows: {} — sampled / penalized / ratio-rule step+verify tail = shard GEMM + \
                              row all-gather ({} rows per 1 MiB epoch, {:.0} KB per row per rank) + the unchanged sampler \
                              (--tp-vp-sampled {})",
                             if xtp::vp_sampled_on() { "ON" } else { "OFF (the replicated head)" }, xtp::VP_GATHER_ROWS,
                             (n_sh as f64) * 2.0 / 1e3, xtp::vp_sampled_desc(xtp::vp_sampled_code()));
                } else if world == 4 {
                    // TP-4H2: the same tail at world 4 — recursive-doubling row all-gather (2 epochs per group of
                    // <= 4 rows: the own shard, then the two shards held), default ON (D-TP4-3). The state printed
                    // is the RESOLVED code (the head's flag, installed on every rank before the model load).
                    xtp::set_vp_rows_cols(n_sh as usize);
                    println!("TP-4H2 vocab-parallel sampled rows (world 4): {} — sampled / penalized / ratio-rule step+verify tail = \
                              shard GEMM + 2-round recursive-doubling row all-gather ({} rows per group = 2 epochs of <= {:.0} KB, \
                              {:.0} KB per row per rank) + the unchanged sampler (--tp-vp-sampled {})",
                             if xtp::vp_sampled_on() { "ON" } else { "OFF (the replicated head)" }, xtp::VP_GATHER_ROWS,
                             (2 * xtp::VP_GATHER_ROWS as u64 * n_sh as u64 * 2) as f64 / 1e3,
                             (n_sh as f64) * 2.0 / 1e3, xtp::vp_sampled_desc(xtp::vp_sampled_code()));
                } else {
                    // any other world: no row all-gather kernels — the replicated head (still resident) serves the
                    // sampled rows; vp_rows keeps its 1-element placeholder
                    println!("TP-H2 vocab-parallel sampled rows: OFF at world {world} (the row all-gather has kernels at world 2 and 4 \
                              only; sampled / penalized / ratio-rule rows take the replicated head)");
                }
                Some(VpHead { q, base: rank * n_sh, n_sh })
            }
            _ => None,
        };
        // TP-H #3 (--tp-dh-shard, default on): each rank screens 1/world of the draft head's blocks and the
        // doorbell reassembles the replicated block-maxima array bit for bit (dhead.rs / xtp.rs).
        let mut dhead = dhead;
        if let (Some(dh), Some((rank, world))) = (dhead.as_mut(), vp_rw) {
            if xtp::dh_shard_on() && (world == 2 || world == 4) && xtp::dec_xport_mode() == 1 {
                dh.enable_shard(&dev, rank as usize, world as usize)?;
                if let Some((a, b, nblk)) = dh.shard_span() {
                    println!("TP-H sharded MTP-head screen: rank {rank}/{world} screens blocks [{a}, {b}) of {nblk} \
                              (1/{world} of the screen bytes per draft pass; bmax reassembled through the doorbell, \
                              bitwise the replicated screen; --tp-dh-shard=0 = replicated)");
                }
            }
        }
        // TP-A: attach the RDMA link LAST (every weight is resident and shape-asserted first).
        let tp_state = match tp {
            Some(t) => Some(xtp::TpState::attach(&dev, &stream, t, cfg.hidden_size)?),
            None => None,
        };

        Ok(Arc::new(FwdModel {
            tc,
            dev,
            cfg,
            embed,
            layers,
            hc_mixer,
            lm_head,
            lm_head_draft,
            lm_head_vp,
            dhead,
            conv_state,
            s_state,
            w4s_lptr,
            width,
            k_cache,
            kv_fmt,
            max_pos,
            bytes_per_round: bytes_round,
            ple,
            ple_state,
            ple_hist: std::sync::Mutex::new(vec![248046i32; width * 2]),
            snap,
            mtp,
            stream,
            cos_tab,
            rope_map,
            rope_plen,
            rope_delta,
            mrope_tab,
            qm_cos,
            qm_sin,
            qsa_mrope,
            qsa_full,
            cos_gather_ok,
            graphs: std::sync::Mutex::new(std::collections::HashMap::new()),
            qsa_keys: qsa_keys_vec,
            qsa_pool: qsa_pool_vec,
            qsa_cos,
            qsa_sin,
            hc_fuse_cap,
            wp11_cap,
            w4hc_grid,
            w4hc_cap,
            rc_lut,
            esel_hist,
            expert_hist,
            qsa_dbg,
            qsa_rowdbg,
            tp: tp_state,
        }))
    }
}

// ---------------------------------------------------------------------------
// Ladder + forward
// ---------------------------------------------------------------------------

pub struct LadderCtx {
    pub dir: String,
    pub step: usize,
    pub layers: Vec<usize>,
    /// Dump only at this forward step (the comparison position; None = every step).
    pub only_step: Option<usize>,
    /// TP-A: capture into memory instead of files (name, row-0 values as f32) — the xtp probe's
    /// per-layer rank-identity digests and cross-TP comparisons. None = the file dumps above.
    pub mem: Option<std::sync::Mutex<Vec<(String, Vec<f32>)>>>,
    /// TP-B: with `mem`, store a 64-bit DIGEST of the whole captured buffer (two f32 carrying the
    /// hash bits) instead of row-0 values — the prefill rank-identity check (G-T1-b) over every
    /// row of a chunk without holding the chunk's activations.
    pub digest: bool,
    /// TP-SP2 (the G-T1-b redesign for row ownership): with `digest`, ALSO a digest per rank row
    /// block of every own-row buffer class (`sp_row_class`), named `<name>@<block>`; None = today.
    pub sp: Option<SpDigest>,
}

/// TP-SP2: what the row-block digests of one sequence-parallel chunk cover (see LadderCtx.sp).
#[derive(Clone, Debug)]
pub struct SpDigest {
    /// the prefill scratch's row capacity (every f32 row buffer is cap x its row width)
    pub cap: usize,
    /// the chunk's rows
    pub c: usize,
    /// every rank's row block of the chunk (rank order)
    pub blocks: Vec<(usize, usize)>,
    /// Some(b) = digest block b only (the sequence-parallel run: this rank's own block); None = every
    /// block (the replicated reference run of the same chunk)
    pub only: Option<usize>,
    /// fault injection (`--xtp-sp-fault L`, this run and rank only): after layer L's residual update,
    /// flip the lowest mantissa bit of the first element of the first own row of the streams
    pub fault_layer: Option<usize>,
}

/// TP-SP2: the prefill buffer classes that hold only the OWN rows in a sequence-parallel chunk (the
/// streams, the mixer / MoE outputs after a reduce-scatter, the inject coefficients, the final mix);
/// embed, xpre / xpre_mlp (x after the all-gather) and every decode buffer stay whole-buffer classes.
pub fn sp_row_class(name: &str) -> bool {
    matches!(name.trim_end_matches(|c: char| c.is_ascii_digit()), "rmid" | "yatt" | "inj" | "ymlp" | "layer" | "precollapse" | "finalmix")
}

/// TP-B: word-wise FNV-1a-style 64-bit digest (the rank-identity hash of a whole buffer).
pub(crate) fn digest_words(it: impl Iterator<Item = u64>) -> u64 {
    let mut h = 0xcbf2_9ce4_8422_2325u64;
    for w in it { h = (h ^ w).wrapping_mul(0x100_0000_01b3); h ^= h >> 29; }
    h
}

impl LadderCtx {
    /// TP-SP2: push `name@b` digests of the row blocks of `words` (row width `rw` words) — every block
    /// (the reference run) or only the own one (the sequence-parallel run).
    fn push_blocks(&self, mm: &std::sync::Mutex<Vec<(String, Vec<f32>)>>, name: &str, words: &[u64], rw: usize) {
        let Some(sp) = self.sp.as_ref() else { return };
        if !sp_row_class(name) || rw == 0 { return; }
        for (b, &(lo, hi)) in sp.blocks.iter().enumerate() {
            if sp.only.map_or(false, |o| o != b) || hi * rw > words.len() { continue; }
            let d = digest_words(words[lo * rw..hi * rw].iter().copied());
            mm.lock().unwrap().push((format!("{name}@{b}"), vec![f32::from_bits(d as u32), f32::from_bits((d >> 32) as u32)]));
        }
    }
    fn dump(&self, dev: &Arc<CudaDevice>, buf: &CudaSlice<f32>, name: &str, m: usize) -> Result<()> {
        let host = dev.dtoh_sync_copy(buf)?;
        if let (Some(mm), true) = (self.mem.as_ref(), self.digest) {
            let d = digest_words(host.iter().map(|v| v.to_bits() as u64));
            mm.lock().unwrap().push((name.to_string(), vec![f32::from_bits(d as u32), f32::from_bits((d >> 32) as u32)]));
            if let Some(sp) = self.sp.as_ref() {
                let w: Vec<u64> = host.iter().map(|v| v.to_bits() as u64).collect();
                self.push_blocks(mm, name, &w, host.len() / sp.cap.max(1));
            }
            return Ok(());
        }
        if let Some(mm) = self.mem.as_ref() {
            let rw = host.len() / m.max(1);
            mm.lock().unwrap().push((name.to_string(), host[..rw].to_vec()));
            return Ok(());
        }
        let path = format!("{}/{}_s{:03}.f32", self.dir, name, self.step);
        let mut f = std::fs::File::create(&path)?;
        let rw = host.len() / m.max(1);
        for v in &host[..rw] {
            f.write_all(&v.to_le_bytes())?;
        }
        Ok(())
    }
    /// Per-layer f16-row dump for the verify-vs-plain diff (same convention:
    /// row 0 to disk as f32).
    fn dump_u16(&self, dev: &Arc<CudaDevice>, buf: &CudaSlice<u16>, name: &str, n: usize) -> Result<()> {
        let host = dev.dtoh_sync_copy(buf)?;
        if let (Some(mm), true) = (self.mem.as_ref(), self.digest) {
            let d = digest_words(host[..n].iter().map(|&b| b as u64));
            mm.lock().unwrap().push((name.to_string(), vec![f32::from_bits(d as u32), f32::from_bits((d >> 32) as u32)]));
            if let Some(sp) = self.sp.as_ref() {
                let w: Vec<u64> = host[..n].iter().map(|&b| b as u64).collect();
                self.push_blocks(mm, name, &w, n / sp.c.max(1));
            }
            return Ok(());
        }
        if let Some(mm) = self.mem.as_ref() {
            mm.lock().unwrap().push((name.to_string(), host[..n].iter().map(|&b| f16::from_bits(b).to_f32()).collect()));
            return Ok(());
        }
        let path = format!("{}/{}_s{:03}.f32", self.dir, name, self.step);
        let mut f = std::fs::File::create(&path)?;
        for &b in &host[..n] {
            let v = f16::from_bits(b).to_f32();
            f.write_all(&v.to_le_bytes())?;
        }
        Ok(())
    }
    fn want(&self, li: usize) -> bool {
        self.layers.contains(&li) && self.active()
    }
    fn want_steps(&self, li: usize) -> bool {
        self.layers.contains(&li) && !self.dir.is_empty()
    }
    fn active(&self) -> bool {
        self.only_step.map_or(true, |s| s == self.step)
    }
}

impl FwdModel {
    /// S-A3-f-d Item 1b: plain-path col-0 dump pass (--mtp-dump=<dir>). Runs
    /// AFTER a completed forward_step (never inside a graph capture): reads the
    /// committed col-0 planes of the same buffers the verify side dumps, with a
    /// `_p` name suffix so the two sides never collide in the dump dir. No
    /// kernel launches — pure dtoh + file IO.
    fn diag_plain_dump(&self, l: &Launcher, sc: &mut Scratch, m: usize) -> Result<()> {
        let _ = l;
        let d = std::path::PathBuf::from(crate::opts::var(crate::opt!("mtp-dump"))
            .map_err(|_| anyhow::anyhow!(crate::opt!("mtp-dump")))?);
        std::fs::create_dir_all(&d)?;
        let dump_f = |d: &std::path::PathBuf, buf: &CudaSlice<f32>, name: &str, r: usize| -> Result<()> {
            let host = self.dev.dtoh_sync_copy(buf)?;
            let path = format!("{}/{}_p.f32", d.display(), name);
            let w = buf.len() / m;
            let mut f = std::fs::File::create(&path)?;
            let s = (r * w).min(host.len());
            let e = ((r + 1) * w).min(host.len());
            for &v in &host[s..e] { f.write_all(&v.to_le_bytes())?; }
            Ok(())
        };
        let dump_u = |d: &std::path::PathBuf, buf: &CudaSlice<u16>, name: &str, r: usize| -> Result<()> {
            let host = self.dev.dtoh_sync_copy(buf)?;
            let path = format!("{}/{}_p.f32", d.display(), name);
            let w = buf.len() / m;
            let mut f = std::fs::File::create(&path)?;
            let s = (r * w).min(host.len());
            let e = ((r + 1) * w).min(host.len());
            for &b in &host[s..e] {
                f.write_all(&f16::from_bits(b).to_f32().to_le_bytes())?;
            }
            Ok(())
        };
        // ("stagingCTX"/"finalmix" are dumped by forward_step_kernels at the SAME
        // points as verify_kernels; the post-step reads here use distinct names so
        // they never overwrite the 1:1 comparable files.)
        dump_f(&d, &sc.resid, "endctx", 0)?;
        dump_f(&d, &sc.cos, "stagingCOS", 0)?;
        dump_u(&d, &sc.mixer_out, "rmidfinal", 0)?;
        dump_u(&d, &sc.x, "lmheadin", 0)?;
        dump_u(&d, &sc.logits, "press0logits", 0)?;
        let amh = self.dev.dtoh_sync_copy(&sc.argmax)?;
        println!("PLAIN_DIAG argmax[:{}]= {:?}  v={}", m, &amh[..m], self.cfg.vocab_size);
        Ok(())
    }

    fn hc_pre(&self, l: &Launcher, sc: &mut Scratch, hc: &HcDev, m: usize) -> Result<()> {
        self.hc_pre_p(l, sc, hc, m, None)
    }

    /// HC (w4): hc_pre with an optional PENDING inject (`pend` = the y pointer a deferred hc_post
    /// did not launch): the inject then rides the norm launch (xq_hc_inj_norm, bitwise ==
    /// xq_hc_inject + xq_hc_norm).
    fn hc_pre_p(&self, l: &Launcher, sc: &mut Scratch, hc: &HcDev, m: usize, pend: Option<u64>) -> Result<()> {
        // HC --w4hc-xcheck: eager p4c-vs-new bit-diff (never inside a graph capture).
        if w4hc_xcheck() && !stream_capturing(l) {
            return self.w4hc_xcheck_run(l, sc, hc, m, pend);
        }
        self.hc_norm_p(l, sc, hc, m, pend)?;
        // WP11 --hc-step-check: eager old-vs-new bit-diff (never inside a graph capture).
        if hc_step_check_on() && !wp11_off() && !stream_capturing(l) {
            return self.hc_step_check(l, sc, hc, m);
        }
        self.hc_mixer(l, sc, hc, m, wp11_off(), true, false)
    }

    /// The norm half of hc_pre: xq_hc_norm, or (pending inject) the fused xq_hc_inj_norm.
    fn hc_norm_p(&self, l: &Launcher, sc: &mut Scratch, hc: &HcDev, m: usize, pend: Option<u64>) -> Result<()> {
        let h = self.cfg.hidden_size;
        let hcn = self.cfg.hc_count.max(1);
        match pend {
            Some(y_ptr) => xqlaunch!(l, "xq_hc_inj_norm", ((hcn * m) as u32, 1, 1), (1024, 1, 1), 0,
                                     (&mut sc.hn, &mut sc.resid, y_ptr, &sc.inj, &hc.norm,
                                      h as i32, hcn as i32, m as i32, self.cfg.rms_eps))?,
            None => xqlaunch!(l, "xq_hc_norm", ((hcn * m) as u32, 1, 1), (1024, 1, 1), 4096,
                              (&mut sc.hn, &sc.resid, &hc.norm, h as i32, hcn as i32, m as i32, self.cfg.rms_eps))?,
        }
        Ok(())
    }

    /// HC (w4): may this forward defer its hc_post injects into the next hc_pre's norm? Callers
    /// AND this with "no diagnostic reads/writes of sc.resid between the two" (dumps, poison).
    fn hc_defer(&self) -> bool {
        w4hc_inj_on() && self.cfg.hidden_size <= 4096
    }

    /// HC (w4): hc_post, deferred when `defer` (the next hc_pre_p takes `pend`). A still-pending
    /// inject is flushed first (never two in flight).
    fn hc_post_d(&self, l: &Launcher, sc: &mut Scratch, y_ptr: u64, m: usize, defer: bool,
                 pend: &mut Option<u64>) -> Result<()> {
        self.hc_flush(l, sc, m, pend)?;
        if defer {
            *pend = Some(y_ptr);
            Ok(())
        } else {
            self.hc_post(l, sc, y_ptr, m)
        }
    }

    /// HC (w4): launch a pending inject as the plain xq_hc_inject (before anything else touches
    /// sc.resid: the PLE boundary).
    fn hc_flush(&self, l: &Launcher, sc: &mut Scratch, m: usize, pend: &mut Option<u64>) -> Result<()> {
        match pend.take() {
            Some(y_ptr) => self.hc_post(l, sc, y_ptr, m),
            None => Ok(()),
        }
    }

    /// HC --w4hc-xcheck: the p4c hc_pre (pending inject as xq_hc_inject, xq_hc_norm, WP11 fuse,
    /// separate mix) then the new one (xq_hc_inj_norm, xq_hc_w4 with uu written) on the same
    /// inputs — sc.resid and sc.inj (the inject's gate input, overwritten by the mix) restored in
    /// between — and bit-compare resid/hn/dd/uu/x/inj over the m live rows. The NEW results stay.
    fn w4hc_xcheck_run(&self, l: &Launcher, sc: &mut Scratch, hc: &HcDev, m: usize, pend: Option<u64>) -> Result<()> {
        use std::sync::Mutex;
        static ST: Mutex<(u64, u64)> = Mutex::new((0, 0)); // (calls, calls with a mismatch)
        let (h, hcn, lr) = (self.cfg.hidden_size, self.cfg.hc_count.max(1), self.cfg.hc_lowrank);
        let rw = h * hcn;
        self.dev.synchronize()?;
        let (r_in, j_in) = (self.dev.dtoh_sync_copy(&sc.resid)?, self.dev.dtoh_sync_copy(&sc.inj)?);
        // ---- p4c path
        if let Some(y) = pend { self.hc_post(l, sc, y, m)?; }
        self.hc_norm_p(l, sc, hc, m, None)?;
        self.hc_mixer(l, sc, hc, m, wp11_off(), false, true)?;
        self.dev.synchronize()?;
        let o = (self.dev.dtoh_sync_copy(&sc.resid)?, self.dev.dtoh_sync_copy(&sc.hn)?, self.dev.dtoh_sync_copy(&sc.dd)?,
                 self.dev.dtoh_sync_copy(&sc.uu)?, self.dev.dtoh_sync_copy(&sc.x)?, self.dev.dtoh_sync_copy(&sc.inj)?);
        // ---- restore the inputs, new path
        self.dev.htod_copy_into(r_in, &mut sc.resid)?;
        self.dev.htod_copy_into(j_in, &mut sc.inj)?;
        self.dev.synchronize()?;
        let fused_inj = pend.is_some() && self.hc_defer();
        if fused_inj {
            self.hc_norm_p(l, sc, hc, m, pend)?;
        } else {
            if let Some(y) = pend { self.hc_post(l, sc, y, m)?; }
            self.hc_norm_p(l, sc, hc, m, None)?;
        }
        let w4 = self.w4hc_takes(hc, m);
        self.hc_mixer(l, sc, hc, m, wp11_off(), true, true)?;
        self.dev.synchronize()?;
        let n = (self.dev.dtoh_sync_copy(&sc.resid)?, self.dev.dtoh_sync_copy(&sc.hn)?, self.dev.dtoh_sync_copy(&sc.dd)?,
                 self.dev.dtoh_sync_copy(&sc.uu)?, self.dev.dtoh_sync_copy(&sc.x)?, self.dev.dtoh_sync_copy(&sc.inj)?);
        let f32d = |a: &[f32], b: &[f32]| -> (usize, Option<usize>) {
            let mut k = (0usize, None);
            for (i, (p, q)) in a.iter().zip(b.iter()).enumerate() {
                if p.to_bits() != q.to_bits() { k.0 += 1; k.1.get_or_insert(i); }
            }
            k
        };
        let u16d = |a: &[u16], b: &[u16]| -> (usize, Option<usize>) {
            let mut k = (0usize, None);
            for (i, (p, q)) in a.iter().zip(b.iter()).enumerate() {
                if p != q { k.0 += 1; k.1.get_or_insert(i); }
            }
            k
        };
        let dr = f32d(&o.0[..m * rw], &n.0[..m * rw]);
        let dh = u16d(&o.1[..m * rw], &n.1[..m * rw]);
        let dd = u16d(&o.2[..m * lr], &n.2[..m * lr]);
        let du = u16d(&o.3[..m * rw], &n.3[..m * rw]);
        let dx = u16d(&o.4[..m * h], &n.4[..m * h]);
        let di = f32d(&o.5[..m * hcn], &n.5[..m * hcn]);
        let bad = dr.0 + dh.0 + dd.0 + du.0 + dx.0 + di.0;
        let nz = o.4[..m * h].iter().filter(|&&b| b & 0x7fff != 0).count();
        let mut g = ST.lock().unwrap();
        g.0 += 1;
        if bad > 0 { g.1 += 1; }
        if (bad > 0 && g.1 <= 20) || g.0 % 500 == 1 {
            println!("W4HC_XCHECK: call {} m={m} inj-fused {} w4 {} gates {} | mismatches resid {}/{} hn {}/{} dd {}/{} uu {}/{} \
                      x {}/{} inj {}/{} (first {:?} {:?} {:?} {:?} {:?} {:?}) | ref x nonzero {nz} | calls-with-mismatch {}/{}",
                     g.0, fused_inj as u8, w4 as u8, hc.winj.is_some() as u8, dr.0, m * rw, dh.0, m * rw, dd.0, m * lr,
                     du.0, m * rw, dx.0, m * h, di.0, m * hcn, dr.1, dh.1, dd.1, du.1, dx.1, di.1, g.1, g.0);
        }
        Ok(())
    }

    /// HC (w4) + TUNE T0c: the xq_hc_w4 grid in the current tune context — w4hc.g raised to the
    /// phase-B minimum and clamped by the load-time co-residency exactly as at load (so == w4hc_grid at
    /// the default). Never 0 while w4hc_grid > 0: the minimum and the margin do not depend on the target.
    fn w4hc_grid_now(&self) -> u32 {
        if self.w4hc_grid == 0 { return 0; }
        w4hc_default_grid(self.w4hc_cap, self.cfg.hidden_size)
    }

    /// HC (w4): does hc_mixer take xq_hc_w4 for this mixer at width m (non-legacy, w4 allowed)?
    fn w4hc_takes(&self, hc: &HcDev, m: usize) -> bool {
        self.w4hc_grid > 0 && w4hc_fuse_on() && m >= 1 && m <= 8 && (m >= 2 || w4hc_m1_on())
            && hc.q8.as_ref().is_some_and(|q| q.up_kmajor)
            && !matches!(crate::opts::var(crate::opt!("hc-fuse")).as_deref(), Ok("0"))
            && crate::opts::var(crate::opt!("hc-int8-check")).is_err()
    }

    /// WP11 --hc-step-check: run the pre-WP11 fuse+mix, then the WP11 one, on the same hn;
    /// bit-compare dd/uu/x/inj. The WP11 results stay in the buffers for the rest of the step.
    fn hc_step_check(&self, l: &Launcher, sc: &mut Scratch, hc: &HcDev, m: usize) -> Result<()> {
        use std::sync::Mutex;
        static ST: Mutex<(u64, u64)> = Mutex::new((0, 0)); // (calls, calls with a mismatch)
        let (h, hcn, lr) = (self.cfg.hidden_size, self.cfg.hc_count.max(1), self.cfg.hc_lowrank);
        let rw = h * hcn;
        self.hc_mixer(l, sc, hc, m, true, false, true)?;
        self.dev.synchronize()?;
        let (d0, u0, x0, i0) = (self.dev.dtoh_sync_copy(&sc.dd)?, self.dev.dtoh_sync_copy(&sc.uu)?,
                                self.dev.dtoh_sync_copy(&sc.x)?, self.dev.dtoh_sync_copy(&sc.inj)?);
        self.hc_mixer(l, sc, hc, m, false, true, true)?;
        self.dev.synchronize()?;
        let (d1, u1, x1, i1) = (self.dev.dtoh_sync_copy(&sc.dd)?, self.dev.dtoh_sync_copy(&sc.uu)?,
                                self.dev.dtoh_sync_copy(&sc.x)?, self.dev.dtoh_sync_copy(&sc.inj)?);
        // (mismatching elements, first mismatch index, max |old - new|)
        let d16 = |a: &[u16], b: &[u16]| {
            let (mut n, mut first, mut mx) = (0usize, None, 0f32);
            for (i, (&p, &q)) in a.iter().zip(b.iter()).enumerate() {
                if p != q {
                    n += 1;
                    first.get_or_insert(i);
                    mx = mx.max((f16::from_bits(p).to_f32() - f16::from_bits(q).to_f32()).abs());
                }
            }
            (n, first, mx)
        };
        let (dd, uu, xx) = (d16(&d0[..m * lr], &d1[..m * lr]), d16(&u0[..m * rw], &u1[..m * rw]),
                            d16(&x0[..m * h], &x1[..m * h]));
        let (mut ni, mut fi, mut mi) = (0usize, None, 0f32);
        for (i, (&p, &q)) in i0[..m * hcn].iter().zip(i1[..m * hcn].iter()).enumerate() {
            if p.to_bits() != q.to_bits() { ni += 1; fi.get_or_insert(i); mi = mi.max((p - q).abs()); }
        }
        let bad = dd.0 + uu.0 + xx.0 + ni;
        let mut g = ST.lock().unwrap();
        g.0 += 1;
        if bad > 0 { g.1 += 1; }
        if (bad > 0 && g.1 <= 20) || g.0 % 500 == 1 {
            println!("HC_STEP_CHECK: call {} m={} mismatches dd {}/{} uu {}/{} x {}/{} inj {}/{} \
                      (first dd {:?} uu {:?} x {:?} inj {:?}; max|d| {:.3e} {:.3e} {:.3e} {:.3e}) \
                      calls-with-mismatch {}/{}",
                     g.0, m, dd.0, m * lr, uu.0, m * rw, xx.0, m * h, ni, m * hcn,
                     dd.1, uu.1, xx.1, fi, dd.2, uu.2, xx.2, mi, g.1, g.0);
        }
        Ok(())
    }

    /// TP-4Z2 (`--tp-k2-prefetch`): tell the decode K2 about to be launched which weights the kernel behind it streams
    /// (the next hc mixer's int8 down/up matrices, 6.5 MB), so the K2's idle threads pull them into L2 while it waits for the
    /// peer. Decode-sized steps on the W4 mixer path only (the case `hc_mixer` takes the xq_hc_w4 launch); anything else arms
    /// nothing. A prefetch hint: no data path, no output byte.
    fn tp_pf_hint(&self, hc: &HcDev, m: usize) {
        let Some(tp) = self.tp.as_ref() else { return };
        if m > 16 { return; }
        let Some(q) = hc.q8.as_ref() else { return };
        if !self.w4hc_takes(hc, m) { return; }
        let dp = |p: &cudarc::driver::sys::CUdeviceptr| *p as u64;
        tp.set_pf_hint([(dp(q.down_q.device_ptr()), q.down_q.len() as u32), (dp(q.up_q.device_ptr()), q.up_q.len() as u32)]);
    }

    /// The fuse + mix half of hc_pre. `legacy` = the exact pre-WP11 launches (--wp11-off=1,
    /// and the reference run of --hc-step-check). `w4` = xq_hc_w4 allowed (false = the p4c
    /// path: the reference run of --w4hc-xcheck); `want_uu` = xq_hc_w4 must also write uu
    /// (the checks compare it; the mix-fused launch otherwise keeps it in smem only).
    fn hc_mixer(&self, l: &Launcher, sc: &mut Scratch, hc: &HcDev, m: usize, legacy: bool, w4: bool,
                want_uu: bool) -> Result<()> {
        let h = self.cfg.hidden_size;
        let hcn = self.cfg.hc_count.max(1);
        let lr = self.cfg.hc_lowrank;
        let rw = h * hcn;
        // HC (w4): the regridded mixer (>= 2 CTAs/SM, row groups, gates before the barrier) with
        // the mix fused behind it — bitwise == the WP11 twin + xq_hc_mix_rg below.
        if !legacy && w4 && self.w4hc_takes(hc, m) {
            let q = hc.q8.as_ref().context("hc w4: int8 mixer missing")?;
            let mix = w4hc_mix_on();
            let flags = w4hc_geom_flags() | (mix as i32) | ((want_uu as i32) << 1);
            let dp = |p: &cudarc::driver::sys::CUdeviceptr| *p as u64;
            let winj = hc.winj.as_ref().map_or(0u64, |w| dp(w.device_ptr()));
            let ptrs = [dp(sc.dd.device_ptr()), dp(sc.uu.device_ptr()), dp(sc.x.device_ptr()), dp(sc.inj.device_ptr()),
                        dp(sc.hn.device_ptr()), dp(q.down_q.device_ptr()), dp(q.down_s.device_ptr()),
                        dp(q.up_q.device_ptr()), dp(q.up_s.device_ptr()), winj, dp(sc.hc_bar.device_ptr())];
            w4hc_launch(l.stream.stream, self.w4hc_grid_now(), ptrs, hcn as f32, lr, m, h, hcn, flags)?;
            if mix { return Ok(()); }
            return self.hc_mix_only(l, sc, hc, m, legacy);
        }
        // S-A3-f-f ITEM 1: the fused hc mixer — down+silu+up in ONE launch with a
        // self-resetting grid barrier between the K=10240 down GEMV and the up GEMV.
        // The old 3-launch path here was the worst kernel family in the engine
        // (97x grid-3 @ 9.3 GB/s = 68.3 ms/round; f-e budget table §1).
        // Guards: measured co-residency (occupancy API; a barrier without it can
        // deadlock), explicit escape, float4 K-step and smem-staging shape limits.
        // grid.x = clamp(cap*5/6 / m, 4, 40): the WHOLE grid (bx*m blocks) stays
        // co-resident for every m <= 16, so decode and every verify width ride ONE
        // path (batch invariance — per-output reduction order is m-independent).
        let fuse = self.hc_fuse_cap > 0
            && !matches!(crate::opts::var(crate::opt!("hc-fuse")).as_deref(), Ok("0"))
            && rw % 256 == 0 && lr > 0 && lr <= 512 && lr % 8 == 0;
        if fuse {
            let cap = (self.hc_fuse_cap * 5) / 6; // 1/6 safety margin on residency
            let bx = (cap / m as u32).clamp(4, 40);
            if bx * m as u32 <= cap {
                match hc.q8.as_ref() {
                    Some(q) if lr % 16 == 0 => {
                        // WP11 R1/R3/R4: the k-major twins run iff up_q holds the k-major
                        // relayout (load-time, gated on THEIR measured residency); `legacy`
                        // takes the old kernels on the row-major copy. Per-output arithmetic
                        // is identical in all of them (bitwise; bx never changes a bit).
                        let upk = q.up_kmajor && !legacy;
                        let up_rm = if q.up_kmajor { q.up_q_rm.as_ref() } else { Some(&q.up_q) };
                        let pf = wp11_pf_mode();
                        let capk = (self.hc_fuse_cap.min(self.wp11_cap.0) * 5) / 6;
                        let bxk = (capk / m as u32).clamp(1, 40);
                        let capr = (self.hc_fuse_cap.min(self.wp11_cap.1) * 5) / 6;
                        if crate::opts::var(crate::opt!("hc-int8-check")).is_ok() {
                            // diagnostic (eager: --exl3-no-graph=1): fp16 twin first, then int8
                            xqlaunch!(l, "xq_hc_fuse", (bx, m as u32, 1), (256, 1, 1), 0,
                                     (&mut sc.dd, &mut sc.uu, &sc.hn, &hc.down, &hc.up, &sc.hc_bar,
                                      hcn as f32, lr as i32, rw as i32))?;
                            self.dev.synchronize()?;
                            let r = self.dev.dtoh_sync_copy(&sc.uu)?;
                            if q.up_kmajor {
                                xqlaunch!(l, "xq_hc_fuse_i8k", (bxk, m as u32, 1), (256, 1, 1), 0,
                                         (&mut sc.dd, &mut sc.uu, &sc.hn, &q.down_q, &q.down_s, &q.up_q, &q.up_s,
                                          &sc.hc_bar, hcn as f32, lr as i32, rw as i32, pf))?;
                            } else {
                                xqlaunch!(l, "xq_hc_fuse_i8", (bx, m as u32, 1), (256, 1, 1), 0,
                                         (&mut sc.dd, &mut sc.uu, &sc.hn, &q.down_q, &q.down_s, &q.up_q, &q.up_s,
                                          &sc.hc_bar, hcn as f32, lr as i32, rw as i32))?;
                            }
                            self.dev.synchronize()?;
                            let t = self.dev.dtoh_sync_copy(&sc.uu)?;
                            hc_int8_check(&r[..m * rw], &t[..m * rw]);
                        } else if upk && m >= 2 && m <= 8 && hc_rb_on() && capr >= 4 {
                            // WP11 row-batched twin (R1 prefetch, R3 k-major, R4 hn staging).
                            let bxr = hc_bxr().min(capr);
                            let r4 = if wp11_r4_on() && rw % 1024 == 0 { 16 } else { 0 };
                            xqlaunch!(l, "xq_hc_fuse_i8_rbk", (bxr, 1, 1), (256, 1, 1), 0,
                                     (&mut sc.dd, &mut sc.uu, &sc.hn, &q.down_q, &q.down_s, &q.up_q, &q.up_s,
                                      &sc.hc_bar, hcn as f32, (lr as i32) | ((m as i32) << 16), rw as i32, pf | r4))?;
                        } else if upk && bxk * m as u32 <= capk {
                            // WP11 m-grid twin (m = 1 decode/draft/seam; any width rb does not take).
                            let cvt = if wp11_cvt_i2f() { 4 } else { 0 };
                            xqlaunch!(l, "xq_hc_fuse_i8k", (bxk, m as u32, 1), (256, 1, 1), 0,
                                     (&mut sc.dd, &mut sc.uu, &sc.hn, &q.down_q, &q.down_s, &q.up_q, &q.up_s,
                                      &sc.hc_bar, hcn as f32, lr as i32, rw as i32, pf | cvt))?;
                        } else if m >= 2 && m <= 8 && lr <= 512 && hc_rb_on() {
                            // row-batched twin: weights streamed once for all m rows, per-row
                            // arithmetic identical (bitwise). 40 blocks, one grid row.
                            let up_rm = up_rm.context("hc int8: row-major q_up missing for the old kernel")?;
                            let bxr = hc_bxr().min(cap.max(4));
                            xqlaunch!(l, "xq_hc_fuse_i8_rb", (bxr, 1, 1), (256, 1, 1), 0,
                                     (&mut sc.dd, &mut sc.uu, &sc.hn, &q.down_q, &q.down_s, up_rm, &q.up_s,
                                      &sc.hc_bar, hcn as f32, (lr as i32) | ((m as i32) << 16), rw as i32))?;
                        } else {
                            let up_rm = up_rm.context("hc int8: row-major q_up missing for the old kernel")?;
                            xqlaunch!(l, "xq_hc_fuse_i8", (bx, m as u32, 1), (256, 1, 1), 0,
                                     (&mut sc.dd, &mut sc.uu, &sc.hn, &q.down_q, &q.down_s, up_rm, &q.up_s,
                                      &sc.hc_bar, hcn as f32, lr as i32, rw as i32))?;
                        }
                    }
                    _ => xqlaunch!(l, "xq_hc_fuse", (bx, m as u32, 1), (256, 1, 1), 0,
                                  (&mut sc.dd, &mut sc.uu, &sc.hn, &hc.down, &hc.up, &sc.hc_bar,
                                   hcn as f32, lr as i32, rw as i32))?,
                }
            } else {
                // Width beyond the co-resident budget (bench-only widths > 16):
                // fall back to the vectorized 2-kernel path for THIS model-load,
                // consistently for every m within the load.
                xqlaunch!(l, "xq_gemm_f16_v", (((lr as u32) + 7) / 8, m as u32, 1), (256, 1, 1), 0,
                         (&mut sc.dd, &hc.down, &sc.hn, m as i32, lr as i32, rw as i32))?;
                xqlaunch!(l, "xq_silu_div", (((lr * m) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                         (&mut sc.dd, hcn as f32, (lr * m) as i32))?;
                xqlaunch!(l, "xq_gemm_f16_v", (((rw as u32) + 7) / 8, m as u32, 1), (256, 1, 1), 0,
                         (&mut sc.uu, &hc.up, &sc.dd, m as i32, rw as i32, lr as i32))?;
            }
        } else {
            // Original path (also the --hc-fuse=0 escape — consistent for all m).
            xqlaunch!(l, "xq_gemm_f16", (((lr as u32) + 127) / 128, m as u32, 1), (128, 1, 1), 0,
                     (&mut sc.dd, &hc.down, &sc.hn, m as i32, lr as i32, rw as i32))?;
            xqlaunch!(l, "xq_silu_div", (((lr * m) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                     (&mut sc.dd, hcn as f32, (lr * m) as i32))?;
            xqlaunch!(l, "xq_gemm_f16", (((rw as u32) + 127) / 128, m as u32, 1), (128, 1, 1), 0,
                     (&mut sc.uu, &hc.up, &sc.dd, m as i32, rw as i32, lr as i32))?;
        }
        self.hc_mix_only(l, sc, hc, m, legacy)
    }

    /// The mix half of hc_mixer (x + the inject gates from hn and uu): WP11 R2 xq_hc_mix_rg, or
    /// xq_hc_mix4 / xq_hc_mix (legacy / R2 off).
    fn hc_mix_only(&self, l: &Launcher, sc: &mut Scratch, hc: &HcDev, m: usize, legacy: bool) -> Result<()> {
        let h = self.cfg.hidden_size;
        let hcn = self.cfg.hc_count.max(1);
        // WP11 R2: regridded mix — each inject tree alone in its block (loads hoisted, same
        // leaves + pairing), x spread over h/1024 blocks; grid (ninj + nxb, m), block 1024. Bitwise.
        if !legacy && wp11_r2_on() && m <= 64 {
            let ninj = if hc.winj.is_some() { hcn } else { 0 };
            let gx = (ninj + (h + 1023) / 1024) as u32;
            match &hc.winj {
                Some(w) => xqlaunch!(l, "xq_hc_mix_rg", (gx, m as u32, 1), (1024, 1, 1), 0,
                                    (&mut sc.x, &mut sc.inj, &sc.hn, &sc.uu, w, h as i32, hcn as i32, m as i32))?,
                None => xqlaunch!(l, "xq_hc_mix_rg", (gx, m as u32, 1), (1024, 1, 1), 0,
                                 (&mut sc.x, &mut sc.inj, &sc.hn, &sc.uu, 0u64, h as i32, hcn as i32, m as i32))?,
            }
            return Ok(());
        }
        // xq_hc_mix4: the hc inject reductions share one tree pass (bitwise; --hc-mix4=0 = old)
        let (mixk, mixs) = if hcn <= 4 && hc_mix4_on() { ("xq_hc_mix4", 4 * 1024 * 4) } else { ("xq_hc_mix", 4096) };
        match &hc.winj {
            Some(w) => xqlaunch!(l, mixk, (m as u32, 1, 1), (1024, 1, 1), mixs as u32,
                                (&mut sc.x, &mut sc.inj, &sc.hn, &sc.uu, w, h as i32, hcn as i32, m as i32))?,
            None => xqlaunch!(l, mixk, (m as u32, 1, 1), (1024, 1, 1), mixs as u32,
                             (&mut sc.x, &mut sc.inj, &sc.hn, &sc.uu, 0u64, h as i32, hcn as i32, m as i32))?,
        }
        Ok(())
    }

    fn hc_post(&self, l: &Launcher, sc: &mut Scratch, y_ptr: u64, m: usize) -> Result<()> {
        let h = self.cfg.hidden_size;
        let hcn = self.cfg.hc_count.max(1);
        xqlaunch!(l, "xq_hc_inject", (((h * hcn * m) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (&mut sc.resid, y_ptr, &sc.inj, h as i32, hcn as i32, m as i32))?;
        Ok(())
    }

    /// PLE n-gram injection (S-A3-d Phase 0b): emb gather (host) + proj/norm/gate/conv (device),
    /// delta added to the stream stack BEFORE block 1's hc_pre reads it.
    /// S-A3-f Item 1b: HOST half of PLE (n-gram ring update + embedding bits build).
    /// Pure host work on per-slot history + this step's tokens — runs in the step prefix,
    /// OUTSIDE the graphed kernel region.
    fn ple_build_embed(&self, m: usize, toks: &[i32], slots: &[usize], emb_bits: &mut [u16]) -> Result<()> {
        let ple = match self.ple.as_ref() {
            Some(p) => p,
            None => return Ok(()),
        };
        let mut hist = self.ple_hist.lock().unwrap();
        for q in 0..m {
            // S-A3-e FIX: the n-gram ring is PER-SLOT (batch row q is the launch position).
            let s = slots[q];
            let h = [hist[s * 2], hist[s * 2 + 1], toks[q]];
            let uids = ple.ngram_uids(&h);
            ple.embed_row(&uids, &mut emb_bits[q * 2560..(q + 1) * 2560])?;
            if ple_xcheck_on() {
                let mut refr = vec![0u16; 2560];
                ple.embed_row_ref(&uids, &mut refr)?;
                let (n, first) = wp05_diff_u16(&emb_bits[q * 2560..(q + 1) * 2560], &refr);
                if n > 0 || q == 0 {
                    println!("PLE_XCHECK step row {q}/{m} slot {s}: {n} mismatching f16 of 2560 (first (idx, new, old) {first:?})");
                }
            }
            hist[s * 2] = hist[s * 2 + 1];
            hist[s * 2 + 1] = toks[q];
        }
        Ok(())
    }

    /// S-A3-f Item 1b: DEVICE half of PLE — launches only (capture-safe). Reads the
    /// embedding bits uploaded into the persistent sc.ple_emb by the step prefix.
    fn ple_kernels(&self, l: &Launcher, sc: &mut Scratch, m: usize, prefix_done: bool) -> Result<()> {
        let ple = match self.ple.as_ref() {
            Some(p) => p,
            None => return Ok(()),
        };
        let eps = self.cfg.rms_eps as f32;
        let scale = 1.0f32 / (2560f32).sqrt();
        // S-A3-m: row-batched bit-exact twin (weights read once for all m rows).
        anyhow::ensure!(m <= 16, "ple_kernels: m {m} > 16");
        // WP27: `prefix_done` = ple_prefix already ran early (layer 0's MoE window).
        if !prefix_done {
            self.ple_prefix(l, sc, m)?;
        }
        xqlaunch!(l, "xq_ple_norm_f32", (m as u32 * 4, 1, 1), (256, 1, 1), 0,
                 (&sc.resid, &ple.norm_query_w, &mut sc.ple_qn, eps))?;
        xqlaunch!(l, "xq_ple_gate", (m as u32 * 4, 1, 1), (256, 1, 1), 0,
                 (&sc.ple_qn, &sc.ple_kn, &sc.ple_val, &mut sc.ple_gated, scale))?;
        xqlaunch!(l, "xq_ple_norm_hh", (m as u32 * 4, 1, 1), (256, 1, 1), 0,
                 (&sc.ple_gated, &ple.norm_conv_w, &mut sc.ple_normed, eps))?;
        xqlaunch!(l, "xq_ple_conv", (((m * 10240) as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                 (&mut sc.resid, &sc.ple_gated, &sc.ple_normed, &self.ple_state, &ple.conv_w, m as i32, &sc.slots))?;
        xqlaunch!(l, "xq_ple_state_shift", (((m * 10240) as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                 (&sc.ple_normed, *self.ple_state.device_ptr() as u64, m as i32, &sc.slots))?;
        Ok(())
    }

    /// The head of the PLE device chain that reads nothing but the staged embedding bits
    /// (sc.ple_emb): key/value projections (WP09 k-major launch, else the row-major pair) and
    /// the key norm, in the original kernel order. Writes ple_key16 / ple_val / ple_kn only.
    /// Decode (ple_kernels) and verify run it at the layer-1 boundary, or — WP27 PLE fork —
    /// early, beside layer 0's MoE window.
    fn ple_prefix(&self, l: &Launcher, sc: &mut Scratch, m: usize) -> Result<()> {
        let ple = match self.ple.as_ref() {
            Some(p) => p,
            None => return Ok(()),
        };
        let eps = self.cfg.rms_eps as f32;
        // WP09: key+value in ONE coalesced k-major launch (bitwise); else the row-major pair.
        let km = self.ple_proj_km(l, sc, m)?;
        if !km {
        xqlaunch!(l, "xq_gemm_f16_rows", (80u32, 1, 1), (128, 1, 1), 0,
                 (&mut sc.ple_key16, &ple.key_w, &sc.ple_emb, m as i32, 10240i32, 2560i32))?;
        }
        xqlaunch!(l, "xq_ple_norm_f16", (m as u32 * 4, 1, 1), (256, 1, 1), 0,
                 (&sc.ple_key16, &ple.norm_key_w, &mut sc.ple_kn, eps))?;
        if !km {
        xqlaunch!(l, "xq_gemm_f16_rows", (20u32, 1, 1), (128, 1, 1), 0,
                 (&mut sc.ple_val, &ple.value_w, &sc.ple_emb, m as i32, 2560i32, 2560i32))?;
        }
        Ok(())
    }

    /// WP27 PLE fork: launch ple_prefix beside layer 0's MoE window (decode step and verify
    /// alike) instead of at the layer-1 boundary. Same conditions as the layer-1 PLE block.
    fn wp27_ple_early(&self) -> bool {
        crate::exl3_wp27::fork_on(crate::exl3_wp27::FORK_PLE) && self.ple.is_some() && self.layers.len() > 1
            && crate::opts::var(crate::opt!("exl3-no-ple")).is_err()
    }

    /// WP09: the PLE key (N=10240) + value (N=2560) projections of sc.ple_emb through the k-major
    /// twin xq_gemm_f16_rows_km — ONE 100-block launch (80 key + 20 value blocks), coalesced
    /// 1-KB weight bursts, per-output arithmetic identical to xq_gemm_f16_rows (bitwise).
    /// Ok(false) = no k-major copies (--wp09-off=1 / --wp09-ple=0 at load): the caller runs
    /// the row-major pair at its original positions. Launch-only (capture-safe) unless
    /// --wp09-xcheck=1 on an eager step.
    fn ple_proj_km(&self, l: &Launcher, sc: &mut Scratch, m: usize) -> Result<bool> {
        let ple = match self.ple.as_ref() {
            Some(p) => p,
            None => return Ok(false),
        };
        let (kk, vk) = match (ple.key_km.as_ref(), ple.value_km.as_ref()) {
            (Some(a), Some(b)) => (a, b),
            _ => return Ok(false),
        };
        anyhow::ensure!(m >= 1 && m <= 16, "ple_proj_km: m {m} out of 1..=16");
        // W4S (ple): x staged in smem, exact-M body (bitwise; --w4s-off=ple = the launch below)
        if !self.w4s_ple_km(l, sc, kk, vk, m)? {
        xqlaunch!(l, "xq_gemm_f16_rows_km", (100u32, 1, 1), (128, 1, 1), 0,
                 (&mut sc.ple_key16, kk, 10240i32, 80i32, &mut sc.ple_val, vk, 2560i32,
                  &sc.ple_emb, m as i32, 2560i32))?;
        }
        if wp09_xcheck() && !self.stream_capturing() {
            let mut ko = self.dev.alloc_zeros::<u16>(m * 10240)?;
            let mut vo = self.dev.alloc_zeros::<u16>(m * 2560)?;
            xqlaunch!(l, "xq_gemm_f16_rows", (80u32, 1, 1), (128, 1, 1), 0,
                     (&mut ko, &ple.key_w, &sc.ple_emb, m as i32, 10240i32, 2560i32))?;
            xqlaunch!(l, "xq_gemm_f16_rows", (20u32, 1, 1), (128, 1, 1), 0,
                     (&mut vo, &ple.value_w, &sc.ple_emb, m as i32, 2560i32, 2560i32))?;
            self.dev.synchronize()?;
            let kn = self.dev.dtoh_sync_copy(&sc.ple_key16)?;
            let vn = self.dev.dtoh_sync_copy(&sc.ple_val)?;
            let ko = self.dev.dtoh_sync_copy(&ko)?;
            let vo = self.dev.dtoh_sync_copy(&vo)?;
            wp09_diff_u16("ple_key", m, &kn[..m * 10240], &ko);
            wp09_diff_u16("ple_val", m, &vn[..m * 2560], &vo);
        }
        Ok(true)
    }

    /// WP09: greedy argmax of sc.logits rows 0..m (row stride = width = v) -> sc.argmax[0..m].
    /// Default: ONE xq_argmax_rows launch (grid nb x m, last-block reduce, self re-arming
    /// counters) — the same ids as xq_argmax bit for bit (the comparator's order is total).
    /// --wp09-off=1 / --wp09-argmax=0: the m single-block xq_argmax launches.
    fn argmax_rows(&self, l: &Launcher, sc: &mut Scratch, m: usize, v: usize) -> Result<()> {
        if !wp09_argmax_on() {
            for i in 0..m {
                xqlaunch!(l, "xq_argmax", (1, 1, 1), (1024, 1, 1), (1024 * 12) as u32,
                         (&mut sc.argmax, i as i32, &sc.logits, (i * v) as i64, v as i32))?;
            }
            return Ok(());
        }
        anyhow::ensure!(m >= 1 && m <= sc.am_cnt.len(), "argmax_rows: m {m} > scratch width {}", sc.am_cnt.len());
        let nb = wp09_am_nb(m);
        xqlaunch!(l, "xq_argmax_rows", (nb as u32, m as u32, 1), (256, 1, 1), 0,
                 (&mut sc.argmax, 0i32, &sc.logits, 0i64, v as i64, v as i32, &mut sc.am_part, &mut sc.am_cnt))?;
        if wp09_xcheck() && !self.stream_capturing() {
            let mut old = self.dev.alloc_zeros::<i32>(m)?;
            for i in 0..m {
                xqlaunch!(l, "xq_argmax", (1, 1, 1), (1024, 1, 1), (1024 * 12) as u32,
                         (&mut old, i as i32, &sc.logits, (i * v) as i64, v as i32))?;
            }
            self.dev.synchronize()?;
            let a = self.dev.dtoh_sync_copy(&sc.argmax)?;
            let b = self.dev.dtoh_sync_copy(&old)?;
            let mism: Vec<(usize, i32, i32)> = (0..m).filter(|&i| a[i] != b[i]).map(|i| (i, a[i], b[i])).collect();
            println!("WP09_XCHECK argmax m={m} v={v} nb={nb} mism={} first={:?} ids={:?}",
                     mism.len(), mism.first(), &a[..m]);
        }
        Ok(())
    }

    /// WP09 (XCHECK only): true while self.stream is being captured into a graph — the
    /// diagnostic syncs the device, which is illegal inside a capture. (Also WP04/WP14's
    /// eager-only XCHECKs.)
    fn stream_capturing(&self) -> bool {
        use cudarc::driver::sys;
        let mut st = sys::CUstreamCaptureStatus::CU_STREAM_CAPTURE_STATUS_NONE;
        let r = unsafe { sys::cuStreamIsCapturing(self.stream.stream, &mut st) };
        r != sys::CUresult::CUDA_SUCCESS || st != sys::CUstreamCaptureStatus::CU_STREAM_CAPTURE_STATUS_NONE
    }

    /// One MoE call. TP-A: an expert-parallel layer (moe.ep = Some) runs the served expert path
    /// on its LOCAL route tables (the filter inside moe_inner) and then turns the rank's routed
    /// (+ rank-0 shared) contribution into the full-rank moe_out with one FP32 all-reduce.
    fn moe(&self, l: &Launcher, sc: &mut Scratch, moe: &MoeLayer, m: usize) -> Result<()> {
        self.moe_inner(l, sc, moe, m)?;
        if let Some(ep) = moe.ep.as_ref() {
            self.ep_combine_reduce(l, sc, moe, ep, m)?;
        }
        // TP-A xtp diagnostic (eager TP=1 reference only): the reduction-site ulp floor.
        if xtp::moe_ulp_armed() && moe.ep.is_none() && self.tp.is_none() && !stream_capturing(l) {
            self.moe_ulp_perturb(sc, m)?;
        }
        Ok(())
    }

    fn moe_inner(&self, l: &Launcher, sc: &mut Scratch, moe: &MoeLayer, m: usize) -> Result<()> {
        let h = self.cfg.hidden_size;
        let ne = self.cfg.num_experts;
        let topk = self.cfg.num_experts_per_tok;
        let mi = self.cfg.moe_intermediate_size;
        // WP27: fork base for the shared expert (it reads only sc.x) — while capturing, the
        // shared expert becomes a sibling branch of the routed path, joined at xq_moe_combine.
        // Inert when eager or --wp27-off=1 (then this is the linear sequence below).
        let mut wp27 = crate::exl3_wp27::Cap::open(l.stream.stream, sc.wp27_cls, crate::exl3_wp27::FORK_MOE);
        // S-A3-h item 3 rung 1: cooperative expert-stream schedule — port of the
        // reference implementation's exl3_moe_coop_a/b byte schedule (R-M3 §4; 512-thread blocks,
        // one per (expert-run, 32-col group, projection), cp.async.cg staging
        // with 6-deep pipeline groups). Math is INSTRUCTION-IDENTICAL to
        // xq_gemm_grouped_xh (see the bit-identity contract in
        // kernels/exl3_bench.cu): same exl3_dq_from decode -> same f16
        // fragments -> same mma.sync m16n8k16 K-ascending chain, staging is
        // value-transparent. Default OFF until --probe-exl3-binv / bench-mtp
        // confirm bit-equality on hardware; --moe-coop=1 enables,
        // --moe-coop=0 forces the original grouped path (A/B measurement).
        let moe_coop = tune::get(&T_MOE_COOP, &l.cx()) != 0; // TUNE S2 (legacy alias --moe-coop)
        // S-A3-f-d step 0 lever 1: router K-split. ks is a pure function of (K, ne)
        // (batch-invariant); partials + fixed ascending-ks combine. Reduction order
        // vs the monolithic kernel differs → drift-audit protocol applies.
        // --exl3-router-ks=0/1 forces the old path (A-B/diagnostics).
        let rks = router_ks(h as i32, ne as i32);
        let rw_need = rks as usize * m * ne;
        // S-A3-z lever 2: fused routing (router GEMV + K-split combine; top-k + route) — bit-identical
        // to the ks=64 path below. --exl3-router-fused=0 = the old launches; --exl3-router-xcheck=1
        // runs both and diffs logits / ids / wts / route tables bitwise (eager only).
        let fused = rks == 64 && m <= 8 && ne % 4 == 0 && h % 64 == 0 && (h / 64) % 8 == 0 && topk <= 16
            && tune::get(&T_ROUTER_FUSED, &l.cx()) != 0;
        let rxc = fused && crate::opts::var(crate::opt!("exl3-router-xcheck")).is_ok();
        // WP10: routing fold — xq_router_fused + xq_router_topk_route in ONE launch (the last GEMV block
        // runs softmax / top-k / renorm / route), bit-identical. Default ON; --wp10-off=1 = the
        // S-A3-z two-kernel path. With ROUTER_XCHECK the fold is diffed against the ks path;
        // --wp10-xcheck=1 diffs it against the S-A3-z pair (both eager only).
        let fold = fused && wp10_fold_on() && ne <= 512 && m * topk <= 128;
        let fxc = fold && crate::opts::var(crate::opt!("wp10-xcheck")).is_ok();
        if !fused || rxc {
        if rks > 1 && sc.router_ws.len() >= rw_need {
            xqlaunch!(l, "xq_router_ks", (((ne as u32) + 255) / 256, m as u32, rks), (256, 1, 1), 0,
                     (&mut sc.router_ws, &moe.router, &sc.x, m as i32, ne as i32, h as i32, rks as i32))?;
            let mn = (m * ne) as u32;
            xqlaunch!(l, "xq_router_combine", ((mn + 255) / 256, 1, 1), (256, 1, 1), 0,
                     (&sc.router_ws, &mut sc.logits_r, m as i32, ne as i32, rks as i32))?;
        } else {
        // S-A3-f-f ITEM 1: router GEMV — BIT-EXACT twin (float4 loads, identical
        // ascending fp32 accumulation => identical output bits; AGENTS §7).
        xqlaunch!(l, "xq_gemm_f16_f32_v", (((ne as u32) + 255) / 256, m as u32, 1), (256, 1, 1), 0,
                 (&mut sc.logits_r, &moe.router, &sc.x, m as i32, ne as i32, h as i32))?;
        }
        xqlaunch!(l, "xq_router_topk", (m as u32, 1, 1), (256, 1, 1), ((256 + ne + 512) * 4) as u32,
                 (&mut sc.ids, &mut sc.wts, &sc.logits_r, ne as i32, topk as i32, m as i32))?;
        // S-A3-f Item 2: device-side routing — the dedup/slotmap/offset build the host
        // used to do after a sync+dtoh (first-seen over ids row-major, identical
        // semantics), now one kernel. No host round-trip; consumer grids are PADDED to
        // the topk cap and early-exit on the device count.
        xqlaunch!(l, "xq_moe_route", (1, 1, 1), (256, 1, 1), 0,
                 (&sc.ids, m as i32, topk as i32, ne as i32, &mut sc.slotmap, &mut sc.idxmap,
                  &mut sc.esel, &mut sc.offs_gu, &mut sc.offs_d, moe.gu_words, moe.d_words))?;
        }
        if fused && (!fold || fxc) {
            let snap = if rxc {
                self.dev.synchronize()?;
                Some((self.dev.dtoh_sync_copy(&sc.logits_r)?, self.dev.dtoh_sync_copy(&sc.ids)?,
                      self.dev.dtoh_sync_copy(&sc.wts)?, self.dev.dtoh_sync_copy(&sc.slotmap)?,
                      self.dev.dtoh_sync_copy(&sc.idxmap)?, self.dev.dtoh_sync_copy(&sc.esel)?,
                      self.dev.dtoh_sync_copy(&sc.offs_gu)?, self.dev.dtoh_sync_copy(&sc.offs_d)?))
            } else { None };
            xqlaunch!(l, "xq_router_fused", ((ne / 4) as u32, 1, 1), (256, 1, 1), 0,
                     (&mut sc.logits_r, &moe.router, &sc.x, m as i32, ne as i32, h as i32))?;
            let f = xq_raw_fn("xq_router_topk_route")
                .ok_or_else(|| anyhow::anyhow!("xq_router_topk_route raw fn unavailable (stale PTX?)"))?;
            let mut a_ids = *sc.ids.device_ptr() as u64; let mut a_wts = *sc.wts.device_ptr() as u64;
            let mut a_lg = *sc.logits_r.device_ptr() as u64;
            let mut a_ne = ne as i32; let mut a_k = topk as i32; let mut a_b = m as i32;
            let mut a_cnt = *sc.route_cnt.device_ptr() as u64;
            let mut a_sm = *sc.slotmap.device_ptr() as u64; let mut a_ix = *sc.idxmap.device_ptr() as u64;
            let mut a_es = *sc.esel.device_ptr() as u64;
            let mut a_og = *sc.offs_gu.device_ptr() as u64; let mut a_od = *sc.offs_d.device_ptr() as u64;
            let mut a_gw = moe.gu_words; let mut a_dw = moe.d_words;
            let mut args: [*mut std::ffi::c_void; 14] = [
                &mut a_ids as *mut u64 as *mut _, &mut a_wts as *mut u64 as *mut _, &mut a_lg as *mut u64 as *mut _,
                &mut a_ne as *mut i32 as *mut _, &mut a_k as *mut i32 as *mut _, &mut a_b as *mut i32 as *mut _,
                &mut a_cnt as *mut u64 as *mut _, &mut a_sm as *mut u64 as *mut _, &mut a_ix as *mut u64 as *mut _,
                &mut a_es as *mut u64 as *mut _, &mut a_og as *mut u64 as *mut _, &mut a_od as *mut u64 as *mut _,
                &mut a_gw as *mut u64 as *mut _, &mut a_dw as *mut u64 as *mut _,
            ];
            let smem = ((256 + ne + 8 * 16 * 2) * 4) as u32;
            let r = unsafe {
                cudarc::driver::sys::cuLaunchKernel(f, m as u32, 1, 1, 256, 1, 1, smem, self.stream.stream,
                    args.as_mut_ptr(), std::ptr::null_mut())
            };
            anyhow::ensure!(r == cudarc::driver::sys::CUresult::CUDA_SUCCESS, "xq_router_topk_route launch ({r:?})");
            if let Some((l0, i0, w0, s0, x0, e0, g0, d0)) = snap {
                self.dev.synchronize()?;
                let (l1, i1, w1) = (self.dev.dtoh_sync_copy(&sc.logits_r)?, self.dev.dtoh_sync_copy(&sc.ids)?,
                                    self.dev.dtoh_sync_copy(&sc.wts)?);
                let (s1, x1, e1) = (self.dev.dtoh_sync_copy(&sc.slotmap)?, self.dev.dtoh_sync_copy(&sc.idxmap)?,
                                    self.dev.dtoh_sync_copy(&sc.esel)?);
                let (g1, d1) = (self.dev.dtoh_sync_copy(&sc.offs_gu)?, self.dev.dtoh_sync_copy(&sc.offs_d)?);
                let nl = m * ne; let nk = m * topk; let ns = e0[0].max(0) as usize;
                let dl = (0..nl).filter(|&i| l0[i].to_bits() != l1[i].to_bits()).count();
                let di = (0..nk).filter(|&i| i0[i] != i1[i]).count();
                let dw = (0..nk).filter(|&i| w0[i].to_bits() != w1[i].to_bits()).count();
                let dr = (s0 != s1) as usize + (x0[..ns] != x1[..ns]) as usize + (e0[0] != e1[0]) as usize
                    + (g0[..ns] != g1[..ns]) as usize + (d0[..ns] != d1[..ns]) as usize;
                static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
                let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                if c < 4 || dl + di + dw + dr > 0 {
                    println!("ROUTER_XCHECK m={m}: logits bit-diff {dl}/{nl}, ids {di}/{nk}, wts {dw}/{nk}, route tables {dr}/5 (esel {})", e1[0]);
                }
                if dl + di + dw + dr > 0 { anyhow::bail!("fused routing diverges from the reference path"); }
            }
        }
        let mut ep_routed = false; // TP-G lever #5: the fold built this rank's EP tables
        if fold {
            // Reference for the XCHECK = whatever ran above: the ks path (ROUTER_XCHECK) or the
            // S-A3-z pair (--wp10-xcheck). Eager only (syncs + dtoh).
            let snap = if rxc || fxc {
                self.dev.synchronize()?;
                Some((self.dev.dtoh_sync_copy(&sc.logits_r)?, self.dev.dtoh_sync_copy(&sc.ids)?,
                      self.dev.dtoh_sync_copy(&sc.wts)?, self.dev.dtoh_sync_copy(&sc.slotmap)?,
                      self.dev.dtoh_sync_copy(&sc.idxmap)?, self.dev.dtoh_sync_copy(&sc.esel)?,
                      self.dev.dtoh_sync_copy(&sc.offs_gu)?, self.dev.dtoh_sync_copy(&sc.offs_d)?))
            } else { None };
            // W4S (router): the persistent twin xq_router_fold_w4 (bitwise; --w4s-off=router =
            // the fold below). The ROUTER_XCHECK / WP10_XCHECK snapshots above then check it too.
            // A5-K2 (moe.router_coal): the coalesced-weight twin xq_router_fold_c (grid ne/4 x 256,
            // K == 2560 only: the 40-wide slice chains), ahead of W4S router when on.
            let coal = h == 64 * 40 && tune::get(&T_MOE_ROUTER_COAL, &l.cx()) != 0;
            let w4r = !coal && w4s_on(W4S_ROUTER) && self.w4s_router_fold(l, sc, moe, m)?;
            // TP-G (T2 lever #5): on an EP rank, the COAL fold's route tail builds the LOCAL tables
            // itself (xq_router_fold_c_ep; bitwise == fold + xq_moe_route_ep) — one launch fewer per MoE
            // layer. Not under the eager XCHECK snapshots (their reference is the global route).
            let ep_fold = coal && snap.is_none() && moe.ep.is_some() && xtp::route_fold_on();
            let fname = if ep_fold { "xq_router_fold_c_ep" } else if coal { "xq_router_fold_c" } else if w4r { "xq_router_fold_w4" }
                        else if wp10_gemv_remap() { "xq_router_fold" } else { "xq_router_fold_m0" };
            let dsmem = if coal { RFC_SMEM } else { 0 };
            if coal {
                static K2_ONCE: std::sync::Once = std::sync::Once::new();
                K2_ONCE.call_once(|| println!("A5-K2: router fold COAL ON (xq_router_fold_c, grid {} x 256, smem {RFC_SMEM}; \
                                               --router-coal=0 = the previous fold)", ne / 4));
            }
            if !w4r {
            let f = xq_raw_fn(fname)
                .ok_or_else(|| anyhow::anyhow!("{fname} raw fn unavailable (stale PTX?)"))?;
            static WP10_ONCE: std::sync::Once = std::sync::Once::new();
            WP10_ONCE.call_once(|| println!("WP10: routing fold ON ({fname}; --wp10-off=1 = S-A3-z pair, \
                                              --wp10-gemv=0 = legacy GEMV lane map)"));
            let mut a_lg = *sc.logits_r.device_ptr() as u64;
            let mut a_w = *moe.router.device_ptr() as u64; let mut a_x = *sc.x.device_ptr() as u64;
            let mut a_m = m as i32; let mut a_n = ne as i32; let mut a_h = h as i32;
            let mut a_cnt = *sc.fold_cnt.device_ptr() as u64;
            let mut a_ids = *sc.ids.device_ptr() as u64; let mut a_wts = *sc.wts.device_ptr() as u64;
            let mut a_k = topk as i32;
            let mut a_sm = *sc.slotmap.device_ptr() as u64; let mut a_ix = *sc.idxmap.device_ptr() as u64;
            let mut a_es = *sc.esel.device_ptr() as u64;
            let mut a_og = *sc.offs_gu.device_ptr() as u64; let mut a_od = *sc.offs_d.device_ptr() as u64;
            let mut a_gw = moe.gu_words; let mut a_dw = moe.d_words;
            let mut a_lut = moe.ep.as_ref().map_or(0u64, |ep| *ep.lut.device_ptr() as u64);
            let mut args: [*mut std::ffi::c_void; 18] = [
                &mut a_lg as *mut u64 as *mut _, &mut a_w as *mut u64 as *mut _, &mut a_x as *mut u64 as *mut _,
                &mut a_m as *mut i32 as *mut _, &mut a_n as *mut i32 as *mut _, &mut a_h as *mut i32 as *mut _,
                &mut a_cnt as *mut u64 as *mut _, &mut a_ids as *mut u64 as *mut _, &mut a_wts as *mut u64 as *mut _,
                &mut a_k as *mut i32 as *mut _,
                &mut a_sm as *mut u64 as *mut _, &mut a_ix as *mut u64 as *mut _, &mut a_es as *mut u64 as *mut _,
                &mut a_og as *mut u64 as *mut _, &mut a_od as *mut u64 as *mut _,
                &mut a_gw as *mut u64 as *mut _, &mut a_dw as *mut u64 as *mut _,
                &mut a_lut as *mut u64 as *mut _,   // read only by xq_router_fold_c_ep (extra params are ignored)
            ];
            if ep_fold {
                static EPF_ONCE: std::sync::Once = std::sync::Once::new();
                EPF_ONCE.call_once(|| println!("TP-G: EP route folded into the router fold (xq_router_fold_c_ep; \
                                                --tp-route-fold=0 = fold + xq_moe_route_ep)"));
            }
            let grid = ((ne / 4) as u32, 1u32, 1u32);
            if pdl_on() {
                unsafe { launch_pss_raw(l.stream.stream, f, grid, (256, 1, 1), dsmem, &mut args) }
                    .with_context(|| format!("launch {fname} (pdl)"))?;
            } else {
                let r = unsafe {
                    cudarc::driver::sys::cuLaunchKernel(f, grid.0, grid.1, grid.2, 256, 1, 1, dsmem, l.stream.stream,
                        args.as_mut_ptr(), std::ptr::null_mut())
                };
                anyhow::ensure!(r == cudarc::driver::sys::CUresult::CUDA_SUCCESS, "{fname} launch ({r:?})");
            }
            ep_routed = ep_fold;
            } // !w4r
            if let Some((l0, i0, w0, s0, x0, e0, g0, d0)) = snap {
                self.dev.synchronize()?;
                let (l1, i1, w1) = (self.dev.dtoh_sync_copy(&sc.logits_r)?, self.dev.dtoh_sync_copy(&sc.ids)?,
                                    self.dev.dtoh_sync_copy(&sc.wts)?);
                let (s1, x1, e1) = (self.dev.dtoh_sync_copy(&sc.slotmap)?, self.dev.dtoh_sync_copy(&sc.idxmap)?,
                                    self.dev.dtoh_sync_copy(&sc.esel)?);
                let (g1, d1) = (self.dev.dtoh_sync_copy(&sc.offs_gu)?, self.dev.dtoh_sync_copy(&sc.offs_d)?);
                let nl = m * ne; let nk = m * topk; let ns = e0[0].max(0) as usize;
                let dl = (0..nl).filter(|&i| l0[i].to_bits() != l1[i].to_bits()).count();
                let di = (0..nk).filter(|&i| i0[i] != i1[i]).count();
                let dw = (0..nk).filter(|&i| w0[i].to_bits() != w1[i].to_bits()).count();
                let dr = (s0 != s1) as usize + (x0[..ns] != x1[..ns]) as usize + (e0[0] != e1[0]) as usize
                    + (g0[..ns] != g1[..ns]) as usize + (d0[..ns] != d1[..ns]) as usize;
                let first = (0..nl).find(|&i| l0[i].to_bits() != l1[i].to_bits())
                    .map(|i| format!(" first logit diff @[{}][{}] {:e} vs {:e}", i / ne, i % ne, l0[i], l1[i]))
                    .unwrap_or_default();
                static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
                let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                if c < 4 || dl + di + dw + dr > 0 {
                    println!("WP10_XCHECK {fname} vs {} m={m}: logits bit-diff {dl}/{nl}, ids {di}/{nk}, wts {dw}/{nk}, route tables {dr}/5 (esel {}){first}",
                             if fxc { "S-A3-z pair" } else { "ks path" }, e1[0]);
                }
                if dl + di + dw + dr > 0 { anyhow::bail!("WP10 routing fold diverges from the reference path"); }
            }
        }
        // S-A3-f Item 2 selection-identity gate (diagnostic env knob): recompute the OLD
        // host grouping from a dtoh of ids and diff it against the device tables.
        let route_check = crate::opts::var(crate::opt!("exl3-route-check")).is_ok();
        if route_check {
            self.dev.synchronize()?;
            let ids_h = self.dev.dtoh_sync_copy(&sc.ids)?;
            let sm_h = self.dev.dtoh_sync_copy(&sc.slotmap)?;
            let ix_h = self.dev.dtoh_sync_copy(&sc.idxmap)?;
            let es_h = self.dev.dtoh_sync_copy(&sc.esel)?;
            let mut uniq: Vec<i32> = Vec::with_capacity(ids_h.len());
            let mut slotmap_ref = vec![-1i32; ne];
            for e in &ids_h {
                let ei = *e as usize;
                if ei < ne && slotmap_ref[ei] == -1 {
                    slotmap_ref[ei] = uniq.len() as i32;
                    uniq.push(*e);
                }
            }
            let ok = es_h.first() == Some(&(uniq.len() as i32))
                && ix_h[..uniq.len()] == uniq[..]
                && (0..ne).all(|e| sm_h[e] == slotmap_ref[e]);
            static ROUTE_ONCE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(true);
            use std::sync::atomic::Ordering;
            if ROUTE_ONCE.swap(false, Ordering::SeqCst) || !ok {
                println!("EXL3_ROUTE_CHECK: {} (esel device {:?} vs host {})",
                         if ok { "PASS" } else { "FAIL" }, es_h.first(), uniq.len());
            }
            if !ok { anyhow::bail!("device MoE routing diverges from host grouping"); }
        }
        // TP-A: expert parallelism — rebuild slotmap/idxmap/esel/offs over THIS rank's experts
        // (the router + top-k above ran replicated, so ids/wts are the same global tables on
        // every rank). Every consumer below indexes suh/svh/trellis by the LOCAL index.
        if let Some(ep) = moe.ep.as_ref().filter(|_| !ep_routed) {
            xqlaunch!(l, "xq_moe_route_ep", (1, 1, 1), (256, 1, 1), 0,
                     (&sc.ids, m as i32, topk as i32, ne as i32, &ep.lut, &mut sc.slotmap, &mut sc.idxmap,
                      &mut sc.esel, &mut sc.offs_gu, &mut sc.offs_d, moe.gu_words, moe.d_words))?;
        }
        if let Some(hb) = self.esel_hist.as_ref() {
            xqlaunch!(l, "xq_esel_hist", (1, 1, 1), (1, 1, 1), 0, (&sc.esel, hb, m as i32, ESEL_HIST_W as i32))?;
        }
        if let Some((hb, _)) = self.expert_hist.as_ref().filter(|_| m <= 16 && moe.li < self.cfg.num_layers) {
            let p = *hb.device_ptr() as u64 + (moe.li * 2 * ne * 4) as u64;
            xqlaunch_raw!(l, "xq_expert_hist", (1u32, 1, 1), (256, 1, 1), 0, (&sc.ids, m as i32, topk as i32, ne as i32, p))?;
        }
        let emax = sc.idxmap.len() as i32; // w*topk — the padded per-step expert cap
        // A5 WP20: expert word diet + MoE glue as last-arrival epilogues (default on, bitwise):
        // xq_had_suh_multi -> xq_moe_gu_epi -> shared expert -> xq_moe_dn_epi_k<topk>. The code
        // below this block is the old launch sequence — --wp20-off=1, --wp20-epi=0, an
        // explicit --moe-fh=1/--moe-coop=1, a top-k without an instance, an ineligible
        // shape or a failed suh verification take it (every such decision is logged once per
        // width by wp20_select — no silent inertness); rung 1 (the diet twin) still runs there
        // wherever the a1b3 entry does, except on the xcheck's reference pass.
        // --exl3-moe-epi-check=1 runs the old path first (no diet: the true pre-WP20
        // reference), then the WP20 path, and diffs xhd / yd / moe_out bitwise (eager passes).
        let (wp20, rung1_sel) = self.wp20_select(l, sc, m, emax as usize, moe_coop);
        let wp20_chk = wp20.is_some() && wp20_check_on() && !stream_capturing(l);
        if let Some(sel) = wp20 {
            if !wp20_chk { return self.moe_wp20(l, sc, moe, m, emax, sel, &mut wp27); }
            wp20_log_once((6, 0, 0), || "WP20 XCHECK (--exl3-moe-epi-check=1): each eager MoE call runs the pre-WP20 \
                                         sequence (no diet) then the WP20 path and diffs xhd/yd/moe_out bitwise; captured \
                                         graphs record the WP20 path only".to_string());
        }
        let rung1 = rung1_sel && !wp20_chk;
        // Fused per-expert Hadamards (A5 D3 experts, bitwise): suh + a1b3 + svh in ONE launch per GEMM.
        let fh = !moe_coop && moe_fh_on()
            && grouped_fn(m, 2560, 3) == "xq_gemm_grouped_a1b3" && grouped_fn(m, mi, 3) == "xq_gemm_grouped_a1b3"
            && 2560 % 128 == 0 && mi % 128 == 0 && (mi * 2) % 128 == 0 && h % 128 == 0;
        if fh {
            xqlaunch!(l, "xq_gemm_grouped_a1b3_fh", ((emax * ((mi * 2) as i32 / 128)) as u32, 1, 1), (256, 1, 1), a1_smem(m, 2560),
                     (&moe.gu_tr, &sc.offs_gu, &sc.x, 0i32, &moe.suh_gu, &moe.svh_gu, &sc.idxmap, &mut sc.ygu,
                      m as i32, 2560i32, (mi * 2) as i32, &sc.esel))?;
            xqlaunch!(l, "xq_moe_gate_mul", (((emax * m as i32 * mi as i32) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                     (&mut sc.din, &sc.ygu, (m * mi as usize) as i64, &sc.esel))?;
            xqlaunch!(l, "xq_gemm_grouped_a1b3_fh", ((emax * (h as i32 / 128)) as u32, 1, 1), (256, 1, 1), a1_smem(m, mi as usize),
                     (&moe.d_tr, &sc.offs_d, &sc.din, 1i32, &moe.suh_d, &moe.svh_d, &sc.idxmap, &mut sc.yd,
                      m as i32, mi as i32, h as i32, &sc.esel))?;
        } else {
        xqlaunch!(l, "xq_had_suh_multi", ((emax * m as i32 * 20) as u32, 1, 1), (32, 1, 1), 0,
                 (&sc.x, &moe.suh_gu, &sc.idxmap, &mut sc.xh_e, m as i32, 2560i32, &sc.esel, 0i32))?;
        if moe_coop {
            xqlaunch!(l, "xq_moe_coop_a", ((emax * (((mi * 2) as i32) / 32)) as u32, 1, 1), (256, 1, 1), 0,
                     (&moe.gu_tr, &sc.offs_gu, &sc.xh_e, &mut sc.ygu_raw, m as i32, 2560i32, (mi * 2) as i32, 3i32, &sc.esel))?;
        } else {
            xqlaunch!(l, wp20_grouped(grouped_fn(m, 2560, 3), rung1, m, 2560), ((emax * 10) as u32, 1, 1), (256, 1, 1), a1_smem(m, 2560),
                     (&moe.gu_tr, &sc.offs_gu, &sc.xh_e, &mut sc.ygu_raw, m as i32, 2560i32, (mi * 2) as i32, 3i32, &sc.esel))?;
        }
        xqlaunch!(l, "xq_had_svh_multi", ((emax * m as i32 * 10) as u32, 1, 1), (32, 1, 1), 0,
                 (&sc.ygu_raw, &moe.svh_gu, &sc.idxmap, &mut sc.ygu, m as i32, (mi * 2) as i32, &sc.esel))?;
        xqlaunch!(l, "xq_moe_gate_mul", (((emax * m as i32 * mi as i32) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (&mut sc.din, &sc.ygu, (m * mi as usize) as i64, &sc.esel))?;
        xqlaunch!(l, "xq_had_suh_multi", ((emax * m as i32 * (mi as i32 / 128)) as u32, 1, 1), (32, 1, 1), 0,
                 (&sc.din, &moe.suh_d, &sc.idxmap, &mut sc.xhd, m as i32, mi as i32, &sc.esel, 1i32))?;
        if moe_coop {
            xqlaunch!(l, "xq_moe_coop_b", ((emax * (h as i32 / 32)) as u32, 1, 1), (256, 1, 1), 0,
                     (&moe.d_tr, &sc.offs_d, &sc.xhd, &mut sc.yd_raw, m as i32, mi as i32, h as i32, 3i32, &sc.esel))?;
        } else {
            xqlaunch!(l, wp20_grouped(grouped_fn(m, mi, 3), rung1, m, mi), ((emax * (h as i32 / 128)) as u32, 1, 1), (256, 1, 1), a1_smem(m, mi as usize),
                     (&moe.d_tr, &sc.offs_d, &sc.xhd, &mut sc.yd_raw, m as i32, mi as i32, h as i32, 3i32, &sc.esel))?;
        }
        xqlaunch!(l, "xq_had_svh_multi", ((emax * m as i32 * (h as i32 / 128)) as u32, 1, 1), (32, 1, 1), 0,
                 (&sc.yd_raw, &moe.svh_d, &sc.idxmap, &mut sc.yd, m as i32, h as i32, &sc.esel))?;
        }
        // WP27: routed branch ends here (its tail joins at the combine); the shared expert
        // restarts from the fork base (the hc mixer that wrote sc.x).
        let wp27_routed = wp27.cut()?;
        wp27.side_begin()?;
        exl3_chain_pair(l, &moe.sh_gate, &moe.sh_up, &sc.x,
                        &mut sc.chain_xh, &mut sc.chain_yraw, &sc.chain_ws,
                        &mut sc.pair_xh, &mut sc.pair_yraw, &sc.pair_ws,
                        &mut sc.sh1, &mut sc.sh2, m)?;
        self.shared_down(l, sc, moe, m)?; // W4/DENSE: silu folded into the down (else xq_silu_mul + chain)
        wp27.side_end()?;
        wp27.join(&wp27_routed)?; // WP27: the combine reads yd/ids/wts/slotmap (routed) + ysh (shared)
        xqlaunch!(l, "xq_moe_combine", (m as u32, 1, 1), (1024, 1, 1), 4096,
                 (&mut sc.moe_out, &sc.yd, &sc.ysh, &sc.ids, &sc.wts, &sc.slotmap, &moe.sg, &sc.x,
                  topk as i32, h as i32, m as i32))?;
        if let (Some(sel), true) = (wp20, wp20_chk) {
            self.moe_wp20_xcheck(l, sc, moe, m, emax, sel)?;
        }
        Ok(())
    }

    /// A5 WP20 dispatch for ONE MoE call. (Some(sel), _) = rung 2 runs (moe_wp20: the epilogue
    /// kernels sel.gu / sel.dn); (None, rung1) = the old launch sequence, with the diet twin iff
    /// `rung1`. Rung 2 needs: mode 2, no --moe-coop / --moe-fh pre-emption, a compiled
    /// down-epilogue instance for the model's top-k (WP20_TOPKS), the served a1b3 shapes both
    /// sides (A-once smem, 3-bit, --exl3-a1b3 honoured), the epilogue smem (tile + the
    /// [m][top-k] slot/weight tables), the scratch counters/sgv/buffers sized for emax = w*top-k,
    /// the raw kernels present in the PTX, and the one-time suh verification (FwdModel::load does
    /// it eagerly; a capture never verifies). EVERY outcome is logged once per (width, reason):
    /// "WP20 ACTIVE m=.." or "WP20 FALLBACK m=..: <reason>" — the package can never be silently
    /// inert again (v1 was, for the whole top-10 model).
    fn wp20_select(&self, l: &Launcher, sc: &Scratch, m: usize, emax: usize, moe_coop: bool) -> (Option<Wp20Sel>, bool) {
        let mode = wp20_mode();
        let diet = wp20_diet_on();
        if mode == 0 {
            wp20_log_once((0, 0, 0), || "WP20 OFF (--wp20-off=1): pre-WP20 expert path — SHFL decode, 5 glue launches per MoE layer".to_string());
            return (None, false);
        }
        let preempt = if moe_coop { Some("--moe-coop=1 (coop expert kernels) takes precedence") }
            else if moe_fh_on() { Some("--moe-fh=1 (fused-Hadamard xq_gemm_grouped_a1b3_fh) takes precedence") }
            else { None };
        if mode == 1 {
            wp20_log_once((0, 1, 0), || format!("WP20 mode 1 (--wp20-epi=0): rung 1 only — word-diet twin {} in the pre-WP20 \
                                                 launch sequence; MoE epilogues (rung 2) off by request",
                                                if diet { "on" } else { "OFF too (--wp20-diet=0): effectively the pre-WP20 path" }));
            if let Some(why) = preempt {
                wp20_log_once((5, m, 0), || format!("WP20 FALLBACK rung 1 m={m}: {why} — that path has no diet twin"));
                return (None, false);
            }
            return (None, diet);
        }
        let (h, mi, topk) = (self.cfg.hidden_size, self.cfg.moe_intermediate_size, self.cfg.num_experts_per_tok);
        let gu = wp20_gu_fn(diet);
        let dn = wp20_dn_fn(topk, diet);
        let (sgu, sdn) = (a1_smem(m, h) as usize, a1_smem(m, mi) as usize);
        let (need_gu, need_dn) = ((m * 256).max(4096), m * 256 + m * topk * 8);
        let why: Option<(usize, String)> = if let Some(p) = preempt {
            Some((1, p.to_string()))
        } else if dn.is_none() {
            Some((2, format!("top-k {topk} has no down-epilogue instance (compiled: {WP20_TOPKS:?})")))
        } else if m == 0 || h % 128 != 0 || mi % 128 != 0 {
            Some((3, format!("shape m={m} hidden={h} moe_intermediate={mi} (need m >= 1, both multiples of 128)")))
        } else if grouped_fn(m, h, 3) != "xq_gemm_grouped_a1b3" {
            Some((4, format!("gate/up GEMM (K={h}) is off the a1b3 entry at this width: A-once smem m*(K+8)*2 = {} B \
                              (> 48 KiB?) or --exl3-a1b3=0", m * (h + 8) * 2)))
        } else if grouped_fn(m, mi, 3) != "xq_gemm_grouped_a1b3" {
            Some((5, format!("down GEMM (K={mi}) is off the a1b3 entry at this width: A-once smem m*(K+8)*2 = {} B \
                              (> 48 KiB?) or --exl3-a1b3=0", m * (mi + 8) * 2)))
        } else if sgu < need_gu || sdn < need_dn {
            Some((6, format!("epilogue smem: gate/up {sgu} B (need {need_gu}), down {sdn} B (need {need_dn} = tile + [m][top-k] tables)")))
        } else if sc.moe_cnt.len() < emax * (mi / 128) + h / 128 || sc.moe_sgv.len() < m
            || sc.ygu.len() < emax * m * 2 * mi || sc.xhd.len() < emax * m * mi || sc.yd.len() < emax * m * h {
            Some((7, format!("scratch undersized for emax {emax} (counters {}, sgv {}, ygu {}, xhd {}, yd {})",
                             sc.moe_cnt.len(), sc.moe_sgv.len(), sc.ygu.len(), sc.xhd.len(), sc.yd.len())))
        } else if xq_raw_fn(gu).is_none() || dn.and_then(xq_raw_fn).is_none() {
            Some((8, format!("kernel {gu} / {} missing from src/ptx/exl3_bench.ptx (stale PTX?)", dn.unwrap_or("?"))))
        } else {
            None
        };
        let conv: std::result::Result<u32, (usize, String)> = match why {
            Some(w) => Err(w),
            None => match WP20_CONV.get() {
                Some(Some(c)) => Ok(*c),
                Some(None) => Err((9, "the suh verification failed (see the WP20 suh line)".to_string())),
                None if stream_capturing(l) => Err((10, "first eligible call is inside a graph capture before the suh \
                    verification (FwdModel::load verifies eagerly — this graph records the old sequence)".to_string())),
                None => wp20_calibrated(&self.dev).ok_or((9, "the suh verification failed (see the WP20 suh line)".to_string())),
            },
        };
        match conv {
            Ok(c) => {
                let dn = dn.unwrap_or("?");
                wp20_log_once((1, m, topk), || format!(
                    "WP20 ACTIVE m={m}: rungs 1+2 — xq_had_suh_multi -> {gu} -> shared expert -> {dn} (top-k {topk}, emax {emax}, \
                     suh seq 0x{c:02x} (pinned, verified), decode body {}; smem gate/up {sgu} B, down {sdn} B >= {need_dn}); removed per MoE layer: \
                     xq_had_svh_multi x2, xq_moe_gate_mul, down xq_had_suh_multi, xq_moe_combine",
                    if diet { "diet" } else { "SHFL (--wp20-diet=0)" }));
                (Some(Wp20Sel { conv: c, gu, dn, topk }), false)
            }
            Err((code, msg)) => {
                let rung1 = diet && code != 1;
                wp20_log_once((2, m, code), || format!(
                    "WP20 FALLBACK m={m}: MoE epilogues (rung 2) NOT active — {msg}. Running the pre-WP20 launch sequence{}",
                    if rung1 { " with rung 1 (diet twin) wherever the a1b3 entry runs" } else { " (no diet twin)" }));
                (None, rung1)
            }
        }
    }

    /// A5 WP20 MoE experts: suh(x) -> gate/up GEMM (own-tile svh, pair epilogue: silu*mul +
    /// down suh -> xhd; expert 0: shared-gate sigmoid) -> shared expert -> down GEMM (svh -> yd,
    /// last arrival per N-tile: combine -> moe_out). Same bytes as the old path (see the WP20
    /// block in kernels/exl3_bench.cu). Every per-round value is a device buffer (esel, idxmap,
    /// ids, wts, slotmap, the self re-arming counters) — capture/replay safe.
    fn moe_wp20(&self, l: &Launcher, sc: &mut Scratch, moe: &MoeLayer, m: usize, emax: i32, sel: Wp20Sel,
                wp27: &mut crate::exl3_wp27::Cap) -> Result<()> {
        let h = self.cfg.hidden_size;
        let mi = self.cfg.moe_intermediate_size;
        // W4/MOE: the persistent grouped-expert kernels replace the WP20 bodies side by side
        // (gate/up, down) wherever planned; any side without a plan keeps its WP20 kernel (same
        // buffers, counters and sgv contract, so the two mix freely). Logged once per width.
        // p5e: DEFAULT OFF (opt-in --w4moe=1) — parts == 0 => no plan, no log, fold_live false:
        // xq_had_suh_multi + the WP20 gate/up + the shared expert + the WP20 down, the p3 sequence.
        let parts = w4moe_parts();
        let (gu_pk, dn_pk, fold_live) = self.w4moe_plans(m, emax, sel.topk);
        let il = if w4moe_order_il() { MPK_FLAG_IL } else { 0 };
        if parts & (MPK_GU | MPK_DN) != 0 {
            wp20_log_once((7, m, sel.topk), || {
                let f = |p: &Option<MpkPlan>, want: bool, old: &str| match p {
                    Some(p) => format!("{} G={} ({} CTA/SM, ring {} x 3 KB, smem {} B)", p.name, p.grid, p.cps, p.nst, p.smem),
                    None if want && m < w4moe_minm() => format!("{old} (--w4moe-minm={})", w4moe_minm()),
                    None if want => format!("{old} (W4/MOE FALLBACK: no persistent plan at this width)"),
                    None => format!("{old} (--w4moe-off)"),
                };
                format!("W4/MOE ACTIVE m={m}: gate/up {} | down {} | A-fold {} (xq_had_suh_multi {}), item order {}",
                        f(&gu_pk, parts & MPK_GU != 0, sel.gu), f(&dn_pk, parts & MPK_DN != 0, sel.dn),
                        fold_live as u8, if fold_live { "removed" } else { "kept" },
                        if il != 0 { "interleaved" } else { "contiguous" })
            });
        }
        // A5-K7 (moe.gu_fold): the WP20 gate/up forms its own A (xq_moe_gu_epi_f) — no xq_had_suh_multi.
        let gu_fold = gu_pk.is_none() && moe_gu_fold(l, m);
        if gu_fold {
            wp20_log_once((9, m, 0), || if sel.gu == wp20_gu_fn(true) && xq_raw_fn(WP20_GU_FOLD_FN).is_some() {
                format!("A5-K7 GU_FOLD m={m}: xq_had_suh_multi folded into the gate/up prologue ({WP20_GU_FOLD_FN};                          A = f16(H128(x * suh_e)) in-kernel, pinned suh sequence)")
            } else {
                format!("A5-K7 GU_FOLD FALLBACK m={m}: gate/up entry {} (diet off?) or {WP20_GU_FOLD_FN} missing — unfolded pair", sel.gu)
            });
        }
        let gu_fold = gu_fold && sel.gu == wp20_gu_fn(true) && xq_raw_fn(WP20_GU_FOLD_FN).is_some();
        if !fold_live && !gu_fold {
            xqlaunch!(l, "xq_had_suh_multi", ((emax * m as i32 * (h as i32 / 128)) as u32, 1, 1), (32, 1, 1), 0,
                     (&sc.x, &moe.suh_gu, &sc.idxmap, &mut sc.xh_e, m as i32, h as i32, &sc.esel, 0i32))?;
        }
        let cnt = *sc.moe_cnt.device_ptr() as u64;
        let cnt_dn = cnt + (emax as u64) * (mi as u64 / 128) * 4;
        if let Some(p) = gu_pk {
            let xp = *sc.x.device_ptr() as u64;
            mpk_launch_gu(&self.dev, l.stream.stream, &p, *moe.gu_tr.device_ptr() as u64, *sc.offs_gu.device_ptr() as u64,
                          if fold_live { xp } else { *sc.xh_e.device_ptr() as u64 }, *moe.suh_gu.device_ptr() as u64,
                          *sc.ygu.device_ptr() as u64, m, h, 2 * mi, *sc.esel.device_ptr() as u64,
                          *sc.idxmap.device_ptr() as u64, *moe.svh_gu.device_ptr() as u64, *moe.suh_d.device_ptr() as u64,
                          *sc.xhd.device_ptr() as u64, cnt, xp, *moe.sg.device_ptr() as u64,
                          *sc.moe_sgv.device_ptr() as u64, il | if fold_live { MPK_FLAG_FOLD } else { 0 })?;
        } else {
            // (gu_fold: xh = sc.x, ignored by the kernel; the 17th param is the gate/up suh table)
            let mut a = [*moe.gu_tr.device_ptr() as u64, *sc.offs_gu.device_ptr() as u64,
                         if gu_fold { *sc.x.device_ptr() as u64 } else { *sc.xh_e.device_ptr() as u64 },
                         *sc.ygu.device_ptr() as u64];
            let mut d = [m as i32, h as i32, (2 * mi) as i32];
            let mut b = [*sc.esel.device_ptr() as u64, *sc.idxmap.device_ptr() as u64, *moe.svh_gu.device_ptr() as u64,
                         *moe.suh_d.device_ptr() as u64, *sc.xhd.device_ptr() as u64, cnt, *sc.x.device_ptr() as u64,
                         *moe.sg.device_ptr() as u64, *sc.moe_sgv.device_ptr() as u64, *moe.suh_gu.device_ptr() as u64];
            let mut p: [*mut std::ffi::c_void; 17] = [
                &mut a[0] as *mut u64 as *mut _, &mut a[1] as *mut u64 as *mut _, &mut a[2] as *mut u64 as *mut _,
                &mut a[3] as *mut u64 as *mut _, &mut d[0] as *mut i32 as *mut _, &mut d[1] as *mut i32 as *mut _,
                &mut d[2] as *mut i32 as *mut _, &mut b[0] as *mut u64 as *mut _, &mut b[1] as *mut u64 as *mut _,
                &mut b[2] as *mut u64 as *mut _, &mut b[3] as *mut u64 as *mut _, &mut b[4] as *mut u64 as *mut _,
                &mut b[5] as *mut u64 as *mut _, &mut b[6] as *mut u64 as *mut _, &mut b[7] as *mut u64 as *mut _,
                &mut b[8] as *mut u64 as *mut _, &mut b[9] as *mut u64 as *mut _,
            ];
            let (gfn, np) = if gu_fold { (WP20_GU_FOLD_FN, 17) } else { (sel.gu, 16) };
            unsafe { wp20_launch(l.stream.stream, gfn, emax as u32 * (2 * mi as u32 / 128), a1_smem(m, h), &mut p[..np])?; }
        }
        // Shared expert AHEAD of the routed down (its ysh feeds the down's combine epilogue) —
        // the old path's gate|up pair + silu + down (W4/DENSE: two DENSE launches, the silu folded
        // into the down's prologue — opt-in --w4dense=1; default OFF / _SILU=0 = the three old
        // launches, the p3 sequence).
        // W4/MOE lever (c), opt-in --w4moe-shovl=1:
        // while a graph is captured, the shared expert becomes a sibling branch of the routed
        // path (routing .. gate/up) from the MoE fork base (it reads only sc.x) and joins before
        // the down kernel (its combine reads ysh). No spin wait on either branch (last-arrival
        // counters private to the gate/up / down launches; PSK: static striding) => any residency
        // is deadlock-free; same kernels, same inputs => bitwise. Default OFF: the p3c WP27 audit
        // keeps the rung-2 epilogues linear until an in-round A/B shows the overlap pays.
        // A5-K1 (moe.shovl, default ON; escape --moe-shovl=0): the same placement on the DEFAULT rung-2 path (no
        // persistent package needed). Audit (w6/SHOVL): routed branch = router fold (fold_cnt) ->
        // xq_had_suh_multi -> xq_moe_gu_epi (moe_cnt; writes xh_e, ygu, xhd, moe_sgv); shared
        // branch = sh_gate|sh_up pair + silu + sh_down (Quad.cnt of those three Quads; writes
        // chain_*/pair_* scratch, sh1, sh2, ysh; reads sc.x) — write sets disjoint from every
        // sibling read, no counter shared, no spin wait on either branch.
        let shovl = moe_shovl() || (w4moe_shovl() && parts & (MPK_GU | MPK_DN) != 0);
        if shovl && stream_capturing(l) {
            wp20_log_once((8, m, 0), || format!("A5-K1 SHOVL m={m}: shared expert on a WP27 sibling branch of the routed path \
                (router .. {}), joined before {} (captured graphs only; eager = linear)", sel.gu, sel.dn));
        }
        let routed = if shovl { Some(wp27.cut()?) } else { None };
        if shovl { wp27.side_begin()?; }
        exl3_chain_pair(l, &moe.sh_gate, &moe.sh_up, &sc.x,
                        &mut sc.chain_xh, &mut sc.chain_yraw, &sc.chain_ws,
                        &mut sc.pair_xh, &mut sc.pair_yraw, &sc.pair_ws,
                        &mut sc.sh1, &mut sc.sh2, m)?;
        self.shared_down(l, sc, moe, m)?; // W4/DENSE: silu folded into the down (else xq_silu_mul + chain)
        if let Some(t) = routed {
            wp27.side_end()?;
            wp27.join(&t)?; // W4/MOE (c): the down launch depends on the routed tail AND the shared tail
        }
        if let Some(p) = dn_pk {
            mpk_launch_dn(&self.dev, l.stream.stream, &p, *moe.d_tr.device_ptr() as u64, *sc.offs_d.device_ptr() as u64,
                          *sc.xhd.device_ptr() as u64, *sc.yd.device_ptr() as u64, m, mi, h,
                          *sc.esel.device_ptr() as u64, *sc.idxmap.device_ptr() as u64, *moe.svh_d.device_ptr() as u64,
                          cnt_dn, *sc.ysh.device_ptr() as u64, *sc.ids.device_ptr() as u64, *sc.wts.device_ptr() as u64,
                          *sc.slotmap.device_ptr() as u64, *sc.moe_sgv.device_ptr() as u64,
                          *sc.moe_out.device_ptr() as u64, sel.topk, il)?;
        } else {
            let mut a = [*moe.d_tr.device_ptr() as u64, *sc.offs_d.device_ptr() as u64, *sc.xhd.device_ptr() as u64,
                         *sc.yd.device_ptr() as u64];
            let mut d = [m as i32, mi as i32, h as i32];
            let mut b = [*sc.esel.device_ptr() as u64, *sc.idxmap.device_ptr() as u64, *moe.svh_d.device_ptr() as u64,
                         cnt_dn, *sc.ysh.device_ptr() as u64, *sc.ids.device_ptr() as u64, *sc.wts.device_ptr() as u64,
                         *sc.slotmap.device_ptr() as u64, *sc.moe_sgv.device_ptr() as u64, *sc.moe_out.device_ptr() as u64];
            let mut k = sel.topk as i32;                // the instance's TOPK (the kernel traps on a mismatch)
            let mut p: [*mut std::ffi::c_void; 18] = [
                &mut a[0] as *mut u64 as *mut _, &mut a[1] as *mut u64 as *mut _, &mut a[2] as *mut u64 as *mut _,
                &mut a[3] as *mut u64 as *mut _, &mut d[0] as *mut i32 as *mut _, &mut d[1] as *mut i32 as *mut _,
                &mut d[2] as *mut i32 as *mut _, &mut b[0] as *mut u64 as *mut _, &mut b[1] as *mut u64 as *mut _,
                &mut b[2] as *mut u64 as *mut _, &mut b[3] as *mut u64 as *mut _, &mut b[4] as *mut u64 as *mut _,
                &mut b[5] as *mut u64 as *mut _, &mut b[6] as *mut u64 as *mut _, &mut b[7] as *mut u64 as *mut _,
                &mut b[8] as *mut u64 as *mut _, &mut b[9] as *mut u64 as *mut _, &mut k as *mut i32 as *mut _,
            ];
            unsafe { wp20_launch(l.stream.stream, sel.dn, emax as u32 * (h as u32 / 128), a1_smem(m, mi), &mut p)?; }
        }
        Ok(())
    }

    /// W4/MOE plans for one MoE call at width m: (gate/up, down, A-fold live). A side without a
    /// plan (--w4moe-off part, or not launchable) keeps its WP20 rung-2 kernel.
    fn w4moe_plans(&self, m: usize, emax: i32, topk: usize) -> (Option<MpkPlan>, Option<MpkPlan>, bool) {
        let (h, mi) = (self.cfg.hidden_size, self.cfg.moe_intermediate_size);
        let parts = w4moe_parts();
        let fold = parts & MPK_FOLD != 0;
        let on = m >= w4moe_minm();
        let gu = if on && parts & MPK_GU != 0 { mpk_plan(&self.dev, true, topk, m, h, 2 * mi, emax as usize, fold) } else { None };
        let dn = if on && parts & MPK_DN != 0 { mpk_plan(&self.dev, false, topk, m, mi, h, emax as usize, false) } else { None };
        let fold_live = fold && gu.is_some();
        (gu, dn, fold_live)
    }

    /// --exl3-moe-epi-check: the old path has just run (eager); snapshot its xhd / yd /
    /// moe_out, run the WP20 path over the same routing, diff bitwise, and check every
    /// counter re-armed to 0. Prints the first calls and any mismatch; a mismatch fails the
    /// request (the diagnostic must never be silent).
    fn moe_wp20_xcheck(&self, l: &Launcher, sc: &mut Scratch, moe: &MoeLayer, m: usize, emax: i32, sel: Wp20Sel) -> Result<()> {
        let (h, mi) = (self.cfg.hidden_size, self.cfg.moe_intermediate_size);
        let conv = sel.conv;
        self.dev.synchronize()?;
        let es = (self.dev.dtoh_sync_copy(&sc.esel)?[0].max(0) as usize).min(emax as usize);
        let (nx, ny, no) = (es * m * mi, es * m * h, m * h);
        let ng = es * m * 2 * mi;
        let x0 = self.dev.dtoh_sync_copy(&sc.xhd)?;
        let y0 = self.dev.dtoh_sync_copy(&sc.yd)?;
        let o0 = self.dev.dtoh_sync_copy(&sc.moe_out)?;
        let g0 = self.dev.dtoh_sync_copy(&sc.ygu)?;
        // W4/MOE: NaN-poison every output the new path must write (xhd, yd, moe_out, ygu, the
        // shared-gate sigmoids) — a skipped write can never compare equal on the old bytes.
        for buf in [&sc.xhd, &sc.yd, &sc.moe_out, &sc.ygu] {
            let n = buf.len();
            xqlaunch!(l, "xq_memset_u16", (((n + 255) / 256) as u32, 1, 1), (256, 1, 1), 0, (buf, n as i64, 0x7E00i32))?;
        }
        let nsg = sc.moe_sgv.len();
        self.dev.htod_sync_copy_into(&vec![f32::NAN; nsg], &mut sc.moe_sgv)?;
        self.dev.synchronize()?;
        let (gu_pk, dn_pk, fold_live) = self.w4moe_plans(m, emax, sel.topk);
        self.moe_wp20(l, sc, moe, m, emax, sel, &mut crate::exl3_wp27::Cap::none())?;
        self.dev.synchronize()?;
        let x1 = self.dev.dtoh_sync_copy(&sc.xhd)?;
        let y1 = self.dev.dtoh_sync_copy(&sc.yd)?;
        let o1 = self.dev.dtoh_sync_copy(&sc.moe_out)?;
        let g1 = self.dev.dtoh_sync_copy(&sc.ygu)?;
        let cnt = self.dev.dtoh_sync_copy(&sc.moe_cnt)?;
        let diff = |a: &[u16], b: &[u16]| -> (usize, Option<(usize, u16, u16)>) {
            let mut n = 0;
            let mut first = None;
            for (i, (p, q)) in a.iter().zip(b.iter()).enumerate() {
                if p != q { n += 1; if first.is_none() { first = Some((i, *p, *q)); } }
            }
            (n, first)
        };
        let (dx, fx) = diff(&x0[..nx], &x1[..nx]);
        let (dy, fy) = diff(&y0[..ny], &y1[..ny]);
        let (dn, fo) = diff(&o0[..no], &o1[..no]);
        let (dg, fg) = diff(&g0[..ng], &g1[..ng]);
        let armed = cnt.iter().all(|&c| c == 0);
        let bad = dx + dy + dn + dg > 0 || !armed || es == 0;
        static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
        let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        if c < 4 || bad {
            let first = [("ygu", fg), ("xhd", fx), ("yd", fy), ("moe_out", fo)].iter()
                .filter_map(|(n, f)| f.map(|(i, p, q)| format!(" {n}[{i}] old {p:04x} new {q:04x}")))
                .collect::<String>();
            let gu = gu_pk.map_or(sel.gu, |p| p.name);
            let dnn = dn_pk.map_or(sel.dn, |p| p.name);
            let g = |p: &Option<MpkPlan>| p.map_or(String::new(), |p| format!(" G{}", p.grid));
            let gu = if gu_pk.is_none() && moe_gu_fold(l, m) && sel.gu == wp20_gu_fn(true) {
                WP20_GU_FOLD_FN } else { gu };
            println!("MOE_EPI_CHECK m={m} esel={es} topk={} {gu}{}+{dnn}{} fold {} suh seq 0x{conv:02x}: bit-diff ygu {dg}/{ng}, \
                      xhd {dx}/{nx}, yd {dy}/{ny}, moe_out {dn}/{no} (outputs NaN-poisoned first); counters {}{}",
                     sel.topk, g(&gu_pk), g(&dn_pk), fold_live as u8, if armed { "re-armed" } else { "NOT re-armed" },
                     if first.is_empty() { String::new() } else { format!(" (first mismatches:{first})") });
        }
        if bad { anyhow::bail!("WP20 / W4-MOE MoE path diverges from the old expert path"); }
        Ok(())
    }

    /// One round: m lanes. Returns greedy ids per lane. States mutate in place
    /// (conv/s/KV via raw device pointers — forward_step takes &self).
    /// S-A3-i: visible-token count up to which the indexer selects EVERY block (dense
    /// attention is exact there); past it the QSA path is the model spec.
    /// S-A3-o diagnostic: print the cumulative --exl3-esel-hist table (no-op when off). Called at
    /// every request finish as well as at drop, so a server stopped by SIGTERM (no drop) still
    /// leaves the table in its log — the last block printed is the run's total.
    pub fn dump_esel_hist(&self) {
        let Some(h) = self.esel_hist.as_ref() else { return };
        match self.dev.dtoh_sync_copy(h) {
            Ok(v) => {
                for m in 1..=16usize {
                    let row = &v[m * ESEL_HIST_W..(m + 1) * ESEL_HIST_W];
                    let n: i64 = row.iter().map(|&c| c as i64).sum();
                    if n == 0 { continue; }
                    let mean = row.iter().enumerate().map(|(e, &c)| e as f64 * c as f64).sum::<f64>() / n as f64;
                    let nz: Vec<String> = row.iter().enumerate().filter(|(_, &c)| c > 0)
                        .map(|(e, &c)| format!("{e}:{c}")).collect();
                    println!("ESEL_HIST m={m} calls={n} mean={mean:.2} [{}]", nz.join(" "));
                }
            }
            Err(e) => eprintln!("[exl3] --exl3-esel-hist dtoh: {e}"),
        }
    }

    /// TP-I #6 diagnostic: write the cumulative --tp-ep-hist routing histogram (no-op when off).
    pub fn dump_expert_hist(&self) {
        let Some((hb, path)) = self.expert_hist.as_ref() else { return };
        let (nl, ne) = (self.cfg.num_layers, self.cfg.num_experts);
        match self.dev.dtoh_sync_copy(hb) {
            Ok(v) => {
                let live: Vec<&[i32]> = (0..nl).map(|l| &v[l * 2 * ne..l * 2 * ne + ne]).collect();
                let picks: Vec<&[i32]> = (0..nl).map(|l| &v[l * 2 * ne + ne..(l + 1) * 2 * ne]).collect();
                let j = serde_json::json!({"ne": ne, "layers": nl, "topk": self.cfg.num_experts_per_tok,
                                           "live": live, "picks": picks});
                if let Err(e) = std::fs::write(path, j.to_string()) { eprintln!("[exl3] --tp-ep-hist write {path}: {e}"); }
            }
            Err(e) => eprintln!("[exl3] --tp-ep-hist dtoh: {e}"),
        }
    }

    pub fn qsa_limit(&self) -> usize { self.cfg.indexer_budget + self.cfg.indexer_compress_ratio - 1 }
    /// K1: the attention kernels' max_pos argument with the KV format in bits 28..31.
    fn mpf(&self) -> i32 { (self.max_pos as i32) | ((self.kv_fmt as i32) << 28) }
    /// TP-B: the geometry of attention target `att_i` — the trunk's per-rank heads (`tc`), or the
    /// replicated MTP head's global ones (HEAD_ATT).
    fn acfg_i(&self, att_i: usize) -> &crate::qwen::Config { if att_i == HEAD_ATT { &self.cfg } else { &self.tc } }
    /// TP-B: acfg_i keyed by the layer itself (the head's AttnLayer is the replicated one).
    fn acfg(&self, a: &AttnLayer) -> &crate::qwen::Config {
        if self.mtp.as_ref().map_or(false, |hh| std::ptr::eq(a, &hh.attn)) { &self.cfg } else { &self.tc }
    }
    /// WP25: xq_attn_sel_combine's `rows` with the KV format in bits 28..31 (q8 rotates the
    /// merged output back to the model basis there).
    fn rows_kvf(&self, rows: usize) -> i32 { (rows as i32) | ((self.kv_fmt as i32) << 28) }
    /// Raw indexer key plane of attention target `att_i` (a trunk attention index, or
    /// HEAD_ATT = the MTP draft head); None = no plane.
    fn qsa_keys_p(&self, att_i: usize) -> Option<u64> {
        if att_i == HEAD_ATT {
            if head_qsa_off() { return None; }
            self.mtp.as_ref().and_then(|h| h.qsa_keys.as_ref()).map(|k| *k.device_ptr() as u64)
        } else {
            self.qsa_keys.get(att_i).map(|k| *k.device_ptr() as u64)
        }
    }
    /// Pooled-key plane of attention target `att_i` (None = pooled path off for it).
    fn qsa_pool_p(&self, att_i: usize) -> Option<u64> {
        if att_i == HEAD_ATT {
            if head_qsa_off() { return None; }
            self.mtp.as_ref().and_then(|h| h.qsa_pool.as_ref()).map(|k| *k.device_ptr() as u64)
        } else {
            self.qsa_pool.get(att_i).map(|k| *k.device_ptr() as u64)
        }
    }
    /// Combined K/V cache of attention target `att_i` (trunk layer or HEAD_ATT).
    fn kv_p(&self, att_i: usize) -> u64 {
        if att_i == HEAD_ATT {
            *self.mtp.as_ref().expect("HEAD_ATT without a head").kv.device_ptr() as u64
        } else {
            *self.k_cache[att_i].device_ptr() as u64
        }
    }
    /// Long-context decode fix (2026-09-26): the graphed QSA block scorer used a grid over the
    /// whole WINDOW (max_pos/ratio blocks per row); at a 262K window that is 8,192 CTAs per row per
    /// attention layer every step, almost all exiting at `j >= nb` — ~7 tok/s decode at 32K
    /// context. The grid is now the power-of-two bucket (>= 1024 blocks) covering the largest
    /// position of the step; returns (grid blocks, bucket id for the graph key). Rows mask by
    /// their own position exactly as before, so scores are identical.
    pub fn qsa_grid_bucket(&self, max_pos_in_step: usize) -> (usize, usize) {
        let ratio = self.cfg.indexer_compress_ratio.max(1);
        let stride = (self.max_pos / ratio).max(1);
        let need = (max_pos_in_step + 1) / ratio + 1;
        let b = need.next_power_of_two().max(1024).min(stride);
        (b, if b == stride { 63 } else { b.trailing_zeros() as usize })
    }
    /// WP04: true when EVERY scoring launch of a decode/verify/draft graph is the bucket-free
    /// `qsa_score_pooled_mr` (pooled planes on the trunk AND the head, kernel present, not
    /// escaped) — only then may the graph keys drop the grid bucket.
    fn qsa_bucket_free(&self) -> bool {
        score_mr_on()
            && !self.qsa_pool.is_empty()
            && self.qsa_pool.len() == self.qsa_keys.len()
            && self.mtp.as_ref().map_or(true, |h| h.qsa_keys.is_none() || h.qsa_pool.is_some())
            && self.dev.get_func("gpu_batch", "qsa_score_pooled_mr").is_some()
    }
    /// qsa_grid_bucket with the KEY component: (grid blocks for the legacy scorer, bucket id for
    /// the graph key — 0 when the scorer is bucket-free, so one graph per regime serves every
    /// context and no request pays a capture at a power-of-two crossing).
    pub fn qsa_grid_bucket_key(&self, max_pos_in_step: usize) -> (usize, usize) {
        let (g, b) = self.qsa_grid_bucket(max_pos_in_step);
        (g, if self.qsa_bucket_free() { 0 } else { b })
    }
    // (WP04's own `stream_capturing` was byte-identical to WP09's — p2 keeps WP09's copy.)
    /// QSA live at this context? (--qsa-exl3=0 = the owner's A/B escape hatch.)
    pub fn qsa_live(&self, max_visible: usize) -> bool {
        self.cfg.has_indexer() && max_visible > self.qsa_limit() && !qsa_disabled()
    }

    /// S-A3-r FIX: the raw indexer key plane is SPEC STATE maintained on EVERY forward (the
    /// reference: "side planes ... maintained on EVERY cached forward; the sparse attention itself
    /// only engages once some query position exceeds sparse_threshold()"). Before this, keys
    /// were written only once a row was past qsa_limit(), so the whole dense prefix (positions
    /// 0..=2051) stayed ZERO and every sparse selection ranked ~513 zero-key blocks at one
    /// constant score. Dense-regime rows now append their raw keys with the SAME launches the
    /// sparse path uses (indexer chain -> bf16 -> qsa_key_write_b; the key column is untouched
    /// by the q-only qnorm_rope, so it is not needed here). Decode/verify rows (m <= 16).
    /// W4/DENSE lever (d): an attention layer's same-input chains (all read sc.x) — q_proj
    /// (`with_q`), k|v and the indexer qk when the layer has one and the scratch holds its rows —
    /// as ONE exl3_dks launch (one ramp, one tail; the small k/v/indexer items fill the q items'
    /// last round). Every output is its own chain's, bitwise. Returns Ok(true) iff the indexer qk
    /// was produced here (sc.qsa_qk): the qsa key / step functions then skip their exl3_chain of
    /// it. Otherwise the old launches run (each may still take a DENSE launch of its own).
    fn attn_in_chains(&self, l: &Launcher, sc: &mut Scratch, a: &AttnLayer, m: usize, with_q: bool) -> Result<bool> {
        if dense::multi_on() && m <= 16 {
            use dense::{dptr, DOut};
            let yr = (dptr(&sc.chain_yraw), sc.chain_yraw.len()); // FIX=0 tail: member by member
            let o = |y: &CudaSlice<u16>| DOut { y: dptr(y), y_len: y.len(), yraw: yr.0, yraw_len: yr.1, xh: 0, xh_len: 0 };
            let mut qs: Vec<&Quad> = Vec::with_capacity(4);
            let mut outs: Vec<DOut> = Vec::with_capacity(4);
            if with_q { qs.push(&a.q_proj); outs.push(o(&sc.qg)); }
            qs.push(&a.k_proj); outs.push(o(&sc.kp));
            qs.push(&a.v_proj); outs.push(o(&sc.vp));
            let idx = a.idx.as_ref().filter(|ix| sc.qsa_qk.len() >= m * ix.qk.n.max(0) as usize);
            let x = (dptr(&sc.x), sc.x.len());
            let ws = [(dptr(&sc.chain_ws), sc.chain_ws.len())];
            if let Some(ix) = idx {
                let (mut q2, mut o2) = (qs.clone(), outs.clone());
                q2.push(&ix.qk);
                o2.push(o(&sc.qsa_qk));
                if dense::dense_chains(l, &q2, &o2, x, (0, 0), m, &ws)? { return Ok(true); }
            }
            if dense::dense_chains(l, &qs, &outs, x, (0, 0), m, &ws)? { return Ok(false); }
        }
        if with_q {
            exl3_chain(l, &a.q_proj, &sc.x, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.qg, m, &sc.chain_ws)?;
        }
        exl3_chain_pair(l, &a.k_proj, &a.v_proj, &sc.x,
                        &mut sc.chain_xh, &mut sc.chain_yraw, &sc.chain_ws,
                        &mut sc.pair_xh, &mut sc.pair_yraw, &sc.pair_ws,
                        &mut sc.kp, &mut sc.vp, m)?;
        Ok(false)
    }

    /// W4/DENSE: the shared expert's down chain on silu(gate) * up. With the silu prologue (lever d:
    /// xq_silu_mul folded into the down's input transform) it is ONE launch reading sh1 / sh2 and
    /// sh1 keeps the gate output (nothing reads it after this); else the old xq_silu_mul (in place
    /// into sh1) + the down chain. Bitwise either way (xq_silu_mul's element expression verbatim).
    fn shared_down(&self, l: &Launcher, sc: &mut Scratch, moe: &MoeLayer, m: usize) -> Result<()> {
        let mi = moe.sh_down.k as usize; // TP-B: the rank's shared-expert intermediate slice (640 at TP=1)
        if dense::silu_on() && m <= 16 {
            use dense::{dptr, DOut};
            let o = DOut { y: dptr(&sc.ysh), y_len: sc.ysh.len(), yraw: dptr(&sc.chain_yraw), yraw_len: sc.chain_yraw.len(),
                           xh: 0, xh_len: 0 };
            if sc.sh1.len() >= m * mi && sc.sh2.len() >= m * mi
                && dense::dense_chains(l, &[&moe.sh_down], &[o], (dptr(&sc.sh1), m * mi), (dptr(&sc.sh2), m * mi), m,
                                       &[(dptr(&sc.chain_ws), sc.chain_ws.len())])? {
                return Ok(());
            }
        }
        let sh1p = *sc.sh1.device_ptr() as u64;
        xqlaunch!(l, "xq_silu_mul", (((m * mi) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (&mut sc.sh1, sh1p, &sc.sh2, (m * mi) as i64))?;
        exl3_chain(l, &moe.sh_down, &sc.sh1, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.ysh, m, &sc.chain_ws)
    }

    /// `idx_pre`: sc.qsa_qk already holds this step's indexer projection (W4/DENSE attention group,
    /// attn_in_chains — the same exl3 chain, same bits), so the chain is not re-run here.
    fn qsa_keys_append_dense(&self, l: &Launcher, sc: &mut Scratch, a: &AttnLayer, att_i: usize, m: usize,
                             idx_pre: bool) -> Result<()> {
        let Some(ix) = a.idx.as_ref() else { return Ok(()); };
        if !self.cfg.has_indexer() || qsa_disabled() { return Ok(()); }
        let Some(keys_p) = self.qsa_keys_p(att_i) else { return Ok(()); };
        let cfg = &self.cfg;
        let (hdx, heads) = (cfg.indexer_head_dim, cfg.indexer_n_heads);
        let qk_dim = (heads + 1) * hdx;
        if sc.qsa_qk.len() < m * qk_dim { return Ok(()); }
        if !idx_pre {
            exl3_chain(l, &ix.qk, &sc.x, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.qsa_qk, m, &sc.chain_ws)?;
        }
        let ncnv = (m * qk_dim) as i64;
        xqlaunch!(l, "xq_qsa_h2b", ((((ncnv + 255) / 256).max(1)) as u32, 1, 1), (256, 1, 1), 0,
                  (&mut sc.qsa_qkb, &sc.qsa_qk, ncnv))?;
        gblaunch!(l, "qsa_key_write_b", ((m * hdx) as u32, 1, 1), (256, 1, 1), 0,
                  (keys_p, &sc.qsa_qkb, &sc.pos, &sc.slot_ids, self.max_pos as i32, 0i32,
                   qk_dim as i32, (heads * hdx) as i32, hdx as i32, m as i32))?;
        if let (Some(pool_p), Some(params)) = (self.qsa_pool_p(att_i), ix.params.as_ref()) {
            let nblk_stride = (self.max_pos / cfg.indexer_compress_ratio).max(1);
            let geom: u64 = (self.max_pos as u64) | ((nblk_stride as u64) << 40);
            gblaunch!(l, "qsa_pool_update_b", ((m.div_ceil(8)) as u32, 1, 1), (256, 1, 1), 0,
                      (pool_p, keys_p, &sc.pos, &sc.slot_ids, (*params.device_ptr()) as u64, geom as i64, m as i32))?;
        }
        Ok(())
    }

    /// S-A3-r FIX, prefill twin: a fully-dense chunk (no sparse rows) appends its raw indexer
    /// keys too — the same launches qsa_attn_prefill_rows runs for all c rows of a straddle chunk.
    fn qsa_keys_append_dense_rows(&self, l: &Launcher, psc: &mut PrefillScratch, a: &AttnLayer,
                                  att_i: usize, slot: usize, pos0: usize, c: usize) -> Result<()> {
        let Some(ix) = a.idx.as_ref() else { return Ok(()); };
        if !self.cfg.has_indexer() || qsa_disabled() { return Ok(()); }
        let Some(keys_p) = self.qsa_keys_p(att_i) else { return Ok(()); };
        let cfg = &self.cfg;
        let (hdx, heads) = (cfg.indexer_head_dim, cfg.indexer_n_heads);
        let qk_dim = (heads + 1) * hdx;
        // prefill scratch sizes the indexer buffers only when QSA can engage (qsa_on)
        if psc.qsa_qk.len() < c * qk_dim || psc.qsa_qkb.len() < c * qk_dim || psc.pos_rows.len() < c { return Ok(()); }
        pf_chain_check_n(&ix.qk, c, &psc.chain_xh, &psc.chain_yraw)?; // PFX1 (c)
        exl3_chain(l, &ix.qk, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.qsa_qk, c, &psc.chain_ws)?;
        let ncnv = (c * qk_dim) as i64;
        xqlaunch!(l, "xq_qsa_h2b", ((((ncnv + 255) / 256).max(1)) as u32, 1, 1), (256, 1, 1), 0,
                  (&mut psc.qsa_qkb, &psc.qsa_qk, ncnv))?;
        gblaunch!(l, "qsa_key_write_b", ((c * hdx) as u32, 1, 1), (256, 1, 1), 0,
                  (keys_p, &psc.qsa_qkb, &psc.pos_rows, &psc.slot_rows, self.max_pos as i32, 0i32,
                   qk_dim as i32, (heads * hdx) as i32, hdx as i32, c as i32))?;
        self.qsa_pool_range(l, a, att_i, keys_p, slot, pos0, c)?;
        Ok(())
    }

    /// Refresh the pooled-key plane over the blocks covered by rows [pos0, pos0+c) of `slot`.
    fn qsa_pool_range(&self, l: &Launcher, a: &AttnLayer, att_i: usize, keys_p: u64,
                      slot: usize, pos0: usize, c: usize) -> Result<()> {
        let (Some(pool_p), Some(ix)) = (self.qsa_pool_p(att_i), a.idx.as_ref()) else { return Ok(()); };
        let Some(params) = ix.params.as_ref() else { return Ok(()); };
        if c == 0 { return Ok(()); }
        let cfg = &self.cfg;
        let (hdx, ratio) = (cfg.indexer_head_dim, cfg.indexer_compress_ratio);
        let nblk_stride = (self.max_pos / ratio).max(1);
        let j0 = pos0 / ratio;
        let j1 = ((pos0 + c - 1) / ratio + 1).min(nblk_stride);
        if j1 <= j0 { return Ok(()); }
        gblaunch!(l, "qsa_pool_range_b", (((j1 - j0).div_ceil(8)) as u32, 1, 1), (256, 1, 1), 0,
                  (pool_p + (slot * nblk_stride * hdx * 2) as u64, keys_p + (slot * self.max_pos * hdx * 2) as u64,
                   (*params.device_ptr()) as u64, j0 as i32, j1 as i32, slot as i32))?;
        Ok(())
    }

    /// S-A3-i: the QSA sparse attention step for `m` rows (decode m=1 or verify m=k+1):
    /// indexer projection -> raw-key append -> block scoring -> top-k (ascending) ->
    /// K/V cache write (bit-identical words, shared fn) + q staging -> gathered
    /// split-K flash-decode -> split merge. Replaces xq_attn_decode / _group above
    /// the dense threshold; see PLAN/S_A3_I_ATTENTION_DECODE.md for the contracts.
    /// `idx_pre`: sc.qsa_qk already holds this step's indexer projection (W4/DENSE attention group).
    /// `one_slot`: every row belongs to ONE slot at consecutive positions (a verify) — only then
    /// is the W4/QSA row-shared union gather used (decode steps carry one row per lane/slot).
    fn qsa_attn_step(&self, l: &Launcher, sc: &mut Scratch, a: &AttnLayer, att_i: usize, m: usize,
                     idx_pre: bool, one_slot: bool) -> Result<()> {
        let cfg = self.acfg_i(att_i); // TP-B: per-rank heads (trunk) / global (the replicated head)
        let (ix, params) = a.idx.as_ref().and_then(|i| i.params.as_ref().map(|p| (i, p)))
            .expect("qsa_attn_step: indexer without params");
        let (hdx, heads, ratio) = (cfg.indexer_head_dim, cfg.indexer_n_heads, cfg.indexer_compress_ratio);
        let qk_dim = (heads + 1) * hdx;
        let nblk_stride = (self.max_pos / ratio).max(1);
        let sel_max = self.qsa_limit();
        let keys_p = self.qsa_keys_p(att_i).context("qsa_attn_step: no key plane")?;
        let params_p = (*params.device_ptr()) as u64;
        // indexer projection (EXL3 3bpw chain) -> bf16 -> q heads normed+roped in place
        // (idx_pre: the W4/DENSE attention group already produced it, same chain, same bits)
        if !idx_pre {
            exl3_chain(l, &ix.qk, &sc.x, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.qsa_qk, m, &sc.chain_ws)?;
        }
        let ncnv = (m * qk_dim) as i64;
        xqlaunch!(l, "xq_qsa_h2b", ((((ncnv + 255) / 256).max(1)) as u32, 1, 1), (256, 1, 1), 0,
                  (&mut sc.qsa_qkb, &sc.qsa_qk, ncnv))?;
        xqlaunch!(l, "xq_qsa_qnorm_rope", ((m * heads) as u32, 1, 1), (hdx as u32, 1, 1), 0,
                  (&mut sc.qsa_qkb, &ix.qn, &sc.cos, heads as i32, hdx as i32,
                   cfg.rotary_dim as i32, m as i32, cfg.rms_eps))?;
        // raw-key append + block scoring (pooled keys recomputed from raws — the
        // HF-validated bf16 kernels, launched here against the exl3 slot/pos tables)
        gblaunch!(l, "qsa_key_write_b", ((m * hdx) as u32, 1, 1), (256, 1, 1), 0,
                  (keys_p, &sc.qsa_qkb, &sc.pos, &sc.slot_ids, self.max_pos as i32, 0i32,
                   qk_dim as i32, (heads * hdx) as i32, hdx as i32, m as i32))?;
        let geom: u64 = (self.max_pos as u64) | ((qk_dim as u64) << 20) | ((nblk_stride as u64) << 40);
        let grid_nblk = if sc.qsa_grid_nblk > 0 { sc.qsa_grid_nblk.min(nblk_stride) } else { nblk_stride };
        if let Some(pool_p) = self.qsa_pool_p(att_i) {
            // refresh the blocks this step's rows touched, then score from the plane (exact)
            gblaunch!(l, "qsa_pool_update_b", ((m.div_ceil(8)) as u32, 1, 1), (256, 1, 1), 0,
                      (pool_p, keys_p, &sc.pos, &sc.slot_ids, params_p, geom as i64, m as i32))?;
            if self.qsa_bucket_free() {
                // WP04: bucket-free persistent scorer — fixed grid, per-row block bound on device,
                // bit-identical scores (--exl3-score-mr=0 = the bucketed kernel below).
                let smem = (m.min(QSA_MR_ROWS) * heads * hdx * 4) as u32;
                gblaunch!(l, "qsa_score_pooled_mr", (qsa_mr_ctas(), m.div_ceil(QSA_MR_ROWS) as u32, 1), (256, 1, 1), smem,
                          (&mut sc.qsa_scores, &sc.qsa_qkb, pool_p, &sc.pos, &sc.slot_ids, params_p,
                           (geom | score_mr_geom_flag()) as i64, m as i32))?;
                if wp14_xcheck(crate::opt!("exl3-score-xcheck")) && !self.stream_capturing() {
                    self.wp04_xcheck_scores(l, sc, att_i, m, pool_p, params_p, geom, nblk_stride)?;
                }
            } else {
            gblaunch!(l, "qsa_score_pooled_b", ((grid_nblk.div_ceil(8)) as u32, m as u32, 1), (256, 1, 1), 0,
                      (&mut sc.qsa_scores, &sc.qsa_qkb, pool_p, &sc.pos, &sc.slot_ids, params_p, geom as i64))?;
            }
        } else {
            gblaunch!(l, "qsa_score_b", ((grid_nblk.div_ceil(8)) as u32, m as u32, 1), (256, 1, 1), 0,
                      (&mut sc.qsa_scores, &sc.qsa_qkb, keys_p, &sc.pos, &sc.slot_ids,
                       0u64, 0u64, params_p, geom as i64))?;
        }
        // S-A3-i review fix: SELECT_ALL is unsafe past sel_max (list overflow) and
        // redundant below it (the dense branch IS the full selection) — constant 0.
        let sel_all = 0i32;
        // WP14 stage 1: the bit-identical top-k twin (--exl3-topk-v2=0 = the original).
        // A5-K3 (attn.qsa_select / --qsa-select=1): the latency-lean twin asc3 (same bits as asc2).
        let topk_k = if qsa_select_on() { "xq_qsa_topk_asc3" } else if topk_v2_on() { "xq_qsa_topk_asc2" }
                     else { "xq_qsa_topk_asc" };
        if qsa_select_on() {
            static K3_ONCE: std::sync::Once = std::sync::Once::new();
            K3_ONCE.call_once(|| println!("A5-K3: QSA top-k select asc3 ON (xq_qsa_topk_asc3, grid m x 1024; \
                                           --qsa-select=0 = xq_qsa_topk_asc2)"));
        }
        xqlaunch!(l, topk_k, (m as u32, 1, 1), (1024, 1, 1), 0,
                  (&mut sc.qsa_sel, &mut sc.qsa_psel, &sc.qsa_scores, &sc.pos,
                   params_p, nblk_stride as i32, sel_all))?;
        if (topk_v2_on() || qsa_select_on()) && wp14_xcheck(crate::opt!("exl3-topk-xcheck")) && !self.stream_capturing() {
            self.wp14_xcheck_topk(l, sc, att_i, m, params_p, nblk_stride, sel_max, topk_k)?;
        }
        if let Some((k, ds_, dp_, _, _)) = self.qsa_rowdbg.as_ref() {
            if *k == att_i {
                xqlaunch!(l, "xq_dbg_scatter_sel", (m as u32, 1, 1), (256, 1, 1), 0,
                          (*ds_.device_ptr() as u64, *dp_.device_ptr() as u64, &sc.qsa_sel, &sc.qsa_psel,
                           &sc.pos, sel_max as i32, QSA_ROWDUMP_CAP as i32))?;
            }
        }
        if let Some((k, ds, dc, _, _)) = self.qsa_dbg.as_ref() {
            if *k == att_i {
                xqlaunch!(l, "xq_copy_f32", (((sel_max as u32) + 255) / 256, 1, 1), (256, 1, 1), 0,
                          (*ds.device_ptr() as u64, *sc.qsa_sel.device_ptr() as u64, sel_max as i64, 0i64, 0i64))?;
                xqlaunch!(l, "xq_copy_f32", (((nblk_stride as u32) + 255) / 256, 1, 1), (256, 1, 1), 0,
                          (*dc.device_ptr() as u64, *sc.qsa_scores.device_ptr() as u64, nblk_stride as i64, 0i64, 0i64))?;
            }
        }
        // K/V write (bit-identical words) + q staging, then the gathered attention
        let nh_p = (cfg.num_heads as i32) | ((cfg.num_kv_heads as i32) << 16);
        let hd_p = (cfg.head_dim as i32) | ((cfg.rotary_dim as i32) << 16);
        xqlaunch!(l, "xq_attn_prep", ((m * cfg.num_kv_heads) as u32, 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                  (&mut sc.qstage, self.kv_p(att_i),
                   &sc.qg, &sc.kp, &sc.vp, &a.qnkn, &sc.cos, &sc.slots,
                   nh_p, hd_p, self.mpf(), cfg.rms_eps))?;
        let nsd = qsa_splits_dec();
        let split_len = sel_max.div_ceil(nsd);
        let g2: u64 = (nsd as u64) | ((sel_max as u64) << 20) | ((self.mpf() as u32 as u64) << 32);
        // W4/QSA (p5d: DEFAULT OFF, opt-in --w4qsa=1 — bitwise but slower in-round, see
        // w4qsa_on): the union gather stages each selected K/V row ONCE for all of a verify's
        // rows (one slot, consecutive positions). Bit-identical partials; the old dispatch serves
        // by default and always for decode steps (one row per lane/slot), m = 1 and the
        // --w4qsa-off=1 escape.
        let union_smem = if one_slot && m >= 2 && w4qsa_on() {
            qsa_union_fits(self.kv_fmt, cfg.num_heads, cfg.num_kv_heads, cfg.head_dim, m, split_len)
        } else { None };
        if let Some(smem) = union_smem {
            let xc = w4qsa_xcheck() && !self.stream_capturing();
            if xc {
                // poison the partials so a skipped write can never compare equal by accident
                self.w4qsa_poison(l, sc)?;
            }
            let ngrp = (cfg.num_heads / cfg.num_kv_heads) / QU_HPW;
            let split_hd = ((split_len as u32) | ((cfg.head_dim as u32) << 16)) as i32;
            xqlaunch!(l, "xq_attn_sel_union", ((cfg.num_kv_heads * nsd * ngrp) as u32, 1, 1), ((32 * m) as u32, 1, 1),
                      smem as u32,
                      (&mut sc.qsa_pm, &mut sc.qsa_pl, &mut sc.qsa_pacc, &sc.qstage,
                       self.kv_p(att_i), &sc.qsa_sel, &sc.qsa_psel, &sc.slots,
                       nh_p, g2 as i64, split_hd, m as i32))?;
            if xc {
                self.w4qsa_xcheck_gather(l, sc, att_i, m, nh_p, g2, split_len, nsd)?;
            }
        } else {
            let (pm, pl, pa) = (*sc.qsa_pm.device_ptr() as u64, *sc.qsa_pl.device_ptr() as u64,
                                *sc.qsa_pacc.device_ptr() as u64);
            let kname = self.qsa_gather_old(l, sc, att_i, m, nh_p, g2, split_len, nsd, pm, pl, pa)?;
            if kname.starts_with("xq_attn_sel_hg") && wp14_xcheck(crate::opt!("exl3-gather-xcheck")) && !self.stream_capturing() {
                self.wp14_xcheck_gather(l, sc, att_i, m, nh_p, g2, split_len, nsd, kname)?;
            }
        }
        xqlaunch!(l, "xq_attn_sel_combine", ((m * cfg.num_heads) as u32, 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                  (&mut sc.normed, &sc.qsa_pm, &sc.qsa_pl, &sc.qsa_pacc, &sc.qg,
                   nh_p, nsd as i32, self.rows_kvf(m)))?;
        Ok(())
    }

    /// The pre-W4/QSA decode/verify gather dispatch into the partial buffers at (pm, pl, pacc) —
    /// hg1 / hg3 (WP14) or splitk4 / splitk (all bit-identical partials). Returns the kernel name.
    #[allow(clippy::too_many_arguments)]
    fn qsa_gather_old(&self, l: &Launcher, sc: &Scratch, att_i: usize, m: usize, nh_p: i32, g2: u64,
                      split_len: usize, nsd: usize, pm: u64, pl: u64, pa: u64) -> Result<&'static str> {
        let cfg = self.acfg_i(att_i); // TP-B: per-rank heads (trunk) / global (the replicated head)
        // A5 D6: decode/verify take the float4 twin (bit-identical partials, S-A3-v SEL_XCHECK);
        // the scalar kernel was 10.7 ms of a 32K-context verify. --exl3-sel-vec=0 = scalar.
        let sel_kname = if tune::get_cur(&T_SEL_VEC) == 0 {
            "xq_attn_sel_splitk" } else { "xq_attn_sel_splitk4" };
        // WP14 rungs 1/2: head-grouped gather with a cp.async K/V ring — same grid, splits and
        // split_len, bit-identical partials (--exl3-sel-gather=legacy|hg1|hg3|auto, default auto).
        let hpw = sel_gather_hpw(m);
        let gqa = cfg.num_heads / cfg.num_kv_heads.max(1);
        let hg = hpw > 0 && cfg.head_dim == 256 && gqa >= 1 && gqa <= 12
            && gqa * cfg.num_kv_heads == cfg.num_heads
            && kv_rowbytes(self.kv_fmt, cfg.head_dim) <= 1024 && split_len < 0x10000;
        if hg {
            let kname = if hpw == 1 { "xq_attn_sel_hg1" } else { "xq_attn_sel_hg3" };
            let nw = gqa.div_ceil(hpw);
            let split_hd = ((split_len as u32) | ((cfg.head_dim as u32) << 16)) as i32;
            xqlaunch!(l, kname, ((m * cfg.num_kv_heads * nsd) as u32, 1, 1), ((nw * 32) as u32, 1, 1), 0,
                      (pm, pl, pa, &sc.qstage,
                       self.kv_p(att_i), &sc.qsa_sel, &sc.qsa_psel, &sc.slots,
                       nh_p, g2 as i64, split_hd))?;
            Ok(kname)
        } else {
            xqlaunch!(l, sel_kname, ((m * cfg.num_kv_heads * nsd) as u32, 1, 1), (256, 1, 1), 0,
                      (pm, pl, pa, &sc.qstage,
                       self.kv_p(att_i), &sc.qsa_sel, &sc.qsa_psel, &sc.slots,
                       nh_p, g2 as i64, split_len as i32))?;
            Ok(sel_kname)
        }
    }

    /// W4/QSA XCHECK helper: fill the verify partial buffers with a NaN pattern (0x7FC0DEAD) on the
    /// compute stream, so a union launch that skips a (row, head, split) cannot match the old
    /// kernel's value by reusing a stale one.
    fn w4qsa_poison(&self, l: &Launcher, sc: &Scratch) -> Result<()> {
        use cudarc::driver::sys;
        for (p, n) in [(*sc.qsa_pm.device_ptr(), sc.qsa_pm.len()), (*sc.qsa_pl.device_ptr(), sc.qsa_pl.len()),
                       (*sc.qsa_pacc.device_ptr(), sc.qsa_pacc.len())] {
            let r = unsafe { sys::cuMemsetD32Async(p, 0x7FC0_DEAD, n, l.stream.stream) };
            anyhow::ensure!(r == sys::CUresult::CUDA_SUCCESS, "W4QSA_XCHECK poison memset failed: {r:?}");
        }
        Ok(())
    }

    /// W4/QSA --w4qsa-xcheck=1 (eager only): rerun the OLD dispatch (the kernel --w4qsa-off=1
    /// would launch: hg3 by default) into poisoned scratch partials and diff pm / pl / pacc bitwise
    /// over every (row, head, split) against the union kernel's. Prints the first calls, every
    /// mismatch and powers of two, with a running count of mismatching calls; a mismatching call
    /// is repaired with the old kernel's partials so the run continues on the old path's output.
    #[allow(clippy::too_many_arguments)]
    fn w4qsa_xcheck_gather(&self, l: &Launcher, sc: &Scratch, att_i: usize, m: usize, nh_p: i32, g2: u64,
                           split_len: usize, nsd: usize) -> Result<()> {
        let (nh, hd) = (self.acfg_i(att_i).num_heads, self.cfg.head_dim);
        let np = m * nh * nsd;
        let poison = f32::from_bits(0x7FC0_DEAD);
        let (xm, xl, xa) = (self.dev.htod_sync_copy(&vec![poison; np])?, self.dev.htod_sync_copy(&vec![poison; np])?,
                            self.dev.htod_sync_copy(&vec![poison; np * hd])?);
        let kname = self.qsa_gather_old(l, sc, att_i, m, nh_p, g2, split_len, nsd,
                                        *xm.device_ptr() as u64, *xl.device_ptr() as u64, *xa.device_ptr() as u64)?;
        self.dev.synchronize()?;
        let (tm, tl, ta) = (self.dev.dtoh_sync_copy(&sc.qsa_pm)?, self.dev.dtoh_sync_copy(&sc.qsa_pl)?,
                            self.dev.dtoh_sync_copy(&sc.qsa_pacc)?);
        let (rm, rl, ra) = (self.dev.dtoh_sync_copy(&xm)?, self.dev.dtoh_sync_copy(&xl)?, self.dev.dtoh_sync_copy(&xa)?);
        let nd = |x: &[f32], y: &[f32]| x.iter().zip(y).filter(|(p, q)| p.to_bits() != q.to_bits()).count();
        let (dm, dl, da) = (nd(&tm[..np], &rm[..np]), nd(&tl[..np], &rl[..np]), nd(&ta[..np * hd], &ra[..np * hd]));
        // success signal: the reference is real (no poison left, live splits present)
        let live = rm[..np].iter().filter(|v| **v > f32::NEG_INFINITY).count();
        let left = rm[..np].iter().chain(&rl[..np]).chain(&ra[..np * hd]).filter(|v| v.to_bits() == 0x7FC0_DEAD).count();
        static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
        static BAD: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
        let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let bad = dm + dl + da + left > 0 || live == 0;
        if bad { BAD.fetch_add(1, std::sync::atomic::Ordering::Relaxed); }
        if c < 4 || bad || (c + 1).is_power_of_two() {
            let lay = if att_i == HEAD_ATT { "head".to_string() } else { att_i.to_string() };
            let first = (0..np).find(|&i| tm[i].to_bits() != rm[i].to_bits() || tl[i].to_bits() != rl[i].to_bits())
                .map(|i| format!(" first partial {i}: m {:e}/{:e} l {:e}/{:e}", tm[i], rm[i], tl[i], rl[i]))
                .unwrap_or_default();
            println!("W4QSA_XCHECK #{c} layer {lay} m={m} kv_fmt={}: xq_attn_sel_union vs {kname} bit-differ pm {dm} pl {dl} \
                      pacc {da} of {np} / {} (live splits {live}, poison left {left}; mismatching calls so far {}){first}",
                     self.kv_fmt, np * hd, BAD.load(std::sync::atomic::Ordering::Relaxed));
        }
        if bad {
            // repair: continue the request on the OLD kernel's partials (the combine reads them
            // next), so an XCHECK run always emits the old path's tokens and keeps counting
            use cudarc::driver::sys;
            for (dst, src, n) in [(*sc.qsa_pm.device_ptr(), *xm.device_ptr(), np), (*sc.qsa_pl.device_ptr(), *xl.device_ptr(), np),
                                  (*sc.qsa_pacc.device_ptr(), *xa.device_ptr(), np * hd)] {
                let r = unsafe { sys::cuMemcpyDtoDAsync_v2(dst, src, n * 4, l.stream.stream) };
                anyhow::ensure!(r == sys::CUresult::CUDA_SUCCESS, "W4QSA_XCHECK repair copy failed: {r:?}");
            }
            self.dev.synchronize()?;
        }
        Ok(())
    }

    /// WP04 --exl3-score-xcheck (eager only): rerun the bucketed `qsa_score_pooled_b` over the
    /// FULL window into a scratch row set and diff every score both kernels write (j < nb_b).
    #[allow(clippy::too_many_arguments)]
    fn wp04_xcheck_scores(&self, l: &Launcher, sc: &Scratch, att_i: usize, m: usize, pool_p: u64,
                          params_p: u64, geom: u64, nblk_stride: usize) -> Result<()> {
        let mut xs = self.dev.alloc_zeros::<f32>(m * nblk_stride)?;
        gblaunch!(l, "qsa_score_pooled_b", ((nblk_stride.div_ceil(8)) as u32, m as u32, 1), (256, 1, 1), 0,
                  (&mut xs, &sc.qsa_qkb, pool_p, &sc.pos, &sc.slot_ids, params_p, geom as i64))?;
        self.dev.synchronize()?;
        let (a, b) = (self.dev.dtoh_sync_copy(&sc.qsa_scores)?, self.dev.dtoh_sync_copy(&xs)?);
        let pos = self.dev.dtoh_sync_copy(&sc.pos)?;
        if a.len() < m * nblk_stride {
            println!("SCORE_XCHECK skipped: score scratch {} < {m} x {nblk_stride}", a.len());
            return Ok(());
        }
        let ratio = self.cfg.indexer_compress_ratio.max(1);
        let (mut nd, mut tot, mut first) = (0usize, 0usize, String::new());
        for r in 0..m {
            let nb = (((pos[r] + 1).max(0) as usize) / ratio).min(nblk_stride);
            for j in 0..nb {
                tot += 1;
                let (x, y) = (a[r * nblk_stride + j], b[r * nblk_stride + j]);
                if x.to_bits() != y.to_bits() {
                    if nd == 0 { first = format!(" first (row {r}, block {j}): mr {x:e} vs {y:e}"); }
                    nd += 1;
                }
            }
        }
        static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
        let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        if c < 4 || nd > 0 || c.is_power_of_two() {
            let lay = if att_i == HEAD_ATT { "head".to_string() } else { att_i.to_string() };
            println!("SCORE_XCHECK #{c} layer {lay} m={m} pos0={}: qsa_score_pooled_mr vs pooled_b bit-differ {nd}/{tot}{first}",
                     pos[0]);
        }
        Ok(())
    }

    /// WP14 --exl3-topk-xcheck (eager only): rerun `xq_qsa_topk_asc` into scratch lists and
    /// diff pos_sel and the emitted entries [0, pos_sel] of every row.
    #[allow(clippy::too_many_arguments)]
    fn wp14_xcheck_topk(&self, l: &Launcher, sc: &Scratch, att_i: usize, m: usize, params_p: u64,
                        nblk_stride: usize, sel_max: usize, kname: &str) -> Result<()> {
        let mut xsel = self.dev.alloc_zeros::<i32>(m * sel_max)?;
        let mut xps = self.dev.alloc_zeros::<i32>(m)?;
        xqlaunch!(l, "xq_qsa_topk_asc", (m as u32, 1, 1), (1024, 1, 1), 0,
                  (&mut xsel, &mut xps, &sc.qsa_scores, &sc.pos, params_p, nblk_stride as i32, 0i32))?;
        self.dev.synchronize()?;
        let (s1, p1) = (self.dev.dtoh_sync_copy(&sc.qsa_sel)?, self.dev.dtoh_sync_copy(&sc.qsa_psel)?);
        let (s0, p0) = (self.dev.dtoh_sync_copy(&xsel)?, self.dev.dtoh_sync_copy(&xps)?);
        let (mut nd, mut tot, mut first) = (0usize, 0usize, String::new());
        for r in 0..m {
            tot += 1;
            if p0[r] != p1[r] {
                if nd == 0 { first = format!(" first: row {r} pos_sel v2 {} vs {}", p1[r], p0[r]); }
                nd += 1;
                continue;
            }
            let n = ((p0[r] + 1).max(0) as usize).min(sel_max);
            for i in 0..n {
                tot += 1;
                if s0[r * sel_max + i] != s1[r * sel_max + i] {
                    if nd == 0 { first = format!(" first: row {r} entry {i}: v2 {} vs {}", s1[r * sel_max + i], s0[r * sel_max + i]); }
                    nd += 1;
                }
            }
        }
        static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
        let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        if c < 4 || nd > 0 || c.is_power_of_two() {
            let lay = if att_i == HEAD_ATT { "head".to_string() } else { att_i.to_string() };
            println!("TOPK_XCHECK #{c} layer {lay} m={m} pos_sel0={}: {kname} vs asc differ {nd}/{tot}{first}", p1[0]);
        }
        Ok(())
    }

    /// WP14 --exl3-gather-xcheck (eager only): rerun the legacy `xq_attn_sel_splitk4` into
    /// scratch partials and diff pm / pl / pacc bitwise over every (row, head, split).
    #[allow(clippy::too_many_arguments)]
    fn wp14_xcheck_gather(&self, l: &Launcher, sc: &Scratch, att_i: usize, m: usize, nh_p: i32, g2: u64,
                          split_len: usize, nsd: usize, kname: &str) -> Result<()> {
        let (nh, hd) = (self.acfg_i(att_i).num_heads, self.cfg.head_dim);
        let np = m * nh * nsd;
        let (mut xm, mut xl, mut xa) = (self.dev.alloc_zeros::<f32>(np)?, self.dev.alloc_zeros::<f32>(np)?,
                                        self.dev.alloc_zeros::<f32>(np * hd)?);
        xqlaunch!(l, "xq_attn_sel_splitk4", ((m * self.acfg_i(att_i).num_kv_heads * nsd) as u32, 1, 1), (256, 1, 1), 0,
                  (&mut xm, &mut xl, &mut xa, &sc.qstage, self.kv_p(att_i), &sc.qsa_sel, &sc.qsa_psel, &sc.slots,
                   nh_p, g2 as i64, split_len as i32))?;
        self.dev.synchronize()?;
        let (tm, tl, ta) = (self.dev.dtoh_sync_copy(&sc.qsa_pm)?, self.dev.dtoh_sync_copy(&sc.qsa_pl)?,
                            self.dev.dtoh_sync_copy(&sc.qsa_pacc)?);
        let (rm, rl, ra) = (self.dev.dtoh_sync_copy(&xm)?, self.dev.dtoh_sync_copy(&xl)?, self.dev.dtoh_sync_copy(&xa)?);
        let nd = |x: &[f32], y: &[f32]| x.iter().zip(y).filter(|(p, q)| p.to_bits() != q.to_bits()).count();
        let (dm, dl, da) = (nd(&tm[..np], &rm[..np]), nd(&tl[..np], &rl[..np]), nd(&ta[..np * hd], &ra[..np * hd]));
        static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
        let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        if c < 4 || dm + dl + da > 0 || c.is_power_of_two() {
            let lay = if att_i == HEAD_ATT { "head".to_string() } else { att_i.to_string() };
            let first = (0..np).find(|&i| tm[i].to_bits() != rm[i].to_bits() || tl[i].to_bits() != rl[i].to_bits())
                .map(|i| format!(" first partial {i}: m {:e}/{:e} l {:e}/{:e}", tm[i], rm[i], tl[i], rl[i]))
                .unwrap_or_default();
            println!("GATHER_XCHECK #{c} layer {lay} m={m}: {kname} vs xq_attn_sel_splitk4 bit-differ pm {dm} pl {dl} pacc {da} of {np} / {}{first}",
                     np * hd);
        }
        Ok(())
    }

    /// WP13: may this trunk attention layer run the v3 dense kernels? They are built for
    /// hd 256 / GQA 12 (TP-4G: or GQA 6, the W=4 shape) and hold at most DV3_TS positions per row, so the dense regime must be
    /// BOUNDED by the QSA switch: the layer has an indexer, QSA is not disabled, and the
    /// switch point (positions <= qsa_limit) fits the plane. Graph keys carry the regime, so a
    /// graph captured dense is never replayed past qsa_limit. Everything else keeps v2.
    fn dense_v3_ok(&self, a: &AttnLayer) -> bool {
        let cfg = self.acfg(a); // TP-B
        dense_v3_on()
            && cfg.head_dim == 256
            && cfg.num_kv_heads > 0
            && dv3_group(cfg.num_heads, cfg.num_kv_heads).is_some()
            && a.idx.is_some()
            && cfg.has_indexer()
            && !qsa_disabled()
            && self.qsa_limit() < DV3_TS
    }

    /// WP13: dense attention v3 for `m` rows (decode step: rows are lanes with their own
    /// slot; verify: one slot, positions p..p+m-1). Output -> sc.normed, K/V words -> the
    /// cache — bit-identical to xq_attn_decode_group (verify) / xq_attn_decode (step).
    /// Launches only; every grid depends on m alone (graph-safe), positions from sc.slots.
    fn dense_attn_v3(&self, l: &Launcher, sc: &mut Scratch, a: &AttnLayer, kv: u64, m: usize,
                     verify: bool, att_i: usize) -> Result<()> {
        let cfg = self.acfg_i(att_i); // TP-B: per-rank heads (trunk) / global (the replicated head)
        let nh_p = (cfg.num_heads as i32) | ((cfg.num_kv_heads as i32) << 16);
        let hd_p = (cfg.head_dim as i32) | ((cfg.rotary_dim as i32) << 16);
        let nkv = cfg.num_kv_heads;
        let g = dv3_group(cfg.num_heads, nkv)
            .ok_or_else(|| anyhow::anyhow!("dense_attn_v3: {} heads / {} kv heads is not a dense-v3 group", cfg.num_heads, nkv))?;
        let (dots_name, kold, sd, acc_block) = dv3_plan(g, m);
        xqlaunch!(l, "xq_attn_dense_prep", ((m * cfg.num_heads) as u32, 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                  (&mut sc.qstage, kv, &sc.qg, &sc.kp, &sc.vp, &a.qnkn, &sc.cos, &sc.slots,
                   nh_p, hd_p, self.mpf(), cfg.rms_eps))?;
        // ~96 CTAs (2/SM at 46 KB smem) whatever m is; each strides over the row's 64-position
        // chunks on device (36 = the whole plane at m = 1).
        let nchg = (96 / (nkv * m)).clamp(1, DV3_NCH);
        xqlaunch!(l, dots_name, (nchg as u32, nkv as u32, m as u32), (256, 1, 1), 0,
                  (&mut sc.dv3_s, &mut sc.dv3_pm, &sc.qstage, kv, &sc.slots, nh_p, hd_p, self.mpf()))?;
        // one row: 16-dim slices (4x the CTAs); verify widths: 64-dim slices (4 chains/thread)
        // W4S (dattn): the 5-stage-ring twin (bitwise; --w4s-off=dattn = kold)
        let kname = self.w4s_dattn_kname(kold);
        xqlaunch!(l, kname, ((cfg.head_dim / sd) as u32, nkv as u32, m as u32), (acc_block, 1, 1), 0,
                  (&mut sc.normed, &sc.dv3_s, &sc.dv3_pm, kv, &sc.qg, &sc.slots, nh_p, hd_p, self.mpf()))?;
        self.w4s_dattn_xcheck(l, sc, kv, m, kname, kold, sd, cfg, acc_block)?;
        if dense_xcheck_on() && sc.dv3_xc.len() >= m * cfg.num_heads * cfg.head_dim {
            // the old kernel into the side buffer (it rewrites the same K/V words), then diff
            if verify {
                xqlaunch!(l, "xq_attn_decode_group", ((cfg.num_heads as u32), m as u32, 1), (cfg.head_dim as u32, 1, 1), 0,
                          (&mut sc.dv3_xc, &sc.qg, &sc.kp, &sc.vp, kv, &a.qnkn, &sc.cos, &sc.slots,
                           nh_p, hd_p, self.mpf(), cfg.rms_eps))?;
            } else {
                xqlaunch!(l, "xq_attn_decode", ((m as u32) * (cfg.num_heads as u32), 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                          (&mut sc.dv3_xc, &sc.qg, &sc.kp, &sc.vp, kv, &a.qnkn, &sc.cos, &sc.slots,
                           nh_p, hd_p, self.mpf(), cfg.rms_eps))?;
            }
            let tag = (att_i.min(255) | (m.min(255) << 8) | ((verify as usize) << 16)) as i32;
            xqlaunch!(l, "xq_dv3_xcheck", (1, 1, 1), (256, 1, 1), 0,
                      (&sc.normed, &sc.dv3_xc, (m * cfg.num_heads * cfg.head_dim) as i32, &mut sc.dv3_xst, tag))?;
        }
        Ok(())
    }

    pub fn forward_step(&self, sc: &mut Scratch, toks: &[i32], pos_host: &[usize], slots: &[usize],
                        mut ladder: Option<&mut LadderCtx>) -> Result<Vec<i32>> {
        let m = toks.len();
        let l = Launcher { dev: &self.dev, stream: &self.stream };
        let cfg = &self.tc; // TP-B: the trunk's per-rank geometry
        let h = cfg.hidden_size;
        let hcn = cfg.hc_count.max(1);
        let kd = cfg.lin_k_dim;
        let vd = cfg.lin_v_dim;
        let nh = cfg.lin_num_v_heads;
        let nk = cfg.lin_num_k_heads;
        let conv_dim = cfg.key_dim() * 2 + cfg.value_dim();
        let ck = cfg.conv_kernel;

        // S-A3-e FIX: htod_copy_into asserts HOST.len == DST.len and the serve path runs
        // m < width (one request prefills in its slot on a width-8 scratch). Stage with
        // fresh exact-size allocations instead - every kernel grid is m-sized and all
        // state addressing is slot-based for b < m, so nothing reads beyond m.
        // S-A3-f Item 1: persistent width-sized staging buffers (htod_copy_into wants
        // exact host len); lanes >= m stay zero — every consumer grid is m-sized and all
        // state addressing is slot-based, so padded lanes are never read.
        let w = sc.toks.len();
        // WP02: a row past the window writes K/V (and reads cos_tab) out of bounds — refuse it.
        anyhow::ensure!(pos_host.iter().all(|&p| p < self.max_pos),
                        "forward_step: position {:?} outside the KV window (max_pos {})", pos_host, self.max_pos);
        let mut toks_v = toks.to_vec();
        toks_v.resize(w, 0);
        self.dev.htod_copy_into(toks_v, &mut sc.toks)?;
        let pos_h: Vec<i32> = pos_host.iter().map(|p| *p as i32).collect();
        let mut pos_v = pos_h.clone();
        pos_v.resize(w, 0);
        self.dev.htod_copy_into(pos_v, &mut sc.pos)?;
        let mut slotpos: Vec<i32> = vec![0; w * 2];
        let mut sids_v: Vec<i32> = vec![0; w];
        for (i, pp) in pos_host.iter().enumerate() {
            slotpos[i * 2] = slots[i] as i32;
            slotpos[i * 2 + 1] = *pp as i32;
            sids_v[i] = slots[i] as i32;
        }
        self.dev.htod_copy_into(slotpos, &mut sc.slots)?;
        self.dev.htod_copy_into(sids_v, &mut sc.slot_ids)?;
        // S-A3-i: the graph is keyed by (width, regime) — the dense/sparse branch is a
        // capture-time property; each regime captures once per width on its first step.
        let qsa = self.qsa_live(pos_host.iter().copied().max().unwrap_or(0));
        let (qg, qb) = self.qsa_grid_bucket_key(pos_host.iter().copied().max().unwrap_or(0));
        sc.qsa_grid_nblk = qg;
        // WP15: a penalized step is its own graph (bit 40), so unpenalized steps replay the
        // pre-WP15 graphs untouched. WP04: the base key is gkey_of (shared with the precapture,
        // which runs unpenalized: pen_live is false at boot).
        let gkey = gkey_of(m, qsa, qb) | ((sc.pen_live as usize) << 40) | sk(sc) // TP-C: + the scratch id
            | self.vp_key(sc, m); // TP-H #4: the vocab-parallel greedy tail = its own graph

        // RoPE: gather this step's rows from the load-time table. The table was built
        // with the SAME host powf/cos/sin code the old per-step loop ran, so the bits
        // are identical; the gather is a plain row copy.
        let rdim = cfg.rotary_dim;
        let cs_stride = (2 * rdim) as i32;
        { let _ = cs_stride; // VIS-2: the mrope-aware gather (text-only slots: cos_tab[pos], unchanged)
        let slots_src = SlotSrc::Pairs(*sc.slots.device_ptr() as u64);
        self.cos_gather(&l, &mut sc.cos, *sc.pos.device_ptr() as u64, slots_src, m)?; }
        // S-A3-f Item 1b: PLE host half (ring + embedding bits) — pure host work plus a
        // padded upload into the persistent buffer; OUTSIDE the graphed kernel region.
        if self.ple.is_some() && crate::opts::var(crate::opt!("exl3-no-ple")).is_err() {
            let mut emb_bits = vec![0u16; w * 2560];
            self.ple_build_embed(m, toks, slots, &mut emb_bits)?;
            self.dev.htod_copy_into(emb_bits, &mut sc.ple_emb)?;
        }


        // TP-C (rung 4): graphs under TP. K1/K2 take only the ctx pointer and derive the epoch on
        // device, so a replay advances the protocol without re-capture; every doorbell sits on the
        // serial spine after its fork's join (design §2.3; audit in PLAN/notes_2026-09-28/TP-C.md).
        // Capture executes nothing (no barrier runs during a capture), eager and replay run the
        // identical barrier sequence, so a rank that fails a capture stays in lockstep eagerly.
        let want_graph = ladder.is_none()
            && crate::opts::var(crate::opt!("exl3-route-check")).is_err()
            && crate::opts::var(crate::opt!("exl3-no-graph")).is_err()
            && !wp12_xcheck();
        let dump_active = !want_graph
            && crate::opts::var(crate::opt!("mtp-dump")).as_deref().map_or(false, |s| !s.is_empty());
        let graphed = want_graph && self.graphs.lock().unwrap().contains_key(&gkey);
        if autotune::armed() && autotune::li_step(self, sc, m, qsa, qb)? {
            // TUNE T1 (§5.3): the armed --autotune harness ran this step from its LI arm's graph
            // (bitwise twins: the trajectory is the same whichever arm runs)
        } else if graphed {
            self.graphs.lock().unwrap().get(&gkey).unwrap().launch();
        } else {
            self.forward_step_kernels(&l, sc, m, ladder.as_deref_mut(), dump_active, qsa)?;
        }
        self.dev.synchronize()?;
        let ids = self.dev.dtoh_sync_copy(&sc.argmax)?;
        if let Some(ld) = ladder.as_deref_mut() {
            if ld.active() {
                ld.dump_u16(&self.dev, &sc.logits, "logits", self.cfg.vocab_size)?;
            }
            ld.step += 1;
        }
        // MTP_DIAG (plain path, graph-safe): with --mtp-dump set, run the DUMP
        // hook pass after the step; never inside a graph capture (host file IO).
        if crate::opts::var(crate::opt!("mtp-dump")).as_deref().map_or(false, |s| !s.is_empty()) {
            if !want_graph {
                self.diag_plain_dump(&l, sc, m)?;
            }
        }
        // S-A3-f Item 1b: first (warmup) step at this width ran eager and its outputs are
        // already read back above — record the same kernel sequence into a graph for the
        // next step. Capture failure is loud and leaves this engine eager (never wrong).
        if want_graph && !graphed {
            self.capture_step_graph(&l, sc, m, gkey, qsa);
        }
        Ok(ids)
    }

    /// S-A3-f Item 1b: the decode-step kernel sequence (embed gather → layers → final
    /// mixer → lm_head → argmax). Launches ONLY — no uploads, no host reads, no
    /// allocations — so it is legal to run eager, or record into a CUDA graph.
    fn forward_step_kernels(&self, l: &Launcher, sc: &mut Scratch, m: usize,
                            mut ladder: Option<&mut LadderCtx>, diag: bool, qsa: bool) -> Result<()> {
        let _tc = tune::enter(tune::Ctx::fam(tune::Fam::Step, m).regime(qsa)); // TUNE family scope
        let cfg = &self.tc; // TP-B: the trunk's per-rank geometry
        let h = cfg.hidden_size;
        let hcn = cfg.hc_count.max(1);
        let kd = cfg.lin_k_dim;
        let vd = cfg.lin_v_dim;
        let nh = cfg.lin_num_v_heads;
        let nk = cfg.lin_num_k_heads;
        let conv_dim = cfg.key_dim() * 2 + cfg.value_dim();
        let ck = cfg.conv_kernel;
        // WP12 XCHECK: eager only (never inside a capture — it syncs and reads back)
        let wp12_xchk = wp12_xcheck() && !self.wp12_capturing();
        // WP27: graph class of this body + the early PLE prefix (see ple_prefix).
        sc.wp27_cls = crate::exl3_wp27::CLS_STEP;
        let ple_early = self.wp27_ple_early();
        let mut wp27_ple = crate::exl3_wp27::Cap::none();
        let mut wp27_ple_tail = crate::exl3_wp27::Tail::default();
        xqlaunch!(l, "xq_embed_resid", (((h * hcn * m) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (&mut sc.resid, &self.embed, &sc.toks, h as i32, hcn as i32, m as i32))?;
        if let Some(ld) = ladder.as_deref_mut() {
            if ld.active() {
                ld.dump(&self.dev, &sc.resid, "embed", m)?;
            }
        }
        // S-A3-f-d Item 1b (MTP_DIAG plain side): when --mtp-dump is set and this
        // step runs EAGER (diag=true — never during graph capture), mirror the
        // verify_kernels dump set at the SAME buffer+point so the A/B diff is 1:1
        // with no offsets. Pure dtoh + file IO between launches; col 0 = row-0
        // slice (w = len/m).
        let pd = if diag {
            crate::opts::var(crate::opt!("mtp-dump")).ok().filter(|s| !s.is_empty())
                .map(std::path::PathBuf::from)
        } else {
            None
        };
        let pd_f32 = |d: &std::path::PathBuf, buf: &CudaSlice<f32>, name: &str| -> Result<()> {
            let host = self.dev.dtoh_sync_copy(buf)?;
            let w = buf.len() / m;
            let mut f = std::fs::File::create(format!("{}/{}_p.f32", d.display(), name))?;
            for &v in &host[..w.min(host.len())] { f.write_all(&v.to_le_bytes())?; }
            Ok(())
        };
        let pd_u16 = |d: &std::path::PathBuf, buf: &CudaSlice<u16>, name: &str| -> Result<()> {
            let host = self.dev.dtoh_sync_copy(buf)?;
            let w = buf.len() / m;
            let mut f = std::fs::File::create(format!("{}/{}_p.f32", d.display(), name))?;
            for &b in &host[..w.min(host.len())] {
                f.write_all(&f16::from_bits(b).to_f32().to_le_bytes())?;
            }
            Ok(())
        };
        if let Some(d) = pd.as_ref() {
            self.dev.synchronize()?;
            pd_f32(d, &sc.resid, "stagingCTX")?;
            // MTP_DIAG: the live GDN/conv state row this step starts from (layer 0).
            let host = self.dev.dtoh_sync_copy(&self.s_state[0])?;
            let mut f = std::fs::File::create(format!("{}/g0sin_p.f32", d.display()))?;
            for &v in &host { f.write_all(&v.to_le_bytes())?; }
            let hostc = self.dev.dtoh_sync_copy(&self.conv_state[0])?;
            let mut f2 = std::fs::File::create(format!("{}/g0cin_p.f32", d.display()))?;
            for &v in &hostc { f2.write_all(&v.to_le_bytes())?; }
        }

        let mut gdn_i = 0usize;
        let mut att_i = 0usize;
        // HC (w4): deferred injects (xq_hc_inj_norm) unless a ladder/dump/poison diagnostic touches
        // sc.resid or sc.inj between an hc_post and the next hc_pre; flushed before the PLE chain.
        let hc_def = self.hc_defer() && ladder.is_none() && pd.is_none()
            && crate::opts::var(crate::opt!("exl3-poison")).is_err();
        let mut hc_pend: Option<u64> = None;
        for (li, layer) in self.layers.iter().enumerate() {
            if li == 1 && self.ple.is_some() { self.hc_flush(&l, sc, m, &mut hc_pend)?; }
            // MTP_DIAG: same point as verify_kernels (loop top, pre-hc_pre) — 1:1 stage.
            if let Some(d) = pd.as_ref() {
                self.dev.synchronize()?;
                pd_u16(d, &sc.x, &format!("xpre{li}"))?;
            }
            if li == 1 && self.ple.is_some() {
                // S-A3-e NaN-poison probe (--exl3-poison): fill pure-activation scratch with
            // fp16 NaN so any read of a row >= m (stale data from a smaller previous batch)
            // surfaces as NaN logits -> deterministic argmax 0, instead of plausible drift.
            // Accumulators (chain_yraw, y*_raw) are skipped: they are read-modify-write.
            if crate::opts::var(crate::opt!("exl3-poison")).is_ok() {
                let g16 = |n: usize| (((n + 255) / 256).max(1) as u32, 1, 1);
                for buf in [
                    &sc.x, &sc.qkv, &sc.qg, &sc.zbuf, &sc.a_out, &sc.b_out, &sc.core,
                    &sc.mixer_out, &sc.moe_out, &sc.ysh, &sc.yd, &sc.xh_e,
                ] {
                    let n = buf.len();
                    xqlaunch!(l, "xq_memset_u16", g16(n), (256, 1, 1), 0,
                              (buf, n as i64, 0x7E00i32))?;
                }
                {
                    let n = sc.inj.len();
                    xqlaunch!(l, "xq_memset_f32", g16(n), (256, 1, 1), 0,
                              (&mut sc.inj, 0i64, n as i64))?;
                }
            }
                if crate::opts::var(crate::opt!("exl3-no-ple")).is_err() {
                    wp27_ple.join(&wp27_ple_tail)?; // WP27: the early PLE prefix branch joins here
                    self.ple_kernels(&l, sc, m, ple_early)?;
                }
            }
            self.hc_pre_p(&l, sc, &layer.hc_attn, m, hc_pend.take())?;
            self.tp_pf_hint(&layer.hc_mlp, m);   // TP-4Z2: the mixer-out reduce's K2 prefetches the mlp-site hc weights
            if let Some(ld) = ladder.as_deref_mut() {
                if ld.want(li) {
                    self.dev.synchronize()?;
                    ld.dump_u16(&self.dev, &sc.x, &format!("xpre{li}"), (m * cfg.hidden_size))?; // sc.x = mixed GEMM input [m,h]
                }
            }
            match &layer.mixer {
                Mixer::Gdn(g) => {
                    // WP27 GDN fork: the in_z chain (its own scratch) runs beside conv -> scan
                    // (it starts after in_qkv, off its bandwidth window) and joins before the
                    // gate (zbuf); a|b runs beside in_qkv and joins before the scan (b_out/a_out).
                    let zdup = crate::exl3_wp27::fork_on(crate::exl3_wp27::FORK_GDN) && sc.wp27_z_fits(&g.in_z, m);
                    let mut wp27 = if zdup {
                        crate::exl3_wp27::Cap::open(l.stream.stream, sc.wp27_cls, crate::exl3_wp27::FORK_GDN)
                    } else { crate::exl3_wp27::Cap::none() };
                    exl3_chain(&l, &g.in_qkv, &sc.x, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.qkv, m, &sc.chain_ws)?;
                    let wp27_q = wp27.mark()?; // in_qkv tail: the z chain and the conv both hang off it
                    wp27.side_begin()?;
                    if zdup {
                        exl3_chain(&l, &g.in_z, &sc.x, &mut sc.z_xh, &mut sc.z_yraw, &mut sc.zbuf, m, &sc.z_ws)?;
                    } else {
                    exl3_chain(&l, &g.in_z, &sc.x, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.zbuf, m, &sc.chain_ws)?;
                    }
                    wp27.side_end()?;
                    let wp27_z = wp27.cut()?; // a|b restarts from the fork base
                    // S-A3-f-f ITEM 1: a/b projections — warp-per-output vectorized GEMV.
                    // Was ONE block of 64 threads for K=2560 (72 launches @ 7.1 GB/s).
                    // WP12 ab: both in ONE launch (bitwise per output; --wp12-off=ab = two).
                    if wp12_on(WP12_AB) {
                        xqlaunch!(l, "xq_gemm_f16_v_ab", (12u32, m as u32, 1), (256, 1, 1), 0,
                                 (&mut sc.a_out, &mut sc.b_out, &g.a_w, &g.b_w, &sc.x, m as i32, nh as i32, h as i32))?;
                        if wp12_xchk { self.wp12_xcheck_ab(&l, sc, g, m, "step a|b")?; }
                    } else {
                    xqlaunch!(l, "xq_gemm_f16_v", (6u32, m as u32, 1), (256, 1, 1), 0,
                             (&mut sc.a_out, &g.a_w, &sc.x, m as i32, nh as i32, h as i32))?;
                    xqlaunch!(l, "xq_gemm_f16_v", (6u32, m as u32, 1), (256, 1, 1), 0,
                             (&mut sc.b_out, &g.b_w, &sc.x, m as i32, nh as i32, h as i32))?;
                    }
                    let wp27_ab = wp27.cut_to(&wp27_q)?; // WP27: resume from the in_qkv tail
                    if let Some(ld) = ladder.as_deref_mut() {
                        if ld.want_steps(li) {
                            self.dev.synchronize()?;
                            ld.dump_u16(&self.dev, &sc.qkv, &format!("g{li}_qkv"), m * conv_dim)?;
                            ld.dump_u16(&self.dev, &sc.b_out, &format!("g{li}_b"), m * nh)?;
                            ld.dump_u16(&self.dev, &sc.a_out, &format!("g{li}_a"), m * nh)?;
                        }
                    }
                    xqlaunch!(l, "xq_conv1d", (((conv_dim * m) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                             (&mut sc.qkv, (*self.conv_state[gdn_i].device_ptr()) as u64, &g.conv_w,
                              conv_dim as i32, ck as i32, m as i32, &sc.slots, conv_dim as i32))?;
                    wp27.join(&wp27_ab)?; // WP27: the scan reads b_out/a_out
                    // MTP_DIAG layer-0 bisect: pre/post-conv planes (live state).
                    if li == 0 {
                        if let Some(d) = pd.as_ref() {
                            self.dev.synchronize()?;
                            pd_u16(d, &sc.qkv, "l0conv")?;
                        }
                    }
                    if let Some(ld) = ladder.as_deref_mut() {
                        if ld.want_steps(li) {
                            self.dev.synchronize()?;
                            ld.dump_u16(&self.dev, &sc.qkv, &format!("g{li}_conv"), m * conv_dim)?;
                            ld.dump_u16(&self.dev, &sc.zbuf, &format!("g{li}_z"), m * vd)?;
                        }
                    }
                    let nchunk = vd / 32;
                    let smem = (kd * 33 + kd + 32 * 3 + kd * 2) * 4;
                    if wp12_on(WP12_STEP) && kd == 128 && vd == 128 {
                        // WP12 step: the verify chunk's register-resident device body at C = 1
                        // (AGENTS §2.8), grid m*nh x 128 threads; bitwise == xq_gdn_step.
                        // XCHECK: snapshot the live plane first, replay the old kernel on it after.
                        let twin = if wp12_xchk { Some(self.wp12_state_twin(&l, gdn_i)?) } else { None };
                        xqlaunch!(l, "xq_gdn_step_r", ((m * nh) as u32, 1, 1), (128, 1, 1), 0,
                                 (&mut sc.core, &sc.qkv, (*self.s_state[gdn_i].device_ptr()) as u64,
                                  &sc.b_out, &sc.a_out, nh as i32, nk as i32, kd as i32, vd as i32,
                                  &g.a_log, &g.dt_bias, &sc.slots))?;
                        if let Some(st2) = twin { self.wp12_xcheck_decode_step(&l, sc, g, gdn_i, m, st2)?; }
                    } else {
                    xqlaunch!(l, "xq_gdn_step", ((m * nh * nchunk) as u32, 1, 1), (kd as u32, 1, 1), smem as u32,
                             (&mut sc.core, &sc.qkv, (*self.s_state[gdn_i].device_ptr()) as u64,
                              &sc.b_out, &sc.a_out, nh as i32, nk as i32, kd as i32, vd as i32,
                              &g.a_log, &g.dt_bias, &sc.slots))?;
                    }
                    if li == 0 {
                        if let Some(d) = pd.as_ref() {
                            self.dev.synchronize()?;
                            pd_u16(d, &sc.core, "l0core")?;
                        }
                    }
                    if let Some(ld) = ladder.as_deref_mut() {
                        if ld.want_steps(li) {
                            self.dev.synchronize()?;
                            ld.dump_u16(&self.dev, &sc.core, &format!("g{li}_core"), m * vd)?;
                        }
                    }
                    wp27.join(&wp27_z)?; // WP27: the gate reads zbuf
                    xqlaunch!(l, "xq_gdn_gate", ((m * nh) as u32, 1, 1), (vd as u32, 1, 1), (vd * 4) as u32,
                             (&mut sc.normed, &sc.core, &sc.zbuf, &g.norm, vd as i32, nh as i32, m as i32, cfg.rms_eps))?;
                    if li == 0 {
                        if let Some(d) = pd.as_ref() {
                            self.dev.synchronize()?;
                            pd_u16(d, &sc.normed, "l0gate")?;
                        }
                    }
                    if let Some(ld) = ladder.as_deref_mut() {
                        if ld.want_steps(li) {
                            self.dev.synchronize()?;
                            ld.dump_u16(&self.dev, &sc.normed, &format!("g{li}_gate"), m * vd)?;
                        }
                    }
                    self.chain_o(l, &g.out_proj, &sc.normed, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.mixer_out, m, &sc.chain_ws)?; // TP-B: row-parallel -> all-reduce
                    if li == 0 {
                        if let Some(d) = pd.as_ref() {
                            self.dev.synchronize()?;
                            pd_u16(d, &sc.mixer_out, "l0yatt")?;
                        }
                    }
                    gdn_i += 1;
                }
                Mixer::Attn(a) => {
                    // q, k|v (+ the indexer qk) — W4/DENSE: one launch; else the old chains
                    let idx_pre = self.attn_in_chains(l, sc, a, m, true)?;
                    let nh_p = (cfg.num_heads as i32) | ((cfg.num_kv_heads as i32) << 16);
                    let hd_p = (cfg.head_dim as i32) | ((cfg.rotary_dim as i32) << 16);
                    // S-A3-i: past the dense threshold the model's own attention is the
                    // QSA selection; below it this dense kernel IS the spec (bit-identical
                    // to the pre-port engine, graphs included).
                    if qsa && a.idx.is_some() {
                        self.qsa_attn_step(l, sc, a, att_i, m, idx_pre, false)?;   // rows = lanes (own slots)
                    } else {
                    self.qsa_keys_append_dense(l, sc, a, att_i, m, idx_pre)?;
                    if self.dense_v3_ok(a) {
                        // WP13: dense v3, bitwise to xq_attn_decode (--exl3-dense-v3=0 = it)
                        self.dense_attn_v3(l, sc, a, (*self.k_cache[att_i].device_ptr()) as u64, m, false, att_i)?;
                    } else {
                    xqlaunch!(l, "xq_attn_decode", ((m as u32) * (cfg.num_heads as u32), 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                              (&mut sc.normed, &sc.qg, &sc.kp, &sc.vp,
                               (*self.k_cache[att_i].device_ptr()) as u64,
                               &a.qnkn, &sc.cos, &sc.slots,
                               nh_p, hd_p, self.mpf(), cfg.rms_eps))?;
                    }
                    }
                    self.chain_o(l, &a.o_proj, &sc.normed, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.mixer_out, m, &sc.chain_ws)?; // TP-B: row-parallel -> all-reduce
                    att_i += 1;
                }
            }
            let yatt_p = *sc.mixer_out.device_ptr() as u64;
            self.hc_post_d(&l, sc, yatt_p, m, hc_def, &mut hc_pend)?; // attn site: inject mixer_out
            if li == 0 {
                if let Some(d) = pd.as_ref() {
                    self.dev.synchronize()?;
                    pd_f32(d, &sc.resid, "l0rattn")?;
                }
            }
            if let Some(ld) = ladder.as_deref_mut() {
                if ld.want_steps(li) {
                    self.dev.synchronize()?;
                    ld.dump(&self.dev, &sc.resid, &format!("rmid{li}"), m)?;
                    ld.dump_u16(&self.dev, &sc.mixer_out, &format!("yatt{li}"), m * h)?;
                }
            }
            self.hc_pre_p(&l, sc, &layer.hc_mlp, m, hc_pend.take())?; // re-mix from the UPDATED residual for the mlp site
            if let Some(ld) = ladder.as_deref_mut() {
                if ld.want_steps(li) {
                    self.dev.synchronize()?;
                    ld.dump_u16(&self.dev, &sc.x, &format!("xpre_mlp{li}"), m * h)?;
                    ld.dump(&self.dev, &sc.inj, &format!("inj{li}"), m)?;
                }
            }
            if li == 0 && ple_early {
                // WP27: the PLE prefix (reads only sc.ple_emb) as a sibling branch of layer 0's
                // MoE window; joined at the layer-1 PLE boundary (no hc barrier in between).
                wp27_ple = crate::exl3_wp27::Cap::open(l.stream.stream, sc.wp27_cls, crate::exl3_wp27::FORK_PLE);
                wp27_ple.side_begin()?;
                self.ple_prefix(&l, sc, m)?;
                wp27_ple.side_end()?;
                wp27_ple_tail = wp27_ple.cut()?;
            }
            self.tp_pf_hint(self.layers.get(li + 1).map_or(&self.hc_mixer, |nl| &nl.hc_attn), m);   // TP-4Z2: the MoE reduce's K2 prefetches the next hc mixer's weights
            self.moe(&l, sc, &layer.moe, m)?;
            if li == 0 {
                if let Some(d) = pd.as_ref() {
                    self.dev.synchronize()?;
                    pd_u16(d, &sc.moe_out, "l0ymlp")?;
                }
            }
            // TP-A (G-T1-b): the replicated router logits + the post-all-reduce MoE output.
            if let Some(ld) = ladder.as_deref_mut() {
                if ld.want(li) && ld.mem.is_some() {
                    self.dev.synchronize()?;
                    ld.dump(&self.dev, &sc.logits_r, &format!("rlog{li}"), m)?;
                    ld.dump_u16(&self.dev, &sc.moe_out, &format!("ymlp{li}"), m * h)?;
                    // TP-B: the mixer output after its row-parallel all-reduce (replicated)
                    ld.dump_u16(&self.dev, &sc.mixer_out, &format!("yatt{li}"), m * h)?;
                }
            }
            if let Some(ld) = ladder.as_deref_mut() {
                if ld.want_steps(li) {
                    self.dev.synchronize()?;
                    ld.dump_u16(&self.dev, &sc.moe_out, &format!("ymlp{li}"), m * h)?;
                    ld.dump_u16(&self.dev, &sc.ysh, &format!("ysh{li}"), m * h)?;
                    ld.dump_u16(&self.dev, &sc.yd, &format!("yd{li}"), m * self.cfg.num_experts_per_tok * h)?;
                }
            }
            let ymlp_p = *sc.moe_out.device_ptr() as u64;
            self.hc_post_d(&l, sc, ymlp_p, m, hc_def, &mut hc_pend)?; // mlp site: inject moe_out (was stale mixer_out — root cause)
            if li == 0 {
                if let Some(d) = pd.as_ref() {
                    self.dev.synchronize()?;
                    pd_f32(d, &sc.resid, "l0rmlp")?;
                }
            }
            if let Some(ld) = ladder.as_deref_mut() {
                if ld.want(li) {
                    self.dev.synchronize()?;
                    ld.dump(&self.dev, &sc.resid, &format!("layer{li}"), m)?;
                }
            }
        }

        if let Some(ld) = ladder.as_deref_mut() {
            if ld.active() {
                self.dev.synchronize()?;
                ld.dump(&self.dev, &sc.resid, "precollapse", m)?;
            }
        }
        // final mixer: streams -> hidden (no inject); sc.x holds the hidden after hc_pre
        self.hc_pre_p(&l, sc, &self.hc_mixer, m, hc_pend.take())?;
        // MTP_DIAG: same buffer+point as verify's "finalmix" (sc.resid AFTER the final
        // hc_pre, f32) — 1:1 comparable with finalmix_s000.
        if let Some(d) = pd.as_ref() {
            self.dev.synchronize()?;
            pd_f32(d, &sc.resid, "finalmix")?;
        }
        if let Some(ld) = ladder.as_deref_mut() {
            if ld.active() {
                let hh = h;
                ld.dump_u16(&self.dev, &sc.x, "finalmix", hh)?;
            }
        }
        let v = cfg.vocab_size;
        if self.vp_greedy(sc, m) && ladder.is_none() && !diag {
            // TP-H #4: vocab-parallel greedy tail (see verify_kernels). The ladder / MTP_DUMP
            // diagnostics read the full logits row, so they keep the replicated head (never graphed).
            self.vp_greedy_tail(&l, sc, m)?;
            return Ok(());
        }
        if self.vp_gather(sc, m) && ladder.is_none() && !diag {
            // TP-H2 (--tp-vp-sampled): shard GEMM + row all-gather -> sc.logits rows 0..m = the replicated
            // head's rows bit for bit; the penalty / argmax / sampler below run unchanged on them.
            self.vp_gather_tail(&l, sc, m)?;
        } else {
        exl3_chain(&l, &self.lm_head, &sc.x, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.logits, m, &sc.chain_ws)?;
        }
        // WP15: penalties before BOTH the argmax and the sampler (only in pen_live graphs).
        self.pen_rows(l, sc, m)?;
        // WP09: one multi-block launch for all m rows (bitwise the same ids; escape inside).
        self.argmax_rows(l, sc, m, v)?;
        // API-parity G2: sampled rows overwrite their id (zero-param rows exit at once).
        xqlaunch!(l, "xq_sample_rows", (m as u32, 1, 1), (1024, 1, 1), 0,
                 (&mut sc.argmax, &sc.logits, v as i32, &sc.samp))?;
        Ok(())
    }

    /// WP15: `xq_pen_rows` over the m logits rows (decode lanes or verify rows; the row -> slot /
    /// position / input-token tables are sc.slots / sc.toks). No launch unless penalties are
    /// staged, so unpenalized steps are the pre-WP15 kernel sequence exactly.
    fn pen_rows(&self, l: &Launcher, sc: &mut Scratch, m: usize) -> Result<()> {
        if !sc.pen_live {
            return Ok(());
        }
        let v = self.cfg.vocab_size;
        xqlaunch!(l, "xq_pen_rows", (v.div_ceil(PEN_SPAN) as u32, m as u32, 1), (256, 1, 1), 0,
                  (&mut sc.logits, v as i32, &sc.pen, &sc.toks, &sc.slots, &mut sc.pen_hist,
                   PEN_RING_LOG2 as i32))?;
        Ok(())
    }

    /// S-A3-f Item 1b: record forward_step_kernels at width m into a CUDA graph on the
    /// model's blocking stream (gpu.rs CudaGraph wrapper — the DSV4 capture mechanism).
    fn capture_step_graph(&self, l: &Launcher, sc: &mut Scratch, m: usize, gkey: usize, qsa: bool) {
        use cudarc::driver::sys;
        let raw = self.stream.stream;
        unsafe {
            let r = sys::cuStreamBeginCapture_v2(raw, sys::CUstreamCaptureMode::CU_STREAM_CAPTURE_MODE_THREAD_LOCAL);
            if r != sys::CUresult::CUDA_SUCCESS {
                println!("EXL3_GRAPH: BeginCapture failed ({r:?}) at width {m} — staying eager");
                return;
            }
        }
        let cap = self.forward_step_kernels(l, sc, m, None, false, qsa);
        let mut graph: sys::CUgraph = std::ptr::null_mut();
        let r2 = unsafe { sys::cuStreamEndCapture(raw, &mut graph) };
        if r2 != sys::CUresult::CUDA_SUCCESS || cap.is_err() {
            println!("EXL3_GRAPH: capture failed (end={r2:?}, body={:?}) at width {m} — staying eager", cap.err());
            return;
        }
        crate::exl3_wp27::finish(graph, "step", m); // WP27: node priorities + DAG receipt
        if !self.tp_spine_audit(graph, "step", m) { unsafe { sys::cuGraphDestroy(graph); } return; } // TP-C: barriers on the spine
        unsafe {
            let mut exec: sys::CUgraphExec = std::ptr::null_mut();
            let r3 = crate::exl3_wp27::instantiate(&mut exec, graph); // WP27 (= cuGraphInstantiate_v2 unless --wp27-prio=1)
            sys::cuGraphDestroy(graph);
            if r3 == sys::CUresult::CUDA_SUCCESS {
                precap_upload(exec, raw);
                self.graphs.lock().unwrap().insert(gkey, crate::gpu::CudaGraph::from_exec(exec, raw));
                if graph_log_on() { println!("EXL3_GRAPH: captured decode step at width {m}"); }
            } else {
                println!("EXL3_GRAPH: instantiate failed ({r3:?}) at width {m} — staying eager");
            }
        }
    }
}


impl FwdModel {
    /// S-A3-e — one MTP draft-head pass for m lanes (M1, EXL3 weight path).
    ///
    /// INPUT contract: `sc.resid` holds the per-lane stream tap [m, hc, h] f32 — the trunk's
    /// pre-collapse stack after the last committed step (or the head's own previous output
    /// when chaining drafts). `toks` = the token whose embedding enters (the committed token
    /// for the first draft step, then the previously drafted id). `pos_host` = per-lane
    /// ABSOLUTE main position of that token (drives both RoPE and the head-KV write slot).
    ///
    /// S-A3-f-d chain modes (reference patch 0003 structure):
    /// - `toks_device`: skip the toks upload — sc.toks already holds the ids (the caller
    ///   D2D-copied the previous step's argmax there). `toks` content ignored.
    /// - `keep_dev`: run the draft lm_head + argmax but SKIP the dtoh sync — the id stays
    ///   in sc.argmax (device) for the next chain step / the accept kernel.
    ///
    /// OUTPUT: sc.resid = the head's updated stream stack (the next chain step's tap);
    /// with `want_logits` the per-lane draft argmax (host-returned unless keep_dev).
    #[allow(clippy::too_many_arguments)]
    /// S-A3-p: the device half of head_forward — launches only (graph-capturable). Reads
    /// toks/pos/slots from the persistent device staging buffers.
    fn head_launches(&self, l: &Launcher, sc: &mut Scratch, head: &DraftHead, m: usize, qsa: bool,
                     want_logits: bool) -> Result<()> {
        let cfg = &self.cfg;
        let h = cfg.hidden_size;
        let hcn = cfg.hc_count.max(1);
        let rdim = cfg.rotary_dim;
        let cs_stride = (2 * rdim) as i32;
        sc.wp27_cls = crate::exl3_wp27::CLS_DRAFT; // WP27: graph class of this body (MoE fork)
        { let _ = cs_stride; // VIS-2: the mrope-aware gather (text-only slots: cos_tab[pos], unchanged)
        let slots_src = SlotSrc::Pairs(*sc.slots.device_ptr() as u64);
        self.cos_gather(&l, &mut sc.cos, *sc.pos.device_ptr() as u64, slots_src, m)?; }

        // ---- entry (their Qwen4ExpMTPInputLayer, stream_tap=True, out_dtype=f32) ----
        // grouped_norm over the tap with pre_fc_norm_hidden [hc*h]; fc_hidden per stream.
        xqlaunch!(l, "xq_hc_norm", ((hcn * m) as u32, 1, 1), (1024, 1, 1), 4096,
                 (&mut sc.hn, &sc.resid, &head.pre_fc_norm_hidden, h as i32, hcn as i32, m as i32, cfg.rms_eps))?;
        exl3_chain(l, &head.fc_hidden, &sc.hn, &mut sc.hcx, &mut sc.hcy, &mut sc.hf, m * hcn, &sc.chain_ws)?;
        // embedding branch: gather (f32, broadcast rows) -> norm(pre_fc_norm_embedding) -> fc_embedding.
        xqlaunch!(l, "xq_embed_resid", (((h * hcn * m) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (&mut sc.he32, &self.embed, &sc.toks, h as i32, hcn as i32, m as i32))?;
        xqlaunch!(l, "xq_hc_norm", ((hcn * m) as u32, 1, 1), (1024, 1, 1), 4096,
                 (&mut sc.hn, &sc.he32, &head.pre_fc_norm_embedding, h as i32, hcn as i32, m as i32, cfg.rms_eps))?;
        exl3_chain(l, &head.fc_embed, &sc.hn, &mut sc.hcx, &mut sc.hcy, &mut sc.yd, m * hcn, &sc.chain_ws)?;
        // streams = h + emb, exact float add of halves, f32 out (their out_dtype).
        xqlaunch!(l, "xq_add_f16_f32", (((h * hcn * m) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (&mut sc.resid, &sc.hf, &sc.yd, ((h * hcn * m) as i64)))?;

        // ---- the head's hyper-connected attn+MoE block (same device sequence as a trunk layer) ----
        self.hc_pre(l, sc, &head.hc_attn, m)?;
        let a = &head.attn;
        // q, k|v (+ the indexer qk) — W4/DENSE: one launch; else the old chains
        let idx_pre = self.attn_in_chains(l, sc, a, m, true)?;
        let nh_p = (cfg.num_heads as i32) | ((cfg.num_kv_heads as i32) << 16);
        let hd_p = (cfg.head_dim as i32) | ((cfg.rotary_dim as i32) << 16);
        if qsa && a.idx.is_some() && !qsa_disabled() && !head_qsa_off() {
            // Head QSA: past qsa_limit the draft attends its own indexer's selection (spec).
            self.qsa_attn_step(l, sc, a, HEAD_ATT, m, idx_pre, false)?;
        } else if draft_attn_legacy() || cfg.head_dim != 256 {
            self.qsa_keys_append_dense(l, sc, a, HEAD_ATT, m, idx_pre)?;
            xqlaunch!(l, "xq_attn_decode", ((m as u32) * (cfg.num_heads as u32), 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                      (&mut sc.normed, &sc.qg, &sc.kp, &sc.vp,
                       (*head.kv.device_ptr()) as u64,
                       &a.qnkn, &sc.cos, &sc.slots,
                       nh_p, hd_p, self.mpf(), cfg.rms_eps))?;
        } else {
            // the head's raw indexer keys are spec state on every forward (S-A3-r rule)
            self.qsa_keys_append_dense(l, sc, a, HEAD_ATT, m, idx_pre)?;
            // W4S (draft): dense_prep (grid m*nh) + splitk4_w4 + combine_w4, bitwise to the three
            // launches below (--w4s-off=draft = those).
            if !self.w4s_draft_attn(l, sc, head, a, m)? {
            // A5 D5: prep (K/V cache write + q staging) -> dense split-K (GQA-shared K/V
            // reads, range from the row's position on device) -> ascending split combine.
            xqlaunch!(l, "xq_attn_prep", ((m * cfg.num_kv_heads) as u32, 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                      (&mut sc.qstage, (*head.kv.device_ptr()) as u64,
                       &sc.qg, &sc.kp, &sc.vp, &a.qnkn, &sc.cos, &sc.slots,
                       nh_p, hd_p, self.mpf(), cfg.rms_eps))?;
            let geom: u64 = (DRAFT_ATTN_SPLITS as u64) | ((self.mpf() as u32 as u64) << 32);
            xqlaunch!(l, "xq_attn_dense_splitk4", ((m * cfg.num_kv_heads * DRAFT_ATTN_SPLITS) as u32, 1, 1), (256, 1, 1), 0,
                      (&mut sc.dpm, &mut sc.dpl, &mut sc.dpacc, &sc.qstage,
                       (*head.kv.device_ptr()) as u64, &sc.slots, nh_p, geom as i64))?;
            xqlaunch!(l, "xq_attn_sel_combine", ((m * cfg.num_heads) as u32, 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                      (&mut sc.normed, &sc.dpm, &sc.dpl, &sc.dpacc, &sc.qg,
                       nh_p, DRAFT_ATTN_SPLITS as i32, self.rows_kvf(m)))?;
            } // !w4s_draft_attn
        }
        exl3_chain(l, &a.o_proj, &sc.normed, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.mixer_out, m, &sc.chain_ws)?;
        let yatt_p = *sc.mixer_out.device_ptr() as u64;
        // HC (w4): both head injects ride the next hc_pre norm (nothing reads sc.resid between).
        let (hc_def, mut hc_pend) = (self.hc_defer(), None);
        self.hc_post_d(l, sc, yatt_p, m, hc_def, &mut hc_pend)?;
        self.hc_pre_p(l, sc, &head.hc_mlp, m, hc_pend.take())?;
        self.moe(l, sc, &head.moe, m)?;
        let ymlp_p = *sc.moe_out.device_ptr() as u64;
        self.hc_post_d(l, sc, ymlp_p, m, hc_def, &mut hc_pend)?;

        // ---- exit: the head's own mixer collapses streams -> hidden; trunk lm_head drafts. ----
        self.hc_pre_p(l, sc, &head.mixer, m, hc_pend.take())?;
        if want_logits {
            // S-A3-f-d: the draft chain uses the PRUNED head slice when present
            // (reference patch 0002). Draft-only; out-of-slice argmax = verify rejection;
            // the FULL head always verifies, so accepted bits never change.
            let q = match self.lm_head_draft.as_ref() {
                Some(qd) if m == 1 => qd,
                _ => &self.lm_head,
            };
            exl3_chain(&l, q, &sc.x, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.logits, m, &sc.chain_ws)?;
            let v = q.n as usize;
            // WP15 draft mirror (draft-only): a graphed draft pass proposes from the same
            // penalized distribution the verify will judge (in-chain drafts count as past).
            if let (true, 1, Some(di)) = (sc.pen_live, m, sc.pen_draft_i) {
                xqlaunch!(l, "xq_pen_draft", (v.div_ceil(PEN_SPAN) as u32, 1, 1), (256, 1, 1), 0,
                          (&mut sc.logits, v as i32, &sc.pen, &sc.draft_meta, &sc.d_dev, di as i32,
                           &sc.pen_hist, PEN_RING_LOG2 as i32))?;
            }
            // WP24: a draft pass under --spec-sampling ratio SAMPLES its draft from the top-32
            // proposal q' (xq_rq_draft mode 2, replaces the argmax); the dump rung (mode 1) keeps
            // the argmax draft and only records the pass's top-32. Default (mode 0) = unchanged.
            match (m, sc.rq_draft_i, sc.rq_mode) {
                (1, Some(di), 2) => self.rq_draft(l, sc, v, di, 2)?,
                (1, Some(di), 1) => {
                    self.argmax_rows(l, sc, m, v)?;
                    self.rq_draft(l, sc, v, di, 1)?;
                }
                // WP09: one multi-block launch (bitwise the same draft ids; escape inside).
                _ => self.argmax_rows(l, sc, m, v)?,
            }
        }
        Ok(())
    }

    /// WP24: xq_rq_draft over draft pass `i`'s logits row (sc.logits[..v], the pruned head after
    /// the WP15 draft mirror): its top-32 -> sc.rq_list row i, and (mode 2) the draft sampled from
    /// q' -> sc.argmax[0] (draft_pass then routes it to d_dev[i] / the next pass's token exactly
    /// like the argmax). Counter = draft_meta[3] + i; params = sc.rq_dsamp. Launches only
    /// (graph-capturable; the pass index is baked per pass graph like the other tail launches).
    fn rq_draft(&self, l: &Launcher, sc: &mut Scratch, v: usize, i: usize, mode: i32) -> Result<()> {
        let nb = crate::wp24::draft_nb(v);
        anyhow::ensure!(crate::wp24::draft_fits(v) && i <= MTP_MAX_K,
                        "rq_draft: vocab {v} / pass {i} outside the xq_rq_draft envelope");
        // i0 = i: list row i AND counter draft_meta[3] + i (row r = 0 of a one-row grid)
        xqlaunch!(l, "xq_rq_draft", (nb as u32, 1, 1), (256, 1, 1), 0,
                  (&mut sc.argmax, &sc.logits, v as i32, &mut sc.rq_part, &mut sc.rq_cnt,
                   &mut sc.rq_list, &sc.rq_dsamp, &sc.draft_meta, i as i32, mode))?;
        Ok(())
    }

    /// WP24 rung 0 on the DHEAD / DHEADP tails (--wp24-dump, rq_mode 1): the served tail has
    /// already written the pass's draft (argmax, dconf, d_dev, toks — untouched here, so the
    /// trajectory is the served one); recompute the slice logits from the same sc.x (the old
    /// tail's exl3_chain, + the WP15 draft mirror when penalties are live — DHEAD's XCHECK does the
    /// same) and record their top-32 into rq_list row i. Launches only (graph-capturable).
    fn rq_dump_list(&self, l: &Launcher, sc: &mut Scratch, q: &Quad, i: usize) -> Result<()> {
        if sc.rq_mode != 1 {
            return Ok(());
        }
        exl3_chain(l, q, &sc.x, &mut sc.chain_xh, &mut sc.chain_yraw, &mut sc.logits, 1, &sc.chain_ws)?;
        let v = q.n as usize;
        if sc.pen_live && pen_draft_on() {
            xqlaunch!(l, "xq_pen_draft", (v.div_ceil(PEN_SPAN) as u32, 1, 1), (256, 1, 1), 0,
                      (&mut sc.logits, v as i32, &sc.pen, &sc.draft_meta, &sc.d_dev, i as i32,
                       &sc.pen_hist, PEN_RING_LOG2 as i32))?;
        }
        self.rq_draft(l, sc, v, i, 1)
    }

    pub fn head_forward(&self, sc: &mut Scratch, head: &DraftHead, toks: &[i32],
                        pos_host: &[usize], slots: &[usize], want_logits: bool,
                        toks_device: bool, keep_dev: bool) -> Result<Vec<i32>> {
        let m = toks.len();
        let l = Launcher { dev: &self.dev, stream: &self.stream };
        let cfg = &self.cfg;

        // S-A3-f Item 1: persistent width-sized staging buffers + table-gather RoPE
        // (same contract as forward_step; see the note there).
        let w = sc.toks.len();
        if !toks_device {
            let mut toks_v = toks.to_vec();
            toks_v.resize(w, 0);
            self.dev.htod_copy_into(toks_v, &mut sc.toks)?;
        }
        let pos_h: Vec<i32> = pos_host.iter().map(|p| *p as i32).collect();
        let mut pos_v = pos_h.clone();
        pos_v.resize(w, 0);
        self.dev.htod_copy_into(pos_v, &mut sc.pos)?;
        let mut slotpos: Vec<i32> = vec![0; w * 2];
        for (i, pp) in pos_host.iter().enumerate() {
            slotpos[i * 2] = slots[i] as i32;
            slotpos[i * 2 + 1] = *pp as i32;
        }
        self.dev.htod_copy_into(slotpos, &mut sc.slots)?;
        // head QSA: the selection kernels read the deinterleaved slot table + the grid bucket
        let mut sids = vec![0i32; sc.slot_ids.len()];
        for (i, &s_) in slots.iter().enumerate() { if i < sids.len() { sids[i] = s_ as i32; } }
        self.dev.htod_copy_into(sids, &mut sc.slot_ids)?;
        let pmax = pos_host.iter().copied().max().unwrap_or(0);
        sc.qsa_grid_nblk = self.qsa_grid_bucket(pmax).0;
        let qsa = self.qsa_live(pmax);
        self.head_launches(&l, sc, head, m, qsa, want_logits)?;
        if want_logits {
            if keep_dev {
                Ok(Vec::new())
            } else {
                self.dev.synchronize()?;
                Ok(self.dev.dtoh_sync_copy(&sc.argmax)?)
            }
        } else {
            Ok(Vec::new())
        }
    }
}

// ---------------------------------------------------------------------------
// Drivers: generate / ladder / bench
// ---------------------------------------------------------------------------

pub struct FwdArgs {
    pub dir: String,
    pub prompt: Option<String>,
    pub ids_file: Option<String>,
    pub max_new: usize,
    pub width: usize,
    pub ladder_dir: Option<String>,
    pub ladder_layers: Vec<usize>,
    pub ladder_step: Option<usize>,
    pub max_pos: usize,
    pub bench_steps: usize,
    pub widths: Vec<usize>,
    pub prefill_chunk: Option<usize>,
}

const EOS_IDS: [i32; 2] = [248044, 248046];

pub fn run(a: &FwdArgs) -> Result<()> {
    let model = FwdModel::load(&a.dir, a.width.max(a.widths.iter().copied().max().unwrap_or(1)), a.max_pos)?;
    let mut sc = Scratch::new(&model.dev, &model.cfg, a.width.max(a.widths.iter().copied().max().unwrap_or(1)), model.cfg.rotary_dim)?;

    // prompt ids: explicit file wins; else tokenizer encode
    let mut prompt_ids: Vec<u32> = match &a.ids_file {
        Some(f) => {
            let s = std::fs::read_to_string(f)?;
            let v: Vec<u32> = serde_json::from_str(&s).or_else(|_| {
                s.split_whitespace().map(|x| x.parse::<u32>()).collect::<std::result::Result<_, _>>()
            })?;
            v
        }
        None => {
            let text = a.prompt.clone().context("--prompt or --prompt-ids required")?;
            let tok = crate::tokenizer::QwenTokenizer::from_file(&format!("{}/tokenizer.json", a.dir))?;
            tok.encode(&text, false)?
        }
    };
    println!("prompt: {} tokens (first 8: {:?})", prompt_ids.len(), &prompt_ids[..prompt_ids.len().min(8)]);

    let mut ladder = a.ladder_dir.as_ref().map(|d| {
        std::fs::create_dir_all(d).ok();
        LadderCtx { dir: d.clone(), step: 0, layers: a.ladder_layers.clone(), only_step: a.ladder_step, mem: None, digest: false, sp: None }
    });

    // prefill: chunked sweeps (S-A3-f-b, --prefill-chunk N) or sequential decode-step
    let mut t0 = std::time::Instant::now();
    let w = a.width.max(1);
    let mut pos = 0usize;
    let mut last = prompt_ids[0] as i32;
    if let Some(cw) = a.prefill_chunk.filter(|&c| c > 0) {
        // chunked: process prompt[..len-1] in C-token sweeps (the final token
        // enters via the first decode step, same as the sequential path).
        let n = prompt_ids.len().saturating_sub(1);
        let mut psc = model.prefill_scratch(cw)?;
        // S-A3-u: --prefill-warmup=1 = the serve's startup warm-up before the timed prefill;
        // --prefill-reps=k = k timed prefills in one process (rep 1 = cold-process, rep 2+ = warm).
        if crate::opts::var(crate::opt!("prefill-warmup")).is_ok() {
            model.prefill_warmup(&mut psc, 0, &FwdModel::prefill_warmup_widths(cw))?;
            // PFX1 (e): the bench measures the serve's post-boot posture — wait for the plans
            if let Some(h) = model.lt_prewarm_start() { let _ = h.join(); }
        }
        let reps: usize = crate::opts::var(crate::opt!("prefill-reps")).ok().and_then(|v| v.parse().ok()).unwrap_or(1).max(1);
        for rep in 1..reps {
            let tr = std::time::Instant::now();
            let mut p2 = 0usize;
            while p2 < n {
                let end = (p2 + cw).min(n);
                let toks: Vec<i32> = prompt_ids[p2..end].iter().map(|&t| t as i32).collect();
                model.prefill_chunk(&mut psc, &toks, p2, 0, false, None)?;
                p2 = end;
            }
            let dt = tr.elapsed().as_secs_f32();
            println!("prefill rep {rep}: {} tokens in {:.2}s ({:.0} tok/s)", prompt_ids.len(), dt, prompt_ids.len() as f32 / dt);
            model.reset_slot(0)?;
        }
        if reps > 1 || crate::opts::var(crate::opt!("prefill-warmup")).is_ok() {
            t0 = std::time::Instant::now(); // the reported prefill excludes warm-up / earlier reps
        }
        while pos < n {
            let end = (pos + cw).min(n);
            let toks: Vec<i32> = prompt_ids[pos..end].iter().map(|&t| t as i32).collect();
            model.prefill_chunk(&mut psc, &toks, pos, 0, false, None)?;
            pos = end;
        }
    } else {
        for (i, t) in prompt_ids.iter().enumerate() {
            last = *t as i32;
            if i + 1 < prompt_ids.len() {
                let toks_w = vec![last; w];
                let pos_w: Vec<_> = (0..w).map(|_| pos).collect();
                let slots_w: Vec<usize> = (0..w).collect();
                model.forward_step(&mut sc, &toks_w, &pos_w, &slots_w, ladder.as_mut())?;
                pos += 1;
            }
        }
    }
    last = *prompt_ids.last().context("empty prompt")? as i32;
    let prefill_s = t0.elapsed().as_secs_f32();
    if a.prefill_chunk.is_some() {
        println!("prefill: {} tokens in {:.1}s ({:.0} tok/s, chunked wide-M prefill, C={})",
                 prompt_ids.len(), prefill_s, prompt_ids.len() as f32 / prefill_s.max(1e-9),
                 a.prefill_chunk.unwrap_or(0));
    } else {
        println!("prefill: {} tokens in {:.1}s ({:.0} tok/s, sequential decode-step prefill)",
                 prompt_ids.len(), prefill_s, prompt_ids.len() as f32 / prefill_s.max(1e-9));
    }

    // greedy decode
    let mut out_ids: Vec<u32> = Vec::with_capacity(a.max_new);
    let mut round_ms: Vec<f64> = Vec::new();
    for step in 0..a.max_new {
        let ts = std::time::Instant::now();
        let toks_w = vec![last; w];
        let pos_w: Vec<_> = (0..w).map(|_| pos).collect();
        let slots_w: Vec<usize> = (0..w).collect();
        let ids = model.forward_step(&mut sc, &toks_w, &pos_w, &slots_w, ladder.as_mut())?;
        for lane in 1..w {
            anyhow::ensure!(ids[lane] == ids[0], "lane {lane} diverged at step {step}: assembled batch-invariance broken");
        }
        round_ms.push(ts.elapsed().as_secs_f64() * 1000.0);
        // Gated per-step top-k dump (S-A3-d Phase 1b margin evidence; diagnostics-only env).
        if let Ok(tk_dir) = crate::opts::var(crate::opt!("step-topk-dir")) {
            let lg = model.dev.dtoh_sync_copy(&sc.logits)?;
            let kv: Vec<f32> = lg.iter().map(|&b| half::f16::from_bits(b).to_f32()).collect();
            let mut idx: Vec<u32> = (0..lg.len() as u32).collect();
            idx.sort_by(|&a, &b| kv[b as usize].partial_cmp(&kv[a as usize])
                .unwrap_or(std::cmp::Ordering::Equal));
            let top: Vec<String> = idx.iter().take(8)
                .map(|&i| format!("[{},{}]", i, kv[i as usize])).collect();
            use std::io::Write;
            if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true)
                .open(format!("{tk_dir}/topk.jsonl")) {
                let _ = writeln!(f, "{{\"step\":{},\"argmax\":{},\"top\":[{}]}}",
                    step, ids[0], top.join(","));
            }
        }
        let id = ids[0];
        pos += 1;
        if EOS_IDS.contains(&id) {
            println!("EOS at step {step} (id {id})");
            break;
        }
        out_ids.push(id as u32);
        last = id;
    }

    // report
    let tok = crate::tokenizer::QwenTokenizer::from_file(&format!("{}/tokenizer.json", a.dir))?;
    let text = tok.decode(&out_ids, true)?;
    round_ms.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let med = round_ms.get(round_ms.len() / 2).copied().unwrap_or(0.0);
    println!("generated {} tokens; round ms: median {:.1} p10 {:.1} p90 {:.1}",
             out_ids.len(), med,
             round_ms.get(round_ms.len() / 10).copied().unwrap_or(0.0),
             round_ms.get(round_ms.len() * 9 / 10).copied().unwrap_or(0.0));
    println!("effective GB/s (byte model / median round): {:.1}",
             model.bytes_per_round as f64 / 1e9 / (med / 1000.0));
    println!("---- TEXT ----");
    println!("{text}");
    println!("---- IDS ----");
    println!("{out_ids:?}");

    // width sweep (bench mode): flatness through the assembled model
    if a.widths.len() > 1 || a.bench_steps > 0 {
        let widths = if a.widths.is_empty() { vec![a.width] } else { a.widths.clone() };
        for w in widths {
            // states reset per width via a fresh load (the honest offline reset)
            let m2 = FwdModel::load(&a.dir, w, a.max_pos)?;
            let mut sc2 = Scratch::new(&m2.dev, &m2.cfg, w, m2.cfg.rotary_dim)?;
            let mut pos2 = 0usize;
            let mut last2 = prompt_ids[0] as i32;
            for (i, t) in prompt_ids.iter().enumerate() {
                last2 = *t as i32;
                if i + 1 < prompt_ids.len() {
                    m2.forward_step(&mut sc2, &[last2], &[pos2], &[0], None)?;
                    pos2 += 1;
                }
            }
            let lanes: Vec<i32> = vec![last2; w];
            let mut poss: Vec<usize> = (0..w).map(|_| pos2).collect();
            let mut ms = Vec::new();
            for _ in 0..a.bench_steps.max(1) {
                let ts = std::time::Instant::now();
                let slots_w: Vec<usize> = (0..w).collect();
                m2.forward_step(&mut sc2, &lanes, &poss, &slots_w, None)?;
                ms.push(ts.elapsed().as_secs_f64() * 1000.0);
                for p in poss.iter_mut() {
                    *p += 1;
                }
            }
            ms.sort_by(|a, b| a.partial_cmp(b).unwrap());
            let med = ms.get(ms.len() / 2).copied().unwrap_or(0.0);
            println!("W={w}: median round {:.1} ms over {} steps (byte model {:.2} GB/round → {:.1} GB/s)",
                     med, ms.len(), m2.bytes_per_round as f64 / 1e9,
                     m2.bytes_per_round as f64 / 1e9 / (med / 1000.0));
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// S-A3-e — M1 draft-quality harness (the G-A3-4 instrument)
//
// Plain greedy decode is the GROUND TRUTH; the M1 pack head drafts `depth` tokens per step
// from the live tap; every draft is scored against the trunk's own revealed token (exact,
// no approximations). The decode itself is NOT speculated: the exl3 stack has no parallel
// chain-verify (GDN recurrence + per-column KV checkpoints are NVFP4-path machinery), and
// sequential verification degenerates to plain decode. What this measures honestly is the
// DECISION-RELEVANT quantity — M1 draft acceptance and head cost — plus the projected
// economics IF the parallel-verify kernel is ported (the enablement item).
// ---------------------------------------------------------------------------

/// Round record for exact post-hoc scoring.
struct DraftRound {
    drafts: Vec<i32>,
    accepted: usize, // device-computed a for this round (out.a)
}

pub fn run_mtp_bench(a: &FwdArgs, depth: usize) -> Result<()> {
    let depth = depth.max(1);
    let model = FwdModel::load(&a.dir, 1, a.max_pos)?;
    let head = match model.mtp.as_ref() {
        Some(h) => h,
        None => bail!("pack has no mtp.* draft head — M1 unavailable"),
    };
    // S-A3-o: the verify round needs width depth+1 (was 1 -> "scratch width 1 < verify width").
    let mut sc = Scratch::new(&model.dev, &model.cfg, (depth + 1).max(2), model.cfg.rotary_dim)?;

    let prompt_ids: Vec<u32> = match &a.ids_file {
        Some(f) => {
            let s = std::fs::read_to_string(f)?;
            serde_json::from_str(&s).or_else(|_| {
                s.split_whitespace().map(|x| x.parse::<u32>()).collect::<std::result::Result<_, _>>()
            })?
        }
        None => {
            let text = a.prompt.clone().context("--prompt or --prompt-ids required")?;
            let tok = crate::tokenizer::QwenTokenizer::from_file(&format!("{}/tokenizer.json", a.dir))?;
            tok.encode(&text, false)?
        }
    };
    let plen = prompt_ids.len();
    println!("MTP-BENCH depth={depth} prompt={plen} tokens max_new={} model={}", a.max_new, a.dir);

    // ---- prefill (trunk only; the SERVE primes the head ONCE — the chain-verify
    // round mirrors that; the S-A3-e per-position priming is the OLD arm's) ----
    let mut pos = 0usize;
    let mut last = prompt_ids[0] as i32;
    let t0 = std::time::Instant::now();
    let mut psc_keep: Option<PrefillScratch> = None; // WP03: the seam prime reads its head-fill carry
    if let Some(cw) = a.prefill_chunk.filter(|&c| c > 0) {
        // S-A3-r: the SERVED posture — chunked sweeps over prompt[..len-1] (exl3_serve / run()),
        // then the last prompt token through forward_step (its argmax + tap feed round 1).
        let n = plen.saturating_sub(1);
        let psc = psc_keep.insert(model.prefill_scratch(cw)?);
        while pos < n {
            let end = (pos + cw).min(n);
            let toks: Vec<i32> = prompt_ids[pos..end].iter().map(|&t| t as i32).collect();
            model.prefill_chunk(psc, &toks, pos, 0, false, None)?;
            pos = end;
        }
        last = *prompt_ids.last().unwrap() as i32;
        model.forward_step(&mut sc, &[last], &[pos], &[0], None)?;
        pos += 1;
        println!("prefill: {:.1} s (chunked C={cw}, served posture)", t0.elapsed().as_secs_f32());
    } else {
    for (i, t) in prompt_ids.iter().enumerate() {
        last = *t as i32;
        model.forward_step(&mut sc, &[last], &[pos], &[0], None)?;
        pos += 1;
    }
    println!("prefill: {:.1} s", t0.elapsed().as_secs_f32());
    }

    // The trunk's argmax after the last prompt token IS t_plen — the first generated token
    // comes free (no duplicated-token re-consume).
    let mut actual: Vec<u32> = Vec::with_capacity(a.max_new);
    let pred0 = model.dev.dtoh_sync_copy(&sc.argmax)?[0];
    actual.push(pred0 as u32);

    // ---- S-A3-f-d CHAIN-VERIFY arm (the wired serve path): one head prime from
    // the tap that predicted the first bonus, then mtp_round per step.
    model.mtp_seam_prime(&mut sc, psc_keep.as_ref(), head, last, plen, 0)?; // WP03 (the serve's prime)
    let mut rounds: Vec<DraftRound> = Vec::new();
    let mut round_ms: Vec<f64> = Vec::new();
    {
        let mut b = pred0 as i32;
        let mut p = plen;
        let mut tap_row = 0usize;
        // S-A3-t: a first token that is EOS ends the request (the serve stops there; the plain arm
        // does too) — the MTP arm used to keep drafting past it.
        let first_eos = EOS_IDS.contains(&(pred0 as i32));
        while !first_eos && actual.len() < a.max_new {
            let tr = std::time::Instant::now();
            let out = model.mtp_round(&mut sc, head, 0, depth, b, p, tap_row)?;
            round_ms.push(tr.elapsed().as_secs_f64() * 1e3);
            for &e in out.emitted.iter() {
                actual.push(e as u32);
            }
            rounds.push(DraftRound { drafts: out.emitted[..out.a].to_vec(), accepted: out.a });
            b = out.last_tok;
            p = out.pos_next;
            tap_row = out.tap_row;
            if EOS_IDS.contains(&b) {
                break;
            }
        }
    }

    let med = |v: &mut Vec<f64>| -> f64 {
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v.get(v.len() / 2).copied().unwrap_or(0.0)
    };
    // S-A3-f-d: acceptance is now DEVICE-COMPUTED per round (the accept kernel's
    // `a`), not post-hoc. drafted = rounds x depth; accepted = sum of round a's.
    let drafted = rounds.len() * depth;
    let accepted: usize = rounds.iter().map(|r| r.drafts.len()).sum();
    let mean_prefix = if rounds.is_empty() { 0.0 } else {
        accepted as f64 / rounds.len() as f64
    };
    let rms = med(&mut round_ms);
    let acc_pct = if drafted > 0 { 100.0 * accepted as f64 / drafted as f64 } else { 0.0 };
    let e_per_round = if rounds.is_empty() { 0.0 } else { actual.len() as f64 / rounds.len() as f64 };
    let mtp_decode_s = round_ms.iter().sum::<f64>() / 1e3;
    println!("MTP-BENCH RESULT depth={depth} (chain-verify, the wired serve path)");
    println!("  generated {} tokens vs plain greedy ground truth", actual.len());
    println!("  acceptance {accepted}/{drafted} = {acc_pct:.2}%   mean accepted prefix {mean_prefix:.3}   emitted/round {e_per_round:.2}");
    println!("  round (median) {rms:.1} ms   decode-only tok/s {:.1}",
             if mtp_decode_s > 0.0 { (actual.len() - 1) as f64 / mtp_decode_s } else { 0.0 });
    let plain = if rms > 0.0 { 1e3 * e_per_round / rms } else { 0.0 };
    println!("  effective served tok/s (emitted/round / round) {plain:.1}");
    Ok(())
}

// ===========================================================================
// S-A3-f-e: EXL3 packs in the GENERIC gate chain. `--bench-mtp` and
// `--probe-state` dispatch here (main.rs) when --model-dir is an EXL3 pack:
// the generic GpuModel loader cannot read this container (it panicked with a
// bytemuck alignment fault at "Shard 1/9" — the pack's index legitimately
// references NINE safetensors files: 7 model shards + the M1 mixer patch +
// the PLE ngram table — and the generic loader's bf16/f32 casts hit a
// misaligned packed tensor). Both gates run the EXL3 engine (FwdModel).
// ===========================================================================

fn gate_prompt_ids(a: &FwdArgs) -> Result<Vec<u32>> {
    match &a.ids_file {
        Some(f) => {
            let s = std::fs::read_to_string(f)?;
            serde_json::from_str(&s).or_else(|_| {
                s.split_whitespace().map(|x| x.parse::<u32>()).collect::<std::result::Result<Vec<_>, _>>()
                    .map_err(anyhow::Error::from)
            })
        }
        None => {
            // Bare gate invocations (`--bench-mtp --model-dir <m> --depth 2`) must run
            // without flags: default to the S-A3-f corpus sentence (the f round-bench
            // prompt, 16 tokens).
            let text = a.prompt.clone().unwrap_or_else(|| {
                "The theory of general relativity states that gravity is the curvature of spacetime itself".to_string()
            });
            let tok = crate::tokenizer::QwenTokenizer::from_file(&format!("{}/tokenizer.json", a.dir))?;
            tok.encode(&text, false)
        }
    }
}

/// Slot-0 state windows (conv + recurrent) of every GDN layer, as raw bits.
/// Layout is [width slots × per_layer]; slot 0 occupies [0, n).
fn snap_slot0_state(model: &FwdModel) -> Result<(Vec<Vec<u32>>, Vec<Vec<u32>>)> {
    let cfg = &model.tc; // TP-B: this rank's trunk state
    let per_conv = (cfg.key_dim() * 2 + cfg.value_dim()) * cfg.conv_kernel;
    let per_s = cfg.lin_num_v_heads * cfg.lin_k_dim * cfg.lin_v_dim;
    let mut conv = Vec::with_capacity(model.conv_state.len());
    for cs in &model.conv_state {
        let h: Vec<f32> = model.dev.dtoh_sync_copy(cs)?;
        conv.push(h[..per_conv].iter().map(|f| f.to_bits()).collect());
    }
    let mut s = Vec::with_capacity(model.s_state.len());
    for ss in &model.s_state {
        let h: Vec<f32> = model.dev.dtoh_sync_copy(ss)?;
        s.push(h[..per_s].iter().map(|f| f.to_bits()).collect());
    }
    Ok((conv, s))
}

fn state_diff(
    r: &(Vec<Vec<u32>>, Vec<Vec<u32>>),
    c: &(Vec<Vec<u32>>, Vec<Vec<u32>>),
) -> (f64, usize) {
    let mut maxd = 0.0f64;
    let mut neq = 0usize;
    for (lr, lc) in r.0.iter().zip(c.0.iter()).chain(r.1.iter().zip(c.1.iter())) {
        for (a, b) in lr.iter().zip(lc.iter()) {
            if a != b { neq += 1; }
            let (fa, fb) = (f32::from_bits(*a) as f64, f32::from_bits(*b) as f64);
            maxd = maxd.max((fa - fb).abs());
        }
    }
    (maxd, neq)
}

/// `--probe-state` on an EXL3 pack: lane-count state-equivalence probe.
/// For N = 2..=8: slot 0 consumes the SAME prompt+continuation token stream in an
/// N-lane forward_step sweep (lanes 1..N run deterministic distractor prompts),
/// and slot 0's conv/GDN state and argmax stream must be BIT-IDENTICAL to the
/// N=1 reference (the G-A3-5 batch-invariance contract, end-to-end on real
/// tokens and recurrent state — the property the f-d chain-verify lanes need).
pub fn probe_state_exl3(a: &FwdArgs) -> Result<()> {
    let w = 8usize;
    let k_steps = a.max_new.clamp(4, 64);
    let model = FwdModel::load(&a.dir, w, a.max_pos)?;
    let mut sc = Scratch::new(&model.dev, &model.cfg, w, model.cfg.rotary_dim)?;
    let ids = gate_prompt_ids(a)?;
    let v = model.cfg.vocab_size as i32;
    println!("EXL3 GDN state-equivalence probe: prompt={} tokens, K={} continuations, N=1..={w}",
             ids.len(), k_steps);

    // ---- N=1 reference: slot 0 alone, m=1 sweeps ----
    model.reset_slot(0)?;
    let mut pos = 0usize;
    for t in &ids {
        model.forward_step(&mut sc, &[*t as i32], &[pos], &[0], None)?;
        pos += 1;
    }
    let mut ref_toks: Vec<u32> = Vec::with_capacity(k_steps);
    let mut cur = model.dev.dtoh_sync_copy(&sc.argmax)?[0];
    for _ in 0..k_steps {
        ref_toks.push(cur as u32);
        model.forward_step(&mut sc, &[cur], &[pos], &[0], None)?;
        pos += 1;
        cur = model.dev.dtoh_sync_copy(&sc.argmax)?[0];
    }
    let ref_state = snap_slot0_state(&model)?;

    let mut all_exact = true;
    let mut first_bad: Option<usize> = None;
    let v = model.cfg.vocab_size as i32;
    let junk = |step: usize, slot: usize| -> i32 {
        ((step * 131 + slot * 7919 + 17) % ((v - 8) as usize) + 4) as i32
    };
    for n in 2..=w {
        for s in 0..n { model.reset_slot(s)?; }
        let mut posn = vec![0usize; n];
        // prefill sweeps: lane 0 walks the real prompt
        for (i, t) in ids.iter().enumerate() {
            let toks: Vec<i32> = (0..n).map(|s| if s == 0 { *t as i32 } else { junk(i, s) }).collect();
            let slots: Vec<usize> = (0..n).collect();
            model.forward_step(&mut sc, &toks, &posn, &slots, None)?;
            for p in posn.iter_mut() { *p += 1; }
        }
        // continuation sweeps: lane 0 consumes the REFERENCE tokens. The argmax read
        // AFTER sweep j predicts position plen+j+1, i.e. ref_toks[j+1] — the stream
        // under comparison therefore starts with the POST-PREFILL argmax (ref_toks[0]).
        let mut lane0: Vec<u32> = Vec::with_capacity(k_steps + 1);
        lane0.push(model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32);
        for (i, &rt) in ref_toks.iter().enumerate() {
            let toks: Vec<i32> = (0..n).map(|s| if s == 0 { rt as i32 } else { junk(i, s) }).collect();
            let slots: Vec<usize> = (0..n).collect();
            model.forward_step(&mut sc, &toks, &posn, &slots, None)?;
            for p in posn.iter_mut() { *p += 1; }
            lane0.push(model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32);
        }
        let st = snap_slot0_state(&model)?;
        let (maxd, neq) = state_diff(&ref_state, &st);
        // lane0[j] (argmax after consuming ref_toks[j-1]) must equal ref_toks[j]
        let amiss = lane0.iter().zip(ref_toks.iter()).filter(|(a, b)| a != b).count();
        let exact = maxd == 0.0 && neq == 0 && amiss == 0;
        all_exact &= exact;
        println!("N={n}: max |s_state(lane0@m={n}) - s_state(@m=1)| = {maxd:.7}  \
                  bit-neq={neq}  argmax-mismatch={amiss}  {}",
                 if exact { "EXACT MATCH" } else { "DIVERGES" });
        if !exact { first_bad = first_bad.or(Some(n)); }
    }
    // ---- mechanism datum: compare LOGITS row 0 (f16 bits) m=1 vs first-bad N ----
    if let (Some(nbad), false) = (first_bad, all_exact) {
        // replay the reference logits for the first continuation step, then the N-lane ones
        let lg = |model: &FwdModel, sc: &Scratch| -> Vec<u16> { model.logits_host(sc).unwrap() };
        for s in 0..=nbad { model.reset_slot(s).ok(); }
        let mut posn = vec![0usize; nbad];
        for (i, t) in ids.iter().enumerate() {
            let toks: Vec<i32> = (0..nbad).map(|s| if s == 0 { *t as i32 } else { junk(i, s) }).collect();
            let slots: Vec<usize> = (0..nbad).collect();
            model.forward_step(&mut sc, &toks, &posn, &slots, None)?;
            for p in posn.iter_mut() { *p += 1; }
        }
        let mut nref: Vec<u16>;
        {
            // m=1 reference logits at the same position
            for s in 0..1 { model.reset_slot(s).ok(); }
            let mut p0 = 0usize;
            for t in ids.iter() {
                model.forward_step(&mut sc, &[*t as i32], &[p0], &[0], None)?;
                p0 += 1;
            }
            // continue one step at m=1, read logits AFTER it (the compared position)
            model.forward_step(&mut sc, &[ref_toks[0] as i32], &[p0], &[0], None)?;
            nref = lg(&model, &sc);
        }
        for s in 0..nbad { model.reset_slot(s).ok(); }
        let mut posn = vec![0usize; nbad];
        for (i, t) in ids.iter().enumerate() {
            let toks: Vec<i32> = (0..nbad).map(|s| if s == 0 { *t as i32 } else { junk(i, s) }).collect();
            let slots: Vec<usize> = (0..nbad).collect();
            model.forward_step(&mut sc, &toks, &posn, &slots, None)?;
            for p in posn.iter_mut() { *p += 1; }
        }
        model.forward_step(&mut sc, &[ref_toks[0] as i32], &posn.clone(), &(0..nbad).collect::<Vec<_>>(), None)?;
        let nbad_lg = lg(&model, &sc);
        let v = model.cfg.vocab_size;
        let mut ndiff = 0usize;
        let mut max_ulp = 0i32;
        let mut arg_ref = 0usize;
        let mut arg_bad = 0usize;
        for i in 0..v {
            let (a, b) = (nref[i], nbad_lg[i]);
            let (fa, fb) = (half::f16::from_bits(a).to_f32(), half::f16::from_bits(b).to_f32());
            if fa > half::f16::from_bits(nref[arg_ref]).to_f32() { arg_ref = i; }
            if fb > half::f16::from_bits(nbad_lg[arg_bad]).to_f32() { arg_bad = i; }
            if a != b {
                ndiff += 1;
                max_ulp = max_ulp.max((b as i32) - (a as i32)).max((a as i32) - (b as i32));
            }
        }
        println!("LOGITS row0 @m={nbad} vs @m=1 (first cont step): {ndiff}/{v} entries differ, \
                  max ulp {max_ulp}, argmax m=1={arg_ref} (p={:.5}) vs m={nbad}={arg_bad} (p={:.5})",
                 half::f16::from_bits(nref[arg_ref]).to_f32(),
                 half::f16::from_bits(nbad_lg[arg_bad]).to_f32());
    }
    println!("RESULT: {} (exl3 probe_state N=2..={w}, K={k_steps})",
             if all_exact { "EXACT" } else { "DIVERGES" });
    if !all_exact { std::process::exit(1); }
    Ok(())
}

/// Q1 diagnostic (--prefillx-rel=1): slot-0 K/V cache rows of every attention layer for
/// positions < n, dequantized to f32 (q8: the rotated basis — L2 is invariant under the
/// orthonormal H32 rotation), K plane then V plane. Empty for formats without a host decoder.
fn snap_slot0_kv(model: &FwdModel, n: usize) -> Result<Vec<Vec<f32>>> {
    let cfg = &model.tc; // TP-B: this rank's KV heads
    let (nkv, hd, mp) = (cfg.num_kv_heads, cfg.head_dim, model.max_pos);
    let rb = kv_rowbytes(model.kv_fmt, hd);
    let mut out = Vec::with_capacity(model.k_cache.len());
    for kc in &model.k_cache {
        let b: Vec<u8> = model.dev.dtoh_sync_copy(kc)?;
        let mut v = Vec::with_capacity(2 * nkv * n * hd);
        for plane in 0..2 {
            for h in 0..nkv {
                for p in 0..n.min(mp) {
                    let off = ((plane * nkv + h) * mp + p) * rb;
                    let row = &b[off..off + rb];
                    match model.kv_fmt {
                        KV_Q8 => v.extend(kvnll::q8_dequant_row(row, hd)),
                        KV_F32 => v.extend(row.chunks_exact(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))),
                        KV_F16 => v.extend(row.chunks_exact(2).map(|c| half::f16::from_le_bytes([c[0], c[1]]).to_f32())),
                        _ => {}
                    }
                }
            }
        }
        out.push(v);
    }
    Ok(out)
}

/// Q1: (relL2 = ||r-c||/||r||, max|r-c|, max|r|) of one plane.
fn rel_stats(r: &[f32], c: &[f32]) -> (f64, f64, f64) {
    let (mut d2, mut r2, mut md, mut mr) = (0f64, 0f64, 0f64, 0f64);
    for (&a, &b) in r.iter().zip(c.iter()) {
        let (a, b) = (a as f64, b as f64);
        d2 += (a - b) * (a - b); r2 += a * a; md = md.max((a - b).abs()); mr = mr.max(a.abs());
    }
    ((d2 / r2.max(1e-300)).sqrt(), md, mr)
}

/// Q1 magnitude report (--prefillx-rel=1|2): per GDN layer conv + recurrent S, per attention
/// layer K/V cache — relative L2 and max-abs vs the reference; one PFX_RELSUM summary line
/// (=2 also prints every layer).
/// Returns (S relL2 median, KV relL2 median — None when the KV format has no host decoder).
fn prefillx_rel_report(tag: &str, sr: &(Vec<Vec<u32>>, Vec<Vec<u32>>), sc: &(Vec<Vec<u32>>, Vec<Vec<u32>>),
                       kr: &[Vec<f32>], kc: &[Vec<f32>]) -> (f64, Option<f64>) {
    let f = |v: &Vec<u32>| -> Vec<f32> { v.iter().map(|&b| f32::from_bits(b)).collect() };
    let verbose = crate::opts::var(crate::opt!("prefillx-rel")).as_deref() == Ok("2");
    let (mut s_rel, mut c_rel, mut kv_rel) = (Vec::new(), Vec::new(), Vec::new());
    let (mut s_md, mut s_mr, mut s_md_over_mr) = (0f64, 0f64, 0f64);
    for (i, ((cr, cc), (ssr, ssc))) in sr.0.iter().zip(sc.0.iter()).zip(sr.1.iter().zip(sc.1.iter())).enumerate() {
        let (a, _, _) = rel_stats(&f(cr), &f(cc));
        let (b, md, mr) = rel_stats(&f(ssr), &f(ssc));
        if verbose { println!("PFX_REL[{tag}] gdn {i:>2}: conv relL2 {a:.3e} | S relL2 {b:.3e} max|d| {md:.4e} max|ref| {mr:.4e}"); }
        c_rel.push(a); s_rel.push(b);
        s_md = s_md.max(md); s_mr = s_mr.max(mr); s_md_over_mr = s_md_over_mr.max(md / mr.max(1e-30));
    }
    for (i, (a, b)) in kr.iter().zip(kc.iter()).enumerate() {
        let (r, md, mr) = rel_stats(a, b);
        if verbose { println!("PFX_REL[{tag}] attn {i:>2}: K|V relL2 {r:.3e} max|d| {md:.4e} max|ref| {mr:.4e}"); }
        kv_rel.push(r);
    }
    let summ = |v: &mut Vec<f64>| -> String {
        if v.is_empty() { return "n/a".into(); }
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        format!("med {:.3e} max {:.3e}", v[v.len() / 2], v[v.len() - 1])
    };
    println!("PFX_RELSUM[{tag}] S relL2 {} (layer-max |d|/max|ref| {:.3e}; max|d| {:.4e} of max|ref| {:.4e}) | conv relL2 {} | KV relL2 {}",
             summ(&mut s_rel), s_md_over_mr, s_md, s_mr, summ(&mut c_rel), summ(&mut kv_rel));
    // summ sorted both in place
    let med = |v: &Vec<f64>| if v.is_empty() { None } else { Some(v[v.len() / 2]) };
    (med(&s_rel).unwrap_or(f64::NAN), med(&kv_rel))
}

/// Minimal MD5 (RFC 1321) for the prefillx pinned signature — the gate scripts' historical
/// `grep -E "^chunk C=|^RESULT|^reference" log | md5sum | cut -c1-12`, computed in-process.
fn md5_hex(msg: &[u8]) -> String {
    const S: [u32; 64] = [7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
                          5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
                          4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
                          6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21];
    let k: Vec<u32> = (0..64).map(|i| ((i as f64 + 1.0).sin().abs() * 4294967296.0) as u32).collect();
    let mut h: [u32; 4] = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476];
    let mut m = msg.to_vec();
    let bits = (msg.len() as u64).wrapping_mul(8);
    m.push(0x80);
    while m.len() % 64 != 56 { m.push(0); }
    m.extend_from_slice(&bits.to_le_bytes());
    for blk in m.chunks_exact(64) {
        let w: Vec<u32> = blk.chunks_exact(4).map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect();
        let (mut a, mut b, mut c, mut d) = (h[0], h[1], h[2], h[3]);
        for i in 0..64 {
            let (f, g) = match i / 16 {
                0 => ((b & c) | (!b & d), i),
                1 => ((d & b) | (!d & c), (5 * i + 1) % 16),
                2 => (b ^ c ^ d, (3 * i + 5) % 16),
                _ => (c ^ (b | !d), (7 * i) % 16),
            };
            let t = d;
            d = c;
            c = b;
            b = b.wrapping_add(a.wrapping_add(f).wrapping_add(k[i]).wrapping_add(w[g]).rotate_left(S[i]));
            a = t;
        }
        h[0] = h[0].wrapping_add(a); h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c); h[3] = h[3].wrapping_add(d);
    }
    h.iter().flat_map(|x| x.to_le_bytes()).map(|b| format!("{b:02x}")).collect()
}

/// L10 tolerance tier (Q1 recommendation): one chunked arm passes iff its S and KV relL2 medians
/// are <= 3x the same run's one-f32-ulp floor (bit 0) and its first token sits in the reference's
/// near-tie (rank <= 5, gap to top-1 <= 1.0 logit). Returns the failed criteria (empty = pass).
fn prefillx_tier_fails(arm_s: f64, arm_kv: Option<f64>, floor_s: f64, floor_kv: Option<f64>,
                       rank: usize, gap: f32) -> Vec<String> {
    let mut f = Vec::new();
    if !(arm_s <= 3.0 * floor_s) { f.push(format!("S relL2 {arm_s:.3e} > 3x floor {floor_s:.3e}")); }
    match (arm_kv, floor_kv) {
        (Some(a), Some(fl)) => if !(a <= 3.0 * fl) { f.push(format!("KV relL2 {a:.3e} > 3x floor {fl:.3e}")); },
        (None, None) => {}
        _ => f.push("KV relL2 missing on one side".into()),
    }
    if rank > 5 { f.push(format!("first-token rank {rank} > 5")); }
    if !(gap <= 1.0) { f.push(format!("first-token gap {gap:.4} > 1.0 logit")); }
    f
}

#[cfg(test)]
mod l10_prefillx_tests {
    use super::*;

    #[test]
    fn md5_matches_rfc1321_vectors() {
        assert_eq!(md5_hex(b""), "d41d8cd98f00b204e9800998ecf8427e");
        assert_eq!(md5_hex(b"abc"), "900150983cd24fb0d6963f7d28e17f72");
        assert_eq!(md5_hex(b"The quick brown fox jumps over the lazy dog"), "9e107d9d372bb6826bd81d3542a419d6");
        // a multi-block message (> 64 bytes, padding crosses a block)
        assert_eq!(md5_hex(b"12345678901234567890123456789012345678901234567890123456789012345678901234567890"),
                   "57edf4a22be3c955ac49da2e2107b67a");
    }

    #[test]
    fn tier_passes_q1_default_and_rejects_the_flash256_defect() {
        // Q1 ids16 default vs its bit-0 floor: S 2.21e-2 / 1.03e-2, KV 2.86e-2 / 1.60e-2, rank 1
        assert!(prefillx_tier_fails(2.21e-2, Some(2.86e-2), 1.03e-2, Some(1.60e-2), 1, 0.0).is_empty());
        // Q1 p2k default: rank 4 gap 0.95 sits inside the near-tie
        assert!(prefillx_tier_fails(4.7e-2, Some(1.04e-1), 2.83e-2, Some(6.2e-2), 4, 0.95).is_empty());
        // the flash256 staging defect (--pq8-flash=1): 5.3x / 4.8x the floor
        let f = prefillx_tier_fails(1.50e-1, Some(2.95e-1), 2.83e-2, Some(6.2e-2), 1, 0.0);
        assert_eq!(f.len(), 2, "{f:?}");
        // first token outside the near-tie, NaN relL2 (report missing), KV on one side only
        assert_eq!(prefillx_tier_fails(1e-2, None, 1e-2, None, 6, 0.5).len(), 1);
        assert_eq!(prefillx_tier_fails(1e-2, None, 1e-2, None, 2, 1.5).len(), 1);
        assert_eq!(prefillx_tier_fails(f64::NAN, None, 1e-2, None, 1, 0.0).len(), 1);
        assert_eq!(prefillx_tier_fails(1e-2, Some(1e-2), 1e-2, None, 1, 0.0).len(), 1);
    }
}

/// `--probe-exl3-prefillx`: chunked-prefill vs token-by-token equivalence on the
/// EXL3 engine (S-A3-f-d serve-text investigation). For several chunk widths C,
/// runs the serve's exact prefill arm (prefill_chunk sweeps + prefill_argmax)
/// and compares the first generated token and the final slot-0 conv/GDN state
/// against the reference token-by-token forward_step sweep. Any mismatch is a
/// serve-correctness bug that prose smokes cannot see (chat derailed through
/// prefill_chunk while the same ids through forward_step were exact).
pub fn probe_prefill_x(a: &FwdArgs) -> Result<()> {
    let model = FwdModel::load(&a.dir, 1, a.max_pos)?;
    let mut sc = Scratch::new(&model.dev, &model.cfg, 1, model.cfg.rotary_dim)?;
    let ids = gate_prompt_ids(a)?;
    let n = ids.len();
    println!("EXL3 prefill-equivalence probe: prompt={n} tokens");

    // S-A3-r: with --prefillx-qsa-keys the indexer key planes are zeroed before each arm, so
    // each arm's dump shows only its own writes (the planes are otherwise never reset).
    let zero_qsa_keys = || -> Result<()> {
        if crate::opts::var(crate::opt!("prefillx-qsa-keys")).is_err() { return Ok(()); }
        let l = Launcher { dev: &model.dev, stream: &model.stream };
        for k in model.qsa_keys.iter() {
            let n = k.len() as i64;
            xqlaunch!(l, "xq_memset_u16", (((n + 255) / 256) as u32, 1, 1), (256, 1, 1), 0,
                     (*k.device_ptr() as u64, n, 0i32))?;
        }
        model.dev.synchronize()?;
        Ok(())
    };
    // Reference arm: token-by-token forward_step sweeps (decode-kernel path).
    zero_qsa_keys()?;
    model.reset_slot(0)?;
    for (i, t) in ids.iter().enumerate() {
        model.forward_step(&mut sc, &[*t as i32], &[i], &[0], None)?;
    }
    let arg_ref = model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32;
    let st_ref = snap_slot0_state(&model)?;
    // L10: --prefillx-tier=1 runs the Q1 tolerance tier (implies the relL2 report and the
    // bit-0 ulp floor); --prefillx-expect-sig=<hex> checks the pinned signature.
    let tier_on = crate::opts::var(crate::opt!("prefillx-tier")).map_or(false, |v| v != "0" && !v.is_empty());
    let expect_sig: Option<String> = crate::opts::var(crate::opt!("prefillx-expect-sig")).ok()
        .map(|v| v.trim().to_ascii_lowercase()).filter(|v| !v.is_empty());
    // the signature's lines, in print order (reference / chunk C= / the absolute RESULT line)
    let mut sig_text = String::new();
    let rel_on = crate::opts::var(crate::opt!("prefillx-rel")).is_ok() || tier_on;
    let kv_ref = if rel_on { snap_slot0_kv(&model, n)? } else { Vec::new() };
    // S-A3-q: the reference's top-3 logits — a first-token MISMATCH inside a near-tie margin
    // is the drift class; outside it, a real divergence.
    let lg = model.dev.dtoh_sync_copy(&sc.logits)?;
    let v = model.cfg.vocab_size.min(lg.len());
    let mut top: Vec<(f32, usize)> = lg[..v].iter().enumerate()
        .map(|(i, &b)| (half::f16::from_bits(b).to_f32(), i)).collect();
    top.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
    let line = format!("reference (token-by-token forward_step): first={arg_ref}  top3 logits {:?}",
                       &top[..3.min(top.len())]);
    println!("{line}");
    sig_text += &line; sig_text.push('\n');
    // S-A3-r diagnostic --prefillx-qsa-keys=1: which positions of QSA layer 0's raw indexer
    // key plane (slot 0) each arm has written (non-zero rows), and key diffs where both wrote.
    let qsa_keys_dump = |tag: &str, prev: Option<&Vec<u16>>| -> Result<Option<Vec<u16>>> {
        if crate::opts::var(crate::opt!("prefillx-qsa-keys")).is_err() || model.qsa_keys.is_empty() { return Ok(None); }
        let hdx = model.cfg.indexer_head_dim;
        let v = model.dev.dtoh_sync_copy(&model.qsa_keys[0])?;
        let rows = (v.len() / hdx).min(n);
        let nz: Vec<usize> = (0..rows).filter(|&r| v[r * hdx..(r + 1) * hdx].iter().any(|&b| b != 0)).collect();
        let (lo, hi) = (nz.first().copied(), nz.last().copied());
        let mut msg = format!("QSA_KEYS[{tag}] layer0 slot0: written rows {} of {rows} (first {:?}, last {:?})", nz.len(), lo, hi);
        if let Some(pv) = prev {
            let (mut both, mut differ, mut only_this, mut only_ref) = (0, 0, 0, 0);
            for r in 0..rows {
                let a = &pv[r * hdx..(r + 1) * hdx]; let b = &v[r * hdx..(r + 1) * hdx];
                let (za, zb) = (a.iter().any(|&x| x != 0), b.iter().any(|&x| x != 0));
                match (za, zb) { (true, true) => { both += 1; if a != b { differ += 1; } }
                                 (false, true) => only_this += 1, (true, false) => only_ref += 1, _ => {} }
            }
            msg += &format!("; vs reference: both {both} (bit-differ {differ}), only-this {only_this}, only-ref {only_ref}");
        }
        println!("{msg}");
        Ok(Some(v))
    };
    let keys_ref = qsa_keys_dump("reference", None)?;
    let dbg_ref: Option<(Vec<i32>, Vec<f32>)> = match model.qsa_dbg.as_ref() {
        Some((_, ds, dc, _, _)) => Some((model.dev.dtoh_sync_copy(ds)?, model.dev.dtoh_sync_copy(dc)?)),
        None => None,
    };
    // S-A3-r: the last QSA layer's selection list + block scores for the final prompt row.
    let qsa_on_dump = crate::opts::var(crate::opt!("prefillx-qsa-keys")).is_ok() && model.cfg.has_indexer();
    let sel_pitch = model.qsa_limit();
    let nbs = (model.max_pos / model.cfg.indexer_compress_ratio).max(1);
    let sel_ref: Option<(Vec<i32>, Vec<f32>)> = if qsa_on_dump {
        let sel = model.dev.dtoh_sync_copy(&sc.qsa_sel)?;
        let ps = model.dev.dtoh_sync_copy(&sc.qsa_psel)?;
        let scv = model.dev.dtoh_sync_copy(&sc.qsa_scores)?;
        let cnt = (ps[0] + 1).max(0) as usize;
        Some((sel[..cnt.min(sel_pitch)].to_vec(), scv[..nbs].to_vec()))
    } else { None };

    // Chunked arm: the serve's exact loop at chunk width C.
    let mut all_ok = true;
    // S-A3-q: --prefillx-widths=a,b,c overrides the width list (serve widths 256/2048).
    // S-A3-s: an entry "A+B" = irregular split (first chunk A, then B-token chunks).
    // TP-4X1: an entry "g<C>" / "g<C>a" runs the SERVED chunk grid of this prompt (the real
    // plan_grid: tail checkpoint at message boundary - 8 = n - 14, merge cap as under TP; trailing
    // 'a' = --prefill-absorb-tail), so the old / steady-4095 / absorbed grids are probed as served.
    let served_grid = |c: usize, absorb: bool| -> Vec<usize> {
        let tail = wp16::tail_point(Some(n.saturating_sub(6)), 0, n, c, tail_ckpt_extra_chunk());
        wp16::plan_grid(0, n, c, true, tail, wp16::merge_cap(c, true), absorb.then(recon_min_rows), true)
    };
    let widths: Vec<(usize, usize, Option<(String, Vec<usize>)>)> = crate::opts::var(crate::opt!("prefillx-widths")).ok()
        .map(|v| v.split(',').filter_map(|x| {
            let x = x.trim();
            if let Some(g) = x.strip_prefix('g') {
                let (num, absorb) = match g.strip_suffix('a') { Some(h) => (h, true), None => (g, false) };
                let c: usize = num.parse().ok()?;
                let ends = served_grid(c.min(n), absorb);
                let mut prev = 0usize;
                let rows: Vec<usize> = ends.iter().map(|&e| { let r = e - prev; prev = e; r }).collect();
                println!("served grid {x} (n={n}): {} chunk(s) rows {:?}", rows.len(), rows);
                return Some((rows[0], rows.iter().copied().max().unwrap_or(1), Some((x.to_string(), ends))));
            }
            match x.split_once('+') {
                Some((a, b)) => Some((a.parse().ok()?, b.parse().ok()?, None)),
                None => x.parse().ok().map(|c: usize| (c, c, None)),
            }
        }).collect())
        .unwrap_or_else(|| vec![1, 2, 4, 8, 16, 32, 60].into_iter().map(|c| (c, c, None)).collect());
    let dec_rows: Option<(Vec<i32>, Vec<i32>)> = match model.qsa_rowdbg.as_ref() {
        Some((_, ds, dp, _, _)) => Some((model.dev.dtoh_sync_copy(ds)?, model.dev.dtoh_sync_copy(dp)?)),
        None => None,
    };
    // S-A3-u: a width longer than the prompt is CLAMPED to it (one chunk), never skipped — the
    // old `continue` let a 16-token prompt at C=2048 compare nothing and still print EXACT.
    let mut arms = 0usize;
    // L10 tier inputs per chunked arm: (tag, S med, KV med, first-token rank, gap)
    let mut tier_arms: Vec<(String, f64, Option<f64>, usize, f32)> = Vec::new();
    for (c_first, c, explicit) in widths {
        let (c_first, c) = (c_first.min(n), c.min(n));
        arms += 1;
        zero_qsa_keys()?;
        model.reset_slot(0)?;
        let mut psc = model.prefill_scratch(c.max(c_first))?;
        let mut pos = 0usize;
        let mut last0 = 0usize;
        let label = explicit.as_ref().map_or(format!("{c_first:>3}+{c}"), |(l, _)| l.clone());
        let mut ex_it = explicit.as_ref().map(|(_, v)| v.iter().copied());
        while pos < n {
            let w = if pos == 0 { c_first } else { c };
            let end = match ex_it.as_mut() { Some(it) => it.next().context("explicit grid ended before n")?, None => (pos + w).min(n) };
            let tk: Vec<i32> = ids[pos..end].iter().map(|&t| t as i32).collect();
            last0 = pos;
            model.prefill_chunk(&mut psc, &tk, pos, 0, end == n, None)?;
            pos = end;
        }
        let arg_c = model.prefill_argmax(&psc)?;
        if let (Some((dsel, dps)), Some((k, _, _, ps, pp))) = (dec_rows.as_ref(), model.qsa_rowdbg.as_ref()) {
            // per-row selection diff over every sparse position both paths recorded
            let psel_ = model.dev.dtoh_sync_copy(ps)?; let pps = model.dev.dtoh_sync_copy(pp)?;
            let sm = model.qsa_limit();
            let (mut nrows, mut ndiff, mut first, mut tot) = (0usize, 0usize, None, 0usize);
            let mut per_chunk: std::collections::BTreeMap<usize, (usize, usize)> = Default::default();
            for p in (model.qsa_limit() + 1)..n.min(QSA_ROWDUMP_CAP) {
                if dps[p] < 0 || pps[p] < 0 { continue; }
                nrows += 1;
                let a: std::collections::BTreeSet<i32> = dsel[p * sm..p * sm + (dps[p] + 1) as usize].iter().copied().collect();
                let b: std::collections::BTreeSet<i32> = psel_[p * sm..p * sm + (pps[p] + 1) as usize].iter().copied().collect();
                let d = a.symmetric_difference(&b).count();
                let ch = if p < c_first { 0 } else { 1 + (p - c_first) / c };
                let e = per_chunk.entry(ch).or_insert((0, 0)); e.0 += 1;
                if d > 0 { ndiff += 1; tot += d; e.1 += 1; if first.is_none() { first = Some((p, d)); } }
            }
            println!("QSA_ROWS[C={c_first}+{c}] layer {k}: sparse rows compared {nrows}, rows with different selection {ndiff} (first {:?}, total sym-diff {tot}); per chunk (rows, differing): {:?}",
                     first, per_chunk);
        }
        if let (Some((sr, scr)), Some((k, _, _, ps, pcs))) = (dbg_ref.as_ref(), model.qsa_dbg.as_ref()) {
            let r = n - 1 - last0;
            let sp = model.qsa_limit();
            let sel = model.dev.dtoh_sync_copy(ps)?; let scv = model.dev.dtoh_sync_copy(pcs)?;
            let row = &sel[r * sp..(r + 1) * sp]; let srow = &scv[r * nbs..(r + 1) * nbs];
            let a: std::collections::BTreeSet<i32> = sr.iter().copied().filter(|&x| x >= 0).collect();
            let b: std::collections::BTreeSet<i32> = row.iter().copied().filter(|&x| x >= 0).collect();
            let nb = n / model.cfg.indexer_compress_ratio;
            let mut sorted: Vec<f32> = scr[..nb].to_vec(); sorted.sort_by(|x, y| y.partial_cmp(x).unwrap());
            let kth = model.cfg.indexer_budget / model.cfg.indexer_compress_ratio;
            let (mut md, mut mean) = (0f32, 0f64);
            for i in 0..nb { let d = (scr[i] - srow[i]).abs(); md = md.max(d); mean += d as f64; }
            println!("QSA_DUMP[C={c}] QSA layer {k} final row: sel sym-diff {} positions; score |diff| max {:.4} mean {:.4}; ref score @rank {kth} {:.4} vs @rank {} {:.4} (selection margin {:.4})",
                     a.symmetric_difference(&b).count(), md, mean / nb as f64,
                     sorted[kth - 1], kth + 1, sorted[kth], sorted[kth - 1] - sorted[kth]);
        }
        if let Some((sr, scr)) = sel_ref.as_ref() {
            let r = n - 1 - last0;
            let sel = model.dev.dtoh_sync_copy(&psc.qsa_sel)?;
            let ps = model.dev.dtoh_sync_copy(&psc.qsa_psel)?;
            let scv = model.dev.dtoh_sync_copy(&psc.qsa_scores)?;
            let cnt = (ps[r] + 1).max(0) as usize;
            let sc_ = &sel[r * sel_pitch..r * sel_pitch + cnt.min(sel_pitch)];
            let scc = &scv[r * nbs..(r + 1) * nbs];
            let a: std::collections::BTreeSet<i32> = sr.iter().copied().collect();
            let b: std::collections::BTreeSet<i32> = sc_.iter().copied().collect();
            let only_ref: Vec<i32> = a.difference(&b).copied().take(12).collect();
            let only_chk: Vec<i32> = b.difference(&a).copied().take(12).collect();
            let nb = ((n) / model.cfg.indexer_compress_ratio).min(nbs);
            let (mut maxd, mut arg) = (0f32, 0usize);
            for i in 0..nb { let d = (scr[i] - scc[i]).abs(); if d.is_finite() && d > maxd { maxd = d; arg = i; } }
            // S-A3-r scorer twin: SAME key plane (last QSA layer), SAME normed/roped q row (the
            // prefill's final row), SAME position -> decode qsa_score_b vs the prefill scores.
            {
                let cfg = &model.cfg;
                let (hdx, heads) = (cfg.indexer_head_dim, cfg.indexer_n_heads);
                let qk_dim = (heads + 1) * hdx;
                let last_att = model.qsa_keys.len() - 1;
                let params_p = model.layers.iter().filter_map(|ly| match &ly.mixer {
                    Mixer::Attn(a) => a.idx.as_ref().and_then(|i| i.params.as_ref()).map(|p| *p.device_ptr() as u64),
                    _ => None }).last().unwrap();
                let l = Launcher { dev: &model.dev, stream: &model.stream };
                let qrow = model.dev.dtoh_sync_copy(&psc.qsa_qkb)?[r * qk_dim..(r + 1) * qk_dim].to_vec();
                let mut qv = vec![0u16; sc.qsa_qkb.len()]; qv[..qk_dim].copy_from_slice(&qrow);
                model.dev.htod_copy_into(qv, &mut sc.qsa_qkb)?;
                let mut pv = vec![0i32; sc.pos.len()]; pv[0] = (n - 1) as i32;
                model.dev.htod_copy_into(pv, &mut sc.pos)?;
                model.dev.htod_copy_into(vec![0i32; sc.slot_ids.len()], &mut sc.slot_ids)?;
                let keys_p = *model.qsa_keys[last_att].device_ptr() as u64;
                let geom: u64 = (model.max_pos as u64) | ((qk_dim as u64) << 20) | ((nbs as u64) << 40);
                gblaunch!(l, "qsa_score_b", ((nbs.div_ceil(8)) as u32, 1u32, 1), (256, 1, 1), 0,
                          (&mut sc.qsa_scores, &sc.qsa_qkb, keys_p, &sc.pos, &sc.slot_ids,
                           0u64, 0u64, params_p, geom as i64))?;
                model.dev.synchronize()?;
                let dsc = model.dev.dtoh_sync_copy(&sc.qsa_scores)?;
                let (mut md, mut ai, mut cnt_big) = (0f32, 0usize, 0usize);
                for i in 0..nb {
                    let d = (dsc[i] - scc[i]).abs();
                    if d.is_finite() { if d > md { md = d; ai = i; } if d > 1e-2 { cnt_big += 1; } }
                }
                println!("QSA_SCORER_TWIN[C={c}] identical inputs (pos {}, {} blocks): decode-vs-prefill max|diff| {:.5} @blk {} (decode {:.4} prefill {:.4}); blocks with |diff|>1e-2: {}",
                         n - 1, nb, md, ai, dsc[ai], scc[ai], cnt_big);
            }
            println!("QSA_SEL[C={c}] final row, last QSA layer: ref {} entries, chunk {} entries; sym-diff {} (only-ref {:?}, only-chunk {:?}); block-score max|diff| {:.4} @blk {} (ref {:.4} chunk {:.4}); ref first/last {:?}/{:?} chunk first/last {:?}/{:?}",
                     sr.len(), sc_.len(), a.symmetric_difference(&b).count(), only_ref, only_chk, maxd, arg,
                     scr[arg], scc[arg], sr.first(), sr.last(), sc_.first(), sc_.last());
        }
        let _ = qsa_keys_dump(&format!("chunk C={c_first}+{c}"), keys_ref.as_ref())?;
        let st_c = snap_slot0_state(&model)?;
        let (maxd, neq) = state_diff(&st_ref, &st_c);
        let mut rel_meds = (f64::NAN, None);
        if rel_on {
            let kv_c = snap_slot0_kv(&model, n)?;
            rel_meds = prefillx_rel_report(&format!("C={}", label.trim()), &st_ref, &st_c, &kv_ref, &kv_c);
        }
        let am = arg_c != arg_ref;
        let ok = !am && neq == 0;
        all_ok &= ok;
        // S-A3-s: where the chunked first token sits in the REFERENCE's logits (rank, gap to top-1).
        let rk = top.iter().position(|&(_, i)| i as u32 == arg_c);
        if let Some(rk) = rk {
            println!("  chunked first={arg_c}: reference rank {} logit {:.4} (gap to ref top-1 {:.4})",
                     rk + 1, top[rk].0, top[0].0 - top[rk].0);
        }
        let (rank, gap) = rk.map_or((usize::MAX, f32::INFINITY), |r| (r + 1, top[0].0 - top[r].0));
        tier_arms.push((format!("C={}", label.trim()), rel_meds.0, rel_meds.1, rank, gap));
        let line = format!("chunk C={label}: first={arg_c} ({}), state maxd={maxd:.7} bit-neq={neq}  {}",
                           if am { "MISMATCH" } else { "match" }, if ok { "OK" } else { "DIVERGES" });
        println!("{line}");
        sig_text += &line; sig_text.push('\n');
    }
    // Q1 noise floor (--prefillx-ulp=none,0,13,...): re-run the token-by-token REFERENCE,
    // injecting after every token but the last a pseudo-random 1-bit flip at mantissa bit k into
    // ~half the elements of every GDN recurrent state (k=0: one f32 ulp; k=13: ~one f16 ulp,
    // relative 2^-10). "none" = the plain rerun (determinism control). The drift this produces
    // is what pure rounding-level perturbation of the same recurrence amplifies to.
    let mut ulp_list: Option<String> = crate::opts::var(crate::opt!("prefillx-ulp")).ok();
    if tier_on && !ulp_list.as_deref().map_or(false, |l| l.split(',').any(|x| x.trim() == "0")) {
        ulp_list = Some(match ulp_list { Some(l) if !l.trim().is_empty() => format!("{l},0"), _ => "0".into() });
    }
    let mut floor0: Option<(f64, Option<f64>)> = None;
    if let Some(list) = ulp_list {
        let cfg = &model.cfg;
        let per_s = cfg.lin_num_v_heads * cfg.lin_k_dim * cfg.lin_v_dim;
        let l = Launcher { dev: &model.dev, stream: &model.stream };
        for ent in list.split(',').map(|x| x.trim()).filter(|x| !x.is_empty()) {
            let bit: Option<u32> = if ent == "none" { None } else { ent.parse().ok() };
            zero_qsa_keys()?;
            model.reset_slot(0)?;
            for (i, t) in ids.iter().enumerate() {
                model.forward_step(&mut sc, &[*t as i32], &[i], &[0], None)?;
                let Some(k) = bit else { continue };
                if i + 1 == n || k > 22 { continue; }
                for (li, ss) in model.s_state.iter().enumerate() {
                    let mut h: Vec<f32> = model.dev.dtoh_sync_copy(ss)?;
                    for (j, x) in h[..per_s].iter_mut().enumerate() {
                        let mut z = (j as u64) ^ ((i as u64) << 40) ^ ((li as u64) << 52);
                        z = z.wrapping_add(0x9E37_79B9_7F4A_7C15);
                        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                        z ^= z >> 31;
                        let b = x.to_bits();
                        if z & 1 == 1 && (b & 0x7F80_0000) != 0 { *x = f32::from_bits(b ^ (1u32 << k)); }
                    }
                    let tmp = model.dev.htod_copy(h[..per_s].to_vec())?;
                    let dst = *ss.device_ptr() as u64;
                    xqlaunch!(l, "xq_copy_f32", (((per_s + 255) / 256) as u32, 1, 1), (256, 1, 1), 0,
                              (dst, &tmp, per_s as i64, 0i64, 0i64))?;
                    model.dev.synchronize()?;
                }
            }
            let arg_u = model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32;
            let st_u = snap_slot0_state(&model)?;
            let (maxd, neq) = state_diff(&st_ref, &st_u);
            if rel_on {
                let kv_u = snap_slot0_kv(&model, n)?;
                let m = prefillx_rel_report(&format!("ULP bit={ent}"), &st_ref, &st_u, &kv_ref, &kv_u);
                if bit == Some(0) { floor0 = Some(m); }
            }
            println!("ULP-FLOOR bit={ent}: first={arg_u} ({}), state maxd={maxd:.7} bit-neq={neq}",
                     if arg_u == arg_ref { "match" } else { "MISMATCH" });
        }
    }
    anyhow::ensure!(arms > 0, "probe_prefill_x compared no chunked arm (empty width list)");
    let line = format!("RESULT: {} (exl3 probe_prefill_x, {arms} arm(s) compared)", if all_ok { "EXACT" } else { "DIVERGES" });
    println!("{line}");
    sig_text += &line; sig_text.push('\n');
    // L10 (a) the pinned signature: md5 of the reference / chunk C= / absolute RESULT lines, first
    // 12 hex = exactly the historical `grep -E "^chunk C=|^RESULT|^reference" | md5sum | cut -c1-12`
    // (this line and the verdicts below match none of those patterns except the new RESULT lines,
    // which come AFTER — scripts that grep the log see extra ^RESULT lines only when they opt in).
    let sig = md5_hex(sig_text.as_bytes())[..12].to_string();
    println!("PREFILLX_SIG {sig} (md5[:12] of the reference/chunk/RESULT lines; {arms} arm(s))");
    let mut new_ok = true;
    if let Some(want) = expect_sig.as_ref() {
        let ok = *want == sig;
        new_ok &= ok;
        println!("RESULT: {} (signature {sig}, expected {want})", if ok { "PREFILLX_SIG_OK" } else { "PREFILLX_SIG_MISMATCH" });
    }
    // L10 (b) the Q1 tolerance tier
    if tier_on {
        let mut ok = true;
        match floor0 {
            None => { ok = false; println!("PREFILLX_TIER no bit-0 floor measured (relL2 report unavailable)"); }
            Some((fs, fkv)) => {
                let fkv_s = fkv.map_or("n/a".to_string(), |v| format!("{v:.3e}"));
                println!("PREFILLX_TIER floor (bit 0): S relL2 med {fs:.3e} | KV relL2 med {fkv_s}");
                for (tag, s_m, kv_m, rank, gap) in &tier_arms {
                    let fails = prefillx_tier_fails(*s_m, *kv_m, fs, fkv, *rank, *gap);
                    let kv_x = match (kv_m, fkv) { (Some(a), Some(b)) => format!("{:.2}x", a / b), _ => "n/a".into() };
                    println!("PREFILLX_TIER[{tag}] S {:.2}x KV {kv_x} of floor | first rank {rank} gap {gap:.4} -> {}",
                             s_m / fs, if fails.is_empty() { "ok".to_string() } else { format!("FAIL ({})", fails.join("; ")) });
                    ok &= fails.is_empty();
                }
            }
        }
        new_ok &= ok;
        println!("RESULT: {} (tolerance tier: S/KV relL2 med <= 3x the bit-0 ulp floor, first token rank <= 5 within 1.0 logit; {arms} arm(s))",
                 if ok { "PREFILLX_TIER_OK" } else { "PREFILLX_TIER_FAIL" });
    }
    // exit code: the legacy absolute verdict, unless the caller asked for the re-baselined checks
    // (the served posture can never be EXACT — Q1) — then they decide.
    let pass = if expect_sig.is_some() || tier_on { new_ok } else { all_ok };
    if !pass { std::process::exit(1); }
    Ok(())
}

/// `--probe-exl3-pfxtrace`: S-A3-f-d night instrument. Diffs the serve's
/// chunked prefill arm (prefill_chunk at C=1, the degenerate width) against
/// the token-by-token reference arm (forward_step) STAGE BY STAGE at token 0
/// (per-layer: embed / hc / qkv-z / a-b / conv / gdn / gate / attn / moe via
/// the LadderCtx dump files), then sweeps the remaining tokens (state
/// snapshots) for the FIRST diverging token position. Classifies the
/// divergence: rounding-class (tiny at the first kernel-family difference,
/// smooth growth) vs semantic (O(1) jump at a named stage = the bug).
pub fn probe_pfx_trace(a: &FwdArgs) -> Result<()> {
    let dir_r = "/tmp/pfx_ref".to_string();
    let dir_c = "/tmp/pfx_chk".to_string();
    for d in [&dir_r, &dir_c] {
        let _ = std::fs::remove_dir_all(d);
        std::fs::create_dir_all(d)?;
    }
    let model = FwdModel::load(&a.dir, 1, a.max_pos)?;
    let mut sc = Scratch::new(&model.dev, &model.cfg, 1, model.cfg.rotary_dim)?;
    let ids = gate_prompt_ids(a)?;
    let nl = model.layers.len();
    println!("EXL3 prefill TRACE: {} tokens, {nl} layers; stage diff @ token 0 + first-divergent-token sweep", ids.len());

    // ---- Arm R: token-by-token reference (decode kernels), dumps at token 0.
    model.reset_slot(0)?;
    let mut snaps_r: Vec<Vec<u32>> = Vec::new();
    {
        let mut ld = LadderCtx { dir: dir_r.clone(), step: 0, layers: (0..nl).collect(), only_step: Some(0), mem: None, digest: false, sp: None };
        model.forward_step(&mut sc, &[ids[0] as i32], &[0], &[0], Some(&mut ld))?;
    }
    snaps_r.push(flat_state(&snap_slot0_state(&model)?));
    for (i, t) in ids.iter().enumerate().skip(1) {
        model.forward_step(&mut sc, &[*t as i32], &[i], &[0], None)?;
        if snaps_r.len() < 8 { snaps_r.push(flat_state(&snap_slot0_state(&model)?)); }
    }
    let arg_ref = model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32;

    // ---- Arm C: the serve loop at C=1, dumps at token 0.
    model.reset_slot(0)?;
    let mut psc = model.prefill_scratch(1)?;
    let mut snaps_c: Vec<Vec<u32>> = Vec::new();
    {
        let ld = LadderCtx { dir: dir_c.clone(), step: 0, layers: (0..nl).collect(), only_step: Some(0), mem: None, digest: false, sp: None };
        model.prefill_chunk(&mut psc, &[ids[0] as i32], 0, 0, true, Some(&ld))?;
    }
    snaps_c.push(flat_state(&snap_slot0_state(&model)?));
    for (i, t) in ids.iter().enumerate().skip(1) {
        model.prefill_chunk(&mut psc, &[*t as i32], i, 0, i + 1 == ids.len(), None)?;
        if snaps_c.len() < 8 { snaps_c.push(flat_state(&snap_slot0_state(&model)?)); }
    }
    let arg_chk = model.prefill_argmax(&psc)?;

    // ---- Per-token first divergence (state bits, first 8 tokens).
    let mut first_tok: Option<usize> = None;
    for i in 0..snaps_r.len().min(snaps_c.len()) {
        let neq = snaps_r[i].iter().zip(snaps_c[i].iter()).filter(|(a, b)| a != b).count();
        if neq > 0 { first_tok = Some(i); println!("state bits diverge at token {i} (of compared {}): neq={neq}", snaps_r[i].len()); break; }
    }
    if first_tok.is_none() { println!("state bits EXACT for first {} token(s)", snaps_r.len().min(snaps_c.len())); }

    // ---- Stage diff at token 0, execution order.
    let mut names: Vec<String> = std::fs::read_dir(&dir_r)?
        .filter_map(|e| e.ok().map(|e| e.file_name().to_string_lossy().to_string()))
        .filter(|f| f.ends_with("_s000.f32"))
        .map(|f| f.trim_end_matches("_s000.f32").to_string())
        .collect();
    names.sort_by_key(|n| stage_key(n));
    println!("{:<14} {:>4} {:>12} {:>10} {:>10}", "stage", "n", "max|d|", "@idx", "rel");
    let (mut first_any, mut first_sem): (Option<String>, Option<String>) = (None, None);
    for name in &names {
        let cf = format!("{dir_c}/{name}_s000.f32");
        if !std::path::Path::new(&cf).exists() {
            println!("{name:<14} present in reference only");
            continue;
        }
        let rv = read_f32_le(&format!("{dir_r}/{name}_s000.f32"))?;
        let cv = read_f32_le(&cf)?;
        let n = rv.len().min(cv.len());
        if rv.len() != cv.len() { println!("{name:<14} LENGTH MISMATCH {} vs {}", rv.len(), cv.len()); }
        let (mut md, mut mi, mut mg) = (0.0f64, 0usize, 0.0f64);
        for i in 0..n {
            let d = (rv[i] as f64 - cv[i] as f64).abs();
            if d > md { md = d; mi = i; }
            mg = mg.max((rv[i] as f64).abs());
        }
        let rel = if mg > 1e-9 { md / mg } else { md };
        if md == 0.0 { continue; }
        let tag = if rel > 1e-2 && md > 1e-3 { "  <== SEMANTIC" } else { "" };
        println!("{name:<14} {n:>9} {md:>12.4e} {mi:>10} {rel:>10.2e}{tag}");
        if first_any.is_none() { first_any = Some(name.clone()); }
        if first_sem.is_none() && rel > 1e-2 && md > 1e-3 { first_sem = Some(name.clone()); }
    }
    match (&first_any, &first_sem) {
        (a, s) => {
            println!("FIRST DIFF: {}", a.clone().unwrap_or_else(|| "(none — bitwise identical)".into()));
            println!("FIRST SEMANTIC: {}", s.clone().unwrap_or_else(|| "(none above threshold)".into()));
        }
    }
    println!("first token: ref={arg_ref} chk={arg_chk} ({})",
             if arg_ref == arg_chk { "match" } else { "MISMATCH" });
    Ok(())
}

fn flat_state(s: &(Vec<Vec<u32>>, Vec<Vec<u32>>)) -> Vec<u32> {
    let mut v = Vec::new();
    v.extend(s.0.iter().flatten());
    v.extend(s.1.iter().flatten());
    v
}

fn read_f32_le(p: &str) -> Result<Vec<f32>> {
    let b = std::fs::read(p)?;
    Ok(b.chunks_exact(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect())
}

/// Execution-order key for trace stage names (layer, stage-within-layer);
/// global stages sort last.
fn stage_key(name: &str) -> (usize, usize) {
    match name {
        "embed" => return (usize::MAX, 0),
        "precollapse" => return (usize::MAX, 1),
        "finalmix" => return (usize::MAX, 2),
        "logits" => return (usize::MAX, 3),
        _ => {}
    }
    if let Some(rest) = name.strip_prefix('g') {
        if let Some(p) = rest.find('_') {
            let li: usize = rest[..p].parse().unwrap_or(0);
            let pri = match &rest[p + 1..] { "qkv" => 1, "z" => 2, "b" => 3, "a" => 4, "conv" => 5, "core" => 6, "gate" => 7, _ => 8 };
            return (li, pri);
        }
    }
    let dstart = name.rfind(|c: char| !c.is_ascii_digit()).map(|p| p + 1).unwrap_or(0);
    let li: usize = name[dstart..].parse().unwrap_or(0);
    let pri = match &name[..dstart] {
        "xpre" => 0, "rmid" => 10, "yatt" => 11, "xpre_mlp" => 12, "inj" => 13,
        "ysh" => 14, "yd" => 15, "ymlp" => 16, "layer" => 20, _ => 30,
    };
    (li, pri)
}

/// `--bench-mtp` on an EXL3 pack: REAL chain-verify losslessness + draft
/// acceptance. Arm M (slot 0) prefills token-by-token, primes the head ONCE
/// (tap_snapshot + head_prime — the serve's prime), then decodes with
/// `mtp_round` (k+1-width verify, on-device accept, shadow commit). Arm S
/// (slot 0 after a state reset) runs the same generation with the head DEAD
/// and plain sequential decode. The trunk token streams must be BIT-IDENTICAL —
/// the verify/accept/commit machinery must reproduce sequential greedy exactly.
pub fn bench_mtp_exl3(a: &FwdArgs, depth: usize) -> Result<()> {
    let depth = depth.max(1);
    let model = FwdModel::load(&a.dir, 1, a.max_pos)?;
    let head = match model.mtp.as_ref() {
        Some(h) => h,
        None => bail!("pack has no mtp.* draft head — MTP probe unavailable"),
    };
    // scratch holds the VERIFY width m=k+1 (mtp_round asserts it); arm S's m=1
    // steps ride the same buffer fine.
    let mut sc = Scratch::new(&model.dev, &model.cfg, (depth + 1).max(2), model.cfg.rotary_dim)?;
    let prompt_ids = gate_prompt_ids(a)?;
    let plen = prompt_ids.len();
    println!("MTP end-to-end probe (exl3): prompt={plen} tokens, depth={depth}, max_new={} model={}",
             a.max_new, a.dir);

    // ---- Arm M: REAL chain-verify rounds (mtp_round) — the path the serve runs.
    // Token-by-token prefill writes sc (the true tap), one prime, then k+1-width
    // verify rounds. The lossless contract is actual == seq_tokens (arm S):
    // verify/accept/commit must reproduce sequential greedy bit-for-bit.
    // (The OLD arm M ran plain sequential decode with the head drafting alongside
    // and scored drafts post-hoc — it never executed the chain-verify round, so
    // "LOSSLESS_OK" proved only that priming does not perturb the trunk. That
    // same-class equivalence is exactly the §3 blind spot; bug 5 lived behind it.)
    // S-A3-x --mtp-cover=<L>: plain greedy FIRST (the true tokens), then per-round teacher-forced
    // head ranks at levels 1..L before each real round; CSV to --mtp-cover-out (default /tmp/mtp_cover.csv).
    let cover_l: usize = crate::opts::var(crate::opt!("mtp-cover")).ok().and_then(|v| v.parse().ok()).unwrap_or(0);
    let mut truth: Vec<u32> = Vec::new();
    let mut cover_rows: Vec<(usize, Vec<usize>, usize)> = Vec::new();
    if cover_l > 0 {
        let mut psc_t: Option<PrefillScratch> = None;
        model.reset_slot(0)?;
        model.prefill_prompt(&mut sc, &prompt_ids, a.prefill_chunk, &mut psc_t)?;
        truth.push(model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32);
        for k in 0..(a.max_new + cover_l + depth + 2) {
            let tok = truth[k] as i32;
            if EOS_IDS.contains(&tok) { break; }
            model.forward_step(&mut sc, &[tok], &[plen + k], &[0], None)?;
            truth.push(model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32);
        }
        model.reset_slot(0)?;
        println!("MTP_COVER: truth {} tokens, levels 1..={cover_l}", truth.len());
    }
    let mut actual: Vec<u32> = Vec::with_capacity(a.max_new);
    let t0 = std::time::Instant::now();
    // S-A3-t: --prefill-chunk C = the SERVED posture (chunked prompt[..n-1] + the last token
    // through forward_step) for BOTH arms — the only posture that exercises the head-KV fill.
    let mut psc_opt: Option<PrefillScratch> = None;
    model.prefill_prompt(&mut sc, &prompt_ids, a.prefill_chunk, &mut psc_opt)?;
    let pred0 = model.dev.dtoh_sync_copy(&sc.argmax)?[0];
    actual.push(pred0 as u32);
    // DIAG (--bmtp-diag=plain): run ONE plain forward_step consuming pred0 and
    // print its argmax — the col-0 ground truth — then restore state via reset+reprefill.
    if crate::opts::var(crate::opt!("bmtp-diag")).as_deref() == Ok("plain") {
        model.forward_step(&mut sc, &[pred0 as i32], &[plen], &[0], None)?;
        println!("DIAG plain-step argmax after pred0: {}",
                 model.dev.dtoh_sync_copy(&sc.argmax)?[0]);
        model.reset_slot(0)?;
        let mut pos = 0usize;
        for t in prompt_ids.iter() {
            model.forward_step(&mut sc, &[*t as i32], &[pos], &[0], None)?;
            pos += 1;
        }
    }
    // the serve's prime: snapshot the tap that predicted pred0, feed the head the
    // last prompt token with it (round 1's draft-extend reuses taps_keep[0]).
    if crate::opts::var(crate::opt!("bmtp-diag")).as_deref() != Ok("noprime") {
        let last_prompt = *prompt_ids.last().unwrap() as i32;
        model.mtp_seam_prime(&mut sc, psc_opt.as_ref(), head, last_prompt, plen, 0)?; // WP03
    } else {
        model.tap_snapshot(&mut sc, 0)?;
        println!("DIAG prime SKIPPED (noprime)");
    }
    let mut rounds: Vec<DraftRound> = Vec::new();
    let mut trunk_ms: Vec<f64> = Vec::new();
    let mut head_ms: Vec<f64> = Vec::new();
    {
        let mut b = pred0 as i32;
        let mut p = plen;
        let mut tap_row = 0usize;
        // S-A3-t: a first token that is EOS ends the request (the serve stops there; the plain arm
        // does too) — the MTP arm used to keep drafting past it.
        let first_eos = EOS_IDS.contains(&(pred0 as i32));
        while !first_eos && actual.len() < a.max_new {
            if cover_l > 0 {
                let off = p - plen;   // truth[off] = b (the token entering at p)
                if off + cover_l < truth.len() && truth[off] as i32 == b {
                    let tg: Vec<i32> = truth[off + 1..=off + cover_l].iter().map(|&x| x as i32).collect();
                    let r = model.mtp_cover(&mut sc, head, b, p, tap_row, &tg)?;
                    cover_rows.push((p, r, 0));
                }
            }
            let tt = std::time::Instant::now();
            let out = model.mtp_round(&mut sc, head, 0, depth, b, p, tap_row)?;
            if let Some(last) = cover_rows.last_mut() { if last.0 == p { last.2 = out.a; } }
            trunk_ms.push(tt.elapsed().as_secs_f64() * 1e3);
            for &e in out.emitted.iter() {
                actual.push(e as u32);
            }
            rounds.push(DraftRound { drafts: out.drafts, accepted: out.a });
            b = out.last_tok;
            p = out.pos_next;
            tap_row = out.tap_row;
            if EOS_IDS.contains(&b) { break; }
        }
    }
    // S-A3-f-d Item 1b FIX-3 companion: a round emits a+1 tokens (accepted +
    // bonus), so the chain can overshoot max_new. Trim to the requested horizon
    // — the lossless compare is exact-length by design.
    actual.truncate(a.max_new);
    let mtp_s = t0.elapsed().as_secs_f64();

    // ---- Arm S: same generation, head DEAD (state fully reset first) ----
    model.reset_slot(0)?;
    let mut seq_tokens: Vec<u32> = Vec::with_capacity(a.max_new);
    let t1 = std::time::Instant::now();
    model.prefill_prompt(&mut sc, &prompt_ids, a.prefill_chunk, &mut psc_opt)?;
    seq_tokens.push(model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32);
    for k in 0..a.max_new.saturating_sub(1) {
        let tok = seq_tokens[k] as i32;
        if EOS_IDS.contains(&tok) { break; }
        model.forward_step(&mut sc, &[tok], &[plen + k], &[0], None)?;
        seq_tokens.push(model.dev.dtoh_sync_copy(&sc.argmax)?[0] as u32);
    }
    let seq_s = t1.elapsed().as_secs_f64();

    // ---- acceptance scoring from the DEVICE accept count (out.a per round).
    // The chain round emits a variable number of tokens, so the old post-hoc
    // stream-index scoring (k+1+j) no longer applies; out.a is authoritative.
    let drafted = rounds.len() * depth;
    let accepted: usize = rounds.iter().map(|r| r.accepted).sum();
    let prefix_sum: usize = rounds.iter().map(|r| r.accepted).sum();
    let med = |v: &mut Vec<f64>| -> f64 {
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v.get(v.len() / 2).copied().unwrap_or(0.0)
    };
    let (tms, hms) = (med(&mut trunk_ms), med(&mut head_ms));
    let acc_pct = if drafted > 0 { 100.0 * accepted as f64 / drafted as f64 } else { 0.0 };
    let mean_prefix = if rounds.is_empty() { 0.0 } else { prefix_sum as f64 / rounds.len() as f64 };
    let mtp_tok_s = if mtp_s > 0.0 { actual.len() as f64 / mtp_s } else { 0.0 };
    let seq_tok_s = if seq_s > 0.0 { seq_tokens.len() as f64 / seq_s } else { 0.0 };
    println!("MTP tokens : {:?}", &actual[..actual.len().min(20)]);
    println!("SEQ tokens : {:?}", &seq_tokens[..seq_tokens.len().min(20)]);
    println!("acceptance rate: {:.1}%  (drafts accepted / total drafts, 1-ahead)  mean matched prefix {:.3}",
             acc_pct, mean_prefix);
    println!("trunk round (median) {tms:.1} ms   head draft x{depth} (median) {hms:.1} ms");
    println!("throughput: MTP {:.1} tok/s   sequential {:.1} tok/s", mtp_tok_s, seq_tok_s);

    if cover_l > 0 && !cover_rows.is_empty() {
        let path = crate::opts::var(crate::opt!("mtp-cover-out")).unwrap_or_else(|_| "/tmp/mtp_cover.csv".into());
        let mut csv = String::from("pos,accepted");
        for i in 1..=cover_l { csv += &format!(",r{i}"); }
        for i in 1..=cover_l { csv += &format!(",c{i}"); }
        csv.push('\n');
        for (p, r, acc) in &cover_rows {
            csv += &format!("{p},{acc}");
            for x in r { csv += &format!(",{}", if *x == usize::MAX { -1i64 } else { *x as i64 }); }
            csv.push('\n');
        }
        std::fs::write(&path, csv)?;
        let n = cover_rows.len() as f64;
        for lv in 0..cover_l {
            let hit = |j: usize| cover_rows.iter().filter(|(_, r, _)| r[lv] != usize::MAX && r[lv] < j).count() as f64 / n;
            let chain = cover_rows.iter().filter(|(_, r, _)| r[..=lv].iter().all(|&x| x == 0)).count() as f64 / n;
            println!("MTP_COVER level {}: top1 {:.3} top2 {:.3} top3 {:.3} top4 {:.3} | chain-prefix(all top1 to here) {:.3}",
                     lv + 1, hit(1), hit(2), hit(3), hit(4), chain);
        }
        println!("MTP_COVER: {} rounds -> {path}", cover_rows.len());
    }
    let lossless = actual == seq_tokens;
    if lossless {
        println!("RESULT: LOSSLESS_OK (MTP-primed output == plain greedy, {} tokens; exl3 path)",
                 actual.len());
        Ok(())
    } else {
        let div = actual.iter().zip(seq_tokens.iter()).position(|(a, b)| a != b);
        println!("RESULT: MISMATCH at token {:?} — head priming PERTURBS the trunk", div);
        if let Some(d) = div {
            let lo = d.saturating_sub(6);
            let hi = (d + 6).min(actual.len()).min(seq_tokens.len());
            println!("  ctx MTP[{}..{}]: {:?}", lo, hi, &actual[lo..hi]);
            println!("  ctx SEQ[{}..{}]: {:?}", lo, hi, &seq_tokens[lo..hi]);
        }
        std::process::exit(1);
    }
}

impl FwdModel {
    /// Host copy of the full logits scratch [W rows x vocab] - sampled serving lanes read
    /// their row from here (the device argmax path skips it).
    /// API-parity G2: stage per-row sampler params for the NEXT forward_step / mtp_round
    /// (row r = scratch row r). `None` rows are greedy. Must be called before every step
    /// whose rows differ from the last staged set; an all-greedy call after an all-greedy
    /// state is free (no upload).
    pub fn set_sampling(&self, sc: &mut Scratch, rows: &[Option<SampParams>]) -> Result<()> {
        let live = rows.iter().any(|r| r.is_some());
        if !live && !sc.samp_live {
            return Ok(());
        }
        let n = sc.samp.len();
        anyhow::ensure!(rows.len() * 8 <= n, "set_sampling: {} rows > scratch width {}", rows.len(), n / 8);
        let mut buf = vec![0u32; n];
        for (r, p) in rows.iter().enumerate() {
            if let Some(p) = p {
                buf[r * 8..r * 8 + 8].copy_from_slice(&p.pack());
            }
        }
        self.dev.htod_copy_into(buf, &mut sc.samp)?;
        sc.samp_live = live;
        Ok(())
    }

    /// WP24: `set_sampling` for an MTP round plus the real-q draft sampler. `rq = None` is
    /// exactly `set_sampling` (draft mode 0, match-rule verify: today's graphs) and clears every
    /// WP24 staging bit. Mode 2 stages the sampled rows with flag 2 (xq_sample_rows_rq: rows
    /// 0..m-2 judge their draft under min(1, p/q'), the bonus row samples p) and the draft params;
    /// mode 1 (--wp24-dump) keeps the match-rule rows and only adds the top-32 lists. The modes
    /// ride the draft / verify graph keys (rq_draft_key / rq_verify_key).
    pub fn set_spec_sampling(&self, sc: &mut Scratch, rows: &[Option<SampParams>],
                             rq: Option<RqStage>) -> Result<()> {
        let Some(rq) = rq else {
            sc.rq_mode = 0;
            sc.rq_live = false;
            sc.rq_dctr = 0;
            return self.set_sampling(sc, rows);
        };
        anyhow::ensure!(rq.mode == 1 || rq.mode == 2, "set_spec_sampling: mode {} (1 dump, 2 real-q)", rq.mode);
        anyhow::ensure!(rq.tau.is_finite() && rq.tau > 0.0, "set_spec_sampling: draft temperature {}", rq.tau);
        if rq.mode == 2 {
            let n = sc.samp.len();
            anyhow::ensure!(rows.len() * 8 <= n, "set_spec_sampling: {} rows > scratch width {}", rows.len(), n / 8);
            let mut buf = vec![0u32; n];
            for (r, p) in rows.iter().enumerate() {
                if let Some(p) = p {
                    // flag 2 = a real-q row (xq_sample_rows treats any non-zero flag as sampled)
                    buf[r * 8..r * 8 + 8].copy_from_slice(&p.pack_flag(2));
                }
            }
            self.dev.htod_copy_into(buf, &mut sc.samp)?;
            sc.samp_live = rows.iter().any(|r| r.is_some());
        } else {
            self.set_sampling(sc, rows)?;
        }
        let d = rq.pack();
        if d != sc.rq_dsamp_host {
            self.dev.htod_copy_into(d.to_vec(), &mut sc.rq_dsamp)?;
            sc.rq_dsamp_host = d;
        }
        sc.rq_mode = rq.mode;
        sc.rq_live = rq.mode == 2;
        sc.rq_dctr = rq.dctr as i32;
        Ok(())
    }

    /// WP15: stage per-row penalty params for the NEXT forward_step / mtp_round (row r = scratch
    /// row r, same contract as set_sampling). All-None after an all-None state is free.
    pub fn set_penalties(&self, sc: &mut Scratch, rows: &[Option<PenParams>]) -> Result<()> {
        let live = rows.iter().any(|r| r.is_some());
        if !live && !sc.pen_live {
            return Ok(());
        }
        let n = sc.pen.len();
        anyhow::ensure!(rows.len() * 8 <= n, "set_penalties: {} rows > scratch width {}", rows.len(), n / 8);
        let mut buf = vec![0u32; n];
        for (r, p) in rows.iter().enumerate() {
            if let Some(p) = p {
                buf[r * 8..r * 8 + 8].copy_from_slice(&p.pack());
            }
        }
        self.dev.htod_copy_into(buf, &mut sc.pen)?;
        sc.pen_live = live;
        sc.pen_mono = rows.iter().flatten().all(|p| p.monotone());
        Ok(())
    }

    /// WP15: seed `slot`'s penalty ring with the committed prompt positions 0..toks.len() (the
    /// chunk-prefilled prompt[..plen-1]; the seam step commits the last prompt token itself).
    /// Only the tail the largest window can reach is written.
    pub fn pen_seed(&self, sc: &mut Scratch, slot: usize, toks: &[u32]) -> Result<()> {
        anyhow::ensure!((slot + 1) * PEN_RING <= sc.pen_hist.len(),
                        "pen_seed: slot {slot} outside the scratch penalty ring");
        let mut ring = vec![0i32; PEN_RING];
        let from = toks.len().saturating_sub(PEN_RING - 64);
        for (p, &t) in toks.iter().enumerate().skip(from) {
            ring[p & (PEN_RING - 1)] = t as i32;
        }
        let mut dst = sc.pen_hist.slice_mut(slot * PEN_RING..(slot + 1) * PEN_RING);
        self.dev.htod_sync_copy_into(&ring, &mut dst)?;
        Ok(())
    }

    pub fn logits_host(&self, sc: &Scratch) -> Result<Vec<u16>> {
        Ok(self.dev.dtoh_sync_copy(&sc.logits)?)
    }

    /// TP-C (G-T1-b graphed): FNV-64 digests of the replicated outputs the last step / round left
    /// in the scratch — each of the first `rows` logits rows, the whole residual (the tap class)
    /// and the whole taps window — to be compared across ranks. Syncs + dtoh: harness only.
    pub fn tp_ident_digests(&self, sc: &Scratch, rows: usize) -> Result<Vec<u64>> {
        self.dev.synchronize()?;
        let fnv = |it: &mut dyn Iterator<Item = u32>| -> u64 {
            let mut h = 0xcbf2_9ce4_8422_2325u64;
            for w in it { h ^= w as u64; h = h.wrapping_mul(0x0000_0100_0000_01b3); }
            h
        };
        let v = self.cfg.vocab_size;
        // TP-H #4: under the vocab-parallel greedy tail the logits are per-rank SHARDS (not
        // replicated); the replicated output of the tail is the merged key row (value + global id)
        // and the ids — digest those instead.
        let mut out: Vec<u64> = if self.vp_greedy(sc, rows) {
            let ks = self.dev.dtoh_sync_copy(&sc.vp_keys)?;
            let ids = self.dev.dtoh_sync_copy(&sc.argmax)?;
            (0..rows.min(16)).map(|r| fnv(&mut [ks[r] as u32, (ks[r] >> 32) as u32, ids[r] as u32].into_iter())).collect()
        } else {
            let lg = self.dev.dtoh_sync_copy(&sc.logits)?;
            (0..rows.min(lg.len() / v))
                .map(|r| fnv(&mut lg[r * v..(r + 1) * v].iter().map(|&x| x as u32))).collect()
        };
        let rs = self.dev.dtoh_sync_copy(&sc.resid)?;
        out.push(fnv(&mut rs.iter().map(|x| x.to_bits())));
        let tk = self.dev.dtoh_sync_copy(&sc.taps_keep)?;
        out.push(fnv(&mut tk.iter().map(|x| x.to_bits())));
        Ok(out)
    }

    pub fn dev(&self) -> &Arc<CudaDevice> { &self.dev }
    /// S-A3-e serve fix: zero this slot's conv + GDN recurrent state rows and the host
    /// PLE n-gram ring. Finished lanes left state behind and the next request on the slot
    /// inherited it (request 1 exact, later requests drift). k_cache needs no reset
    /// (write-before-read per position).
    pub fn reset_slot(&self, slot: usize) -> Result<()> {
        self.reset_slot_ex(slot, false)
    }

    /// PFX1 (b): `reset_slot` for a slot whose next use is a CHUNKED prefill from position 0
    /// (the serve's fresh-prompt admit). With the head fill on (--exl3-head-fill != 0) the
    /// slot's head-KV memset (1.07 GB f32 / 0.28 GB q8 at a 262K window) is skipped: every
    /// head-KV row a draft pass can READ is written by this request before it is read —
    ///   rows 0..plen-2   head_fill_rows (every prefill chunk, the full row incl. q8 scales),
    ///   row  plen-1      the seam prime (mtp_seam_prime: head_kv_rows, or head_prime),
    ///   row  p (round)   draft pass 0 writes (xq_attn_prep) before its attention, or the
    ///                    control round's mtp_plain_prime; rows p+1.. the chain's own passes;
    ///   accepted rows    rewritten by the re-prime (device path: rows < a only);
    /// and every head-attention kernel reads positions 0..=p only (xq_attn_dense_splitk4 t < p+1,
    /// xq_attn_softmax / xq_attn_scan t <= p, QSA selections <= p). Stale rows > p are never read.
    /// The one-time zero at load stays. Bench/probe callers keep `reset_slot` (their token-by-
    /// token prefill has no head fill), as does the boot warm-up.
    pub fn reset_slot_for_prefill(&self, slot: usize) -> Result<()> {
        self.reset_slot_ex(slot, pfx1_on(PFX1_HEADKV) && head_fill_on())
    }

    fn reset_slot_ex(&self, slot: usize, skip_head_kv: bool) -> Result<()> {
        let cfg = &self.tc; // TP-B: the trunk's per-rank geometry
        let per_conv = (cfg.key_dim() * 2 + cfg.value_dim()) * cfg.conv_kernel;
        let per_s = cfg.lin_num_v_heads * cfg.lin_k_dim * cfg.lin_v_dim;
        let l = Launcher { dev: &self.dev, stream: &self.stream };
        let grid = |n: usize| (((n + 255) / 256) as u32, 1, 1);
        for cs in &self.conv_state {
            let n = per_conv as i64;
            xqlaunch!(l, "xq_memset_f32", grid(per_conv), (256, 1, 1), 0,
                      (cs, (slot as i64) * n, n))?;
        }
        for ss in &self.s_state {
            let n = per_s as i64;
            xqlaunch!(l, "xq_memset_f32", grid(per_s), (256, 1, 1), 0,
                      (ss, (slot as i64) * n, n))?;
        }
        // S-A3-f-d: the M1 head's own KV must reset with the slot — the chain-verify
        // draft steps attend the head window [0..pos], and stale entries from the
        // previous request on this slot would poison the draft history (harmless to
        // losslessness — verify rejects — but they drift acceptance round to round).
        if let Some(head) = &self.mtp {
            let per = (head.kv.len() / self.width / 4) as i64; // f32 words (row bytes are % 16)
            if !skip_head_kv {
                xqlaunch!(l, "xq_memset_f32", grid(per as usize), (256, 1, 1), 0,
                          (&head.kv, (slot as i64) * per, per))?;
            } else if pfx1_headkv_poison() {
                // PFX1 (b) gate: NaN-poison the slot's head KV instead of zeroing it — 0x7FC0 is a
                // NaN as f16 (q8 scales), as f32 (0x7FC07FC0) and in the fp8 value/scale bytes, so a
                // draft pass that ever READ a row this request did not write would go NaN and move
                // drafted/accepted. Hashes + drafted/accepted identical to --pfx1-off=headkv
                // prove the invariant on the served path.
                let n = per * 2; // u16 elements
                xqlaunch!(l, "xq_memset_u16", grid(n as usize), (256, 1, 1), 0,
                          (*head.kv.device_ptr() as u64 + (slot as u64) * (per as u64) * 4, n, 0x7FC0i32))?;
            }
        }
        // S-A3-e FIX: reset ONLY the admitted slot's ring pair - the whole-ring reset wiped
        // the state of lanes already decoding in other slots.
        {
            let mut h = self.ple_hist.lock().unwrap();
            h[slot * 2] = 248046i32;
            h[slot * 2 + 1] = 248046i32;
        }
        // PLE device-side conv ring ([W*10240*9] f16, rolled per step, SLOT-indexed as of
        // this build): zero only this slot's row. Zero f16 == 0x0000; row is even-sized.
        {
            let n = (10240 * 9 / 2) as i64;
            let start = (slot as i64) * n;
            xqlaunch!(l, "xq_memset_f32", grid(46080), (256, 1, 1), 0,
                      (*self.ple_state.device_ptr() as u64, start, n))?;
        }
        Ok(())
    }

    /// Prefix cache: copy slot's recurrent state (+ the head-fill carry in `psc`) into its
    /// snapshot. Device copies on the compute stream: bit-exact.
    pub fn snapshot_slot(&self, slot: usize, psc: &PrefillScratch) -> Result<()> {
        self.copy_slot_state(slot, psc, true)
    }
    /// Prefix cache: restore slot's recurrent state (+ carry into `psc`) from its snapshot.
    pub fn restore_slot(&self, slot: usize, psc: &mut PrefillScratch) -> Result<()> {
        self.copy_slot_state(slot, psc, false)
    }
    pub fn prefix_snapshots(&self) -> bool { self.snap.is_some() }
    fn copy_slot_state(&self, slot: usize, psc: &PrefillScratch, save: bool) -> Result<()> {
        let snap = self.snap.as_ref().context("prefix snapshots not allocated")?;
        let cfg = &self.tc; // TP-B: the trunk's per-rank geometry
        let l = Launcher { dev: &self.dev, stream: &self.stream };
        let grid = |n: usize| ((((n as u64) + 255) / 256) as u32, 1, 1);
        let per_conv = (cfg.key_dim() * 2 + cfg.value_dim()) * cfg.conv_kernel;
        let per_s = cfg.lin_num_v_heads * cfg.lin_k_dim * cfg.lin_v_dim;
        let rw = cfg.hc_count.max(1) * cfg.hidden_size;
        let mut cp = |live: u64, sn: u64, n: usize| -> Result<()> {
            let off = (slot * n) as i64;
            let (dst, src) = if save { (sn, live) } else { (live, sn) };
            xqlaunch!(l, "xq_copy_f32", grid(n), (256, 1, 1), 0, (dst, src, n as i64, off, off))?;
            Ok(())
        };
        for (lv, sv) in self.conv_state.iter().zip(snap.conv.iter()) {
            cp(*lv.device_ptr() as u64, *sv.device_ptr() as u64, per_conv)?;
        }
        for (lv, sv) in self.s_state.iter().zip(snap.s.iter()) {
            cp(*lv.device_ptr() as u64, *sv.device_ptr() as u64, per_s)?;
        }
        // PLE f16 ring row = 10240*9 halves = 46080 f32 words
        cp(*self.ple_state.device_ptr() as u64, *snap.ple.device_ptr() as u64, 10240 * 9 / 2)?;
        // head-fill carry: psc holds ONE carry (the slot being prefilled); the snapshot keeps one per slot
        {
            let (dst, src, doff, soff) = if save {
                (*snap.carry.device_ptr() as u64, *psc.hfill_carry.device_ptr() as u64, (slot * rw) as i64, 0i64)
            } else {
                (*psc.hfill_carry.device_ptr() as u64, *snap.carry.device_ptr() as u64, 0i64, (slot * rw) as i64)
            };
            if psc.hfill_carry.len() >= rw {
                xqlaunch!(l, "xq_copy_f32", grid(rw), (256, 1, 1), 0, (dst, src, rw as i64, doff, soff))?;
            }
        }
        let mut live = self.ple_hist.lock().unwrap();
        let mut sh = snap.hist.lock().unwrap();
        if save { sh[slot * 2] = live[slot * 2]; sh[slot * 2 + 1] = live[slot * 2 + 1]; }
        else { live[slot * 2] = sh[slot * 2]; live[slot * 2 + 1] = sh[slot * 2 + 1]; }
        Ok(())
    }

    /// Argmax ids of the last forward_step, read back to host (serve prefill uses this
    /// to capture the first generated token).
    pub fn argmax_host(&self, sc: &Scratch) -> Result<Vec<u32>> {
        let v = self.dev.dtoh_sync_copy(&sc.argmax)?;
        Ok(v.iter().map(|&x| x as u32).collect())
    }
    pub fn max_pos(&self) -> usize { self.max_pos }
    /// Host bytes held by the RAM-resident PLE n-gram table ([ple-ram], see ple_ram_load);
    /// 0 when the table is read through the page cache (pread) or the model has no PLE. These are
    /// ordinary host Vec pages — invisible to nvidia-smi — but on GB10 they come out of the same
    /// unified pool cuMemGetInfo reports, so they are part of a load's measured footprint.
    pub fn ple_ram_bytes(&self) -> u64 {
        self.ple.as_ref().and_then(|p| p.ram.as_ref())
            .map(|r| r.iter().map(|v| v.len() as u64).sum()).unwrap_or(0)
    }
    /// PLE n-gram table residency label for receipts: "on" (RAM-resident), "pread" (page cache),
    /// or "none" (the model has no PLE).
    pub fn ple_residency(&self) -> &'static str {
        match self.ple.as_ref() {
            None => "none",
            Some(p) if p.ram.is_some() => "on",
            Some(_) => "pread",
        }
    }

    /// S-A3-f-g: staging size (u16 elements) for the prefill reconstruct path —
    /// the largest trunk dense matrix the wide-M arm will dequant per call.
    /// lm_head is excluded (it only ever runs at m=1 in prefill and stays trellis).
    pub fn recon_staging_elems(&self) -> usize {
        let mut mx = 0usize;
        let mut scan = |q: &Quad| mx = mx.max(q.k as usize * q.n as usize);
        for l in &self.layers {
            match &l.mixer {
                Mixer::Gdn(g) => { scan(&g.in_qkv); scan(&g.in_z); scan(&g.out_proj); }
                Mixer::Attn(a) => { scan(&a.q_proj); scan(&a.k_proj); scan(&a.v_proj); scan(&a.o_proj); }
            }
            scan(&l.moe.sh_gate);
            scan(&l.moe.sh_up);
            scan(&l.moe.sh_down);
        }
        mx
    }

    /// S-A3-f-g: build the reconstruct-path buffer handles for this prefill scratch.
    fn recon_bufs(&self, psc: &PrefillScratch) -> ReconBufs {
        ReconBufs {
            ws: *psc.recon_ws.device_ptr() as u64,
            ws_len: psc.recon_ws.len(),
            rc: *self.rc_lut.device_ptr() as u64,
            ltws: *psc.lt_ws.device_ptr() as u64,
            ltws_len: psc.lt_ws.len(),
        }
    }

    /// Scratch constructor for the serve backend (fields stay private to this module).
    pub fn scratch(dev: &Arc<CudaDevice>, cfg: &crate::qwen::Config, w: usize) -> Result<Scratch> {
        Scratch::new(dev, cfg, w, cfg.rotary_dim)
    }
}

// ===========================================================================
// S-A3-f-b: CHUNKED PREFILL. Process C consecutive tokens of ONE slot in one
// sweep: weight ops at M=C rows (wide-M GEMM), recurrences looped inside the
// chunk kernels. Prefill sits OUTSIDE the batch-invariance contract (same rule
// as the NVFP4 line's prefill); the ladder gate measures drift vs the
// sequential decode-step path on real chunks.
// ===========================================================================

// ---------------------------------------------------------------------------
// WP18 rung A (PLAN/SURPASS_PLAN_2026-09-26.md): bounded prefill QSA selection, bitwise.
// The old path scored every (sparse row, visible block) of a chunk into a [c][max_pos/ratio] f32
// matrix (qsa_score_prefill_b; 0.54 GB at C = 2048 on a 262K window) and ran xq_qsa_topk_asc per
// row. WP18 walks each group of `rows` sparse rows over tiles of WP18_T blocks: xq_wp18_score
// fills a [rows][WP18_T] slab with the SAME score bits, xq_wp18_merge folds the tile into each
// row's carried top-K list under the same total order (key desc, block asc) and emits the
// ascending selection list on the row's last tile (kernel notes: kernels/exl3_bench.cu, 3c).
// --wp18-off=1 = the old path; --wp18-xcheck=1 = run both, diff lists + score bits
// (eager); --wp18-rows = slab rows per group (default 256, multiple of 32, 32..2048).
// ---------------------------------------------------------------------------
pub(crate) const WP18_T: usize = 8192;     // kernels/exl3_bench.cu WP18_T (slab row pitch)
pub(crate) const WP18_TM: usize = 32;      // WP18_TM (rows per scorer CTA)
pub(crate) const WP18_TN: usize = 64;      // WP18_TN (blocks per scorer CTA)
pub(crate) const WP18_MT: usize = 512;     // WP18_MT (merge threads)
pub(crate) const WP18_KMAX: usize = 512;   // WP18_KMAX (carried-list capacity)

fn wp18_off() -> bool {
    static V: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *V.get_or_init(|| wp14_xcheck(crate::opt!("wp18-off")))
}
fn wp18_xcheck() -> bool {
    static V: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *V.get_or_init(|| wp14_xcheck(crate::opt!("wp18-xcheck")))
}
pub(crate) fn wp18_rows() -> usize {
    static V: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *V.get_or_init(|| {
        let r = crate::opts::var(crate::opt!("wp18-rows")).ok().and_then(|v| v.parse::<usize>().ok()).unwrap_or(256);
        (r.clamp(WP18_TM, 2048) / WP18_TM) * WP18_TM
    })
}

/// One launch pair of the WP18 walk: row group [g0, g0+gn) of the sparse rows (first position
/// pos_first), tile kt. score_grid.0 == 0: no block of the tile is visible (only when the group's
/// widest row has nb == 0 — the merge still runs to emit tail-only lists).
#[derive(Clone, Copy, Debug)]
pub(crate) struct Wp18Step {
    pub g0: usize,
    pub gn: usize,
    pub pos_first: usize,
    pub kt: usize,
    pub score_grid: (u32, u32),
}

/// The WP18 walk for `rows` consecutive sparse rows starting at position `pos_first0`: row groups
/// of `rg`, each over tiles 0..ceil(nb_max / WP18_T) in ascending order (the merge's contract).
pub(crate) fn wp18_plan(pos_first0: usize, rows: usize, ratio: usize, rg: usize) -> Vec<Wp18Step> {
    let mut v = Vec::new();
    let mut g0 = 0;
    while g0 < rows {
        let gn = rg.min(rows - g0);
        let pos_first = pos_first0 + g0;
        let nb_max = (pos_first + gn) / ratio;             // the group's last (widest) row
        let nt = nb_max.div_ceil(WP18_T).max(1);
        for kt in 0..nt {
            let tb = nb_max.saturating_sub(kt * WP18_T).min(WP18_T);
            let gx = tb.div_ceil(WP18_TN) as u32;
            v.push(Wp18Step { g0, gn, pos_first, kt, score_grid: (gx, if gx > 0 { gn.div_ceil(WP18_TM) as u32 } else { 0 }) });
        }
        g0 += gn;
    }
    v
}

#[cfg(test)]
mod wp18_tests {
    use super::*;

    /// wp18_plan is the SPEC the walk implements: row groups of `rg` in ascending order, each over
    /// the ascending 8,192-block tile ladder 0..ceil(nb_max / T); score_grid sizes the
    /// xq_wp18_score CTA grid ((ceil(tb / TN), ceil(gn / TM)); (0, 0) only when the group's widest
    /// row has nb == 0 — the merge still runs to emit tail-only lists). The merge's carried-list
    /// contract (a row's tile kt may read the list only after tile kt - 1 wrote it) needs the FULL
    /// ladder per group. (The GPU side is checked by --probe-exl3-binv / --wp18-xcheck on the box.)
    #[test]
    fn wp18_plan_groups_and_tiles_cover() {
        for &(pos0, rows, ratio, rg) in &[
            (8_189usize, 77usize, 4usize, 256usize), // odd tail chunk past the dense limit
            (0, 2048, 4, 256),                       // whole-chunk sparse rows, default groups
            (126_976, 2048, 4, 2048),                // 128K window end, one wide group (4 tiles)
            (3, 5, 8, 32),                           // rg floor, ratio > rows
            (0, 1, 4, 2048),                         // single row, nb == 0 (merge-only step)
        ] {
            let v = wp18_plan(pos0, rows, ratio, rg);
            let (mut next, mut i) = (0usize, 0usize);
            while i < v.len() {
                let g0 = v[i].g0;
                let gn = rg.min(rows - g0);
                assert_eq!(g0, next, "pos0={pos0} rows={rows} rg={rg}: group starts at {g0}, want {next}");
                let pos_first = pos0 + g0;
                let nb_max = (pos_first + gn) / ratio;
                let nt = nb_max.div_ceil(WP18_T).max(1);
                let kts: Vec<usize> = v[i..i + nt].iter().map(|s| s.kt).collect();
                assert_eq!(kts, (0..nt).collect::<Vec<_>>(),
                    "pos0={pos0} rows={rows} rg={rg}: tiles of group {g0} not the ascending ladder 0..{nt}");
                for k in 0..nt {
                    let s = &v[i + k];
                    assert_eq!((s.g0, s.gn, s.pos_first), (g0, gn, pos_first));
                    let tb = nb_max.saturating_sub(k * WP18_T).min(WP18_T);
                    let gx = tb.div_ceil(WP18_TN) as u32;
                    let gy = if gx > 0 { gn.div_ceil(WP18_TM) as u32 } else { 0 };
                    assert_eq!(s.score_grid, (gx, gy), "pos0={pos0} rows={rows} rg={rg} kt={k}");
                    assert!(gx > 0 || nb_max == 0, "pos0={pos0} rows={rows} rg={rg} kt={k}: gx == 0 with visible blocks");
                }
                i += nt;
                next = g0 + gn;
            }
            assert_eq!(next, rows, "pos0={pos0} rows={rows} rg={rg}: groups cover {next} rows");
        }
    }
}

/// WP18 buffers of one PrefillScratch: [rows][WP18_T] slab + [rows][topk] carried lists, and the
/// XCHECK reference lists/counters.
pub(crate) struct Wp18Scratch {
    rows: usize,
    slab: CudaSlice<f32>,
    ck: CudaSlice<u32>,
    ci: CudaSlice<i32>,
    x: Option<(CudaSlice<i32>, CudaSlice<i32>, CudaSlice<i32>)>,
}

impl Wp18Scratch {
    fn new(m: &FwdModel, c: usize) -> Result<Option<Self>> {
        let cfg = &m.cfg;
        let ratio = cfg.indexer_compress_ratio;
        let topk = if ratio > 0 { cfg.indexer_budget / ratio } else { 0 };
        // shape contract of the kernels + the diagnostics that read the full matrix
        let why_not = if wp18_off() { Some("--wp18-off") }
            else if !cfg.has_indexer() { Some("no indexer") }
            else if cfg.indexer_head_dim != 128 || cfg.indexer_n_heads != 4 { Some("indexer shape != hd 128 x 4 heads") }
            else if ratio == 0 || topk == 0 || topk > WP18_KMAX { Some("topk outside 1..=512") }
            else if m.qsa_dbg.is_some() { Some("--qsa-dump-layer reads the full matrix") }
            else if crate::opts::var(crate::opt!("prefillx-qsa-keys")).is_ok() { Some("--prefillx-qsa-keys reads the full matrix") }
            else { None };
        let nblk_stride = (m.max_pos / ratio.max(1)).max(1);
        static ONCE: std::sync::Once = std::sync::Once::new();
        if let Some(w) = why_not {
            ONCE.call_once(|| println!("WP18: bounded prefill selection OFF ({w}) — [c][max_pos/ratio] score matrix"));
            return Ok(None);
        }
        let rows = wp18_rows().min(c.max(1));
        let dev = &m.dev;
        let x = if wp18_xcheck() {
            Some((dev.alloc_zeros::<i32>(c * (cfg.indexer_budget + ratio))?, dev.alloc_zeros::<i32>(c)?,
                  dev.alloc_zeros::<i32>(4)?))
        } else { None };
        ONCE.call_once(|| println!("WP18: bounded prefill selection ON — slab {rows} x {WP18_T} f32 ({:.1} MB) + carried \
                                    top-{topk} lists ({:.1} MB) replace the [c][{nblk_stride}] matrix ({:.1} MB at c = {c}){}",
                                   (rows * WP18_T * 4) as f64 / 1e6, (rows * topk * 8) as f64 / 1e6,
                                   (c * nblk_stride * 4) as f64 / 1e6,
                                   if x.is_some() { "; --wp18-xcheck: the old matrix is kept as the reference" } else { "" }));
        Ok(Some(Wp18Scratch {
            rows,
            slab: dev.alloc_zeros::<f32>(rows * WP18_T)?,
            ck: dev.alloc_zeros::<u32>(rows * topk)?,
            ci: dev.alloc_zeros::<i32>(rows * topk)?,
            x,
        }))
    }
}

/// C-row scratch for the chunked prefill sweep (separate from the decode
/// `Scratch`, which is width-scaled for serving lanes; the compact MoE row
/// lists make the per-expert buffers O(C*topk), not O(E*C)).
pub struct PrefillScratch {
    pub c: usize,
    sids: CudaSlice<i32>,
    // per-row activation buffers ([C, ...])
    resid: CudaSlice<f32>,
    hn: CudaSlice<u16>,
    dd: CudaSlice<u16>,
    uu: CudaSlice<u16>,
    inj: CudaSlice<f32>,
    x: CudaSlice<u16>,
    x_last: CudaSlice<u16>, // row C-1 copy for the final lm_head chain
    // S-A3-t: MTP-head KV fill over the prompt (allocated only when a draft head exists):
    // shifted trunk streams / embed streams (f32 [c][hc*h]), the two fc outputs (f16 [c][hc*h]),
    // and the carry = trunk streams of the previous chunk's last row (f32 [hc*h]).
    hfill_s: CudaSlice<f32>,
    hfill_a: CudaSlice<u16>,
    hfill_b: CudaSlice<u16>,
    hfill_carry: CudaSlice<f32>,
    // S-A3-u D: device-side MoE routing — tile list [(expert, super-row)] + its length, the
    // identity expert map, per-expert trellis offsets, and the identity row map (down side).
    pf_tiles: CudaSlice<i32>,
    /// A5-P1 WP19: 4 per-MT-class tile lists (stride = the single list's capacity) + counts.
    pf_tiles4: CudaSlice<i32>,
    pf_ntiles4: CudaSlice<i32>,
    pf_ntiles: CudaSlice<i32>,
    pf_ident: CudaSlice<i32>,
    pf_offs_gu: CudaSlice<u64>,
    pf_offs_d: CudaSlice<u64>,
    pf_dident: CudaSlice<i32>,
    chain_xh: CudaSlice<u16>,
    chain_yraw: CudaSlice<u16>,
    // S-A3-f-f: split-K workspace for the ks arm — the DECODE branch DOES run here
    // when a final chunk has <= 16 rows (see prefill_scratch sizing note).
    chain_ws: CudaSlice<f32>,
    // S-A3-f-g: reconstruct staging (largest trunk dense matrix, f16, written
    // whole by exl3_decode_dump before any read) + cuBLASLt workspace.
    recon_ws: CudaSlice<u16>,
    lt_ws: CudaSlice<u8>,
    qkv: CudaSlice<u16>,
    qg: CudaSlice<u16>,
    kp: CudaSlice<u16>,
    vp: CudaSlice<u16>,
    zbuf: CudaSlice<u16>,
    a_out: CudaSlice<u16>,
    b_out: CudaSlice<u16>,
    core: CudaSlice<u16>,
    normed: CudaSlice<u16>,
    mixer_out: CudaSlice<u16>,
    logits_r: CudaSlice<f32>,
    ids: CudaSlice<i32>,
    wts: CudaSlice<f32>,
    idxmap: CudaSlice<i32>,
    moe_out: CudaSlice<u16>,
    sh1: CudaSlice<u16>,
    sh2: CudaSlice<u16>,
    ysh: CudaSlice<u16>,
    cos: CudaSlice<f32>,
    toks: CudaSlice<i32>,
    // compact MoE buffers ([R = C*topk, ...]) + row lists
    xh_e: CudaSlice<u16>,
    ygu_raw: CudaSlice<u16>,
    ygu: CudaSlice<u16>,
    din: CudaSlice<u16>,
    xhd: CudaSlice<u16>,
    yd_raw: CudaSlice<u16>,
    yd: CudaSlice<u16>,
    offs_gu: CudaSlice<u64>,
    offs_d: CudaSlice<u64>,
    // TP-B: expert-parallel prefill — the chunk's routed ids in this rank's LOCAL expert space
    // (-1 = remote), [c * topk]
    ids_ep: CudaSlice<i32>,
    row_tok: CudaSlice<i32>,
    row_eidx: CudaSlice<i32>,
    cand: CudaSlice<i32>,
    offs_row: CudaSlice<i32>,
    cnt: CudaSlice<i32>,
    moerows: CudaSlice<i32>,
    // PLE
    ple_emb: CudaSlice<u16>,
    ple_key16: CudaSlice<u16>,
    ple_val: CudaSlice<u16>,
    ple_kn: CudaSlice<f32>,
    ple_qn: CudaSlice<f32>,
    ple_gated: CudaSlice<u16>,
    ple_normed: CudaSlice<u16>,
    // S-A3-i QSA prefill pipes (row-range [t0, c) of a chunk rides the selection path)
    qsa_qk: CudaSlice<u16>,      // [c][640] f16 indexer projection
    qsa_qkb: CudaSlice<u16>,     // [c][640] bf16
    qsa_blocks: CudaSlice<u16>,  // [nblk][128] bf16 pooled block keys
    qsa_scores: CudaSlice<f32>,  // [c][nblk_stride] (WP18 on: empty unless --wp18-xcheck)
    qsa_sel: CudaSlice<i32>,     // [c][sel_max]
    qsa_psel: CudaSlice<i32>,    // [c]
    // WP18 rung A: bounded prefill selection (None = the full-matrix path)
    wp18: Option<Wp18Scratch>,
    pos_rows: CudaSlice<i32>,    // [c] logical positions (pos0 + i)
    // VIS-2: the image request being prefilled (None = text): its merged image embeddings
    // [n_img][hidden] (fp16-rounded f32) and, per prompt position, the image row it takes (-1 = a
    // token embedding); vis_rows [c] is the per-chunk upload of that map for xq_splice_rows.
    pub vis_img: Option<CudaSlice<f32>>,
    pub vis_src: Vec<i32>,
    vis_rows: CudaSlice<i32>,
    slot_rows: CudaSlice<i32>,   // [c] slot ids
    slotpos_rows: CudaSlice<i32>,// [c][2] (slot, pos) for prep/splitk
    qstage: CudaSlice<f32>,      // [c][nh][hd]
    qsa_pm: CudaSlice<f32>,      // [c*nh*QSA_SPLITS]
    qsa_pl: CudaSlice<f32>,
    qsa_pacc: CudaSlice<f32>,    // [c*nh*QSA_SPLITS*hd]
    pub logits: CudaSlice<u16>,
    argmax: CudaSlice<i32>,
    // WP05: pinned prologue tables + PLE rows (None = pre-WP05 htod_sync_copy path)
    wp05: Option<Wp05PfStage>,
    // TP-I2 item 1: the MoE reduce's rows-landed hook (set by prefill_chunk around moe_prefill) and
    // whether the EP combine's reduce ran it (then the next hc_pre skips its inject+norm)
    pf_hook: Option<xtp::PfHook>,
    pf_hooked: bool,
    // TP-SP: this rank's row block while a sequence-parallel chunk's MoE runs (set by prefill_chunk
    // around moe_prefill: the EP combine then reduce-SCATTERS into the own rows)
    sp_rows: Option<xtp::SpRows>,
}

impl FwdModel {
    pub fn prefill_scratch(&self, c: usize) -> Result<PrefillScratch> {
        let cfg = &self.cfg;
        let dev = &self.dev;
        let h = cfg.hidden_size;
        let hc = cfg.hc_count.max(1);
        let lr = cfg.hc_lowrank;
        let rw = h * hc;
        let v = cfg.vocab_size;
        let topk = cfg.num_experts_per_tok;
        let r = c * topk;
        let qsa_on = cfg.has_indexer();
        let nblk_stride = (self.max_pos / cfg.indexer_compress_ratio).max(1);
        let sel_max = cfg.indexer_budget + cfg.indexer_compress_ratio;
        let hf = if self.mtp.is_some() { c * rw } else { 1 };
        let ne = cfg.num_experts;
        let (gu_w, d_w) = self.layers.first().map(|ly| (ly.moe.gu_words, ly.moe.d_words)).unwrap_or((0, 0));
        let pf_same = gu_w > 0 && self.layers.iter().all(|ly| ly.moe.gu_words == gu_w && ly.moe.d_words == d_w);
        let max_tiles = r / 16 + ne;
        let wp18 = if qsa_on { Wp18Scratch::new(self, c)? } else { None };
        Ok(PrefillScratch {
            c,
            pf_tiles: dev.alloc_zeros::<i32>(if pf_same { 2 * max_tiles } else { 1 })?,
            pf_ntiles: dev.alloc_zeros::<i32>(1)?,
            pf_tiles4: dev.alloc_zeros::<i32>(if pf_same { 8 * max_tiles } else { 1 })?,
            pf_ntiles4: dev.alloc_zeros::<i32>(4)?,
            pf_ident: dev.htod_sync_copy(&(0..ne as i32).collect::<Vec<i32>>())?,
            pf_offs_gu: dev.htod_sync_copy(&(0..ne as u64).map(|e| e * gu_w).collect::<Vec<u64>>())?,
            pf_offs_d: dev.htod_sync_copy(&(0..ne as u64).map(|e| e * d_w).collect::<Vec<u64>>())?,
            pf_dident: dev.htod_sync_copy(&(0..r as i32).collect::<Vec<i32>>())?,
            hfill_s: dev.alloc_zeros::<f32>(hf)?,
            hfill_a: dev.alloc_zeros::<u16>(hf)?,
            hfill_b: dev.alloc_zeros::<u16>(hf)?,
            hfill_carry: dev.alloc_zeros::<f32>(if self.mtp.is_some() { rw } else { 1 })?,
            sids: dev.htod_sync_copy(&vec![0i32, 0i32])?,
            qsa_qk: dev.alloc_zeros::<u16>(c * if qsa_on { (cfg.indexer_n_heads + 1) * cfg.indexer_head_dim } else { 0 })?,
            qsa_qkb: dev.alloc_zeros::<u16>(c * if qsa_on { (cfg.indexer_n_heads + 1) * cfg.indexer_head_dim } else { 0 })?,
            qsa_blocks: dev.alloc_zeros::<u16>(if qsa_on { nblk_stride * cfg.indexer_head_dim } else { 0 })?,
            // WP18: the [c][nblk_stride] score matrix (0.54 GB at C = 2048 / 262K) exists only on the
            // old path, or as the XCHECK reference.
            qsa_scores: dev.alloc_zeros::<f32>(c * if qsa_on && (wp18.is_none() || wp18_xcheck()) { nblk_stride } else { 0 })?,
            qsa_sel: dev.alloc_zeros::<i32>(c * if qsa_on { sel_max } else { 0 })?,
            qsa_psel: dev.alloc_zeros::<i32>(c)?,
            wp18,
            pos_rows: dev.alloc_zeros::<i32>(c)?,
            vis_img: None,
            vis_src: Vec::new(),
            vis_rows: dev.alloc_zeros::<i32>(c)?,
            slot_rows: dev.alloc_zeros::<i32>(c)?,
            slotpos_rows: dev.alloc_zeros::<i32>(c * 2)?,
            qstage: dev.alloc_zeros::<f32>(c * cfg.num_heads * cfg.head_dim)?,
            qsa_pm: dev.alloc_zeros::<f32>(c * cfg.num_heads * QSA_SPLITS)?,
            qsa_pl: dev.alloc_zeros::<f32>(c * cfg.num_heads * QSA_SPLITS)?,
            qsa_pacc: dev.alloc_zeros::<f32>(c * cfg.num_heads * QSA_SPLITS * cfg.head_dim)?,
            resid: dev.alloc_zeros::<f32>(c * rw)?,
            hn: dev.alloc_zeros::<u16>(c * rw)?,
            dd: dev.alloc_zeros::<u16>(c * lr)?,
            uu: dev.alloc_zeros::<u16>(c * rw)?,
            inj: dev.alloc_zeros::<f32>(c * hc)?,
            x: dev.alloc_zeros::<u16>(c * h)?,
            x_last: dev.alloc_zeros::<u16>(h)?,
            // S-A3-f-b FIX: same as Scratch — must hold c * max_chain_K
            // (out_proj K=6144; c*2560 caused OOB reads from row c*2560/K).
            chain_xh: dev.alloc_zeros::<u16>(c * 12288)?,
            // PFX1 (c): every m = c chain has N <= PF_CHAIN_NMAX (asserted in exl3_chain_rb /
            // pf_chain_check), the head fc chains are 4c x 2560, and the vocab-wide lm_head runs
            // at m = 1 — c*vocab (1.02 GB at C = 2048) was never needed; max(c*12288, vocab) is.
            chain_yraw: dev.alloc_zeros::<u16>(if pfx1_on(PFX1_YRAW) { (c * PF_CHAIN_NMAX).max(v) } else { c * v })?,
            // S-A3-f-d step 0b FIX (serve smoke, both boxes): this ws is NOT dummy —
            // a final chunk with <= 16 rows runs the decode branch of exl3_chain_impl,
            // where ks>1 chains write split-K partials here ("prefill is m>16" was a
            // stale assumption; short-tail prompts crashed with "chain_ws too small").
            // Same 2M-float sizing as Scratch::new (8 MB).
            chain_ws: dev.alloc_zeros::<f32>(2_000_000)?,
            // S-A3-f-g: reconstruct staging + cuBLASLt workspace (uninitialized is
            // fine: staging is written whole by the decode kernel before any read;
            // the Lt workspace is written by cuBLASLt).
            recon_ws: unsafe { dev.alloc::<u16>(self.recon_staging_elems()) }?,
            lt_ws: unsafe { dev.alloc::<u8>(32 * 1024 * 1024) }?,
            qkv: dev.alloc_zeros::<u16>(c * 10240)?,
            qg: dev.alloc_zeros::<u16>(c * 12288)?,
            kp: dev.alloc_zeros::<u16>(c * 512)?,
            vp: dev.alloc_zeros::<u16>(c * 512)?,
            zbuf: dev.alloc_zeros::<u16>(c * 6144)?,
            a_out: dev.alloc_zeros::<u16>(c * 48)?,
            b_out: dev.alloc_zeros::<u16>(c * 48)?,
            core: dev.alloc_zeros::<u16>(c * 48 * 128)?,
            normed: dev.alloc_zeros::<u16>(c * 6144)?,
            mixer_out: dev.alloc_zeros::<u16>(c * h)?,
            logits_r: dev.alloc_zeros::<f32>(c * cfg.num_experts)?,
            ids: dev.alloc_zeros::<i32>(r)?,
            wts: dev.alloc_zeros::<f32>(r)?,
            idxmap: dev.alloc_zeros::<i32>(cfg.num_experts)?,
            moe_out: dev.alloc_zeros::<u16>(c * h)?,
            sh1: dev.alloc_zeros::<u16>(c * cfg.moe_intermediate_size)?,
            sh2: dev.alloc_zeros::<u16>(c * cfg.moe_intermediate_size)?,
            ysh: dev.alloc_zeros::<u16>(c * h)?,
            cos: dev.alloc_zeros::<f32>(c * 2 * cfg.rotary_dim)?,
            toks: dev.alloc_zeros::<i32>(c)?,
            xh_e: dev.alloc_zeros::<u16>(r * 2560)?,
            ygu_raw: dev.alloc_zeros::<u16>(r * 1280)?,
            ygu: dev.alloc_zeros::<u16>(r * 1280)?,
            din: dev.alloc_zeros::<u16>(r * 640)?,
            xhd: dev.alloc_zeros::<u16>(r * 640)?,
            yd_raw: dev.alloc_zeros::<u16>(r * 2560)?,
            yd: dev.alloc_zeros::<u16>(r * 2560)?,
            offs_gu: dev.alloc_zeros::<u64>(cfg.num_experts)?,
            offs_d: dev.alloc_zeros::<u64>(cfg.num_experts)?,
            ids_ep: dev.alloc_zeros::<i32>(r)?,
            row_tok: dev.alloc_zeros::<i32>(r)?,
            row_eidx: dev.alloc_zeros::<i32>(r)?,
            cand: dev.alloc_zeros::<i32>(r)?,
            offs_row: dev.alloc_zeros::<i32>(cfg.num_experts + 1)?,
            cnt: dev.alloc_zeros::<i32>(cfg.num_experts)?,
            moerows: dev.alloc_zeros::<i32>(1)?,
            ple_emb: dev.alloc_zeros::<u16>(c * 2560)?,
            ple_key16: dev.alloc_zeros::<u16>(c * 10240)?,
            ple_val: dev.alloc_zeros::<u16>(c * 2560)?,
            ple_kn: dev.alloc_zeros::<f32>(c * 4 * 2560)?,
            ple_qn: dev.alloc_zeros::<f32>(c * 4 * 2560)?,
            ple_gated: dev.alloc_zeros::<u16>(c * 4 * 2560)?,
            ple_normed: dev.alloc_zeros::<u16>(c * 4 * 2560)?,
            logits: dev.alloc_zeros::<u16>(v)?,
            argmax: dev.alloc_zeros::<i32>(1)?,
            wp05: match Wp05PfStage::new(dev, c, self.ple.is_some()) {
                Ok(s) => Some(s),
                Err(e) => { println!("WP05: pinned prefill staging unavailable ({e:#}) — pageable path"); None }
            },
            pf_hook: None,
            pf_hooked: false,
            sp_rows: None,
        })
    }

    fn ple_forward_chunk(&self, l: &Launcher, psc: &mut PrefillScratch, toks: &[i32], slot: usize) -> Result<()> {
        let ple = match self.ple.as_ref() {
            Some(p) => p,
            None => return Ok(()),
        };
        let eps = self.cfg.rms_eps as f32;
        let scale = 1.0f32 / (2560f32).sqrt();
        let c = toks.len();
        let par = wp05_on("par") && psc.ple_emb.len() >= c * 2560
            && psc.wp05.as_ref().map_or(false, |s| s.c >= c && s.pin.len >= s.off_ple() + c * 2560 * 2);
        if par {
            // WP05: the n-gram history chain is the only order-dependent part — build it
            // sequentially (same ring updates as below), then decode the rows on up to 8 threads
            // into the pinned buffer and enqueue ONE async NULL-stream copy into the persistent
            // psc.ple_emb. No htod_sync_copy: the host never drains the device mid-chunk (layer 0
            // is still executing while the rows are built), and no per-chunk allocation.
            let h3s: Vec<[i32; 3]> = {
                let mut hist = self.ple_hist.lock().unwrap();
                let mut v = Vec::with_capacity(c);
                for q in 0..c {
                    v.push([hist[slot * 2], hist[slot * 2 + 1], toks[q]]);
                    hist[slot * 2] = hist[slot * 2 + 1];
                    hist[slot * 2 + 1] = toks[q];
                }
                v
            };
            let st = psc.wp05.as_mut().unwrap();
            if st.inflight_ple { self.dev.synchronize()?; st.inflight_ple = false; } // only after an error path
            let off = st.off_ple();
            let rows = st.pin.u16s(off, c * 2560);
            ple.rows_par(&h3s, rows, false)?;
            if ple_xcheck_on() {
                let mut refr = vec![0u16; c * 2560];
                ple.rows_par(&h3s, &mut refr, true)?;
                let (n, first) = wp05_diff_u16(rows, &refr);
                println!("PLE_XCHECK prefill slot {slot} rows {c}: {n} mismatching f16 of {} (first (idx, new, old) {first:?})",
                         c * 2560);
            }
            st.pin.htod(off, *psc.ple_emb.device_ptr() as u64, c * 2560 * 2)?;
            st.inflight_ple = true;
        } else {
            let mut hist = self.ple_hist.lock().unwrap();
            // S-A3-f-d night FIX: this buffer is sized c*2560 while ple_build_embed
            // writes c rows (c * 2560 u16s) — indexing it directly panicked as soon
            // as the PLE pack was driven through a 1-row, width-1 prefill scratch
            // (probe_scratch(1)) or a last chunk of 1 row (§2.2 class). The decode
            // path never hits this because it passes a width-sized buffer.
            let mut emb_buf = vec![0u16; c * 2560];
            for q in 0..c {
                let h3 = [hist[slot * 2], hist[slot * 2 + 1], toks[q]];
                let uids = ple.ngram_uids(&h3);
                ple.embed_row(&uids, &mut emb_buf[q * 2560..(q + 1) * 2560])?;
                hist[slot * 2] = hist[slot * 2 + 1];
                hist[slot * 2 + 1] = toks[q];
            }
            psc.ple_emb = self.dev.htod_sync_copy(&emb_buf)?;
        }
        // S-A3-q P2: wide-M PLE projections through the vendor GEMM (opA=T on the plain f16
        // weights) — the hc_pre_rows / a,b arm (prefill drift class); per-row kernel below rmin.
        let rmin = recon_min_rows();
        let use_lt = rmin > 0 && c >= rmin;
        let rb = self.recon_bufs(psc);
        if use_lt {
            exl3_lt_matmul(l, *ple.key_w.device_ptr() as u64, *psc.ple_emb.device_ptr() as u64,
                           *psc.ple_key16.device_ptr() as u64, 2560, 10240, c, true, rb.ltws, rb.ltws_len)?;
        } else {
            xq_gemm_f16_small!(l, &mut psc.ple_key16, &ple.key_w, &psc.ple_emb, c, 10240usize, 2560usize)?;
        }
        xqlaunch!(l, "xq_ple_norm_f16", (c as u32 * 4, 1, 1), (256, 1, 1), 0,
                 (&psc.ple_key16, &ple.norm_key_w, &mut psc.ple_kn, eps))?;
        if use_lt {
            exl3_lt_matmul(l, *ple.value_w.device_ptr() as u64, *psc.ple_emb.device_ptr() as u64,
                           *psc.ple_val.device_ptr() as u64, 2560, 2560, c, true, rb.ltws, rb.ltws_len)?;
        } else {
            xq_gemm_f16_small!(l, &mut psc.ple_val, &ple.value_w, &psc.ple_emb, c, 2560usize, 2560usize)?;
        }
        xqlaunch!(l, "xq_ple_norm_f32", (c as u32 * 4, 1, 1), (256, 1, 1), 0,
                 (&psc.resid, &ple.norm_query_w, &mut psc.ple_qn, eps))?;
        xqlaunch!(l, "xq_ple_gate", (c as u32 * 4, 1, 1), (256, 1, 1), 0,
                 (&psc.ple_qn, &psc.ple_kn, &psc.ple_val, &mut psc.ple_gated, scale))?;
        xqlaunch!(l, "xq_ple_norm_hh", (c as u32 * 4, 1, 1), (256, 1, 1), 0,
                 (&psc.ple_gated, &ple.norm_conv_w, &mut psc.ple_normed, eps))?;
        xqlaunch!(l, "xq_ple_conv_chunk", ((10240u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                 (&mut psc.resid, &psc.ple_gated, &psc.ple_normed, &self.ple_state, &ple.conv_w, slot as i32, c as i32))?;
        Ok(())
    }

    /// Compact per-expert MoE over C chunk rows (deterministic: experts in
    /// ascending id, rows in ascending token order, combine in ascending j).
    fn moe_prefill(&self, l: &Launcher, psc: &mut PrefillScratch, moe: &MoeLayer, c: usize,
                   rb: &ReconBufs) -> Result<()> {
        let h = self.cfg.hidden_size;
        let ne = self.cfg.num_experts;
        let topk = self.cfg.num_experts_per_tok;
        let mi = self.cfg.moe_intermediate_size;
        // PFX1 (a): MT by chunk rows (bitwise across MT; --exl3-wide-mt overrides). TUNE S24:
        // prefill.wide_mt 0 = this rule; 1|2|4|8 = a fixed MT for the chunk class.
        let mt: usize = match tune::get(&T_WIDE_MT, &l.cx()) { v @ (1 | 2 | 4 | 8) => v as usize, _ => pfx1_moe_mt(c) };
        // TP-SP2 (--tp-seq-parallel router): the router GEMM + softmax/top-k on this rank's OWN rows of
        // the chunk (the kernel the replicated chunk would pick, on row-offset pointers: one ascending-k
        // chain per (row, expert), one CTA per row for the top-k), then ONE all-gather of the ids and
        // weights rows — every row's routing is the replicated router's bits on both ranks.
        let sp_router = psc.sp_rows.filter(|_| xtp::seq_parallel_router() && (topk * 4) % 16 == 0);
        if let (Some(s), Some(tp)) = (sp_router, self.tp.as_ref()) {
            anyhow::ensure!(s.c == c, "TP-SP router: chunk {} vs MoE c {c}", s.c);
            let (lo, hi) = s.own;
            let m = hi - lo;
            let (lp, xp) = (*psc.logits_r.device_ptr() as u64, *psc.x.device_ptr() as u64);
            let (ip, wp) = (*psc.ids.device_ptr() as u64, *psc.wts.device_ptr() as u64);
            router_rows_launch(l, lp + (lo * ne * 4) as u64, *moe.router.device_ptr() as u64, xp + (lo * h * 2) as u64,
                               m, c, ne, h, tune::get(&T_PF_ROUTER_ROWS, &l.cx()) != 0)?;
            xqlaunch!(l, "xq_router_topk", (m as u32, 1, 1), (256, 1, 1), ((256 + ne + 512) * 4) as u32,
                     (ip + (lo * topk * 4) as u64, wp + (lo * topk * 4) as u64, lp + (lo * ne * 4) as u64,
                      ne as i32, topk as i32, m as i32))?;
            tp.sp_all_gather_multi(l, &[(ip, topk * 4), (wp, topk * 4)], &s)?;
        } else {
        // S-A3-q P3: row-batched bit-exact twin (router weight read once per 16 tokens).
        if tune::get(&T_PF_ROUTER_ROWS, &l.cx()) != 0 {
            if pfx1_router_rows8(c, ne, h) {
                // PFX1 (d): the same per-(m, n) ascending-k chain on (ne/64) x ceil(c/8) CTAs
                // (rows32 fills 4 x ceil(c/32) CTAs: <= 1 warp per SM at short chunks).
                xqlaunch!(l, "xq_gemm_f16_f32_rows8", ((ne as u32) / 64, c.div_ceil(8) as u32, 1), (64, 1, 1), 0,
                         (&mut psc.logits_r, &moe.router, &psc.x, c as i32, ne as i32, h as i32))?;
            } else if let Some((kn, bm)) = router_tile_kernel(c, ne, h) {
                // TP-4R1: register-tiled, bitwise == rows32 (same ascending-k chain per output)
                xqlaunch!(l, kn, ((ne as u32) / 64, c.div_ceil(bm) as u32, 1), (128, 1, 1), 0,
                         (&mut psc.logits_r, &moe.router, &psc.x, c as i32, ne as i32, h as i32))?;
            } else {
                xqlaunch!(l, "xq_gemm_f16_f32_rows32", ((ne as u32) / 128, ((c + 31) / 32) as u32, 1), (128, 1, 1), 0,
                         (&mut psc.logits_r, &moe.router, &psc.x, c as i32, ne as i32, h as i32))?;
            }
        } else {
            xqlaunch!(l, "xq_gemm_f16_f32", ((ne as u32) / 128, c as u32, 1), (128, 1, 1), 0,
                     (&mut psc.logits_r, &moe.router, &psc.x, c as i32, ne as i32, h as i32))?;
        }
        xqlaunch!(l, "xq_router_topk", (c as u32, 1, 1), (256, 1, 1), ((256 + ne + 512) * 4) as u32,
                 (&mut psc.ids, &mut psc.wts, &psc.logits_r, ne as i32, topk as i32, c as i32))?;
        }
        // S-A3-u D: device-side routing (no host sync) whenever no expert reconstructs (the
        // default). --exl3-moe-devroute=0 = the host routing A/B.
        let moe_rmin: usize = crate::opts::var(crate::opt!("exl3-moe-recon-min")).ok().and_then(|v| v.parse().ok()).unwrap_or(0);
        let ep = moe.ep.as_ref();
        if moe_rmin == 0 && psc.pf_tiles.len() > 1
            && crate::opts::var(crate::opt!("exl3-moe-devroute")).as_deref() != Ok("0") {
            let r = c * topk;
            // TP-B: expert-parallel prefill — the router/top-k above ran replicated (global ids on
            // every rank); count/place run over THIS rank's local expert space (ids_ep: local
            // stacked id or -1, cand = -1 for remote picks), so the tile lists, compact rows and
            // offsets are the rank's own. The stacked tables are local, so pf_ident / pf_offs_*
            // (identity over expert index) address them unchanged.
            let ne_eff = ep.map_or(ne, |e| e.n_local);
            if let Some(e) = ep {
                xqlaunch!(l, "xq_moe_ids_ep", (r.div_ceil(256) as u32, 1, 1), (256, 1, 1), 0,
                         (&psc.ids, &mut psc.ids_ep, &mut psc.cand, &e.lut, r as i32, ne as i32))?;
            }
            let ids_route = if ep.is_some() { *psc.ids_ep.device_ptr() as u64 } else { *psc.ids.device_ptr() as u64 };
            let ne = ne_eff;
            let max_tiles = (r / 16 + ne) as u32;
            // A5-P1 knobs (all bitwise; default OFF): pipelined kernel, WP19 per-expert MT, glue fold.
            let pk = tune::get(&T_PF_MOE_KERNEL, &l.cx()) != 0 && mi % 128 == 0 && h % 128 == 0;
            let pe = tune::get(&T_PF_MOE_MT_PE, &l.cx()) != 0 && psc.pf_tiles4.len() > 1;
            let fold = pk && tune::get(&T_PF_MOE_FOLD, &l.cx()) != 0;
            // A5-L2: MT-class mask of the smem-ring twin (needs the P1 kernel; 16-B aligned trellis runs).
            let pf2 = if pk && (moe.gu_words * 2) % 16 == 0 && (moe.d_words * 2) % 16 == 0 {
                tune::get(&T_PF_MOE_PF2, &l.cx()).clamp(0, 15)
            } else { 0 };
            {
                static SEEN: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);
                let key = 1u8 | (pk as u8) << 1 | (pe as u8) << 2 | (fold as u8) << 3;
                if SEEN.swap(key, std::sync::atomic::Ordering::Relaxed) != key {
                    println!("A5-P1 prefill MoE: kernel={} mt={} fold={} (c {c}, rule mt {mt})",
                             if pk { "xq_moe_pf (pipelined)" } else { "exl3_hmma_gemm_wide_tiles" },
                             if pe { "per-expert (WP19)" } else { "chunk rule" }, fold as u8);
                }
                static SEEN2: std::sync::atomic::AtomicI32 = std::sync::atomic::AtomicI32::new(-1);
                if SEEN2.swap(pf2, std::sync::atomic::Ordering::Relaxed) != pf2 {
                    println!("A5-L2 prefill MoE: pf2 mask={pf2} (xq_moe_pf2 smem trellis ring for MT classes {:?})",
                             (0..4).filter(|k| pf2 & (1 << k) != 0).map(|k| 1 << k).collect::<Vec<i32>>());
                }
            }
            // (mt, tiles ptr, ntiles ptr, grid-y cap) per launch group
            let tl_base = *psc.pf_tiles4.device_ptr() as u64;
            let nt_base = *psc.pf_ntiles4.device_ptr() as u64;
            let groups: Vec<(usize, u64, u64, u32)> = if pe {
                let caps = moe_pf_class_caps(r, ne);
                (0..4).filter(|&k| caps[k] > 0)
                    .map(|k| (1usize << k, tl_base + (k * max_tiles as usize * 2 * 4) as u64, nt_base + (k * 4) as u64,
                              caps[k] as u32))
                    .collect()
            } else {
                vec![(mt, *psc.pf_tiles.device_ptr() as u64, *psc.pf_ntiles.device_ptr() as u64, max_tiles)]
            };
            if pe {
                xqlaunch!(l, "xq_moe_pf_count4", (1, 1, 1), (1024, 1, 1), 0,
                         (ids_route, r as i32, ne as i32, &mut psc.cnt, &mut psc.offs_row, &mut psc.pf_tiles4,
                          &mut psc.pf_ntiles4, max_tiles as i32))?;
            } else {
                xqlaunch!(l, "xq_moe_pf_count", (1, 1, 1), (1024, 1, 1), 0,
                         (ids_route, r as i32, ne as i32, &mut psc.cnt, &mut psc.offs_row, &mut psc.pf_tiles,
                          &mut psc.pf_ntiles, (16 * mt) as i32))?;
            }
            xqlaunch!(l, "xq_moe_pf_place", (ne as u32, 1, 1), (256, 1, 1), 0,
                     (ids_route, r as i32, topk as i32, &psc.offs_row, &mut psc.row_tok, &mut psc.row_eidx, &mut psc.cand))?;
            if ep.is_some() {
                // rows [offs_row[ne_l], r) hold no local pick: give them a valid index (see kernel)
                xqlaunch!(l, "xq_moe_pf_ep_fill", (r.div_ceil(256).min(1024) as u32, 1, 1), (256, 1, 1), 0,
                         (&psc.offs_row, ne as i32, r as i32, &mut psc.row_tok, &mut psc.row_eidx))?;
            }
            if ep.is_some() {
                // TP-4M1: only rows [0, offs_row[ne_l]) are ever read (the rest hold the ep_fill dummy mapping); the live-row
                // twin skips the dead ones and moves 8 B per lane. Same per-element arithmetic (bitwise equal on live rows).
                let live_end = *psc.offs_row.device_ptr() as u64 + (ne * 4) as u64;
                let nitem = (r * 20) as u64;
                let blocks = nitem.div_ceil(8 * XQ_HSL_U as u64).min(XQ_HSL_BLOCKS as u64).max(1) as u32;
                xqlaunch!(l, XQ_HSL_KERNEL, (blocks, 1, 1), (256, 1, 1), 0,
                         (&psc.x, &moe.suh_gu, &psc.pf_ident, &psc.row_tok, &psc.row_eidx, &mut psc.xh_e, live_end, r as i32, 2560i32))?;
            } else {
                xqlaunch!(l, "xq_had_suh_rows", ((r * 20) as u32, 1, 1), (32, 1, 1), 0,
                         (&psc.x, &moe.suh_gu, &psc.pf_ident, &psc.row_tok, &psc.row_eidx, &mut psc.xh_e, r as i32, 2560i32))?;
            }
            let kn_gu = (2560 | ((mi * 2) << 16)) as i32;
            let kn_d = (mi | (h << 16)) as i32;
            let (svh_gu, suh_d, svh_d) = (*moe.svh_gu.device_ptr() as u64, *moe.suh_d.device_ptr() as u64,
                                          *moe.svh_d.device_ptr() as u64);
            for &(gmt, tp, np, cap) in &groups {
                if fold {
                    let (f, sm, nt) = moe_pf_pick('g', gmt, pf2, 3);
                    xqlaunch!(l, f, ((mi as u32) * 2 / 256, cap, 1), (nt, 1, 1), sm,
                             (&moe.gu_tr, &psc.pf_offs_gu, &psc.xh_e, &mut psc.xhd, tp, np,
                              &psc.offs_row, &psc.cnt, kn_gu, 3i32, svh_gu, suh_d))?;
                } else if pk {
                    let (f, sm, _) = moe_pf_pick('t', gmt, pf2, 3);
                    xqlaunch!(l, f, ((mi as u32) * 2 / 128, cap, 1), (256, 1, 1), sm,
                             (&moe.gu_tr, &psc.pf_offs_gu, &psc.xh_e, &mut psc.ygu_raw, tp, np,
                              &psc.offs_row, &psc.cnt, kn_gu, 3i32, 0u64, 0u64))?;
                } else {
                    xqlaunch!(l, "exl3_hmma_gemm_wide_tiles", ((mi as u32) * 2 / 128, cap, 1), (256, 1, 1), 0,
                             (&moe.gu_tr, &psc.pf_offs_gu, &psc.xh_e, &mut psc.ygu_raw, tp, np,
                              &psc.offs_row, &psc.cnt, 2560i32, (mi * 2) as i32, 3i32, gmt as i32))?;
                }
            }
            if !fold {
                xqlaunch!(l, "xq_had_svh_rows", ((r * 10) as u32, 1, 1), (32, 1, 1), 0,
                         (&psc.ygu_raw, &moe.svh_gu, &psc.pf_ident, &psc.row_eidx, &mut psc.ygu, r as i32, (mi * 2) as i32))?;
                xqlaunch!(l, "xq_moe_gate_mul", (((r * mi) as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                         (&mut psc.din, &psc.ygu, mi as i64, &psc.moerows))?;
                xqlaunch!(l, "xq_had_suh_rows", ((r * (mi / 128)) as u32, 1, 1), (32, 1, 1), 0,
                         (&psc.din, &moe.suh_d, &psc.pf_ident, &psc.pf_dident, &psc.row_eidx, &mut psc.xhd, r as i32, mi as i32))?;
            }
            for &(gmt, tp, np, cap) in &groups {
                if fold {
                    let (f, sm, _) = moe_pf_pick('s', gmt, pf2, 3);
                    xqlaunch!(l, f, ((h as u32) / 128, cap, 1), (256, 1, 1), sm,
                             (&moe.d_tr, &psc.pf_offs_d, &psc.xhd, &mut psc.yd, tp, np,
                              &psc.offs_row, &psc.cnt, kn_d, 3i32, svh_d, 0u64))?;
                } else if pk {
                    let (f, sm, _) = moe_pf_pick('t', gmt, pf2, 3);
                    xqlaunch!(l, f, ((h as u32) / 128, cap, 1), (256, 1, 1), sm,
                             (&moe.d_tr, &psc.pf_offs_d, &psc.xhd, &mut psc.yd_raw, tp, np,
                              &psc.offs_row, &psc.cnt, kn_d, 3i32, 0u64, 0u64))?;
                } else {
                    xqlaunch!(l, "exl3_hmma_gemm_wide_tiles", ((h as u32) / 128, cap, 1), (256, 1, 1), 0,
                             (&moe.d_tr, &psc.pf_offs_d, &psc.xhd, &mut psc.yd_raw, tp, np,
                              &psc.offs_row, &psc.cnt, mi as i32, h as i32, 3i32, gmt as i32))?;
                }
            }
            if !fold {
                xqlaunch!(l, "xq_had_svh_rows", ((r * (h / 128)) as u32, 1, 1), (32, 1, 1), 0,
                         (&psc.yd_raw, &moe.svh_d, &psc.pf_ident, &psc.row_eidx, &mut psc.yd, r as i32, h as i32))?;
            }
            return self.moe_prefill_tail(l, psc, moe, c, rb);
        }
        // TP-B: the host-routing A/B path (--exl3-moe-recon-min / MOE_DEVROUTE=0 / no tile lists)
        // is not expert-parallel — refuse loudly instead of computing remote experts' rows.
        anyhow::ensure!(ep.is_none(), "moe_prefill: the host-routing path is not EP-wired (TP-B) — \
                         unset --exl3-moe-recon-min / --exl3-moe-devroute=0 under TP");
        self.dev.synchronize()?;
        let ids_h = self.dev.dtoh_sync_copy(&psc.ids)?;
        let r = c * topk;
        // counting sort by expert id; selected experts in ASCENDING id order.
        // Count ONLY the router-written prefix: psc.ids is scratch-sized
        // (c_scratch*topk) and rows >= c*topk hold stale garbage (§2.2).
        let mut cnt = vec![0i32; ne];
        for x in &ids_h[..r] {
            let ei = *x as usize;
            if ei < ne {
                cnt[ei] += 1;
            }
        }
        let uniq: Vec<i32> = (0..ne).filter(|&e| cnt[e] > 0).map(|e| e as i32).collect();
        let esel = uniq.len();
        let mut slot_of = vec![-1i32; ne];
        for (i, &e) in uniq.iter().enumerate() {
            slot_of[e as usize] = i as i32;
        }
        let mut offs_row = vec![0i32; esel + 1];
        for i in 0..esel {
            offs_row[i + 1] = offs_row[i] + cnt[uniq[i] as usize];
        }
        let mut row_tok = vec![0i32; r];
        let mut row_eidx = vec![0i32; r];
        let mut cand = vec![0i32; r];
        let mut cursor = offs_row[..esel].to_vec();
        for t in 0..c {
            for j in 0..topk {
                let e = ids_h[t * topk + j] as usize;
                let s = slot_of[e] as usize;
                let i = cursor[s] as usize;
                cursor[s] += 1;
                row_tok[i] = t as i32;
                row_eidx[i] = s as i32;
                cand[t * topk + j] = i as i32;
            }
        }
        let offs_gu: Vec<u64> = uniq.iter().map(|e| *e as u64 * moe.gu_words).collect();
        let offs_d: Vec<u64> = uniq.iter().map(|e| *e as u64 * moe.d_words).collect();
        // S-A3-f-b §2.1: these uploads MUST be synchronous — they land on the
        // null stream while the compute kernels run on the forked stream; async
        // copies raced the launches and the kernels read half-uploaded routing
        // tables (varying-layer illegal address). The stream is empty here (we
        // just synchronized for the dtoh), so sync copies cost nothing.
        psc.row_tok = self.dev.htod_sync_copy(&row_tok)?;
        psc.row_eidx = self.dev.htod_sync_copy(&row_eidx)?;
        psc.cand = self.dev.htod_sync_copy(&cand)?;
        psc.offs_row = self.dev.htod_sync_copy(&offs_row)?;
        // The kernel indexes cnt by COMPACT slot (e = blockIdx.x < esel), so it
        // must receive the per-slot counts, not the raw-id-indexed counts
        // (uploading `cnt` made n_live read another expert's count -> reads
        // past row_tok; the varying-layer OOB of 2026-09-20).
        let cnt_c: Vec<i32> = uniq.iter().map(|&e| cnt[e as usize]).collect();
        psc.cnt = self.dev.htod_sync_copy(&cnt_c)?;
        psc.idxmap = self.dev.htod_sync_copy(&uniq)?;
        psc.offs_gu = self.dev.htod_sync_copy(&offs_gu)?;
        psc.offs_d = self.dev.htod_sync_copy(&offs_d)?;
        let msup = (c + 16 * mt - 1) / (16 * mt); // per-expert cnt <= C always
        // gate*up side
        xqlaunch!(l, "xq_had_suh_rows", ((r * 20) as u32, 1, 1), (32, 1, 1), 0,
                 (&psc.x, &moe.suh_gu, &psc.idxmap, &psc.row_tok, &psc.row_eidx, &mut psc.xh_e, r as i32, 2560i32))?;
        // S-A3-f-b: the compact grouped kernel is NOT used — its ygu_raw
        // diverges (rel ~1.7 vs the C=1 reference) while xh_e is bit-exact;
        // root cause not yet found (follow-up). Run the PROVEN wide-M kernel
        // per expert on the compact row blocks instead (~esel launches/side).
        // S-A3-f-g per-expert reconstruct threshold. S-A3-q P4: the MoE side has its OWN knob,
        // default 0 = never reconstruct — every live expert runs the grouped trellis-wide GEMM
        // (the trellis is read once per 64-row super-tile; reconstruct wrote a full fp16 copy
        // of each expert, 2.1 s at 2K). --exl3-moe-recon-min=17 restores the f-g split.
        let rmin: usize = crate::opts::var(crate::opt!("exl3-moe-recon-min")).ok()
            .and_then(|v| v.parse().ok()).unwrap_or(0);
        // S-A3-q P1: the below-threshold experts' wide GEMMs run as ONE grouped launch per side
        // (bitwise == the per-expert launches; --exl3-moe-grouped=0 = the per-expert A/B).
        let grouped = tune::get(&T_PF_MOE_GROUPED, &l.cx()) != 0;
        let wide_msup: u32 = cnt_c.iter()
            .filter(|&&ce| ce > 0 && !(rmin > 0 && ce as usize >= rmin))
            .map(|&ce| ((ce as usize + 16 * mt - 1) / (16 * mt)) as u32)
            .max().unwrap_or(0);
        {
            let gu_base = *moe.gu_tr.device_ptr() as u64;
            let xh_base = *psc.xh_e.device_ptr() as u64;
            let yg_base = *psc.ygu_raw.device_ptr() as u64;
            let xh_stride = 2560u64 * 2;
            let yg_stride = 1280u64 * 2;
            for si in 0..esel {
                // S-A3-f-b: per-SLOT count (cnt[uniq[si]]), NOT cnt[si] — cnt is
                // raw-expert-id indexed; reading it by slot skipped/mis-sized
                // expert groups whenever rare experts went unselected (esel<ne)
                // and left their yd rows stale (3/10 of token-0's experts).
                let ce = cnt_c[si];
                if ce == 0 { continue; }
                let row0 = offs_row[si] as u64;
                let eb = uniq[si] as u64;
                if rmin > 0 && (ce as usize) >= rmin {
                    // S-A3-f-g: reconstruct this expert's fused gate|up ONCE
                    // ([K=2560, N=2mi] plain W_dec), then the vendor GEMM on the
                    // compact row block. Same math as the wide kernel (the staged
                    // matrix is what its mma consumes); fp32-accumulate reduction
                    // order differs — the drift class pre-authorized by the brief.
                    exl3_reconstruct(l, gu_base + eb * moe.gu_words * 2, rb.rc, rb.ws,
                                     2560, (mi * 2) as i32, 3i32)?;
                    exl3_lt_matmul(l, rb.ws, xh_base + row0 * xh_stride,
                                   yg_base + row0 * yg_stride, 2560, (mi * 2) as usize,
                                   ce as usize, false, rb.ltws, rb.ltws_len)?;
                } else if !grouped {
                    let ms_e = ((ce as u64) + (16 * mt - 1) as u64) / (16 * mt) as u64;
                    xqlaunch!(l, "exl3_hmma_gemm_wide", (ms_e as u32, (mi as u32) * 2 / 128, 1), (256, 1, 1), 0,
                         (gu_base + eb * moe.gu_words * 2, xh_base + row0 * xh_stride,
                          yg_base + row0 * yg_stride, ce as i32, 2560i32, (mi * 2) as i32, 3i32, mt as i32))?;
                }
            }
            if grouped && wide_msup > 0 {
                xqlaunch!(l, "exl3_hmma_gemm_wide_grouped", (wide_msup, (mi as u32) * 2 / 128, esel as u32), (256, 1, 1), 0,
                         (&moe.gu_tr, &psc.offs_gu, &psc.xh_e, &mut psc.ygu_raw, &psc.offs_row, &psc.cnt,
                          2560i32, (mi * 2) as i32, 3i32, mt as i32, rmin as i32))?;
            }
        }
        xqlaunch!(l, "xq_had_svh_rows", ((r * 10) as u32, 1, 1), (32, 1, 1), 0,
                 (&psc.ygu_raw, &moe.svh_gu, &psc.idxmap, &psc.row_eidx, &mut psc.ygu, r as i32, (mi * 2) as i32))?;
        // S-A3-f-d night ROOT-CAUSE FIX (the serve-prefill blocker): this launch
        // was missing the kernel's 4th parameter. xq_moe_gate_mul is
        // (din, y_gu, row640, esel) with guard i < (*esel)*row640 — decode passes
        // &sc.esel; prefill passed only 3 args, the 4th param read garbage past
        // the param buffer and the guard killed EVERY thread: din stayed zeros,
        // so every routed-expert row (xhd/yd_raw/yd) was zero and the combine
        // emitted the shared expert only. That is the prefill divergence the
        // trace pinned (yd0 rel=1.00 vs rounding-class upstream), at every chunk
        // width, both prompt classes — junk serve text since f-b/f-g. The kernel
        // needs product(esel,row640) = total compact rows: pass moerows=r with
        // row640 = mi (guard r*mi = r*640 elements; geometry 640/1280 hardcoded
        // in the kernel, matching this pack's moe_intermediate_size).
        self.dev.synchronize()?;
        psc.moerows = self.dev.htod_sync_copy(&[r as i32])?;
        xqlaunch!(l, "xq_moe_gate_mul", (((r * mi) as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                 (&mut psc.din, &psc.ygu, mi as i64, &psc.moerows))?;
        // down side (din is already compact: row_tok pass uses the IDENTITY map)
        let ident: Vec<i32> = (0..r as i32).collect();
        let d_ident = self.dev.htod_sync_copy(&ident)?;
        xqlaunch!(l, "xq_had_suh_rows", ((r * (mi / 128)) as u32, 1, 1), (32, 1, 1), 0,
                 (&psc.din, &moe.suh_d, &psc.idxmap, &d_ident, &psc.row_eidx, &mut psc.xhd, r as i32, mi as i32))?;
        {
            let d_base = *moe.d_tr.device_ptr() as u64;
            let xhd_base = *psc.xhd.device_ptr() as u64;
            let yd_base = *psc.yd_raw.device_ptr() as u64;
            let d_xh_stride = (mi as u64) * 2;
            let yd_stride = 2560u64 * 2;
            for si in 0..esel {
                let ce = cnt_c[si]; // per-SLOT count; see gate/up loop note above
                if ce == 0 { continue; }
                let row0 = offs_row[si] as u64;
                let eb = uniq[si] as u64;
                if rmin > 0 && (ce as usize) >= rmin {
                    // S-A3-f-g: reconstruct this expert's down projection
                    // ([K=mi, N=2560]) once, then the vendor GEMM per row block.
                    exl3_reconstruct(l, d_base + eb * moe.d_words * 2, rb.rc, rb.ws,
                                     mi as i32, 2560i32, 3i32)?;
                    exl3_lt_matmul(l, rb.ws, xhd_base + row0 * d_xh_stride,
                                   yd_base + row0 * yd_stride, mi as usize, 2560usize,
                                   ce as usize, false, rb.ltws, rb.ltws_len)?;
                } else if !grouped {
                    let ms_e = ((ce as u64) + (16 * mt - 1) as u64) / (16 * mt) as u64;
                    xqlaunch!(l, "exl3_hmma_gemm_wide", (ms_e as u32, (h as u32) / 128, 1), (256, 1, 1), 0,
                         (d_base + eb * moe.d_words * 2, xhd_base + row0 * d_xh_stride,
                          yd_base + row0 * yd_stride, ce as i32, mi as i32, h as i32, 3i32, mt as i32))?;
                }
            }
            if grouped && wide_msup > 0 {
                xqlaunch!(l, "exl3_hmma_gemm_wide_grouped", (wide_msup, (h as u32) / 128, esel as u32), (256, 1, 1), 0,
                         (&moe.d_tr, &psc.offs_d, &psc.xhd, &mut psc.yd_raw, &psc.offs_row, &psc.cnt,
                          mi as i32, h as i32, 3i32, mt as i32, rmin as i32))?;
            }
        }
        xqlaunch!(l, "xq_had_svh_rows", ((r * (h / 128)) as u32, 1, 1), (32, 1, 1), 0,
                 (&psc.yd_raw, &moe.svh_d, &psc.idxmap, &psc.row_eidx, &mut psc.yd, r as i32, h as i32))?;
        self.moe_prefill_tail(l, psc, moe, c, rb)
    }

    /// Shared expert + combine — the common end of both prefill MoE routing paths.
    fn moe_prefill_tail(&self, l: &Launcher, psc: &mut PrefillScratch, moe: &MoeLayer, c: usize,
                        rb: &ReconBufs) -> Result<()> {
        let h = self.cfg.hidden_size;
        let topk = self.cfg.num_experts_per_tok;
        let mi = moe.sh_down.k as usize; // TP-B: the rank's shared-expert slice (640 at TP=1)
        // shared expert (dense wide path)
        exl3_chain_rb(l, &moe.sh_gate, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.sh1, c, &psc.chain_ws, rb)?;
        exl3_chain_rb(l, &moe.sh_up, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.sh2, c, &psc.chain_ws, rb)?;
        let sh1p = *psc.sh1.device_ptr() as u64;
        xqlaunch!(l, "xq_silu_mul", (((c * mi) as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                 (&mut psc.sh1, sh1p, &psc.sh2, (c * mi) as i64))?;
        exl3_chain_rb(l, &moe.sh_down, &psc.sh1, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.ysh, c, &psc.chain_ws, rb)?;
        if let Some(ep) = moe.ep.as_ref() {
            // TP-B: this rank's FP32 partial (local picks + its shared term) -> all-reduce -> f16
            return self.ep_combine_reduce_rows(l, psc, moe, ep, c);
        }
        xqlaunch!(l, "xq_moe_combine_rows", (c as u32, 1, 1), (1024, 1, 1), 4096,
                 (&mut psc.moe_out, &psc.yd, &psc.ysh, &psc.cand, &psc.wts, &moe.sg, &psc.x,
                  topk as i32, h as i32, c as i32))?;
        // TP-B xtp diagnostic (eager TP=1 reference only): the reduction-site ulp floor, prefill rows.
        if xtp::moe_ulp_armed() && self.tp.is_none() && !stream_capturing(l) {
            self.moe_ulp_perturb_buf(&mut psc.moe_out, c)?;
        }
        Ok(())
    }

    /// One chunked prefill sweep: `toks.len()` consecutive tokens of `slot`
    /// starting at absolute position `pos0`. The chunk's LAST row passes the
    /// final mixer + lm_head; `want_logits` gates that (intermediate chunks
    /// skip the vocab head entirely).
    /// WP18 rung A: the bounded selection walk for the sparse rows [t0, c) of a chunk — writes
    /// psc.qsa_sel / qsa_psel rows [t0, c) bit-identically to qsa_score_prefill_b +
    /// xq_qsa_topk_asc. `xc`: also diff every scored tile against the reference matrix
    /// (psc.qsa_scores, filled by the caller) into the XCHECK counters.
    #[allow(clippy::too_many_arguments)]
    fn wp18_select(&self, l: &Launcher, psc: &mut PrefillScratch, blocks_p: u64, params_p: u64,
                   pos0: usize, t0: usize, c: usize, xc: bool) -> Result<()> {
        if xc {
            // counters: [0] differing scores, [1] min packed (row << 16 | block) of a difference, [2] compared
            if let Some((_, _, cnt)) = psc.wp18.as_mut().and_then(|w| w.x.as_mut()) {
                self.dev.htod_sync_copy_into(&[0i32, i32::MAX, 0, 0], cnt)?;
            }
        }
        let w = psc.wp18.as_ref().expect("wp18_select without WP18 scratch");
        let cfg = &self.cfg;
        let ratio = cfg.indexer_compress_ratio;
        let qk_dim = (cfg.indexer_n_heads + 1) * cfg.indexer_head_dim;
        let sel_max = self.qsa_limit();
        let nblk_stride = (self.max_pos / ratio).max(1);
        let (slab_p, ck_p, ci_p) = (*w.slab.device_ptr() as u64, *w.ck.device_ptr() as u64, *w.ci.device_ptr() as u64);
        let (qkb_p, sel_p, psel_p) = (*psc.qsa_qkb.device_ptr() as u64, *psc.qsa_sel.device_ptr() as u64,
                                      *psc.qsa_psel.device_ptr() as u64);
        let (cnt_p, full_p) = match (&w.x, xc) {
            (Some((_, _, cnt)), true) => (*cnt.device_ptr() as u64, *psc.qsa_scores.device_ptr() as u64),
            _ => (0u64, 0u64),
        };
        for st in wp18_plan(pos0 + t0, c - t0, ratio, w.rows) {
            let row = t0 + st.g0;                          // chunk row of the group's first row
            if st.score_grid.0 > 0 {
                xqlaunch!(l, "xq_wp18_score", (st.score_grid.0, st.score_grid.1, 1), (256, 1, 1), 0,
                          (slab_p, qkb_p + (row * qk_dim * 2) as u64, blocks_p, params_p,
                           st.pos_first as i32, st.gn as i32, (st.kt * WP18_T) as i32, qk_dim as i32))?;
                if xc {
                    xqlaunch!(l, "xq_wp18_cmp", (st.gn as u32, 1, 1), (256, 1, 1), 0,
                              (cnt_p, slab_p, full_p, params_p, st.pos_first as i32, row as i32,
                               st.kt as i32, nblk_stride as i32))?;
                }
            }
            xqlaunch!(l, "xq_wp18_merge", (st.gn as u32, 1, 1), (WP18_MT as u32, 1, 1), 0,
                      (sel_p + (row * sel_max * 4) as u64, psel_p + (row * 4) as u64, slab_p, ck_p, ci_p,
                       params_p, st.pos_first as i32, st.kt as i32))?;
        }
        Ok(())
    }

    /// --wp18-xcheck report (eager): the WP18 lists vs the old pair's reference lists for rows
    /// [t0, c) — pos_sel and entries [0, pos_sel] — plus the scored-tile bit diff counters.
    fn wp18_xcheck_report(&self, psc: &PrefillScratch, att_i: usize, pos0: usize, t0: usize, c: usize) -> Result<()> {
        use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
        static CALLS: AtomicUsize = AtomicUsize::new(0);
        static ROWS: AtomicUsize = AtomicUsize::new(0);
        static BAD_ROWS: AtomicUsize = AtomicUsize::new(0);
        static SC_TOT: AtomicUsize = AtomicUsize::new(0);
        static SC_BAD: AtomicUsize = AtomicUsize::new(0);
        let (xs, xp, xcnt) = psc.wp18.as_ref().and_then(|w| w.x.as_ref()).expect("WP18 XCHECK buffers");
        let sel_max = self.qsa_limit();
        self.dev.synchronize()?;
        let (s1, p1) = (self.dev.dtoh_sync_copy(&psc.qsa_sel)?, self.dev.dtoh_sync_copy(&psc.qsa_psel)?);
        let (s0, p0) = (self.dev.dtoh_sync_copy(xs)?, self.dev.dtoh_sync_copy(xp)?);
        let cnt = self.dev.dtoh_sync_copy(xcnt)?;
        let (mut bad, mut first) = (0usize, String::new());
        let mut entries = 0usize;
        for t in t0..c {
            let n = ((p0[t] + 1).max(0) as usize).min(sel_max);
            let row_ok = p0[t] == p1[t]
                && s0[t * sel_max..t * sel_max + n] == s1[t * sel_max..t * sel_max + n];
            entries += n;
            if !row_ok {
                if bad == 0 {
                    let i = (0..n).find(|&i| s0[t * sel_max + i] != s1[t * sel_max + i]);
                    first = format!(" first: row {t} (pos {}) pos_sel wp18 {} vs {}; first entry diff {:?}",
                                    pos0 + t, p1[t], p0[t],
                                    i.map(|i| (i, s1[t * sel_max + i], s0[t * sel_max + i])));
                }
                bad += 1;
            }
        }
        let rows = c - t0;
        let (sd, stot) = (cnt[0].max(0) as usize, cnt[2].max(0) as usize);
        let k = CALLS.fetch_add(1, Relaxed);
        let (cr, cb) = (ROWS.fetch_add(rows, Relaxed) + rows, BAD_ROWS.fetch_add(bad, Relaxed) + bad);
        let (ct, cs) = (SC_TOT.fetch_add(stot, Relaxed) + stot, SC_BAD.fetch_add(sd, Relaxed) + sd);
        if k < 4 || bad > 0 || sd > 0 || k.is_power_of_two() || (k + 1) % 64 == 0 {
            let sfirst = if sd > 0 { format!(" (first score diff at row {} block {})", cnt[1] >> 16, cnt[1] & 0xFFFF) } else { String::new() };
            println!("WP18_XCHECK #{k} layer {att_i} pos0 {pos0} rows {rows} (t0 {t0}): lists differ {bad}/{rows} rows \
                      ({entries} entries compared){first}; scores bit-differ {sd}/{stot}{sfirst} | cumulative: rows {cb}/{cr} \
                      differ, scores {cs}/{ct}{}", if bad + sd > 0 { "  <-- MISMATCH" } else { "" });
        }
        Ok(())
    }

    /// S-A3-i: QSA selection + gathered attention for the prefill rows [t0, c) of a
    /// chunk (eager, pointer-offset over the PrefillScratch row buffers). K/V for the
    /// whole chunk are already written by xq_attn_kv_prefill; the indexer projection
    /// runs over all c rows (a 640-wide GEMV — noise next to the chunk's GEMMs) and
    /// only the sparse row range consumes it. Splits = 1 (one block per row x kv head).
    fn qsa_attn_prefill_rows(&self, l: &Launcher, psc: &mut PrefillScratch, a: &AttnLayer, att_i: usize,
                             slot: usize, pos0: usize, t0: usize, c: usize) -> Result<()> {
        let cfg = self.acfg_i(att_i); // TP-B: per-rank heads (trunk) / global (the replicated head)
        let (ix, params) = a.idx.as_ref().and_then(|i| i.params.as_ref().map(|p| (i, p)))
            .expect("qsa_attn_prefill_rows: indexer without params");
        let (hdx, heads, ratio) = (cfg.indexer_head_dim, cfg.indexer_n_heads, cfg.indexer_compress_ratio);
        const QSA_PF_QT: usize = 8;   // mirrors kernels/gpu_batch.cu QSA_PF_QT (queries per block in qsa_score_prefill_b)
        let qk_dim = (heads + 1) * hdx;
        let nblk_stride = (self.max_pos / ratio).max(1);
        let sel_max = self.qsa_limit();
        let rows = c - t0;
        let nblk = ((pos0 + c) / ratio).min(nblk_stride);
        let params_p = (*params.device_ptr()) as u64;
        let keys_p = *self.qsa_keys[att_i].device_ptr() as u64;
        // 1. indexer projection (all c rows) -> bf16 -> q heads normed+roped in place
        pf_chain_check_n(&ix.qk, c, &psc.chain_xh, &psc.chain_yraw)?; // PFX1 (c)
        exl3_chain(l, &ix.qk, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw,
                   &mut psc.qsa_qk, c, &psc.chain_ws)?;
        let ncnv = (c * qk_dim) as i64;
        xqlaunch!(l, "xq_qsa_h2b", ((((ncnv + 255) / 256).max(1)) as u32, 1, 1), (256, 1, 1), 0,
                  (&mut psc.qsa_qkb, &psc.qsa_qk, ncnv))?;
        xqlaunch!(l, "xq_qsa_qnorm_rope", ((c * heads) as u32, 1, 1), (hdx as u32, 1, 1), 0,
                  (&mut psc.qsa_qkb, &ix.qn, &psc.cos, heads as i32, hdx as i32,
                   cfg.rotary_dim as i32, c as i32, cfg.rms_eps))?;
        // 2. raw-key append (all c rows), pooled block keys, tiled scoring
        gblaunch!(l, "qsa_key_write_b", ((c * hdx) as u32, 1, 1), (256, 1, 1), 0,
                  (keys_p, &psc.qsa_qkb, &psc.pos_rows, &psc.slot_rows, self.max_pos as i32, 0i32,
                   qk_dim as i32, (heads * hdx) as i32, hdx as i32, c as i32))?;
        // pooled plane: refresh only this chunk's blocks, then score straight from the slot's
        // plane (exact) — replaces re-pooling ALL nblk blocks every chunk (O(n^2) over a prompt).
        let pool_slot = if self.qsa_pool_p(att_i).is_some() {
            self.qsa_pool_range(l, a, att_i, keys_p, slot, pos0, c)?;
            Some(self.qsa_pool_p(att_i).unwrap() + (slot * nblk_stride * hdx * 2) as u64)
        } else {
            gblaunch!(l, "qsa_block_keys_b", ((nblk.div_ceil(8)) as u32, 1, 1), (256, 1, 1), 0,
                      ((*psc.qsa_blocks.device_ptr()) as u64, keys_p + (slot * self.max_pos * hdx * 2) as u64,
                       params_p, nblk as i32, slot as i32))?;
            None
        };
        let blocks_p = pool_slot.unwrap_or(*psc.qsa_blocks.device_ptr() as u64);
        // sq[] staging is QSA_PF_QT*heads*hd f32 of DYNAMIC shared (kernel contract,
        // gpu_batch.cu:12540): the launch must size it or every sq[i] write is out of
        // bounds — the 2026-09-25 memcheck fault (8,963 invalid __shared__ writes on
        // the first sparse rows). gpu.rs's call site passes the same value.
        let smem = (QSA_PF_QT * heads * hdx * 4) as u32;
        // WP18: the bounded tiled walk (bit-identical lists) replaces the full matrix + top-k;
        // --wp18-xcheck runs the old pair below into reference lists first and diffs.
        let wp18_xc = psc.wp18.as_ref().map(|w| w.x.is_some() && !self.stream_capturing());
        if wp18_xc != Some(false) {
            // Grid over the blocks VISIBLE at the end of this chunk (nblk), not the window's
            // nblk_stride: every j >= nblk returned before writing anyway (j >= (pos0+tlast+1)/ratio),
            // but only AFTER each CTA staged 8 queries x all heads into smem — at a 262K window that
            // is ~65K block slots x 256 query tiles per chunk per layer of pure waste (32K prefill:
            // 704 tok/s at max_pos 262K vs 950 at 40K, 2026-09-26). Same written scores, bit-exact.
            gblaunch!(l, "qsa_score_prefill_b", ((nblk.max(1).div_ceil(256)) as u32, (c.div_ceil(QSA_PF_QT)) as u32, 1), (256, 1, 1), smem,
                      (&mut psc.qsa_scores, &psc.qsa_qkb, blocks_p, params_p,
                       pos0 as i32, c as i32, nblk_stride as i32, qk_dim as i32))?;
            // 3. top-k for the sparse rows [t0, c) — ascending emission (XCHECK: into the reference lists)
            // S-A3-i review fix: SELECT_ALL is unsafe past sel_max (list overflow) and
            // redundant below it (the dense branch IS the full selection) — constant 0.
            let sel_all = 0i32;
            let (sel_b, psel_b) = match psc.wp18.as_ref().and_then(|w| w.x.as_ref()) {
                Some((xs, xp, _)) => (*xs.device_ptr() as u64, *xp.device_ptr() as u64),
                None => (*psc.qsa_sel.device_ptr() as u64, *psc.qsa_psel.device_ptr() as u64),
            };
            xqlaunch!(l, "xq_qsa_topk_asc", (rows as u32, 1, 1), (1024, 1, 1), 0,
                      (sel_b + (t0 * sel_max * 4) as u64,
                       psel_b + (t0 * 4) as u64,
                       (*psc.qsa_scores.device_ptr()) as u64 + (t0 * nblk_stride * 4) as u64,
                       (*psc.pos_rows.device_ptr()) as u64 + (t0 * 4) as u64,
                       params_p, nblk_stride as i32, sel_all))?;
        }
        if let Some(xc) = wp18_xc {
            self.wp18_select(l, psc, blocks_p, params_p, pos0, t0, c, xc)?;
            if xc { self.wp18_xcheck_report(psc, att_i, pos0, t0, c)?; }
        }
        if let Some((k, _, _, ps_, pp_)) = self.qsa_rowdbg.as_ref() {
            if *k == att_i {
                xqlaunch!(l, "xq_dbg_scatter_sel", (rows as u32, 1, 1), (256, 1, 1), 0,
                          (*ps_.device_ptr() as u64, *pp_.device_ptr() as u64,
                           (*psc.qsa_sel.device_ptr()) as u64 + (t0 * sel_max * 4) as u64,
                           (*psc.qsa_psel.device_ptr()) as u64 + (t0 * 4) as u64,
                           (*psc.pos_rows.device_ptr()) as u64 + (t0 * 4) as u64,
                           sel_max as i32, QSA_ROWDUMP_CAP as i32))?;
            }
        }
        if let Some((k, _, _, ps, pc)) = self.qsa_dbg.as_ref() {
            if *k == att_i && c <= 2048 {
                let ns = (c * sel_max) as i64; let nc = (c * nblk_stride) as i64;
                xqlaunch!(l, "xq_copy_f32", ((((ns + 255) / 256) as u32), 1, 1), (256, 1, 1), 0,
                          (*ps.device_ptr() as u64, *psc.qsa_sel.device_ptr() as u64, ns, 0i64, 0i64))?;
                xqlaunch!(l, "xq_copy_f32", ((((nc + 255) / 256) as u32), 1, 1), (256, 1, 1), 0,
                          (*pc.device_ptr() as u64, *psc.qsa_scores.device_ptr() as u64, nc, 0i64, 0i64))?;
            }
        }
        // 4. q staging + gathered attention over the sparse rows (splits = 1)
        let nh_p = (cfg.num_heads as i32) | ((cfg.num_kv_heads as i32) << 16);
        let hd_p = (cfg.head_dim as i32) | ((cfg.rotary_dim as i32) << 16);
        // S-A3-s FIX: a qg row is [q|gate] per head = num_heads * 2*head_dim f16 values, i.e.
        // num_heads*head_dim*4 BYTES (12,288 halves = 24,576 B here). This was
        // num_heads*head_dim*2 (the half-count of ONE of q/gate, read as bytes), so whenever the
        // sparse rows started at t0 > 0 — every chunk that straddles the QSA limit, i.e. mixes
        // dense and sparse rows — xq_attn_prep and xq_attn_sel_combine read the q and gate rows
        // of position p - t0/2 for position p. Pure-sparse chunks (t0 = 0) and decode never
        // offset, which is why only straddle chunks diverged.
        let qrow = cfg.num_heads * cfg.head_dim * 2 * 2;  // f16 bytes/row ([q|gate] per head)
        let krow = cfg.num_kv_heads * cfg.head_dim * 2;
        xqlaunch!(l, "xq_attn_prep", ((rows * cfg.num_kv_heads) as u32, 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                  ((*psc.qstage.device_ptr()) as u64 + (t0 * cfg.num_heads * cfg.head_dim * 4) as u64,
                   (*self.k_cache[att_i].device_ptr()) as u64,
                   (*psc.qg.device_ptr()) as u64 + (t0 * qrow) as u64,
                   (*psc.kp.device_ptr()) as u64 + (t0 * krow) as u64,
                   (*psc.vp.device_ptr()) as u64 + (t0 * krow) as u64,
                   &a.qnkn,
                   (*psc.cos.device_ptr()) as u64 + (t0 * 2 * cfg.rotary_dim * 4) as u64,
                   (*psc.slotpos_rows.device_ptr()) as u64 + (t0 * 2 * 4) as u64,
                   nh_p, hd_p, self.mpf(), cfg.rms_eps))?;
        // S-A3-u E: the SAME split geometry as the decode path (qsa_attn_step): QSA_SPLITS splits of
        // split_len = ceil(sel_max / QSA_SPLITS) per (row, kv head) — was splits = 1, one block
        // serially walking ~2,051 selected positions per row. Each row's reduction now matches
        // decode's exactly (cross-class), and the rows get QSA_SPLITS-way parallelism.
        let split_len = sel_max.div_ceil(QSA_SPLITS);
        let g2: u64 = (QSA_SPLITS as u64) | ((sel_max as u64) << 20) | ((self.mpf() as u32 as u64) << 32);
        let pmb = cfg.num_heads * QSA_SPLITS * 4;
        let pacb = cfg.num_heads * QSA_SPLITS * cfg.head_dim * 4;
        // S-A3-v: the float4 twin of splitk (same grid, values and expression order — bit-identical
        // partials; the prefill gather was LSU-bound on scalar loads). --exl3-sel-vec=0 keeps splitk;
        // --exl3-sel-xcheck=1 runs both and diffs.
        let vec4 = tune::get_cur(&T_SEL_VEC) != 0;
        let xcheck = vec4 && crate::opts::var(crate::opt!("exl3-sel-xcheck")).is_ok();
        // PQ8 item 3: the 8-bit-cache prefill gather (xq_attn_sel_pq8 — bit-identical partials to
        // splitk4: same grid/splits/order; each selected row unpacked ONCE per CTA into an f32 smem
        // tile, 4 warps x 3 heads, next tile's bytes prefetched). Its shape contract: hd 256 (lane
        // owns 8 dims), gqa exactly 12, split_len < 2^16. --pq8-gather=0 = splitk4.
        let gqa = cfg.num_heads / cfg.num_kv_heads.max(1);
        let pq8 = vec4 && !xcheck && pq8_item(2) && self.kv_fmt >= KV_Q8 && cfg.head_dim == 256
            && gqa == 12 && gqa * cfg.num_kv_heads == cfg.num_heads && split_len < 0x10000;
        if pq8 {
            let pq8x = pq8_xcheck() && !self.stream_capturing();
            let (a0, a1) = (t0 * cfg.num_heads * QSA_SPLITS, (t0 + rows) * cfg.num_heads * QSA_SPLITS);
            let split_hd = (split_len as i32) | ((cfg.head_dim as i32) << 16);
            let mut want: Option<(Vec<f32>, Vec<f32>, Vec<f32>)> = None;
            let names: &[&str] = if pq8x { &["xq_attn_sel_splitk4", "xq_attn_sel_pq8"] } else { &["xq_attn_sel_pq8"] };
            for &kname in names {
                if kname == "xq_attn_sel_pq8" {
                    if pq8x {
                        self.dev.synchronize()?;
                        want = Some((self.dev.dtoh_sync_copy(&psc.qsa_pm)?, self.dev.dtoh_sync_copy(&psc.qsa_pl)?,
                                     self.dev.dtoh_sync_copy(&psc.qsa_pacc)?));
                        // poison the rows' partials with f32 NaN (0xFFFFFFFF): an unwritten partial must differ
                        for (buf, n) in [(*psc.qsa_pm.device_ptr() as u64 + (a0 * 4) as u64, (a1 - a0) * 2),
                                         (*psc.qsa_pl.device_ptr() as u64 + (a0 * 4) as u64, (a1 - a0) * 2),
                                         (*psc.qsa_pacc.device_ptr() as u64 + (a0 * cfg.head_dim * 4) as u64,
                                          (a1 - a0) * cfg.head_dim * 2)] {
                            xqlaunch!(l, "xq_memset_u16", (((n as u32) + 255) / 256, 1, 1), (256, 1, 1), 0,
                                      (buf, n as i64, 0xFFFFi32))?;
                        }
                    }
                    xqlaunch!(l, "xq_attn_sel_pq8", ((rows * cfg.num_kv_heads * QSA_SPLITS) as u32, 1, 1), (128, 1, 1), 0,
                              ((*psc.qsa_pm.device_ptr()) as u64 + (t0 * pmb) as u64,
                               (*psc.qsa_pl.device_ptr()) as u64 + (t0 * pmb) as u64,
                               (*psc.qsa_pacc.device_ptr()) as u64 + (t0 * pacb) as u64,
                               (*psc.qstage.device_ptr()) as u64 + (t0 * cfg.num_heads * cfg.head_dim * 4) as u64,
                               (*self.k_cache[att_i].device_ptr()) as u64,
                               (*psc.qsa_sel.device_ptr()) as u64 + (t0 * sel_max * 4) as u64,
                               (*psc.qsa_psel.device_ptr()) as u64 + (t0 * 4) as u64,
                               (*psc.slotpos_rows.device_ptr()) as u64 + (t0 * 2 * 4) as u64,
                               nh_p, g2 as i64, split_hd))?;
                } else {
                    xqlaunch!(l, kname, ((rows * cfg.num_kv_heads * QSA_SPLITS) as u32, 1, 1), (256, 1, 1), 0,
                              ((*psc.qsa_pm.device_ptr()) as u64 + (t0 * pmb) as u64,
                               (*psc.qsa_pl.device_ptr()) as u64 + (t0 * pmb) as u64,
                               (*psc.qsa_pacc.device_ptr()) as u64 + (t0 * pacb) as u64,
                               (*psc.qstage.device_ptr()) as u64 + (t0 * cfg.num_heads * cfg.head_dim * 4) as u64,
                               (*self.k_cache[att_i].device_ptr()) as u64,
                               (*psc.qsa_sel.device_ptr()) as u64 + (t0 * sel_max * 4) as u64,
                               (*psc.qsa_psel.device_ptr()) as u64 + (t0 * 4) as u64,
                               (*psc.slotpos_rows.device_ptr()) as u64 + (t0 * 2 * 4) as u64,
                               nh_p, g2 as i64, split_len as i32))?;
                }
            }
            if let Some((rpm, rpl, racc)) = want {
                self.dev.synchronize()?;
                let (tpm, tpl, tacc) = (self.dev.dtoh_sync_copy(&psc.qsa_pm)?, self.dev.dtoh_sync_copy(&psc.qsa_pl)?,
                                        self.dev.dtoh_sync_copy(&psc.qsa_pacc)?);
                let nd = |x: &[f32], y: &[f32]| x.iter().zip(y).filter(|(p, q)| p.to_bits() != q.to_bits()).count();
                let hd = cfg.head_dim;
                let (dm, dl, da) = (nd(&rpm[a0..a1], &tpm[a0..a1]), nd(&rpl[a0..a1], &tpl[a0..a1]),
                                    nd(&racc[a0 * hd..a1 * hd], &tacc[a0 * hd..a1 * hd]));
                println!("PQ8_XCHECK gather layer {att_i} pos0 {pos0} rows {rows} (t0 {t0}) fmt {}: pq8 vs splitk4 bit-differ pm {dm} pl {dl} pacc {da} of {} / {}{}",
                         kv_fmt_name(self.kv_fmt), a1 - a0, (a1 - a0) * hd,
                         if dm + dl + da == 0 { "" } else { "  <-- MISMATCH" });
            }
        }
        let mut xref: Option<(Vec<f32>, Vec<f32>, Vec<f32>)> = None;
        for kname in ["xq_attn_sel_splitk", "xq_attn_sel_splitk4"] {
            if pq8 { break; }
            let four = kname == "xq_attn_sel_splitk4";
            if four != vec4 && !(xcheck && !four) { continue; }
            xqlaunch!(l, kname, ((rows * cfg.num_kv_heads * QSA_SPLITS) as u32, 1, 1), (256, 1, 1), 0,
                      ((*psc.qsa_pm.device_ptr()) as u64 + (t0 * pmb) as u64,
                       (*psc.qsa_pl.device_ptr()) as u64 + (t0 * pmb) as u64,
                       (*psc.qsa_pacc.device_ptr()) as u64 + (t0 * pacb) as u64,
                       (*psc.qstage.device_ptr()) as u64 + (t0 * cfg.num_heads * cfg.head_dim * 4) as u64,
                       (*self.k_cache[att_i].device_ptr()) as u64,
                       (*psc.qsa_sel.device_ptr()) as u64 + (t0 * sel_max * 4) as u64,
                       (*psc.qsa_psel.device_ptr()) as u64 + (t0 * 4) as u64,
                       (*psc.slotpos_rows.device_ptr()) as u64 + (t0 * 2 * 4) as u64,
                       nh_p, g2 as i64, split_len as i32))?;
            if xcheck && !four {
                self.dev.synchronize()?;
                xref = Some((self.dev.dtoh_sync_copy(&psc.qsa_pm)?, self.dev.dtoh_sync_copy(&psc.qsa_pl)?,
                             self.dev.dtoh_sync_copy(&psc.qsa_pacc)?));
            }
        }
        if let Some((rpm, rpl, racc)) = xref {
            self.dev.synchronize()?;
            let (tpm, tpl, tacc) = (self.dev.dtoh_sync_copy(&psc.qsa_pm)?, self.dev.dtoh_sync_copy(&psc.qsa_pl)?,
                                    self.dev.dtoh_sync_copy(&psc.qsa_pacc)?);
            let (a, b) = (t0 * cfg.num_heads * QSA_SPLITS, (t0 + rows) * cfg.num_heads * QSA_SPLITS);
            let nd = |x: &[f32], y: &[f32]| x.iter().zip(y).filter(|(p, q)| p.to_bits() != q.to_bits()).count();
            let (dm, dl) = (nd(&rpm[a..b], &tpm[a..b]), nd(&rpl[a..b], &tpl[a..b]));
            let da = nd(&racc[a * cfg.head_dim..b * cfg.head_dim], &tacc[a * cfg.head_dim..b * cfg.head_dim]);
            println!("SEL_XCHECK layer {att_i} rows {rows} (t0 {t0}): splitk4 vs splitk bit-differ pm {dm} pl {dl} pacc {da} of {} / {}",
                     b - a, (b - a) * cfg.head_dim);
        }
        xqlaunch!(l, "xq_attn_sel_combine", ((rows * cfg.num_heads) as u32, 1, 1), (cfg.head_dim as u32, 1, 1), 0,
                  ((*psc.normed.device_ptr()) as u64 + (t0 * cfg.num_heads * cfg.head_dim * 2) as u64,
                   (*psc.qsa_pm.device_ptr()) as u64 + (t0 * pmb) as u64,
                   (*psc.qsa_pl.device_ptr()) as u64 + (t0 * pmb) as u64,
                   (*psc.qsa_pacc.device_ptr()) as u64 + (t0 * pacb) as u64,
                   (*psc.qg.device_ptr()) as u64 + (t0 * qrow) as u64,
                   nh_p, QSA_SPLITS as i32, self.rows_kvf(rows)))?;
        Ok(())
    }

    /// PQ8 item 1 (SURPASS_PLAN WP06 item 1): the chunk's K/V append — rows pos0..pos0+c of `slot`
    /// into `cache` (a trunk k_cache, or the MTP head's kv), from psc.kp/psc.vp/psc.cos; the
    /// contract of xq_attn_kv_prefill. Default: the row-parallel twin xq_attn_kv_prefill_rows (grid
    /// c*nkv — every cache byte equal to the serial kernel's); --pq8-kvw=0 / --pq8-off=1 =
    /// the serial kernel (grid nkv). --pq8-xcheck=1 (eager): serial kernel first (reference),
    /// then for poison 0x00 and 0xFF: poison the rows, run the twin, diff every byte.
    #[allow(clippy::too_many_arguments)]
    fn kv_prefill_write(&self, l: &Launcher, psc: &mut PrefillScratch, cache: &CudaSlice<u8>,
                        qnkn: &CudaSlice<u16>, slot: usize, pos0: usize, c: usize, tag: &str) -> Result<()> {
        // TP-B: the trunk caches hold this rank's KV heads; the replicated head's holds all of them.
        let cfg = if self.mtp.as_ref().map_or(false, |hh| std::ptr::eq(cache, &hh.kv)) { &self.cfg } else { &self.tc };
        let (nkv, hd, rdim) = (cfg.num_kv_heads, cfg.head_dim, cfg.rotary_dim);
        let cache_p = *cache.device_ptr() as u64;
        let nkv_hd = (nkv as i32) | ((hd as i32) << 16);
        let rdim_mp = (rdim as i32) | ((self.max_pos as i32) << 8) | ((self.kv_fmt as i32) << 28);
        let slot_pos0: i32 = (slot as i32) | ((pos0 as i32) << 12);
        let rows = pq8_item(0);
        let xcheck = rows && pq8_xcheck() && !self.stream_capturing();
        if !rows || xcheck {
            xqlaunch!(l, "xq_attn_kv_prefill", (nkv as u32, 1, 1), (hd as u32, 1, 1), 0,
                      (&mut psc.kp, &mut psc.vp, cache_p, qnkn, &psc.cos, nkv_hd, rdim_mp, slot_pos0,
                       c as i32, cfg.rms_eps))?;
            if !rows { return Ok(()); }
        }
        if !xcheck {
            xqlaunch!(l, "xq_attn_kv_prefill_rows", ((c * nkv) as u32, 1, 1), (hd as u32, 1, 1), 0,
                      (&mut psc.kp, &mut psc.vp, cache_p, qnkn, &psc.cos, nkv_hd, rdim_mp, slot_pos0,
                       c as i32, cfg.rms_eps))?;
            return Ok(());
        }
        // ---- XCHECK: the 2*nkv row segments (K|V x kv head) of this chunk, as xq_kv_make lays them out
        let rb = kv_rowbytes(self.kv_fmt, hd);
        let seg = |g: usize| (slot * 2 * nkv + g) * self.max_pos * rb + pos0 * rb;
        let snap = |dst: &mut Vec<u8>| -> Result<()> {
            self.dev.synchronize()?;
            dst.resize(2 * nkv * c * rb, 0);
            for g in 0..2 * nkv {
                self.dev.dtoh_sync_copy_into(&cache.slice(seg(g)..seg(g) + c * rb),
                                             &mut dst[g * c * rb..(g + 1) * c * rb])?;
            }
            Ok(())
        };
        let mut want = Vec::new();
        snap(&mut want)?;
        let mut nd = [0usize; 2];
        for (pi, poison) in [0x0000i32, 0xFFFF].into_iter().enumerate() {
            let nh16 = (c * rb / 2) as i64;
            for g in 0..2 * nkv {
                xqlaunch!(l, "xq_memset_u16", (((nh16 + 255) / 256) as u32, 1, 1), (256, 1, 1), 0,
                          (cache_p + seg(g) as u64, nh16, poison))?;
            }
            xqlaunch!(l, "xq_attn_kv_prefill_rows", ((c * nkv) as u32, 1, 1), (hd as u32, 1, 1), 0,
                      (&mut psc.kp, &mut psc.vp, cache_p, qnkn, &psc.cos, nkv_hd, rdim_mp, slot_pos0,
                       c as i32, cfg.rms_eps))?;
            let mut got = Vec::new();
            snap(&mut got)?;
            nd[pi] = want.iter().zip(&got).filter(|(a, b)| a != b).count();
        }
        println!("PQ8_XCHECK kvw {tag} pos0 {pos0} c {c} fmt {}: rows-twin vs serial bytes differ {} (poison 0x00) / {} (poison 0xFF) of {}{}",
                 kv_fmt_name(self.kv_fmt), nd[0], nd[1], want.len(),
                 if nd == [0, 0] { "" } else { "  <-- MISMATCH" });
        Ok(())
    }

    /// PQ8 item 2: the dense-row flash launch (rows [0, t) of the chunk; hd = 256). p5d default:
    /// the bitwise twin xq_attn_prefill_flash256v (PQ8-v2 stages flash256's exact smem image —
    /// .14, 22022ab, binary d9eb3f4f: PQ8_XCHECK flash differ 0 on every layer, f32 and q8; all 8
    /// f32/q8 greedy hashes exact; q8 prefill 2K 995 -> 1,155 tok/s); --pq8-flash=0 =
    /// xq_attn_prefill_flash256. (p3 had it default OFF: v1 was NOT bitwise — p4c @ 6300674 on
    /// .14, 6,039,782 of 12,582,912 halves differ.) --pq8-flash=causal (opt-in, a behaviour
    /// change): xq_attn_prefill_flash256c, the twin with causal K/V staging (flash256 zeroes dims
    /// of the diagonal tile's rows; PQ8-v2 note).
    /// --pq8-xcheck=1 (eager): old kernel first (reference), poison psc.normed rows [0, t)
    /// with f16 NaN (0xFFFF), the twin, diff every f16 of those rows.
    #[allow(clippy::too_many_arguments)]
    fn flash256_launch(&self, l: &Launcher, psc: &mut PrefillScratch, a: &AttnLayer, att_i: usize,
                       slot_pos0: i32, t: usize) -> Result<()> {
        let cfg = self.acfg_i(att_i); // TP-B: per-rank heads (trunk) / global (the replicated head)
        let (nh_a, nkv, hd, rdim) = (cfg.num_heads, cfg.num_kv_heads, cfg.head_dim, cfg.rotary_dim);
        let kc_p = *self.k_cache[att_i].device_ptr() as u64;
        let v = pq8_item(1);
        let causal = v && pq8_flash_causal();
        let xcheck = v && pq8_xcheck() && !self.stream_capturing();
        let twin = if causal { "xq_attn_prefill_flash256c" } else { "xq_attn_prefill_flash256v" };
        let pair = ["xq_attn_prefill_flash256", twin];
        let names: &[&str] = if xcheck { &pair[..] } else if v { &pair[1..] } else { &pair[..1] };
        let n16 = t * nh_a * hd;
        let mut want: Vec<u16> = Vec::new();
        for (ki, &kname) in names.iter().enumerate() {
            if xcheck && ki == 1 {
                self.dev.synchronize()?;
                want = self.dev.dtoh_sync_copy(&psc.normed)?;
                want.truncate(n16);
                xqlaunch!(l, "xq_memset_u16", ((((n16 as i64) + 255) / 256) as u32, 1, 1), (256, 1, 1), 0,
                          (*psc.normed.device_ptr() as u64, n16 as i64, 0xFFFFi32))?;
            }
            xqlaunch!(l, kname, (((t as u32) + 7) / 8, nh_a as u32, 1), (256, 1, 1), 0,
                      (&mut psc.normed, &psc.qg, kc_p, &a.qnkn, &psc.cos, (nkv as i32) | ((nh_a as i32) << 16),
                       (hd as i32) | ((rdim as i32) << 16), self.mpf(), slot_pos0, t as i32, cfg.rms_eps))?;
        }
        if xcheck {
            self.dev.synchronize()?;
            let got = self.dev.dtoh_sync_copy(&psc.normed)?;
            let nd = want.iter().zip(&got[..n16]).filter(|(x, y)| x != y).count();
            println!("PQ8_XCHECK flash layer {att_i} pos0 {} rows {t} fmt {}: {} vs flash256 f16 differ {nd} of {n16}{}",
                     ((slot_pos0 as u32) >> 12), kv_fmt_name(self.kv_fmt), twin.trim_start_matches("xq_attn_prefill_"),
                     if causal { "  (causal staging: differs by design)" } else if nd == 0 { "" } else { "  <-- MISMATCH" });
        }
        Ok(())
    }

    pub fn prefill_chunk(&self, psc: &mut PrefillScratch, toks: &[i32], pos0: usize,
                         slot: usize, want_logits: bool, ld: Option<&LadderCtx>) -> Result<()> {
        let c = toks.len();
        // TP-A rung 3: the chunked prefill MoE (moe_prefill) has no EP filter/reduce site yet —
        // refuse loudly instead of silently mixing a rank's partial into its residual.
        // TP-B: prefill is TP-wired (EP experts + head-sharded mixers + row-parallel reduces).
        let _tc = tune::enter(tune::Ctx::prefill(c)); // TUNE family scope
        let l = Launcher { dev: &self.dev, stream: &self.stream };
        // S-A3-f-g: reconstruct+cuBLASLt handles (env-gated inside exl3_chain_rb).
        let rb = self.recon_bufs(psc);
        let rmin = recon_min_rows();
        let cfg = &self.tc; // TP-B: the trunk's per-rank geometry
        let h = cfg.hidden_size;
        let hcn = cfg.hc_count.max(1);
        let kd = cfg.lin_k_dim;
        let vd = cfg.lin_v_dim;
        let nh = cfg.lin_num_v_heads;
        let nk = cfg.lin_num_k_heads;
        let conv_dim = cfg.key_dim() * 2 + cfg.value_dim();
        let ck = cfg.conv_kernel;
        let theta = cfg.rope_theta;
        let rdim = cfg.rotary_dim;

        let pro = wp05_on("pro") && self.cos_gather_ok && pos0 + c <= self.max_pos
            && psc.wp05.as_ref().map_or(false, |s| s.c >= c)
            && psc.toks.len() >= c && psc.pos_rows.len() >= c && psc.slot_rows.len() >= c
            && psc.slotpos_rows.len() >= 2 * c && psc.cos.len() >= c * 2 * rdim;
        if pro {
            // WP05 prologue: the chunk's tables go through the pinned stage into the PERSISTENT
            // psc buffers with async NULL-stream copies (ordered before the compute stream's
            // kernels by the legacy-stream rule — the same ordering htod_copy_into relied on),
            // and the RoPE rows are a device gather from the load-time cos_tab (bit-identical to
            // the host loop: verified at load, cos_gather_ok). No host drain, no per-chunk
            // allocation, no per-chunk powf/cos/sin loop.
            let has_idx = self.cfg.has_indexer();
            let st = psc.wp05.as_mut().unwrap();
            if st.inflight_tab { self.dev.synchronize()?; st.inflight_tab = false; } // only after an error path
            let cc = st.c;
            st.pin.i32s(0, c).copy_from_slice(toks);
            for (i, x) in st.pin.i32s(4 * cc, c).iter_mut().enumerate() { *x = (pos0 + i) as i32; }
            st.pin.i32s(8 * cc, c).fill(slot as i32);
            {
                let sp = st.pin.i32s(12 * cc, 2 * c);
                for i in 0..c { sp[2 * i] = slot as i32; sp[2 * i + 1] = (pos0 + i) as i32; }
            }
            st.pin.i32s(20 * cc, 1)[0] = (c * cfg.num_experts_per_tok) as i32;
            st.pin.htod(0, *psc.toks.device_ptr() as u64, c * 4)?;
            st.pin.htod(20 * cc, *psc.moerows.device_ptr() as u64, 4)?;
            st.pin.htod(4 * cc, *psc.pos_rows.device_ptr() as u64, c * 4)?;
            if has_idx {
                st.pin.htod(8 * cc, *psc.slot_rows.device_ptr() as u64, c * 4)?;
                st.pin.htod(12 * cc, *psc.slotpos_rows.device_ptr() as u64, c * 8)?;
            }
            st.inflight_tab = true;
            // VIS-2: the mrope-aware gather (text-only slots read cos_tab[pos], unchanged)
            self.cos_gather(&l, &mut psc.cos, *psc.pos_rows.device_ptr() as u64, SlotSrc::Const(slot), c)?;
            if ple_xcheck_on() {
                self.dev.synchronize()?;
                let got = self.dev.dtoh_sync_copy(&psc.cos)?;
                let want = prefill_cossin_host(theta, rdim, pos0, c);
                let nd = got[..want.len()].iter().zip(&want).filter(|(a, b)| a.to_bits() != b.to_bits()).count();
                println!("PLE_XCHECK prefill-rope pos0 {pos0} rows {c}: {nd} mismatching f32 of {}", want.len());
            }
        } else {
        psc.toks = self.dev.htod_sync_copy(toks)?;
        // S-A3-u D: the MoE row count is a per-chunk constant (c * topk) — one upload per chunk.
        self.dev.htod_copy_into(vec![(c * cfg.num_experts_per_tok) as i32], &mut psc.moerows)?;
        // cossin rows for pos0..pos0+c (same layout contract as forward_step)
        let cossin = prefill_cossin_host(theta, rdim, pos0, c);
        psc.cos = self.dev.htod_sync_copy(&cossin)?;
        // S-A3-i: per-row (pos, slot, slot|pos) tables for the bf16 selection kernels
        // (they read LOGICAL positions; the prefill slot is uniform per chunk).
        if self.cfg.has_indexer() {
            let posr: Vec<i32> = (pos0..pos0 + c).map(|p| p as i32).collect();
            psc.pos_rows = self.dev.htod_sync_copy(&posr)?;
            psc.slot_rows = self.dev.htod_sync_copy(&vec![slot as i32; c])?;
            let mut sp: Vec<i32> = Vec::with_capacity(c * 2);
            for p in pos0..pos0 + c { sp.push(slot as i32); sp.push(p as i32); }
            psc.slotpos_rows = self.dev.htod_sync_copy(&sp)?;
        }
        }

        xqlaunch!(l, "xq_embed_resid", (((h * hcn * c) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (&mut psc.resid, &self.embed, &psc.toks, h as i32, hcn as i32, c as i32))?;
        // VIS-2: an image request overwrites its image rows with the tower's merged embeddings
        if psc.vis_img.is_some() {
            anyhow::ensure!(pro, "VIS-2: an image prefill needs the WP05 prologue (the host RoPE fallback has no mrope)");
            anyhow::ensure!(pos0 + c <= psc.vis_src.len(), "VIS-2: chunk {pos0}..{} past the image map ({} rows)",
                            pos0 + c, psc.vis_src.len());
            let rows: Vec<i32> = psc.vis_src[pos0..pos0 + c].to_vec();
            if rows.iter().any(|&r| r >= 0) {
                let mut dst = psc.vis_rows.slice_mut(0..c);
                self.dev.htod_sync_copy_into(&rows, &mut dst)?;
                let img = psc.vis_img.as_ref().unwrap();
                xqlaunch!(l, "xq_splice_rows", (((h * hcn * c) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                         (&mut psc.resid, img, &psc.vis_rows, h as i32, hcn as i32, c as i32))?;
            }
        }
        self.tr_f32(ld, false, 0, &psc.resid, "embed", c)?;
        let mut gdn_i = 0usize;
        let mut att_i = 0usize;
        // A5-P2 prefill.hc_fuse: each hc_post inject is deferred into the next hc_pre's norm
        // (xq_pf_hc_inj_norm). Never with trace dumps (they read resid between the two).
        let pf_defer = self.pf_hc_fuse(&l).0 && ld.is_none();
        let mut pend: Option<u64> = None;
        // TP-I2 item 1 (--tp-prefill-overlap): the deferred inject + the next hc_pre's norm run per
        // landed row range INSIDE the preceding pipelined reduce; `normed` = that already happened, so
        // the next hc_pre_rows_n skips its xq_pf_hc_inj_norm. TP only, and only on the fused-norm path.
        let ov_rows = if pf_defer && self.tp.is_some() { xtp::pf_overlap_rows() } else { 0 };
        let ple_live = self.ple.is_some() && crate::opts::var(crate::opt!("exl3-no-ple")).is_err();
        let mut normed = false;
        // TP-SP1 (--tp-seq-parallel): this rank's row block when the chunk runs sequence-parallel (None =
        // the replicated prefill, every launch below as before). The layer-0 block stays replicated when
        // the PLE follows it (the PLE reads every row of resid at the layer-1 boundary).
        let sp = self.sp_rows_for(psc, c);
        let sp_from = if ple_live { 1 } else { 0 };
        let spl = |li: usize| if li >= sp_from { sp } else { None };
        for (li, layer) in self.layers.iter().enumerate() {
            // S-A3-f-b FIX: PLE injects at the LAYER-1 boundary (decode injects
            // inside the layer loop before block 1's hc_pre) - the pre-loop call
            // put the delta one layer early and poisoned layer 0 from token 0.
            if li == 1 && ple_live {
                // (layer 0's MoE reduce takes no hook when the PLE follows, so `normed` is false here)
                if let Some(y) = pend.take() { self.hc_post_rows(&l, psc, y, c)?; } // A5-P2: PLE reads resid
                self.ple_forward_chunk(&l, psc, toks, slot)?;
            }
            match spl(li) {
                Some(s) => self.hc_pre_rows_sp(&l, psc, &layer.hc_attn, s, pend.take(), std::mem::take(&mut normed), true)?,
                None => self.hc_pre_rows_n(&l, psc, &layer.hc_attn, c, pend.take(), std::mem::take(&mut normed))?,
            }
            self.tr_u16(ld, false, li, &psc.x, &format!("xpre{li}"), c * h)?;
            match &layer.mixer {
                Mixer::Gdn(g) => {
                    exl3_chain_rb(&l, &g.in_qkv, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.qkv, c, &psc.chain_ws, &rb)?;
                    self.tr_u16(ld, true, li, &psc.qkv, &format!("g{li}_qkv"), c * conv_dim)?;
                    exl3_chain_rb(&l, &g.in_z, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.zbuf, c, &psc.chain_ws, &rb)?;
                    self.tr_u16(ld, true, li, &psc.zbuf, &format!("g{li}_z"), c * vd)?;
                    if rmin > 0 && c >= rmin {
                        // S-A3-f-g: the 48-wide a/b projections are the worst
                        // xq_gemm_f16 shape at wide M (one 64-thread block per row,
                        // K-serial loop — nsys: 46.7% of prefill GPU time): route
                        // them through the vendor GEMM (opA=T on the plain f16
                        // [48, K] weights — no reconstruct needed).
                        exl3_lt_matmul(&l, *g.a_w.device_ptr() as u64, *psc.x.device_ptr() as u64,
                                       *psc.a_out.device_ptr() as u64, h as usize, nh,
                                       c, true, rb.ltws, rb.ltws_len)?;
                        exl3_lt_matmul(&l, *g.b_w.device_ptr() as u64, *psc.x.device_ptr() as u64,
                                       *psc.b_out.device_ptr() as u64, h as usize, nh,
                                       c, true, rb.ltws, rb.ltws_len)?;
                    } else {
                        xq_gemm_f16_small!(l, &mut psc.a_out, &g.a_w, &psc.x, c, nh, h)?;
                        xq_gemm_f16_small!(l, &mut psc.b_out, &g.b_w, &psc.x, c, nh, h)?;
                    }
                    self.tr_u16(ld, true, li, &psc.a_out, &format!("g{li}_a"), c * nh)?;
                    self.tr_u16(ld, true, li, &psc.b_out, &format!("g{li}_b"), c * nh)?;
                    if ck <= 8 && tune::get_cur(&T_PF_CONV_PAR) != 0 {
                        // A5 D17: parallel (token, channel) conv into chain_xh (dead between chains),
                        // ring advance from the intact inputs, then copy back — bit-identical to the
                        // serial per-channel loop (4.1 s of a 128K prefill). --exl3-conv-serial = old.
                        let st_p = (*self.conv_state[gdn_i].device_ptr()) as u64;
                        let n = (c * conv_dim) as i64;
                        xqlaunch!(l, "xq_conv1d_chunk_par", (((n + 255) / 256) as u32, 1, 1), (256, 1, 1), 0,
                                  (&mut psc.chain_xh, &psc.qkv, st_p, &g.conv_w,
                                   conv_dim as i32, ck as i32, c as i32, slot as i32, conv_dim as i32))?;
                        xqlaunch!(l, "xq_conv1d_state_upd", ((conv_dim as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                                  (st_p, &psc.qkv, conv_dim as i32, ck as i32, c as i32, slot as i32, conv_dim as i32))?;
                        xqlaunch!(l, "xq_copy_u16", (((n + 255) / 256) as u32, 1, 1), (256, 1, 1), 0,
                                  (&mut psc.qkv, &psc.chain_xh, n, 0i64, 0i64))?;
                    } else {
                    xqlaunch!(l, "xq_conv1d_chunk", ((conv_dim as u32 + 255) / 256, 1, 1), (256, 1, 1), 0,
                             (&mut psc.qkv, (*self.conv_state[gdn_i].device_ptr()) as u64, &g.conv_w,
                              conv_dim as i32, ck as i32, c as i32, slot as i32, conv_dim as i32))?;
                    }
                    self.tr_u16(ld, true, li, &psc.qkv, &format!("g{li}_conv"), c * conv_dim)?;
                    let tc_min = gdn_tc_min_rows();
                    let tc = if tc_min > 0 && c >= tc_min && kd == 128 && vd == 128 {
                        // A5-L1 prefill.gdn_scan: the re-scheduled bitwise twin xq_gdn_chunk_tc2
                        let v2 = tune::get(&T_PF_GDN_SCAN, &l.cx()) != 0;
                        static SEEN: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);
                        if SEEN.swap(1 + v2 as u8, std::sync::atomic::Ordering::Relaxed) != 1 + v2 as u8 {
                            println!("A5-L1 prefill gdn: scan={} ({})", v2 as u8,
                                     if v2 { "xq_gdn_chunk_tc2 wavefront solve + prefetch" } else { "xq_gdn_chunk_tc" });
                        }
                        gdn_chunk_tc_fn(v2)
                    } else { None };
                    // S-A3-v --exl3-gdn-xcheck: the sequential scan on a copy of this slot's state
                    // (twin core rows), diffed against the chunkwise scan below — per-layer error.
                    let gx = if tc.is_some() && crate::opts::var(crate::opt!("exl3-gdn-xcheck")).is_ok() {
                        let ns = nh * kd * vd;
                        let mut st2 = self.dev.alloc_zeros::<f32>(ns)?;
                        let mut core2 = self.dev.alloc_zeros::<u16>(c * nh * vd)?;
                        xqlaunch!(l, "xq_copy_f32", (((ns + 255) / 256) as u32, 1, 1), (256, 1, 1), 0,
                                  (&mut st2, (*self.s_state[gdn_i].device_ptr()) as u64, ns as i64, 0i64, (slot * ns) as i64))?;
                        let smem = (kd * 33 + kd + 32 * 3 + kd * 2) * 4;
                        xqlaunch!(l, "xq_gdn_step_chunk", ((nh * (vd / 32)) as u32, 1, 1), (kd as u32, 1, 1), smem as u32,
                                 (&mut core2, &psc.qkv, (*st2.device_ptr()) as u64,
                                  &psc.b_out, &psc.a_out, (nh | (nk << 16)) as i32, kd as i32, vd as i32,
                                  &g.a_log, &g.dt_bias, (c as i32) << 12, 0u64))?;
                        Some((st2, core2))
                    } else { None };
                    if let Some(f) = tc {
                        // S-A3-v: chunkwise-parallel scan (tensor cores; f32 state master in registers).
                        let mut a_core = *psc.core.device_ptr() as u64;
                        let mut a_qkv = *psc.qkv.device_ptr() as u64;
                        let mut a_st = *self.s_state[gdn_i].device_ptr() as u64;
                        let mut a_b = *psc.b_out.device_ptr() as u64;
                        let mut a_a = *psc.a_out.device_ptr() as u64;
                        let mut a_alog = *g.a_log.device_ptr() as u64;
                        let mut a_dtb = *g.dt_bias.device_ptr() as u64;
                        let mut a_nhnk = (nh | (nk << 16)) as i32;
                        let mut a_slot = slot as i32;
                        let mut a_n = c as i32;
                        let mut args: [*mut std::ffi::c_void; 10] = [
                            &mut a_core as *mut u64 as *mut _, &mut a_qkv as *mut u64 as *mut _,
                            &mut a_st as *mut u64 as *mut _, &mut a_b as *mut u64 as *mut _,
                            &mut a_a as *mut u64 as *mut _, &mut a_alog as *mut u64 as *mut _,
                            &mut a_dtb as *mut u64 as *mut _, &mut a_nhnk as *mut i32 as *mut _,
                            &mut a_slot as *mut i32 as *mut _, &mut a_n as *mut i32 as *mut _,
                        ];
                        let r = unsafe {
                            cudarc::driver::sys::cuLaunchKernel(f, (nh * (vd / GTC_VC)) as u32, 1, 1, 256, 1, 1,
                                GTC_SMEM as u32, self.stream.stream, args.as_mut_ptr(), std::ptr::null_mut())
                        };
                        anyhow::ensure!(r == cudarc::driver::sys::CUresult::CUDA_SUCCESS,
                                        "xq_gdn_chunk_tc launch failed ({r:?})");
                        if let Some((st2, core2)) = gx.as_ref() {
                            self.dev.synchronize()?;
                            let ns = nh * kd * vd;
                            let sa = self.dev.dtoh_sync_copy(st2)?;
                            let sb = self.dev.dtoh_sync_copy(&self.s_state[gdn_i])?;
                            let ca = self.dev.dtoh_sync_copy(core2)?;
                            let cb = self.dev.dtoh_sync_copy(&psc.core)?;
                            let stat = |x: &mut dyn Iterator<Item = (f32, f32)>| {
                                let (mut d2, mut r2, mut mx) = (0f64, 0f64, 0f32);
                                for (p, q) in x { d2 += ((p - q) as f64).powi(2); r2 += (p as f64).powi(2); mx = mx.max((p - q).abs()); }
                                ((d2 / r2.max(1e-30)).sqrt(), mx)
                            };
                            let (sr, sm) = stat(&mut sa.iter().zip(&sb[slot * ns..(slot + 1) * ns]).map(|(p, q)| (*p, *q)));
                            let (cr, cm) = stat(&mut ca.iter().zip(&cb[..c * nh * vd])
                                .map(|(p, q)| (half::f16::from_bits(*p).to_f32(), half::f16::from_bits(*q).to_f32())));
                            println!("GDN_XCHECK layer {li} pos0 {pos0} C {c}: core relL2 {cr:.3e} max {cm:.3e} | state relL2 {sr:.3e} max {sm:.3e}");
                        }
                    } else {
                    let nchunk = vd / 32;
                    let smem = (kd * 33 + kd + 32 * 3 + kd * 2) * 4;
                    // 12-arg cap: slot_C = slot | C<<12
                    let slot_c: i32 = (slot as i32) | ((c as i32) << 12);
                    xqlaunch!(l, "xq_gdn_step_chunk", ((nh * nchunk) as u32, 1, 1), (kd as u32, 1, 1), smem as u32,
                             (&mut psc.core, &psc.qkv, (*self.s_state[gdn_i].device_ptr()) as u64,
                              &psc.b_out, &psc.a_out, (nh | (nk << 16)) as i32, kd as i32, vd as i32,
                              &g.a_log, &g.dt_bias, slot_c, 0u64))?;
                    }
                    self.tr_u16(ld, true, li, &psc.core, &format!("g{li}_core"), c * vd)?;
                    xqlaunch!(l, "xq_gdn_gate", ((c * nh) as u32, 1, 1), (vd as u32, 1, 1), (vd * 4) as u32,
                             (&mut psc.normed, &psc.core, &psc.zbuf, &g.norm, vd as i32, nh as i32, c as i32, cfg.rms_eps))?;
                    self.tr_u16(ld, true, li, &psc.normed, &format!("g{li}_gate"), c * vd)?;
                    let hk = self.pf_hook(psc, &layer.hc_mlp, *psc.mixer_out.device_ptr() as u64, ov_rows);
                    normed = self.chain_o_rb(&l, &g.out_proj, &psc.normed, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.mixer_out, c, &psc.chain_ws, &rb, hk, spl(li))?; // TP-B: row-parallel -> all-reduce (TP-SP: reduce-scatter)

                    gdn_i += 1;
                }
                Mixer::Attn(a) => {
                    exl3_chain_rb(&l, &a.q_proj, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.qg, c, &psc.chain_ws, &rb)?;
                    exl3_chain_rb(&l, &a.k_proj, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.kp, c, &psc.chain_ws, &rb)?;
                    exl3_chain_rb(&l, &a.v_proj, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.vp, c, &psc.chain_ws, &rb)?;
                    let nh_a = cfg.num_heads;
                    let nkv = cfg.num_kv_heads;
                    let hd = cfg.head_dim;
                    // 12-arg cap packing (see kernel headers)
                    let slot_pos0: i32 = (slot as i32) | ((pos0 as i32) << 12);
                    // PQ8 item 1: row-parallel K/V append (bit-identical; --pq8-kvw=0 = serial)
                    self.kv_prefill_write(&l, psc, &self.k_cache[att_i], &a.qnkn, slot, pos0, c,
                                          &format!("layer {att_i}"))?;
                    // S-A3-i: QSA straddle. Rows whose visible position exceeds
                    // qsa_limit() ride the selection path (the model spec past the
                    // threshold — the seam contract needs prefill and decode to agree);
                    // rows at/below stay on the dense kernels, bit-identical to the
                    // pre-port engine. `t` = first sparse row.
                    let t = if a.idx.is_some() && self.qsa_live(pos0 + c - 1) {
                        let lim = self.qsa_limit();
                        if pos0 > lim { 0 } else { (lim + 1 - pos0).min(c) }
                    } else { c };
                    // S-A3-f-g: flash-style prefill attention (speed directive,
                    // owner 2026-09-21). One block per 16-row q-tile with SMEM
                    // K/V staging vs the sweep's one-block-per-head serial
                    // loop. --attn-flash=0 or c<16 keeps the sweep kernel.
                    // S-A3-u A: the hd=256 flash kernel tiles 8 q rows and masks rows >= C at the
                    // store, so it serves ANY t >= 1 (the t >= 16 gate was the 16-row hd=128
                    // kernel's); the per-head serial sweep cost 9.6 ms for 4 rows. The tile's
                    // unmasked tail rows read cache positions < pos0+8, so keep that in range.
                    // Only DEEP tails take it (pos0 >= 256): the sweep's cost is its serial walk over
                    // pos0+t positions, ~free near 0, and it is the decode-softmax class — a short
                    // prompt's chunk on flash drifts ~5x more (ids16 GDN maxd 2.86 -> 13.7) and moved
                    // its greedy text (served ids16 d5 3.90 -> 3.65 tok/round on different text).
                    let flash = (if hd == 256 { t >= 16 || (t >= 1 && pos0 >= 256 && pos0 + 8 <= self.max_pos) }
                                 else { t >= 16 })
                        && (hd == 128 || hd == 256)
                        && !matches!(crate::opts::var(crate::opt!("attn-flash")).as_deref(), Ok("0"));
                    if t > 0 {
                        if flash && hd == 256 {
                            // S-A3-f-d night: hd=256 instantiation (BT=8/BKV=16).
                            // The 128-shape kernel silently corrupted hd=256 packs
                            // (SMEM OOB + half-staged dims) — see the kernel note.
                            // PQ8 item 2: the bitwise flash256v twin by default; --pq8-flash=0 =
                            // flash256, =causal = flash256c (opt-in, output-changing).
                            self.flash256_launch(&l, psc, a, att_i, slot_pos0, t)?;
                        } else if flash && hd == 128 && pq8_item(1) && pq8_flash_causal() {
                            // w5/PFIX (opt-in, output-changing — the same --pq8-flash=causal switch
                            // as flash256c): the hd=128 causal-staging flash twin. Default: hd=128 keeps
                            // the sweep below (xq_attn_prefill_flash, the defective scalar hd=128 flash,
                            // has had no caller since 2463afc).
                            xqlaunch!(l, "xq_attn_prefill_flash128c", (((t as u32) + 15) / 16, nh_a as u32, 1), (512, 1, 1), 0,
                                 (&mut psc.normed, &psc.qg, (*self.k_cache[att_i].device_ptr()) as u64,
                                  &a.qnkn, &psc.cos, (nkv as i32) | ((nh_a as i32) << 16),
                                  (hd as i32) | ((rdim as i32) << 16), self.mpf(),
                                  slot_pos0, t as i32, cfg.rms_eps))?;
                        } else {
                            // S-A3-q FIX: this was `else if flash`, so a chunk with fewer than
                            // 16 dense rows (every tail chunk < 16 tokens, and the QSA-straddle
                            // chunk whose dense part t < 16) ran NO attention for those rows —
                            // psc.normed held stale scratch (prefillx: first-token MISMATCH past
                            // the QSA limit). The sweep kernel serves every non-flash case.
                            xqlaunch!(l, "xq_attn_prefill_q", (nh_a as u32, 1, 1), (hd as u32, 1, 1), 0,
                                 (&mut psc.normed, &psc.qg, (*self.k_cache[att_i].device_ptr()) as u64,
                                  &a.qnkn, &psc.cos, (nkv as i32) | ((nh_a as i32) << 16),
                                  (hd as i32) | ((rdim as i32) << 16), self.mpf(),
                                  slot_pos0, t as i32, cfg.rms_eps))?;
                        }
                    }
                    if t < c {
                        self.qsa_attn_prefill_rows(&l, psc, a, att_i, slot, pos0, t, c)?;
                    } else {
                        // S-A3-r FIX: fully-dense chunk — still append its raw indexer keys.
                        self.qsa_keys_append_dense_rows(&l, psc, a, att_i, slot, pos0, c)?;
                    }
                    let hk = self.pf_hook(psc, &layer.hc_mlp, *psc.mixer_out.device_ptr() as u64, ov_rows);
                    normed = self.chain_o_rb(&l, &a.o_proj, &psc.normed, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.mixer_out, c, &psc.chain_ws, &rb, hk, spl(li))?; // TP-B: row-parallel -> all-reduce (TP-SP: reduce-scatter)
                    att_i += 1;
                }
            }
            let yatt_p = *psc.mixer_out.device_ptr() as u64;
            if pf_defer { pend = Some(yatt_p); } else { self.hc_post_rows_sp(&l, psc, yatt_p, c, spl(li))?; }
            self.tr_f32(ld, false, li, &psc.resid, &format!("rmid{li}"), c)?;
            self.tr_u16(ld, false, li, &psc.mixer_out, &format!("yatt{li}"), c * h)?;
            match spl(li) {
                Some(s) => self.hc_pre_rows_sp(&l, psc, &layer.hc_mlp, s, pend.take(), std::mem::take(&mut normed), true)?,
                None => self.hc_pre_rows_n(&l, psc, &layer.hc_mlp, c, pend.take(), std::mem::take(&mut normed))?,
            }
            self.tr_u16(ld, false, li, &psc.x, &format!("xpre_mlp{li}"), c * h)?;
            self.tr_f32(ld, false, li, &psc.inj, &format!("inj{li}"), c)?;
            // TP-I2 item 1: the MoE reduce's consumer is the NEXT hc_pre (the next layer's hc_attn, or
            // the final mixer) — except before layer 1 when the PLE sits between (it reads resid).
            let next_hc = self.layers.get(li + 1).map_or(&self.hc_mixer, |nl| &nl.hc_attn);
            psc.pf_hook = if li == 0 && ple_live { None }
                          else { self.pf_hook(psc, next_hc, *psc.moe_out.device_ptr() as u64, ov_rows) };
            psc.pf_hooked = false;
            psc.sp_rows = spl(li); // TP-SP: the EP combine reduce-scatters into the own rows
            let r = self.moe_prefill(&l, psc, &layer.moe, c, &rb);
            psc.sp_rows = None;
            r?;
            normed = std::mem::take(&mut psc.pf_hooked);
            psc.pf_hook = None;
            self.tr_u16(ld, false, li, &psc.moe_out, &format!("ymlp{li}"), c * h)?;
            self.tr_u16(ld, false, li, &psc.ysh, &format!("ysh{li}"), c * h)?;
            self.tr_u16(ld, false, li, &psc.yd, &format!("yd{li}"), c * cfg.num_experts_per_tok * h)?;
            let ymlp_p = *psc.moe_out.device_ptr() as u64;
            if pf_defer { pend = Some(ymlp_p); } else { self.hc_post_rows_sp(&l, psc, ymlp_p, c, spl(li))?; }
            // TP-SP2 G-T1-b fault injection (--xtp-sp-fault, the xtp probe's sequence-parallel run on ONE
            // rank only): perturb one OWN row of the streams by one ulp — the redesigned gate must fire
            if let (Some(s), Some(spd)) = (spl(li), ld.and_then(|x| x.sp.as_ref())) {
                if spd.fault_layer == Some(li) { self.sp_fault_flip(psc, s.own.0, li)?; }
            }
            self.tr_f32(ld, false, li, &psc.resid, &format!("layer{li}"), c)?;
        }
        // final mixer over all rows (resid streams), then the LAST row through
        // lm_head (the only logits prefill needs).
        self.tr_f32(ld, false, 0, &psc.resid, "precollapse", c)?;
        match sp {
            // TP-SP: the final mix on the own rows; x is gathered only when the last row's logits are wanted
            Some(s) => self.hc_pre_rows_sp(&l, psc, &self.hc_mixer, s, pend.take(), std::mem::take(&mut normed), want_logits)?,
            None => self.hc_pre_rows_n(&l, psc, &self.hc_mixer, c, pend.take(), std::mem::take(&mut normed))?,
        }
        self.tr_u16(ld, false, 0, &psc.x, "finalmix", c * h)?;
        if want_logits {
            // copy row c-1 of psc.x into psc.x_last (compute-stream kernel), then
            // the 1-row chain + argmax. Interleaved chunks skip the vocab head.
            xqlaunch!(l, "xq_copy_row", (((h as u32) + 255) / 256, 1, 1), (256, 1, 1), 0,
                     (&mut psc.x_last, &psc.x, ((c - 1) * h) as i64, h as i32))?;
            pf_chain_check(&self.lm_head, 1, &psc.chain_xh, &psc.chain_yraw)?; // PFX1 (c): m = 1, N = vocab
            exl3_chain(&l, &self.lm_head, &psc.x_last, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.logits, 1, &psc.chain_ws)?;
            let v = cfg.vocab_size;
            xqlaunch!(l, "xq_argmax", (1, 1, 1), (1024, 1, 1), (1024 * 12) as u32,
                     (&mut psc.argmax, 0i32, &psc.logits, 0i64, v as i32))?;
            self.tr_u16(ld, false, 0, &psc.logits, "logits", v)?;
        }
        // S-A3-t: fill the MTP draft head's KV for this chunk's prompt positions (AGENTS §2.6:
        // the head attends over the prompt; before this it saw ZEROS for every prompt position).
        if let Some(head) = self.mtp.as_ref() {
            if crate::opts::var(crate::opt!("exl3-head-fill")).as_deref() != Ok("0") {
                if let (Some(s), Some(tp)) = (sp, self.tp.as_ref()) {
                    // TP-SP: the head fill reads the final streams of EVERY row (shifted by one): gather
                    // the peer's rows of resid once per chunk (a bit copy; its guard below is the fill's)
                    let rw = h * hcn;
                    if psc.hfill_s.len() >= c * rw {
                        tp.sp_all_gather(&l, *psc.resid.device_ptr() as u64, rw * 4, &s)?;
                    }
                }
                // TP-SP2 G-T1-b: the final streams every row of the head fill reads (gathered under SP)
                // and the carry it leaves (WP16 checkpoints it; the seam prime reads it) — digested only
                // in the redesigned gate's runs (ld.sp), so the replicated G-T1-b is unchanged
                if ld.map_or(false, |x| x.sp.is_some()) { self.tr_f32(ld, false, 0, &psc.resid, "streams", c)?; }
                self.head_fill_rows(&l, psc, head, slot, pos0, c)?;
                if ld.map_or(false, |x| x.sp.is_some()) { self.tr_f32(ld, false, 0, &psc.hfill_carry, "hcarry", 1)?; }
            }
        }
        self.dev.synchronize()?;
        // WP05: the NULL-stream sync retired every pinned-stage copy of this chunk
        if let Some(st) = psc.wp05.as_mut() { st.inflight_tab = false; st.inflight_ple = false; }
        Ok(())
    }

    /// S-A3-t: CHUNKED fill of the MTP draft head's KV cache over prompt rows [pos0, pos0+c) —
    /// the reference implementation's MTP-layer prefill (`draft_model.prefill` over every prompt token with the
    /// shifted target hidden). Position p gets the head's K/V computed from (trunk streams at
    /// p-1, token p) — the same pairing the draft passes use (tap that predicted b, b) — with
    /// the previous chunk's last trunk row carried across chunks and zeros at p = 0 (the reference implementation's
    /// carry). Only the head's entry + hc_attn pre-mix + k/v projections run: its KV depends on
    /// nothing downstream (no attention, MoE or logits). All wide-M launches, no per-token loop.
    /// Runs after the trunk's final mixer: it overwrites psc.resid/hn/x (nothing reads them after
    /// a chunk returns). The serve's single last-position prime (head_prime) is unchanged.
    fn head_fill_rows(&self, l: &Launcher, psc: &mut PrefillScratch, head: &DraftHead,
                      slot: usize, pos0: usize, c: usize) -> Result<()> {
        let cfg = &self.cfg;
        let h = cfg.hidden_size;
        let hcn = cfg.hc_count.max(1);
        let rw = h * hcn;
        if psc.hfill_s.len() < c * rw { return Ok(()); }
        let rb = self.recon_bufs(psc);
        let g = |n: usize| (((n as u32) + 255) / 256, 1u32, 1u32);
        // 1. shifted trunk streams: row 0 = carry (zero at the prompt start), rows 1.. = resid rows 0..c-2
        if pos0 == 0 {
            xqlaunch!(l, "xq_memset_f32", g(rw), (256, 1, 1), 0, (&psc.hfill_carry, 0i64, rw as i64))?;
        }
        xqlaunch!(l, "xq_copy_f32", g(rw), (256, 1, 1), 0,
                  (&mut psc.hfill_s, &psc.hfill_carry, rw as i64, 0i64, 0i64))?;
        if c > 1 {
            xqlaunch!(l, "xq_copy_f32", g((c - 1) * rw), (256, 1, 1), 0,
                      (&mut psc.hfill_s, &psc.resid, ((c - 1) * rw) as i64, rw as i64, 0i64))?;
        }
        xqlaunch!(l, "xq_copy_f32", g(rw), (256, 1, 1), 0,
                  (&mut psc.hfill_carry, &psc.resid, rw as i64, 0i64, ((c - 1) * rw) as i64))?;
        // 2. entry (head_launches' exact sequence at m = c rows): norm(hidden) -> fc_hidden;
        //    embed -> norm -> fc_embed; streams = sum (f32)
        xqlaunch!(l, "xq_hc_norm", ((hcn * c) as u32, 1, 1), (1024, 1, 1), 4096,
                  (&mut psc.hn, &psc.hfill_s, &head.pre_fc_norm_hidden, h as i32, hcn as i32, c as i32, cfg.rms_eps))?;
        exl3_chain_rb(l, &head.fc_hidden, &psc.hn, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.hfill_a,
                      c * hcn, &psc.chain_ws, &rb)?;
        xqlaunch!(l, "xq_embed_resid", (((rw * c) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                  (&mut psc.hfill_s, &self.embed, &psc.toks, h as i32, hcn as i32, c as i32))?;
        xqlaunch!(l, "xq_hc_norm", ((hcn * c) as u32, 1, 1), (1024, 1, 1), 4096,
                  (&mut psc.hn, &psc.hfill_s, &head.pre_fc_norm_embedding, h as i32, hcn as i32, c as i32, cfg.rms_eps))?;
        exl3_chain_rb(l, &head.fc_embed, &psc.hn, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.hfill_b,
                      c * hcn, &psc.chain_ws, &rb)?;
        xqlaunch!(l, "xq_add_f16_f32", (((rw * c) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                  (&mut psc.resid, &psc.hfill_a, &psc.hfill_b, (rw * c) as i64))?;
        // 3. the head block's pre-attention mix, then k/v and the cache write (slot, main positions)
        self.hc_pre_rows(l, psc, &head.hc_attn, c)?;
        let a = &head.attn;
        // head QSA: the head's raw indexer keys over the prompt rows (spec state on every forward)
        self.qsa_keys_append_dense_rows(l, psc, a, HEAD_ATT, slot, pos0, c)?;
        exl3_chain_rb(l, &a.k_proj, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.kp, c, &psc.chain_ws, &rb)?;
        exl3_chain_rb(l, &a.v_proj, &psc.x, &mut psc.chain_xh, &mut psc.chain_yraw, &mut psc.vp, c, &psc.chain_ws, &rb)?;
        // PQ8 item 1: row-parallel K/V append into the head's cache (--pq8-kvw=0 = serial)
        self.kv_prefill_write(l, psc, &head.kv, &a.qnkn, slot, pos0, c, "head")?;
        Ok(())
    }

    /// S-A3-t: prompt prefill for the MTP harnesses. None = token-by-token forward_step over the
    /// whole prompt; Some(C) = the served posture — chunked sweeps over prompt[..n-1], then the
    /// last token through forward_step (its argmax and tap feed round 1). sc.argmax holds the
    /// first generated token afterwards in both postures.
    pub fn prefill_prompt(&self, sc: &mut Scratch, prompt: &[u32], chunk: Option<usize>,
                          psc: &mut Option<PrefillScratch>) -> Result<()> {
        let n = prompt.len();
        anyhow::ensure!(n > 0, "empty prompt");
        match chunk.filter(|&c| c > 0) {
            Some(cw) => {
                if psc.as_ref().map_or(true, |p| p.c < cw) { *psc = Some(self.prefill_scratch(cw)?); }
                let ps = psc.as_mut().unwrap();
                let mut pos = 0usize;
                while pos < n - 1 {
                    let end = (pos + cw).min(n - 1);
                    let toks: Vec<i32> = prompt[pos..end].iter().map(|&t| t as i32).collect();
                    self.prefill_chunk(ps, &toks, pos, 0, false, None)?;
                    pos = end;
                }
                self.forward_step(sc, &[prompt[n - 1] as i32], &[n - 1], &[0], None)?;
            }
            None => {
                for (i, t) in prompt.iter().enumerate() {
                    self.forward_step(sc, &[*t as i32], &[i], &[0], None)?;
                }
            }
        }
        Ok(())
    }

    /// S-A3-u: startup warm-up — dummy prefill chunks at the given widths on `slot`, then
    /// `reset_slot`. cuBLASLt loads its kernels lazily and plans heuristics per (k, n, m) on first
    /// use; on a fresh process that was ~0.42 s of the FIRST prefill (0.33 + 0.09 s gaps before
    /// the first nvjet launches). Standard serve practice: pay it at startup, not on request 1.
    /// State-neutral: every per-slot plane is restored by reset_slot, and K/V + indexer keys are
    /// rewritten before any later read of those positions.
    pub fn prefill_warmup(&self, psc: &mut PrefillScratch, slot: usize, widths: &[usize]) -> Result<()> {
        let t0 = std::time::Instant::now();
        // TP-4S2: where SP is live (world 2 or 4), RAGGED split chunks join the list (see sp_warmup_extra).
        // The decision reads only state every rank agreed at boot (flag, transport, world), never a per-rank
        // probe, so every rank runs the identical list and the exchanges stay SPMD.
        let mut all: Vec<usize> = widths.to_vec();
        if self.sp_warmup_live() { all.extend(Self::sp_warmup_extra(widths)); }
        let mut per_ms: Vec<u32> = Vec::with_capacity(all.len());
        for (i, &w) in all.iter().enumerate() {
            let tw = std::time::Instant::now();
            let w = w.min(psc.c).max(1);
            // PFX1 (e): the full-width chunk records the prefill's cuBLASLt shape families
            let rec = i == 0 && w == psc.c && pfx1_on(PFX1_LTPLANS);
            if rec {
                LT_REC.lock().unwrap().clear();
                LT_REC_ON.store(true, std::sync::atomic::Ordering::Relaxed);
            }
            let toks = vec![1i32; w];
            let r = self.prefill_chunk(psc, &toks, 0, slot, false, None);
            if rec {
                LT_REC_ON.store(false, std::sync::atomic::Ordering::Relaxed);
                let recs = std::mem::take(&mut *LT_REC.lock().unwrap());
                let fams: Vec<(usize, usize, bool, usize, usize)> = recs.iter()
                    .filter(|r| r.2 % w == 0)
                    .map(|&(k, n, m, ta, ws)| (k, n, ta, m / w, ws))
                    .collect();
                *LT_FAMILIES.lock().unwrap() = Some((fams, w));
            }
            r?;
            self.reset_slot(slot)?;
            self.dev.synchronize()?;
            per_ms.push(tw.elapsed().as_millis().min(u32::MAX as u128) as u32);
        }
        self.dev.synchronize()?;
        println!("EXL3 prefill warm-up: widths {:?} in {:.2} s (cuBLASLt kernels + plans loaded before the first request; \
                  per-chunk ms {:?})", all, t0.elapsed().as_secs_f32(), per_ms);
        Ok(())
    }

    /// TP-4S2: the sequence-parallel split is live for this model (world 2 or 4, --tp-seq-parallel on, the
    /// pipelined transport up, not composed with the overlap fold) — the conditions of `sp_rows_for` that are
    /// agreed across ranks at boot. Deliberately NOT the per-width pinned-plan probe (rank-local).
    fn sp_warmup_live(&self) -> bool {
        self.tp.as_ref().map_or(false, |tp| xtp::seq_parallel_on() && tp.sp_ready() && !xtp::pf_overlap_fold())
    }

    /// TP-4S2: extra warm-up widths that make the first SERVED split chunk's one-time costs land at boot.
    /// The base list (full width, 512, 160, ...) is all multiples of 4, so every split chunk it runs has
    /// EQUAL row blocks and a chunk width that is a clean multiple of the quarter. A served chunk is the
    /// prompt length minus the seam token: RAGGED blocks (c = 2018 splits 505/505/505/503), with its own
    /// c-keyed state (cuBLASLt reference + pinned hc plans at quarter m, exchange programs, kernel picks by
    /// M class) that the clean widths never touch. Four widths, none a multiple of 4, each in the split
    /// range [SP_MIN_ROWS, min(C, SP_MAX_ROWS)] and not already in the list: C - 30 (the ~2K-token request
    /// class, c = 2018 at C = 2048), about C/2, about C/7 + 8, and SP_MIN_ROWS + 3. Residues mod 4 are mixed
    /// (2, 1, 3, 3) so world 4 sees ragged quarters and world 2 sees odd halves. Pure: depends only on the
    /// base list (C = its largest entry). Costs about one extra 2K chunk of boot (~1 s at C = 2048).
    pub fn sp_warmup_extra(base: &[usize]) -> Vec<usize> {
        let c = base.iter().copied().max().unwrap_or(0);
        // the largest w' <= w with w' % 4 == r
        let ragged = |w: usize, r: usize| w.saturating_sub((w + 4 - r) % 4);
        let (lo, hi) = (xtp::SP_MIN_ROWS, c.min(xtp::SP_MAX_ROWS));
        let mut out: Vec<usize> = Vec::new();
        for (w, r) in [(c.saturating_sub(30), 2usize), (c / 2, 1), (c / 7 + 8, 3), (xtp::SP_MIN_ROWS + 3, 3)] {
            let w = ragged(w, r);
            if (lo..=hi).contains(&w) && w % 4 != 0 && !base.contains(&w) && !out.contains(&w) { out.push(w); }
        }
        out
    }

    /// Warm-up widths for a chunk width C: the full chunk plus representative tails (cuBLASLt picks
    /// kernels by M range; tails of arbitrary length take other kernels than the full chunk).
    /// PFX1 (f): + width 16 — the c <= 16 tail class (split-K decode-arm chains, xq_gemm_f16
    /// hc/ab, and the head fc chains at 4c = 64 rows through cuBLASLt) loads before request 1.
    pub fn prefill_warmup_widths(c: usize) -> Vec<usize> {
        let mut v = vec![c];
        for w in [512usize, 160, 32] { if w < c { v.push(w); } }
        if pfx1_on(PFX1_W16) && 16 < c { v.push(16); }
        v
    }

    /// PFX1 (e): pre-populate the cuBLASLt plan cache for EVERY chunk row count 1..=C of every
    /// shape family the warm-up's full-width chunk recorded (m = mult * c: the m = c chains, the
    /// hc / PLE / a,b projections, and the head fc chains at m = 4c), wherever m >= the recon
    /// threshold — ascending c, so the short prompts (the TTFT-critical ones) are ready first.
    /// A first-seen prompt length paid +2.5..+10 ms of heuristics on its tail chunk (B3: 258.4
    /// vs 248.5 ms at m = 72). BITWISE: a plan is a pure function of (k, n, m, ta, workspace), so
    /// the pre-built plan is the one the lazy path would build (the lazy path stays as the
    /// fallback for anything not yet built). Runs on its own thread with its own cuBLASLt handle:
    /// host-side descriptor + heuristic calls only (no stream work, no device allocation); the
    /// plan-cache mutex is taken only to probe and insert, never across a heuristic. Returns the
    /// thread (the bench joins it; the serve detaches it and logs completion).
    pub fn lt_prewarm_start(&self) -> Option<std::thread::JoinHandle<()>> {
        if !pfx1_on(PFX1_LTPLANS) { return None; }
        let (fams, cmax) = LT_FAMILIES.lock().unwrap().take()?;
        let rmin = recon_min_rows();
        if fams.is_empty() || rmin == 0 { return None; }
        let dev = self.dev.clone();
        let nf = fams.len();
        let spawned = std::thread::Builder::new().name("pfx1-ltplans".into()).spawn(move || {
            let t0 = std::time::Instant::now();
            if let Err(e) = dev.bind_to_thread() {
                println!("PFX1: ltplans: bind_to_thread failed ({e:?}) — prefill plans stay lazy");
                return;
            }
            let handle = match lt::create_handle() {
                Ok(h) => h,
                Err(e) => { println!("PFX1: ltplans: cublasLtCreate failed ({e:?}) — prefill plans stay lazy"); return; }
            };
            let (mut built, mut had, mut lost) = (0usize, 0usize, 0usize);
            'rows: for c in 1..=cmax {
                for &(k, n, ta, mult, ws) in &fams {
                    let m = mult * c;
                    if m < rmin { continue; }
                    let key: LtKey = (k, n, m, ta as u8);
                    if lt_plans().lock().unwrap().contains_key(&key) { had += 1; continue; }
                    match lt_plan_build(handle, k, n, m, ta, ws) {
                        Ok(p) => {
                            let mut map = lt_plans().lock().unwrap();
                            if let std::collections::hash_map::Entry::Vacant(v) = map.entry(key) {
                                v.insert(p);
                                built += 1;
                            } else {
                                drop(map);
                                lt_plan_drop(p);
                                lost += 1;
                            }
                        }
                        Err(s) => {
                            println!("PFX1: ltplans stopped at c={c}: {s} — the remaining shapes stay lazy");
                            break 'rows;
                        }
                    }
                }
            }
            unsafe { let _ = lt::destroy_handle(handle); }
            println!("PFX1: cuBLASLt prefill plans pre-populated in {:.1} s (background): {built} built, \
                      {had} already cached, {lost} raced the prefill; {nf} shape families x chunk rows 1..={cmax} (m >= {rmin})",
                     t0.elapsed().as_secs_f32());
        });
        match spawned {
            Ok(h) => Some(h),
            Err(e) => { println!("PFX1: ltplans thread spawn failed ({e}) — prefill plans stay lazy"); None }
        }
    }

    /// WP04 (PLAN/SURPASS_PLAN_2026-09-26.md): capture EVERY decode graph the served config can
    /// reach at boot, so no request pays a lazy capture (the first request after a restart paid
    /// ~10 instantiations; an 11K run captured 21 graphs mid-generation at the old power-of-two
    /// scorer buckets). Per regime (dense; sparse when reachable and the scorer is bucket-free —
    /// otherwise its keys carry a bucket and stay lazy), for every lane slot: the decode step at
    /// m = 1..=lanes, verify m = 2..=k+1 (DDS; the fixed chain only verifies at k+1), and the draft
    /// passes 0..k (DDS) or the chain (fixed).
    ///
    /// CAPTURE-ONLY, NOTHING EXECUTES (WP04-v2). v1 ran one EAGER warm step + MTP round per regime
    /// on slot 0 first and "undid" it (planes re-zeroed, reset_slot); on hardware that shifted every
    /// later request's DDS trajectory (python drafted 1043 vs 1041, prose 1255 vs 1245 — hashes
    /// equal, trajectory gate FAILED), and the sparse warm round alone moved dense-only requests
    /// (dense-only vs dense+sparse warm differed although both leave identical planes) — the warm
    /// writes survive in the SCHEDULER SCRATCH, which the first request then reads where the
    /// baseline read fresh buffers. A captured graph only records its launches, so this version
    /// leaves every device byte (scratch, KV/QSA planes, recurrent state, PLE ring) exactly as a
    /// --graph-precapture off boot has it; the only one-time work the eager run used to trigger —
    /// the raw exl3_bench module the fused router launches through, the scorer's SM-count query —
    /// is done host-side first (a module load must not happen inside a capture). Each graph is
    /// then cuGraphUpload-ed (device-side instantiation, no kernel runs) so the first replay does
    /// not pay the upload either. DraftCal / ema_plain live in the scheduler and are not touched.
    /// Prints the graph count, seconds and the cuMemGetInfo delta; stops above 1 GB.
    /// The server's --graph-precapture off skips it (lazy capture as before).
    pub fn precapture_decode_graphs(&self, sc: &mut Scratch, lanes: usize, mtp_k: usize, dds: bool) -> Result<()> {
        if crate::opts::var(crate::opt!("exl3-no-graph")).is_ok()
            || crate::opts::var(crate::opt!("mtp-dump")).map_or(false, |s| !s.is_empty()) {
            println!("EXL3_GRAPH: precapture skipped (graphs off: --exl3-no-graph / --mtp-dump)");
            return Ok(());
        }
        let t0 = std::time::Instant::now();
        let free0 = cudarc::driver::result::mem_get_info().map(|x| x.0).unwrap_or(0);
        let n0 = self.graphs.lock().unwrap().len();
        PRECAP_ACTIVE.store(true, std::sync::atomic::Ordering::Relaxed);
        let r = self.precapture_inner(sc, lanes, mtp_k, dds, free0);
        PRECAP_ACTIVE.store(false, std::sync::atomic::Ordering::Relaxed);
        // the uploads were queued on the compute stream; no kernel was launched
        let synced = self.dev.synchronize().map_err(anyhow::Error::from);
        let free1 = cudarc::driver::result::mem_get_info().map(|x| x.0).unwrap_or(free0);
        let n = self.graphs.lock().unwrap().len().saturating_sub(n0);
        let mb = (free0 as f64 - free1 as f64) / 1e6;
        let up = PRECAP_UPLOAD_FAIL.load(std::sync::atomic::Ordering::Relaxed);
        let upn = if up > 0 { format!(" ({up} cuGraphUpload failed: their first replay uploads)") } else { String::new() };
        match &r {
            Ok(note) => println!("EXL3_GRAPH: precaptured {n} decode graphs at boot in {:.2} s (device mem {mb:+.0} MB){note}{upn}",
                                 t0.elapsed().as_secs_f64()),
            Err(e) => println!("EXL3_GRAPH: precapture FAILED after {n} graphs in {:.2} s (device mem {mb:+.0} MB): {e:#}",
                               t0.elapsed().as_secs_f64()),
        }
        r?;
        synced
    }

    fn precapture_inner(&self, sc: &mut Scratch, lanes: usize, mtp_k: usize, dds: bool, free0: usize) -> Result<String> {
        let l = Launcher { dev: &self.dev, stream: &self.stream };
        let lanes = lanes.clamp(1, self.width);
        let k = mtp_k.clamp(1, MTP_MAX_K);
        let head = if mtp_disabled_by_opt() { None } else { self.mtp.as_ref() };
        // the replay sites' own graph conditions (forward_step / mtp_verify / mtp_round*)
        // (p2 merge: + WP12's xcheck gate, which p1's forward_step / mtp_verify replay sites carry)
        let step_ok = crate::opts::var(crate::opt!("exl3-route-check")).is_err() && !wp12_xcheck();
        let verify_ok = gdn_ring_mode() != 2 && !wp12_xcheck();
        let draft_ok = tune::get_cur(&T_DRAFT_GRAPH) != 0
            && crate::opts::var(crate::opt!("hc-int8-check")).is_err()
            && !dhead::dhead_xcheck(); // (p2 merge) DHEAD's XCHECK turns the draft graphs off at the replay sites
        let bf = self.qsa_bucket_free();
        if [crate::opt!("exl3-score-xcheck"), crate::opt!("exl3-topk-xcheck"), crate::opt!("exl3-gather-xcheck")].iter().any(|v| wp14_xcheck(*v)) {
            println!("EXL3_GRAPH: note — WP04/WP14 XCHECK modes check EAGER calls only; graphed replays are \
                      not checked (run with --exl3-no-graph=1 for full coverage)");
        }
        // Host-side one-time init the eager first launch would otherwise do INSIDE a capture: the
        // fused router's raw-module load (cuModuleLoadDataEx) and the scorer's SM-count query.
        let _ = xq_raw_fn("xq_router_topk_route");
        // (p2 merge, WP04 x WP10/WP20: the decode-path raw entries WP04's base did not have —
        // WP10's routing fold and WP20's epilogues — resolved here too, so no cuModuleGetFunction
        // (and no lazy kernel load) happens inside a capture.)
        for f in ["xq_router_fold", "xq_router_fold_m0", "xq_router_fold_c", "xq_router_fold_c_ep", 
                  "xq_ks_combine_f32_k1l", "xq_moe_combine_ep_k1l", "xq_cvt_f16_f32_k1l", "xq_tp_wait_add_dec", "xq_tp_wait_add_dec_single", "xq_argmax_rows_vp", "xq_tp_wait_keys", "xq_vp_gather_k1", "xq_vp_gather_k2", "xq_vp_gather4_k1", "xq_vp_gather4_k2", "xq_dh_screen_k1", "xq_moe_gu_epi", "xq_moe_gu_epi_sh",
                  WP20_GU_FOLD_FN, "xq_moe_dn_epi_k8", "xq_moe_dn_epi_sh_k8", "xq_moe_dn_epi_k10", "xq_moe_dn_epi_sh_k10"] {
            let _ = xq_raw_fn(f);
        }
        let _ = qsa_mr_ctas();
        // (sparse, a position of that regime): the key only needs the regime (the bucket is 0 when
        // the scorer is bucket-free) and qsa_grid_nblk only feeds the bucketed scorers.
        let mut regimes: Vec<(bool, usize)> = vec![(false, 0)];
        let mut note = format!(" [capture-only, lanes {lanes}, k {k}, {}, regimes: dense",
                               if dds { "DDS passes" } else { "fixed chain" });
        if self.cfg.has_indexer() && !qsa_disabled() {
            let ps = self.qsa_limit() + 1; // the first sparse position
            if !bf {
                note += ", sparse LAZY (bucketed scorer: --exl3-score-mr=0 or no pooled planes)";
            } else if ps < self.max_pos && self.qsa_live(ps) {
                regimes.push((true, ps));
                note += ", sparse (bucket-free)";
            } else {
                note += ", sparse unreachable at this window";
            }
        }
        note += "]";
        let over = || cudarc::driver::result::mem_get_info()
            .map(|(f, _)| free0.saturating_sub(f) > (1usize << 30)).unwrap_or(false);
        const CAP: &str = " [stopped at the 1 GB precapture cap]";
        for &(sparse, p) in &regimes {
            let (qg, qb) = self.qsa_grid_bucket_key(p);
            if step_ok {
                // decode step: m = 1 (seam steps, control rounds) up to every lane (batched plain lanes)
                for m in 1..=lanes {
                    let key = gkey_of(m, sparse, qb) | sk(sc) | self.vp_key(sc, m);
                    if self.graphs.lock().unwrap().contains_key(&key) { continue; }
                    if over() { note += CAP; return Ok(note); }
                    sc.qsa_grid_nblk = qg;
                    self.capture_step_graph(&l, sc, m, key, sparse);
                }
            }
            let Some(h) = head else { continue };
            for s in 0..lanes {
                if verify_ok {
                    let widths: Vec<usize> = if dds { (2..=k + 1).collect() } else { vec![k + 1] };
                    for m in widths {
                        let key = vkey_of(s, m, sparse, qb) | sk(sc) | self.vp_key(sc, m);
                        if self.graphs.lock().unwrap().contains_key(&key) { continue; }
                        if over() { note += CAP; return Ok(note); }
                        sc.qsa_grid_nblk = qg;
                        self.capture_verify_graph(&l, sc, s, m, m - 1, sparse, key);
                    }
                }
                if draft_ok {
                    if dds {
                        for i in 0..k {
                            let key = pkey_of(s, i, sparse, qb) | sk(sc);
                            if self.graphs.lock().unwrap().contains_key(&key) { continue; }
                            if over() { note += CAP; return Ok(note); }
                            sc.qsa_grid_nblk = qg;
                            self.capture_pass_graph(&l, sc, h, i, sparse, key);
                        }
                    } else {
                        let key = dkey_of(s, k, sparse, qb) | sk(sc);
                        if !self.graphs.lock().unwrap().contains_key(&key) {
                            if over() { note += CAP; return Ok(note); }
                            sc.qsa_grid_nblk = qg;
                            self.capture_draft_graph(&l, sc, h, k, sparse, key);
                        }
                    }
                }
            }
        }
        Ok(note)
    }

    pub fn prefill_argmax(&self, psc: &PrefillScratch) -> Result<u32> {
        let ids = self.dev.dtoh_sync_copy(&psc.argmax)?;
        Ok(ids[0] as u32)
    }

    /// hc_pre against the PrefillScratch buffers (same launches as hc_pre at m=C).
    fn hc_pre_rows(&self, l: &Launcher, psc: &mut PrefillScratch, hc: &HcDev, c: usize) -> Result<()> {
        self.hc_pre_rows_p(l, psc, hc, c, None)
    }

    /// A5-P2: which of the fused prefill hc kernels apply to this model (knob AND shape).
    /// (norm, mix): xq_pf_hc_inj_norm needs h % 512 == 0 && h <= 4096; xq_pf_hc_mix_2560x4 the
    /// served h = 2560, hc = 4. Anything else keeps the old launches.
    fn pf_hc_fuse(&self, l: &Launcher) -> (bool, bool) {
        let on = tune::get(&T_PF_HC_FUSE, &l.cx()) != 0;
        let (h, hcn) = (self.cfg.hidden_size, self.cfg.hc_count.max(1));
        let norm = on && h % 512 == 0 && h <= 4096;
        let mix = on && h == 2560 && hcn == 4;
        static SEEN: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);
        let key = 1u8 | (norm as u8) << 1 | (mix as u8) << 2;
        if SEEN.swap(key, std::sync::atomic::Ordering::Relaxed) != key {
            println!("A5-P2 prefill hc: fuse={} (inj_norm {} mix {}; h {h} hc {hcn})", on as u8,
                     if norm { "xq_pf_hc_inj_norm (deferred inject)" } else { "xq_hc_inject+xq_hc_norm" },
                     if mix { "xq_pf_hc_mix_2560x4" } else { "xq_hc_mix4" });
        }
        (norm, mix)
    }

    /// hc_pre_rows with an optional PENDING inject (`pend` = the sublayer output a deferred
    /// hc_post_rows did not launch). With prefill.hc_fuse the inject rides the norm launch
    /// (xq_pf_hc_inj_norm); otherwise the pending inject is launched first (xq_hc_inject).
    fn hc_pre_rows_p(&self, l: &Launcher, psc: &mut PrefillScratch, hc: &HcDev, c: usize,
                     pend: Option<u64>) -> Result<()> {
        self.hc_pre_rows_n(l, psc, hc, c, pend, false)
    }

    /// TP-I2 item 1: the rows-landed hook of a pipelined prefill reduce (xtp::PfHook) for the
    /// hc_pre `hc` whose pending inject is `y`; None when the overlap is off (`rows` == 0).
    fn pf_hook(&self, psc: &PrefillScratch, hc: &HcDev, y: u64, rows: usize) -> Option<xtp::PfHook> {
        if rows == 0 { return None; }
        Some(xtp::PfHook {
            hn: *psc.hn.device_ptr() as u64, resid: *psc.resid.device_ptr() as u64, y,
            inj: *psc.inj.device_ptr() as u64, norm: *hc.norm.device_ptr() as u64,
            h: self.cfg.hidden_size, hcn: self.cfg.hc_count.max(1), eps: self.cfg.rms_eps, rows,
            dual: xtp::pf_overlap_dual(),
            fold: xtp::pf_overlap_fold(),
        })
    }

    /// hc_pre_rows_p; `normed` (TP-I2 item 1) = the pending inject + this hc_pre's norm already ran
    /// per row range inside the preceding reduce (the fused xq_pf_hc_inj_norm), so it is skipped
    /// here and `pend` (that inject's sublayer output) is consumed.
    fn hc_pre_rows_n(&self, l: &Launcher, psc: &mut PrefillScratch, hc: &HcDev, c: usize,
                     pend: Option<u64>, normed: bool) -> Result<()> {
        let h = self.cfg.hidden_size;
        let hcn = self.cfg.hc_count.max(1);
        let lr = self.cfg.hc_lowrank;
        let rw = h * hcn;
        let (fnorm, fmix) = self.pf_hc_fuse(l);
        if normed {
            anyhow::ensure!(fnorm && pend.is_some(), "prefill overlap: a hooked norm without the fused inj_norm path");
        } else if fnorm {
            xqlaunch!(l, "xq_pf_hc_inj_norm", ((hcn * c) as u32, 1, 1), (128, 1, 1), 0,
                     (&mut psc.hn, &mut psc.resid, pend.unwrap_or(0u64), &psc.inj, &hc.norm,
                      h as i32, hcn as i32, c as i32, self.cfg.rms_eps))?;
        } else {
            if let Some(y) = pend { self.hc_post_rows(l, psc, y, c)?; }
            xqlaunch!(l, "xq_hc_norm", ((hcn * c) as u32, 1, 1), (1024, 1, 1), 4096,
                     (&mut psc.hn, &psc.resid, &hc.norm, h as i32, hcn as i32, c as i32, self.cfg.rms_eps))?;
        }
        // S-A3-f-g: the hc down/up projections are the bulk of the prefill
        // xq_gemm_f16 cost (nsys: ~216 launches/chunk, same per-row K-serial
        // shape as a_w/b_w). Wide-M rows go through the vendor GEMM (opA=T);
        // the custom kernel stays for narrow workloads (rmin=0 → unchanged).
        let rmin = recon_min_rows();
        if rmin > 0 && c >= rmin {
            let rb = self.recon_bufs(psc);
            exl3_lt_matmul(l, *hc.down.device_ptr() as u64, *psc.hn.device_ptr() as u64,
                           *psc.dd.device_ptr() as u64, rw, lr as usize, c, true,
                           rb.ltws, rb.ltws_len)?;
            // activation between the two projections is elementwise: keep the
            // original kernel in both arms.
            xqlaunch!(l, "xq_silu_div", (((lr * c) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                     (&mut psc.dd, hcn as f32, (lr * c) as i32))?;
            exl3_lt_matmul(l, *hc.up.device_ptr() as u64, *psc.dd.device_ptr() as u64,
                           *psc.uu.device_ptr() as u64, lr as usize, rw, c, true,
                           rb.ltws, rb.ltws_len)?;
        } else {
            xq_gemm_f16_small!(l, &mut psc.dd, &hc.down, &psc.hn, c, lr, rw)?;
            xqlaunch!(l, "xq_silu_div", (((lr * c) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                     (&mut psc.dd, hcn as f32, (lr * c) as i32))?;
            xq_gemm_f16_small!(l, &mut psc.uu, &hc.up, &psc.dd, c, rw, lr)?;
        }
        if fmix {
            let winj = hc.winj.as_ref().map_or(0u64, |w| *w.device_ptr() as u64);
            xqlaunch!(l, "xq_pf_hc_mix_2560x4", (c as u32, 1, 1), (128, 1, 1), 0,
                     (&mut psc.x, &mut psc.inj, &psc.hn, &psc.uu, winj, c as i32))?;
            return Ok(());
        }
        let (mixk, mixs) = if hcn <= 4 && hc_mix4_on() { ("xq_hc_mix4", 4 * 1024 * 4) } else { ("xq_hc_mix", 4096) };
        match &hc.winj {
            Some(w) => xqlaunch!(l, mixk, (c as u32, 1, 1), (1024, 1, 1), mixs as u32,
                                (&mut psc.x, &mut psc.inj, &psc.hn, &psc.uu, w, h as i32, hcn as i32, c as i32))?,
            None => xqlaunch!(l, mixk, (c as u32, 1, 1), (1024, 1, 1), mixs as u32,
                             (&mut psc.x, &mut psc.inj, &psc.hn, &psc.uu, 0u64, h as i32, hcn as i32, c as i32))?,
        }
        Ok(())
    }

    /// TP-SP1: this rank's row block when a c-row chunk runs sequence-parallel, else None (the
    /// replicated prefill). SPMD: every input is identical on all ranks — the flag (TpConfig), c, the
    /// transport, and the pinned-plan readiness of EVERY rank's block (lt_pin_ready checks all blocks,
    /// at world 4 the quarter blocks — TP-4S).
    fn sp_rows_for(&self, psc: &PrefillScratch, c: usize) -> Option<xtp::SpRows> {
        let tp = self.tp.as_ref()?;
        if !xtp::seq_parallel_on() || !(xtp::SP_MIN_ROWS..=xtp::SP_MAX_ROWS).contains(&c) || !tp.sp_ready() {
            return None;
        }
        static WHY: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());
        let once = |w: String| {
            let mut v = WHY.lock().unwrap();
            if !v.contains(&w) { println!("[exl3-tp] TP-SP: {w}"); v.push(w); }
        };
        if xtp::pf_overlap_fold() {
            once("sequence-parallel prefill is not composed with --tp-prefill-overlap fold: chunks run replicated".into());
            return None;
        }
        let (h, hcn, lr) = (self.cfg.hidden_size, self.cfg.hc_count.max(1), self.cfg.hc_lowrank);
        let (world, rank) = (tp.world as usize, tp.rank as usize);
        let rmin = recon_min_rows();
        if rmin > 0 && c >= rmin {
            let rb = self.recon_bufs(psc);
            for (k, n) in sp_split_shapes(h, hcn, lr) {
                if let Err(e) = lt_pin_ready(k, n, c, world, true, rb.ltws_len) {
                    once(format!("chunk of {c} rows runs replicated: the pinned hc plan (k {k} n {n}) is not runnable ({e:#})"));
                    return None;
                }
            }
        }
        let sp = xtp::SpRows::new(c, rank, world);
        static ONCE: std::sync::Once = std::sync::Once::new();
        ONCE.call_once(|| println!("[exl3-tp] TP-SP sequence-parallel prefill ACTIVE at world {world} (first chunk c {c}: rank {rank} owns rows {:?}, \
                                    row blocks {:?}; chunks of {}..={} rows split, hc GEMM plans pinned to the full chunk's)",
                                   sp.own, &sp.blocks[..world.min(4)], xtp::SP_MIN_ROWS, xtp::SP_MAX_ROWS));
        Some(sp)
    }

    /// TP-SP1: hc_pre_rows_n on this rank's OWN rows of the chunk (every launch of hc_pre_rows_n at the
    /// same per-row arithmetic, on row-offset pointers over sp.own; the hc down/up GEMMs through the
    /// full chunk's cuBLASLt plan PINNED on the own-row layouts), then the all-gather of x (the peer's
    /// rows land in this rank's x) when `gather_x`. inj / hn / resid / dd / uu are written for the own
    /// rows only.
    #[allow(clippy::too_many_arguments)]
    fn hc_pre_rows_sp(&self, l: &Launcher, psc: &mut PrefillScratch, hc: &HcDev, sp: xtp::SpRows,
                      pend: Option<u64>, normed: bool, gather_x: bool) -> Result<()> {
        let tp = self.tp.as_ref().context("TP-SP hc_pre without a TP attachment")?;
        let h = self.cfg.hidden_size;
        let hcn = self.cfg.hc_count.max(1);
        let lr = self.cfg.hc_lowrank;
        let rw = h * hcn;
        let c = sp.c;
        let (lo, hi) = sp.own;
        let b = hi - lo;
        anyhow::ensure!(hi > lo && hi <= c, "TP-SP: empty own block {:?} of {c}", sp.own);
        let (fnorm, fmix) = self.pf_hc_fuse(l);
        let hn = *psc.hn.device_ptr() as u64 + (lo * rw * 2) as u64;
        let resid = *psc.resid.device_ptr() as u64 + (lo * rw * 4) as u64;
        let inj = *psc.inj.device_ptr() as u64 + (lo * hcn * 4) as u64;
        let xo = *psc.x.device_ptr() as u64 + (lo * h * 2) as u64;
        let dd = *psc.dd.device_ptr() as u64 + (lo * lr * 2) as u64;
        let uu = *psc.uu.device_ptr() as u64 + (lo * rw * 2) as u64;
        let pend_o = pend.map(|y| y + (lo * h * 2) as u64);
        if normed {
            anyhow::ensure!(fnorm && pend.is_some(), "prefill overlap: a hooked norm without the fused inj_norm path");
        } else if fnorm {
            xqlaunch!(l, "xq_pf_hc_inj_norm", ((hcn * b) as u32, 1, 1), (128, 1, 1), 0,
                     (hn, resid, pend_o.unwrap_or(0u64), inj, &hc.norm, h as i32, hcn as i32, b as i32, self.cfg.rms_eps))?;
        } else {
            if let Some(y) = pend_o {
                xqlaunch!(l, "xq_hc_inject", (((h * hcn * b) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                         (resid, y, inj, h as i32, hcn as i32, b as i32))?;
            }
            xqlaunch!(l, "xq_hc_norm", ((hcn * b) as u32, 1, 1), (1024, 1, 1), 4096,
                     (hn, resid, &hc.norm, h as i32, hcn as i32, b as i32, self.cfg.rms_eps))?;
        }
        let rmin = recon_min_rows();
        if rmin > 0 && c >= rmin {
            // the replicated chunk takes the vendor GEMM at m = c: run ITS plan's algo on the own rows
            let rb = self.recon_bufs(psc);
            exl3_lt_matmul_pinned(l, *hc.down.device_ptr() as u64, hn, dd, rw, lr, b, c, true, rb.ltws, rb.ltws_len)?;
            xqlaunch!(l, "xq_silu_div", (((lr * b) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0, (dd, hcn as f32, (lr * b) as i32))?;
            exl3_lt_matmul_pinned(l, *hc.up.device_ptr() as u64, dd, uu, lr, rw, b, c, true, rb.ltws, rb.ltws_len)?;
        } else {
            // one CTA row per chunk row: row-offset pointers are the full launch's bits on those rows
            xqlaunch!(l, "xq_gemm_f16", (((lr as u32) + 127) / 128, b as u32, 1), (128, 1, 1), 0,
                     (dd, &hc.down, hn, b as i32, lr as i32, rw as i32))?;
            xqlaunch!(l, "xq_silu_div", (((lr * b) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0, (dd, hcn as f32, (lr * b) as i32))?;
            xqlaunch!(l, "xq_gemm_f16", (((rw as u32) + 127) / 128, b as u32, 1), (128, 1, 1), 0,
                     (uu, &hc.up, dd, b as i32, rw as i32, lr as i32))?;
        }
        let winj = hc.winj.as_ref().map_or(0u64, |w| *w.device_ptr() as u64);
        if fmix {
            xqlaunch!(l, "xq_pf_hc_mix_2560x4", (b as u32, 1, 1), (128, 1, 1), 0, (xo, inj, hn, uu, winj, b as i32))?;
        } else {
            let (mixk, mixs) = if hcn <= 4 && hc_mix4_on() { ("xq_hc_mix4", 4 * 1024 * 4) } else { ("xq_hc_mix", 4096) };
            xqlaunch!(l, mixk, (b as u32, 1, 1), (1024, 1, 1), mixs as u32,
                     (xo, inj, hn, uu, winj, h as i32, hcn as i32, b as i32))?;
        }
        if gather_x {
            tp.sp_all_gather(l, *psc.x.device_ptr() as u64, h * 2, &sp)?;
        }
        Ok(())
    }

    /// TP-SP2 (--xtp-sp-fault, probe only): flip the lowest mantissa bit of the first stream element of
    /// row `row` of the chunk's streams (resid) — a one-rank, one-owned-row divergence.
    fn sp_fault_flip(&self, psc: &mut PrefillScratch, row: usize, li: usize) -> Result<()> {
        let l = Launcher { dev: &self.dev, stream: &self.stream };
        let i = row * self.cfg.hidden_size * self.cfg.hc_count.max(1);
        self.dev.synchronize()?;
        let mut v = vec![0f32; 1];
        self.dev.dtoh_sync_copy_into(&psc.resid.slice(i..i + 1), &mut v)?;
        let f = f32::from_bits(v[0].to_bits() ^ 1);
        let tmp = self.dev.htod_sync_copy(&[f])?;
        xqlaunch!(l, "xq_copy_f32", (1, 1, 1), (256, 1, 1), 0, (&mut psc.resid, &tmp, 1i64, i as i64, 0i64))?;
        self.dev.synchronize()?;
        let rank = self.tp.as_ref().map_or(0, |t| t.rank);
        println!("[exl3-tp] rank {rank}: TP-SP2 FAULT INJECTION (--xtp-sp-fault {li}): layer {li} streams row {row} element 0 \
                  {:e} -> {:e} (one ulp, this rank's own row only)", v[0], f);
        Ok(())
    }

    /// TP-SP1: hc_post_rows over this rank's own rows (the non-deferred path: trace dumps / unfused hc);
    /// None = hc_post_rows over every row.
    fn hc_post_rows_sp(&self, l: &Launcher, psc: &mut PrefillScratch, y_ptr: u64, c: usize,
                       sp: Option<xtp::SpRows>) -> Result<()> {
        let Some(sp) = sp else { return self.hc_post_rows(l, psc, y_ptr, c) };
        let h = self.cfg.hidden_size;
        let hcn = self.cfg.hc_count.max(1);
        let (lo, hi) = sp.own;
        let b = hi - lo;
        xqlaunch!(l, "xq_hc_inject", (((h * hcn * b) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (*psc.resid.device_ptr() as u64 + (lo * h * hcn * 4) as u64, y_ptr + (lo * h * 2) as u64,
                  *psc.inj.device_ptr() as u64 + (lo * hcn * 4) as u64, h as i32, hcn as i32, b as i32))
    }

    /// hc_post against the PrefillScratch residual.
    fn hc_post_rows(&self, l: &Launcher, psc: &mut PrefillScratch, y_ptr: u64, c: usize) -> Result<()> {
        let h = self.cfg.hidden_size;
        let hcn = self.cfg.hc_count.max(1);
        xqlaunch!(l, "xq_hc_inject", (((h * hcn * c) as u32) / 256 + 1, 1, 1), (256, 1, 1), 0,
                 (&mut psc.resid, y_ptr, &psc.inj, h as i32, hcn as i32, c as i32))?;
        Ok(())
    }

    // S-A3-f-d night: optional per-stage trace dumps inside prefill_chunk
    // (--probe-exl3-pfxtrace). Same file names / row-0 semantics as the
    // forward_step LadderCtx dumps, so the two arms diff file-for-file.
    fn tr_u16(&self, ld: Option<&LadderCtx>, steps: bool, li: usize,
              buf: &CudaSlice<u16>, name: &str, n: usize) -> Result<()> {
        if let Some(l) = ld {
            let go = if steps { l.want_steps(li) } else { l.want(li) };
            if go {
                self.dev.synchronize()?;
                l.dump_u16(&self.dev, buf, name, n)?;
            }
        }
        Ok(())
    }
    fn tr_f32(&self, ld: Option<&LadderCtx>, steps: bool, li: usize,
              buf: &CudaSlice<f32>, name: &str, m: usize) -> Result<()> {
        if let Some(l) = ld {
            let go = if steps { l.want_steps(li) } else { l.want(li) };
            if go {
                self.dev.synchronize()?;
                l.dump(&self.dev, buf, name, m)?;
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------------------
// S-A3-f-d — MTP k-chain verify round (the multiplier).
//
// Round structure (reference anatomy answer key, k drafts / width-(k+1) verify):
//   draft-extend  head(b, T_pred(b))                -> d0   [argmax kept on device]
//   draft x k-1   head(d_{i-1}, p+i)                -> d_i  [device-resident chain]
//   VERIFY        trunk rows (b, d0..d_{k-1}) at p..p+k  -> e_0..e_k
//   accept        a = longest prefix with d_i == e_i     [one device kernel]
//   emit          d_0..d_{a-1} + bonus e_a           (a+1 tokens; E = 1+p+..+p^k)
//   commit        replay rows 0..a of every stateful op from the LIVE state
//                 (bit-identical; rows a+1..k never commit)  [device-keyed]
//   re-prime      the head consumed the confirmed tokens via the NEXT round's
//                 draft chain; row a's verify tap becomes that draft-extend tap
//
// Greedy chain-verify is bitwise-lossless by construction: every emitted token
// equals the trunk's own argmax at its position with the true prefix (accepted
// drafts d_i == e_i by the accept check; the bonus IS e_a), the trunk commits
// only valid-row states, and the head never feeds back into the trunk.
// ---------------------------------------------------------------------------

pub struct MtpRoundOut {
    pub a: usize,            // accepted drafts
    pub emitted: Vec<i32>,   // a+1 tokens: d_0..d_{a-1}, e_a
    pub pos_next: usize,     // position of the next round's bonus
    pub last_tok: i32,       // the bonus e_a (next round's b)
    pub tap_row: usize,      // taps_keep row holding the next draft-extend tap
    pub drafts: Vec<i32>,    // the full drafted chain (k) — for post-hoc scoring
    // WP24: host time (ms) this round spent in the --wp24-dump / --wp24-xcheck diagnostics
    // (readbacks + host re-derivation); the serve subtracts it from the round's cost (0 when off).
    pub diag_ms: f64,
}

/// API-parity G2: one row's sampler params for `xq_sample_rows` (temperature -> top-k ->
/// top-p -> min_p -> multinomial). `counter` must differ per sampled row (the uniform is
/// hash(seed, counter)); callers advance it by the rows they consume.
#[derive(Clone, Copy, Debug)]
pub struct SampParams {
    pub temperature: f32,
    pub top_p: f32,
    pub top_k: u32, // 0 = off
    pub min_p: f32, // 0 = off
    pub seed: u64,
    pub counter: u32,
}

impl SampParams {
    /// None when the params are greedy (temperature ~0 or top_k == 1): the argmax id stands.
    pub fn sampled(temperature: f32, top_p: f32, top_k: usize, min_p: f32, seed: u64, counter: u32) -> Option<Self> {
        if temperature < 1e-6 || top_k == 1 {
            return None;
        }
        let top_p = if top_p <= 0.0 || top_p > 1.0 { 1.0 } else { top_p };
        let top_k = if top_k >= u32::MAX as usize { 0 } else { top_k as u32 };
        Some(Self { temperature, top_p, top_k, min_p: min_p.max(0.0), seed, counter })
    }
    fn pack(&self) -> [u32; 8] {
        self.pack_flag(1)
    }
    /// WP24: the same row with row flag `flag` (1 = sampled, 2 = sampled real-q verify row).
    fn pack_flag(&self, flag: u32) -> [u32; 8] {
        [flag, self.temperature.to_bits(), self.top_p.to_bits(), self.top_k,
         self.seed as u32, (self.seed >> 32) as u32, self.counter, self.min_p.to_bits()]
    }
}

/// WP24: one MTP round's real-q draft sampler (see `FwdModel::set_spec_sampling`). `tau` = the
/// draft temperature tau_d, `top_p` / `top_k` = the REQUEST's (q' must be the law the pass samples
/// from, truncation included), `seed` = the request's (the draft domain separates the streams),
/// `dctr` = the lane's draft RNG counter (pass i draws dctr + i; a separate stream from the verify
/// rows' counters). mode 1 = --wp24-dump list only, 2 = real-q.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct RqStage {
    pub mode: u8,
    pub tau: f32,
    pub top_p: f32,
    pub top_k: u32,
    pub seed: u64,
    pub dctr: u32,
}

impl RqStage {
    /// The real-q draft sampler of a lane under `--spec-sampling ratio` (mode 2) or the dump rung
    /// (mode 1), for its NEXT round — None for a greedy lane (SampParams::sampled's rule: greedy
    /// stays on the bitwise match path) and when neither is on. `draft_temp` = --draft-temperature
    /// (None = the request's temperature). ONE rule for the server and the WP24 gate.
    pub fn for_lane(ratio: bool, draft_temp: Option<f32>, temperature: f32, top_p: f32, top_k: usize,
                    min_p: f32, seed: u64, dctr: u32) -> Option<RqStage> {
        let sp = SampParams::sampled(temperature, top_p, top_k, min_p, seed, 0)?;
        let mode = if ratio { 2 } else if crate::wp24::dump_on() { 1 } else { return None };
        Some(RqStage {
            mode,
            tau: draft_temp.unwrap_or(sp.temperature),
            top_p: sp.top_p,
            top_k: sp.top_k,
            seed,
            dctr,
        })
    }
    fn pack(&self) -> [u32; 8] {
        [1, self.tau.to_bits(), self.top_p.to_bits(), self.top_k,
         self.seed as u32, (self.seed >> 32) as u32, 0, 0]
    }
}

/// WP15: one row's penalty params for `xq_pen_rows` / `xq_pen_draft` — the reference implementation's ComboSampler
/// semantics (SS_RepP + SS_PresFreqP over `sustain` full-strength + `decay` fading positions of
/// the full sequence, prompt included; the reference implementation server's default is 1024 + 1024).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PenParams {
    pub rep: f32,
    pub pres: f32,
    pub freq: f32,
    pub sustain: u32,
    pub decay: u32,
}

/// Token ring per slot for the penalty window (positions & (PEN_RING - 1)).
pub const PEN_RING_LOG2: u32 = 13;
pub const PEN_RING: usize = 1 << PEN_RING_LOG2;
/// Largest --penalty-range: the window (sustain + decay - 1) plus a verify's width must fit the
/// ring with room to spare, so an in-flight commit never overwrites a position a row still reads.
pub const PEN_RANGE_MAX: usize = (PEN_RING - 64) / 2;
const PEN_SPAN: usize = 4096; // XQ_PEN_SPAN

impl PenParams {
    /// None when the params are a no-op (the reference implementation's SS_RepP / SS_PresFreqP `alt()` NoOp rule:
    /// rep_p == 1 and pres == freq == 0, or an empty range) — the row stays bit-identical.
    pub fn new(rep: f32, pres: f32, freq: f32, sustain: usize, decay: usize) -> Option<Self> {
        let s = sustain.min(PEN_RANGE_MAX) as u32;
        let d = decay.min(PEN_RANGE_MAX) as u32;
        let rep_on = rep != 1.0 && rep.is_finite() && rep > 0.0;
        let pf_on = (pres != 0.0 && pres.is_finite()) || (freq != 0.0 && freq.is_finite());
        if (!rep_on && !pf_on) || s + d == 0 {
            return None;
        }
        Some(Self {
            rep: if rep_on { rep } else { 1.0 },
            pres: if pres.is_finite() { pres } else { 0.0 },
            freq: if freq.is_finite() { freq } else { 0.0 },
            sustain: s,
            decay: d,
        })
    }
    fn flag(&self) -> u32 {
        (self.rep != 1.0) as u32 | (((self.pres != 0.0 || self.freq != 0.0) as u32) << 1)
    }
    /// DHEADP (w3): true when xq_pen_tok can only LOWER a logit (rep >= 1, pres >= 0, freq >= 0 —
    /// see the monotonicity note on xq_pen_tok). rep < 1 or a negative pres/freq (accepted with a
    /// warning, as the reference engine does) can raise one: those requests keep the old draft head.
    pub fn monotone(&self) -> bool {
        self.rep >= 1.0 && self.pres >= 0.0 && self.freq >= 0.0
    }
    fn pack(&self) -> [u32; 8] {
        [self.flag(), self.rep.to_bits(), self.pres.to_bits(), self.freq.to_bits(),
         self.sustain, self.decay, 0, 0]
    }
}

/// DHEADP (w3): a draft pass's lm_head tail (FwdModel::draft_tail).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DraftTail {
    /// DHEAD: screen + exact rescore (unpenalized drafts)
    Dhead,
    /// DHEADP: screen + bound-expanded, penalized rescore (monotone penalized drafts)
    DheadP,
    /// the full slice head (+ xq_pen_draft when penalized)
    Old,
    /// A5-L4: an unpenalized real-q pass on DHEAD (screen + rescore + xq_rq_draft_dh)
    DheadRq,
}

/// --exl3-pen-draft=0: the draft head proposes from UNpenalized logits (diagnostics A/B of
/// the draft mirror; draft-only either way — the verify decides every emitted token).
fn pen_draft_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| crate::opts::var(crate::opt!("exl3-pen-draft")).as_deref() != Ok("0"))
}

/// WP23: draft depth ceiling 5 -> 7 (verify width m = k+1 <= 8). Every per-round buffer derives
/// from it (d_dev / accept_out / dconf, the per-GDN-layer qkv_save / qkv_post / a_save / b_save /
/// gdn_ring planes), and so does the ring-commit gate (MTP_MAX_K+1 <= GDN_RING_CMAX = 8, the
/// xq_gdn_commit_ring smem extent). The SERVED depth is the runtime cap --exl3-mtp-k
/// (mtp_depth_default, default = this); --exl3-mtp-k=5 reproduces the K5 build's rounds.
pub const MTP_MAX_K: usize = 7;
/// WP23: max rows xq_gdn_commit_ring commits (its kr_sh/g_sh extent + device guard; exl3_bench.cu).
const GDN_RING_CMAX: usize = 8;
/// K1: KV cache storage format. [kv-cache] = f32 (exact) | f16 | fp8 | q8 (the server's
/// --kv-cache). Row bytes per (slot, K|V, kv-head, pos): 4*hd, 2*hd, hd+16 (fp8 + f32 row scale),
/// hd + hd/16 padded to 16 B (q8: int8 codes + one f16 scale per 32-dim group; 272 B at hd=256).
pub const KV_F32: u32 = 0;
pub const KV_F16: u32 = 1;
pub const KV_FP8: u32 = 2;
/// WP25/K3: the reference implementation's "-cq 8" scheme (H32 rotation + int8 midpoint grid + f16 group scale).
pub const KV_Q8: u32 = 3;
/// WP25 probe-only positive control: the q8 layout at 4-bit resolution ([kv-cache]=q4x).
pub const KV_Q4X: u32 = 4;
/// The format when neither --kv-cache nor [kv-cache] names one. Owner decision 2026-09-26:
/// q8 becomes the default AFTER the WP25 GPU quality gate passes — it passed on .14 (quality
/// holds vs the noise floor), so the default is now the reference implementation's q8 cache. `--kv-cache f32`
/// (or [kv-cache]=f32) restores the exact f32 cache.
pub const KV_FMT_DEFAULT: u32 = KV_Q8;
pub fn kv_fmt_from_opts() -> u32 {
    match crate::opts::var(crate::opt!("kv-cache")).as_deref() {
        Ok("f32") => KV_F32,
        Ok("f16") => KV_F16,
        Ok("fp8") => KV_FP8,
        Ok("q8") => KV_Q8,
        Ok("q4x") => KV_Q4X,
        Ok("") | Err(_) => KV_FMT_DEFAULT,
        Ok(other) => {
            eprintln!("[exl3] [kv-cache]={other} is not f32|f16|fp8|q8; using the default {}",
                      kv_fmt_name(KV_FMT_DEFAULT));
            KV_FMT_DEFAULT
        }
    }
}
pub fn kv_fmt_name(fmt: u32) -> &'static str {
    match fmt { KV_F32 => "f32", KV_F16 => "f16", KV_FP8 => "fp8", KV_Q8 => "q8", _ => "q4x" }
}
pub fn kv_rowbytes(fmt: u32, hd: usize) -> usize {
    match fmt {
        KV_F32 => 4 * hd,
        KV_F16 => 2 * hd,
        KV_FP8 => hd + 16,
        _ => hd + (hd / 16).next_multiple_of(16),
    }
}
// WP25: the q8 host reference + --probe-exl3-kvq / --probe-exl3-kvnll. A child module so the
// teacher-forced verify step reaches the private verify/prefill internals without widening them.
#[path = "exl3_kvnll.rs"]
mod kvnll;
pub use kvnll::{probe_kv_nll, probe_kv_q8_selftest, KvNllArgs};

/// Attention-target sentinel for the MTP draft head in the shared QSA helpers.
const HEAD_ATT: usize = usize::MAX;
/// A5 D5: fixed split count of the draft head's dense attention (graph-safe launch constant;
/// the per-split key range is derived on device from the row's position).
pub const DRAFT_ATTN_SPLITS: usize = 64;

/// --exl3-head-qsa=0: draft head stays dense everywhere and appends no indexer keys (A/B).
fn head_qsa_off() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| crate::opts::var(crate::opt!("exl3-head-qsa")).as_deref() == Ok("0"))
}

/// --exl3-draft-attn=legacy restores the one-block-per-query-head `xq_attn_decode` scan.
fn draft_attn_legacy() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| crate::opts::var(crate::opt!("exl3-draft-attn")).as_deref() == Ok("legacy"))
}

/// WP13: dense-regime trunk attention v3 (xq_attn_dense_prep -> _dots -> _acc{1,4}), bitwise
/// to xq_attn_decode_group (verify) / xq_attn_decode (decode step). Default ON;
/// --exl3-dense-v3=0 restores the old per-(head, row) two-pass scan (A/B + bisect escape).
fn dense_v3_on() -> bool {
    tune::get_cur(&T_DENSE_V3) != 0
}
/// TUNE T0 (p3c): WP13's switch. Its geometry (DV3_TS / DV3_NCH / DV3_G) is compile-time, mirrored
/// from the kernel — no runtime schedule knob exists yet (a T4 twin would add one).
pub(crate) const T_DENSE_V3: tune::TunableDef = tune::TunableDef {
    slot: 37, id: "attn.dense_v3", class: tune::Class::S, scope: tune::Scope::Width,
    fams: &[tune::Fam::Step, tune::Fam::Verify, tune::Fam::Util],
    domain: &[0, 1], default: 1, valid: tune::valid_any,
    xcheck: "--probe-exl3-binv EXL3-ATTN (v3 vs v2, f32/f16/fp8/q8) + --exl3-dense-xcheck",
    env: "--exl3-dense-v3", env_parse: || tune::env_on_unless_0(crate::opt!("exl3-dense-v3")), rev: 1, wp: "WP13",
};
/// WP13 XCHECK (diagnostic, --exl3-dense-xcheck=1): after every v3 dense attention the
/// old kernel re-runs into a side buffer and xq_dv3_xcheck diffs the f16 outputs bitwise on
/// device — "[dense-v3-xcheck] MISMATCH ..." per event, a heartbeat every 1024 checks.
/// Graph-safe (device printf); costs the old kernel's time on top of v3's.
fn dense_xcheck_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| crate::opts::var(crate::opt!("exl3-dense-xcheck")).as_deref() == Ok("1"))
}
/// WP13 geometry — mirrors XQ_DV3_TS / XQ_DV3_NCH / XQ_DV3_G / XQ_DV3_G6 in kernels/exl3_bench.cu.
const DV3_TS: usize = 2304;
const DV3_NCH: usize = 36;
const DV3_G: usize = 12;
/// TP-4G: the second instantiation — 6 q heads per kv head (W=4 / TP=4, kv replicated).
const DV3_G6: usize = 6;

/// TP-4G: q heads per kv head the dense-v3 kernels are instantiated for, or None (the layer
/// stays on v2). Pure; `dense_v3_ok` adds the engine-state conditions on top.
pub(crate) fn dv3_group(num_heads: usize, num_kv_heads: usize) -> Option<usize> {
    if num_kv_heads == 0 { None }
    else if num_heads == DV3_G * num_kv_heads { Some(DV3_G) }
    else if num_heads == DV3_G6 * num_kv_heads { Some(DV3_G6) }
    else { None }
}

/// TP-4G / W4S dattn: the 5-stage-ring twin of a dense-v3 accumulate kernel (bitwise to it).
pub(crate) fn dv3_w4_twin(old: &'static str) -> &'static str {
    match old {
        "xq_attn_dense_acc4" => "xq_attn_dense_acc4_w4",
        "xq_attn_dense_acc1" => "xq_attn_dense_acc1_w4",
        "xq_attn_dense_acc4_g6" => "xq_attn_dense_acc4_w4_g6",
        "xq_attn_dense_acc1_g6" => "xq_attn_dense_acc1_w4_g6",
        k => k,
    }
}

/// TP-4G: launch plan of the dense-v3 dots + accumulate kernels for group size `g` (6 | 12) and
/// `m` rows: (dots name, accumulate name BEFORE the W4S twin mapping, accumulate dim slice SD,
/// accumulate block threads = 16 * g). The G=12 names are the pre-TP-4G kernels unchanged.
pub(crate) fn dv3_plan(g: usize, m: usize) -> (&'static str, &'static str, usize, u32) {
    let g6 = g == DV3_G6;
    let dots = if g6 { "xq_attn_dense_dots_g6" } else { "xq_attn_dense_dots" };
    let (acc, sd) = match (m == 1, g6) {
        (true, false) => ("xq_attn_dense_acc1", 16),
        (false, false) => ("xq_attn_dense_acc4", 64),
        (true, true) => ("xq_attn_dense_acc1_g6", 16),
        (false, true) => ("xq_attn_dense_acc4_g6", 64),
    };
    (dots, acc, sd, 16 * g as u32)
}

#[cfg(test)]
mod tp4g_dv3_tests {
    use super::*;

    /// `#define NAME value` of the kernel source, parsed (the host mirrors must equal them).
    fn kdef(name: &str) -> usize {
        let src = include_str!("../kernels/exl3_bench.cu");
        let key = format!("#define {name} ");
        let line = src.lines().find(|l| l.starts_with(&key))
            .unwrap_or_else(|| panic!("#define {name} missing"));
        line[key.len()..].split_whitespace().next().unwrap().parse().unwrap()
    }

    #[test]
    fn dv3_geometry_mirrors_kernel_defines() {
        assert_eq!(kdef("XQ_DV3_TS"), DV3_TS);
        assert_eq!(kdef("XQ_DV3_G"), DV3_G);
        assert_eq!(kdef("XQ_DV3_G6"), DV3_G6);
        assert_eq!(kdef("XQ_DV3_CH"), 64);
        assert_eq!(DV3_TS / 64, DV3_NCH);
    }

    #[test]
    fn dv3_group_gate_truth_table() {
        // G = 12: TP=1 (24/2), TP=2 (12/1), and a wider multiple
        for (nh, nkv) in [(24, 2), (12, 1), (36, 3)] { assert_eq!(dv3_group(nh, nkv), Some(12), "{nh}/{nkv}"); }
        // G = 6: TP=4 (6/1), and the 12/2 shape
        for (nh, nkv) in [(6, 1), (12, 2), (24, 4), (18, 3)] { assert_eq!(dv3_group(nh, nkv), Some(6), "{nh}/{nkv}"); }
        // everything else stays on v2
        for (nh, nkv) in [(8, 1), (16, 2), (24, 1), (20, 2), (10, 1), (7, 1), (9, 1), (3, 1), (1, 1), (0, 2), (12, 0), (0, 0), (13, 2), (5, 1)] {
            assert_eq!(dv3_group(nh, nkv), None, "{nh}/{nkv}");
        }
    }

    #[test]
    fn dv3_plan_names_blocks_and_coverage() {
        // G = 12 is the pre-TP-4G plan, byte for byte
        assert_eq!(dv3_plan(12, 1), ("xq_attn_dense_dots", "xq_attn_dense_acc1", 16, 192));
        assert_eq!(dv3_plan(12, 2), ("xq_attn_dense_dots", "xq_attn_dense_acc4", 64, 192));
        assert_eq!(dv3_plan(12, 16), ("xq_attn_dense_dots", "xq_attn_dense_acc4", 64, 192));
        // G = 6: the _g6 twins, 16 * 6 = 96 threads
        assert_eq!(dv3_plan(6, 1), ("xq_attn_dense_dots_g6", "xq_attn_dense_acc1_g6", 16, 96));
        assert_eq!(dv3_plan(6, 4), ("xq_attn_dense_dots_g6", "xq_attn_dense_acc4_g6", 64, 96));
        for g in [6usize, 12] {
            for m in [1usize, 2, 3, 4, 8, 16] {
                let (_, acc, sd, block) = dv3_plan(g, m);
                // one thread per (head, dim-group): g heads x 16 dgl; the grid's x covers hd = 256
                assert_eq!(block as usize, g * 16);
                assert!(block <= 1024 && block % 32 == 0, "block {block}");
                assert_eq!(256 / sd * sd, 256);
                // the W4S twin always exists and keeps the group suffix
                let tw = dv3_w4_twin(acc);
                assert_ne!(tw, acc);
                assert_eq!(tw.ends_with("_g6"), g == 6, "{tw}");
            }
        }
    }

    #[test]
    fn dv3_every_planned_kernel_is_declared_and_in_the_manifest() {
        let src = include_str!("../kernels/exl3_bench.cu");
        for g in [6usize, 12] {
            for m in [1usize, 4] {
                let (dots, acc, _, _) = dv3_plan(g, m);
                for name in [dots, acc, dv3_w4_twin(acc)] {
                    assert!(src.contains(&format!("\n{name}(")), "kernel {name} not defined in exl3_bench.cu");
                    assert!(crate::exl3_bench::MODULE_FNS.contains(&name), "kernel {name} missing from MODULE_FNS");
                }
            }
        }
    }

    /// Static shared memory per CTA as the kernel source declares it (+ the 16 B ptxas reserves);
    /// the quoted numbers are the `-Xptxas -v` smem of the compiled kernels (TP-4G report).
    fn dots_smem(g: usize) -> usize { g * 32 * 8 * 4 + 8 * 32 * 33 * 4 + 8 * g * 4 + 16 }
    fn acc_smem(g: usize, dpt: usize) -> usize { 2 * 64 * (16 * dpt) * 4 + 2 * 64 * 4 * 4 + g * (64 + 4) * 4 + 16 }
    fn w4a_smem(g: usize, dpt: usize) -> usize { 5 * 32 * (16 * dpt) * 4 + 5 * 32 * 4 * 4 + g * (32 + 4) * 4 + 16 }

    #[test]
    fn dv3_static_smem_arithmetic() {
        const STATIC_CAP: usize = 48 * 1024;
        // G = 12 must equal the pre-TP-4G ptxas numbers exactly
        assert_eq!((dots_smem(12), acc_smem(12, 4), acc_smem(12, 1)), (46480, 38096, 13520));
        assert_eq!((w4a_smem(12, 4), w4a_smem(12, 1)), (45264, 14544));
        // G = 6 (measured by ptxas -v)
        assert_eq!((dots_smem(6), acc_smem(6, 4), acc_smem(6, 1)), (40144, 36464, 11888));
        assert_eq!((w4a_smem(6, 4), w4a_smem(6, 1)), (44400, 13680));
        for g in [6usize, 12] {
            for v in [dots_smem(g), acc_smem(g, 4), acc_smem(g, 1), w4a_smem(g, 4), w4a_smem(g, 1)] {
                assert!(v <= STATIC_CAP, "static smem {v} over 48 KB");
            }
            // 2 CTAs/SM of the dots kernel (launch bounds 256,2) stay inside the 99 KB opt-in cap
            assert!(2 * dots_smem(g) <= 101376);
        }
    }

    /// CPU model of the index arithmetic the G-templated kernels use (the part TP-4G changed):
    /// dots — per chunk a warp walks ceil(G/4) head groups; lane L finishes dot (position L>>2,
    /// head hg*4 + (L&3)), stored / maxed only when that head is < G (PARTIAL guard, G % 4 != 0);
    /// acc — thread tid owns head tid>>4 of the kv group, dim-group tid&15, block = 16 * G.
    /// Every (position, head) must be produced exactly once and no head >= G ever stored.
    #[test]
    fn dv3_lane_maps_cover_each_dot_once() {
        for g in [6usize, 12] {
            let nhg = (g + 3) / 4;
            let partial = g % 4 != 0;
            let mut stores = vec![0u32; 8 * g];          // [position-in-warp][head]
            let mut wmx_writes = vec![0u32; g];          // wmx[warp][head] (one warp)
            let mut tile_rows_computed = 0usize;         // (hg, hh) q-row computations per warp-chunk
            for hg in 0..nhg {
                for hh in 0..4 {
                    if partial && hg * 4 + hh >= g { continue; }
                    tile_rows_computed += 1;
                }
                for lane in 0..32usize {
                    let (i, h) = (lane >> 2, hg * 4 + (lane & 3));
                    if !partial || h < g { stores[i * g + h] += 1; }
                    if lane < 4 && (!partial || hg * 4 + lane < g) { wmx_writes[hg * 4 + lane] += 1; }
                }
            }
            assert!(stores.iter().all(|&c| c == 1), "G={g}: every (position, head) dot stored exactly once");
            assert!(wmx_writes.iter().all(|&c| c == 1), "G={g}: every head's warp max written exactly once");
            assert_eq!(tile_rows_computed, g, "G={g}: one q row per head, none for the padding rows");
            if !partial { assert_eq!(nhg * 4, g); }      // G=12: no guard can fire
            // acc / w4a: 16 * g threads = g heads x 16 dim groups, each (head, dgl) once
            let mut owners = vec![0u32; g * 16];
            for tid in 0..16 * g { owners[(tid >> 4) * 16 + (tid & 15)] += 1; }
            assert!(owners.iter().all(|&c| c == 1));
            // pmx publish: threads 0..G of the dots CTA
            assert!(g <= 256);
        }
    }

    #[test]
    fn dv3_dots_grid_at_w4() {
        // ~96 CTAs whatever m is; nkv = 1 at W=4 (kv replicated), clamp to the 36-chunk plane
        let nchg = |nkv: usize, m: usize| (96 / (nkv * m)).clamp(1, DV3_NCH);
        assert_eq!([nchg(1, 1), nchg(1, 2), nchg(1, 4), nchg(1, 8), nchg(1, 16)], [36, 36, 24, 12, 6]);
        assert_eq!([nchg(2, 1), nchg(2, 4), nchg(2, 16)], [36, 12, 3]);
    }
}
/// S-A3-o G1: ring floats per (token, head) — mirrors XQ_GDN_RS in exl3_bench.cu.
const GDN_RS: usize = 260;

/// S-A3-i: fixed split count of the gathered QSA decode (graph-safe: the split count
/// is a launch constant; each split no-ops past pos_sel).
pub const QSA_SPLITS: usize = 4;
/// Decode/verify split count of the gathered QSA attention (graph-safe launch constant).
/// 4 splits gave rows x 2 kv heads x 4 = 8 CTAs at m=1, each walking ~513 selected tokens
/// serially: 6.4 ms per plain step at 32K context, latency-bound (m=6 cost the same). 32
/// splits = 64 CTAs at m=1. Decode and verify share it (MTP stays bitwise lossless); prefill
/// keeps QSA_SPLITS (2,048-row chunks are already parallel; its partials would be 8x larger),
/// so chunked-prefill vs token-by-token decode now agree to fp32 reassociation, not bits.
pub const QSA_SPLITS_DEC: usize = 32;

/// TUNE T0 (N2): the decode/verify QSA split count is a NUMERICS knob (it moves the reduction
/// grouping) — class N, Global (m-independent: lossless MTP needs decode == verify grouping), so
/// the table never sets it without the owner's consent; the legacy alias keeps its exact parse.
pub(crate) const T_QSA_SPLITS_DEC: tune::TunableDef = tune::TunableDef {
    slot: 8, id: "qsa.splits_dec", class: tune::Class::N, scope: tune::Scope::Global,
    fams: &[tune::Fam::Step, tune::Fam::Verify],
    domain: &[4, 8, 16, 32], default: QSA_SPLITS_DEC as i32, valid: tune::valid_any, xcheck: "drift table (N)",
    env: "--exl3-qsa-splits-dec",
    env_parse: || tune::env_str(crate::opt!("exl3-qsa-splits-dec")).and_then(|v| v.parse::<usize>().ok())
        .filter(|n| (1..=QSA_SPLITS_DEC).contains(n)).map(|n| n as i32),
    rev: 1, wp: "S-A3-qsa",
};

/// Runtime decode/verify split count: QSA_SPLITS_DEC, or --exl3-qsa-splits-dec=4 to restore
/// the pre-2026-09-26 reduction grouping exactly (buffers are sized for the maximum).
fn qsa_splits_dec() -> usize {
    // TUNE T0: N-frozen registry value (env alias or the built-in 32; never a table value)
    (tune::get_cur(&T_QSA_SPLITS_DEC).clamp(1, QSA_SPLITS_DEC as i32)) as usize
}

// ---- WP04 + WP14 (PLAN/SURPASS_PLAN_2026-09-26.md): long-context QSA decode + boot capture ----
// Every switch below is a diagnostic escape (AGENTS §1b): the new paths are bit-identical to the
// old ones, the old ones stay reachable for A/B and bisection.
fn wp_env_flag(o: crate::opts::OptId, default_on: bool) -> bool {
    match crate::opts::var(o).as_deref() {
        Ok("0") | Ok("off") => false,
        Ok(_) => true,
        Err(_) => default_on,
    }
}
/// --exl3-score-mr=0: the bucketed `qsa_score_pooled_b` scorer (and bucket-keyed graphs).
